'use client';

import { AdminFlashSalePage } from '../../../../features/admin/screens/FlashSale';

export const dynamic = 'force-dynamic';

export default function AdminFlashSaleRoute() {
  return <AdminFlashSalePage />;
}

'use client';

import { useEffect, useState } from 'react';
import { Link, useNavigate, useSearchParams } from '../../../lib/navigation';
import { AlertCircle, ArrowLeft, Loader2 } from 'lucide-react';
import { useUser } from '../../../features/shared/state/UserContext';

function normalizeRedirectTarget(value: string | null) {
  if (!value || !value.startsWith('/')) {
    return null;
  }

  return value;
}

function resolvePostAuthDestination(userRole: string, redirectTarget: string | null) {
  if (redirectTarget) return redirectTarget;
  if (userRole === 'admin') return '/admin/dashboard';
  if (userRole === 'seller') return '/seller/dashboard';
  if (userRole === 'reseller') return '/reseller-dashboard/overview';
  return '/account/dashboard';
}

function getHashParams() {
  if (typeof window === 'undefined' || !window.location.hash) {
    return new URLSearchParams();
  }

  return new URLSearchParams(window.location.hash.replace(/^#/, ''));
}

export default function AuthCallbackPage() {
  const navigate = useNavigate();
  const [searchParams] = useSearchParams();
  const { login } = useUser();
  const [error, setError] = useState('');
  const [mode, setMode] = useState<'login' | 'register'>('login');

  useEffect(() => {
    let cancelled = false;
    const pending = (() => {
      try {
        const raw = window.sessionStorage.getItem('lofimart_pending_oauth');
        return raw ? JSON.parse(raw) : null;
      } catch {
        return null;
      }
    })() as {
      redirectTarget?: string | null;
      role?: string | null;
      referralCode?: string | null;
      mode?: 'login' | 'register';
    } | null;

    const redirectTarget = normalizeRedirectTarget(searchParams.get('redirect')) || normalizeRedirectTarget(pending?.redirectTarget || null);
    const role = searchParams.get('role') || pending?.role || undefined;
    const referralCode = searchParams.get('ref') || pending?.referralCode || undefined;
    const currentMode = searchParams.get('mode') === 'register' || pending?.mode === 'register' ? 'register' : 'login';
    setMode(currentMode);

    const run = async () => {
      try {
        const [{ createClient, hasSupabaseBrowserEnv }, { exchangeSupabaseSession, mapAuthMessage }, { default: toast }] = await Promise.all([
          import('@/lib/client'),
          import('@/lib/auth-ui'),
          import('react-hot-toast'),
        ]);

        if (!hasSupabaseBrowserEnv()) {
          throw new Error('Supabase auth is not configured. Add NEXT_PUBLIC_SUPABASE_URL and NEXT_PUBLIC_SUPABASE_PUBLISHABLE_KEY to your .env.');
        }

        const callbackError =
          searchParams.get('error_description') ||
          searchParams.get('error') ||
          getHashParams().get('error_description') ||
          getHashParams().get('error');

        if (callbackError) {
          throw new Error(callbackError);
        }

        const supabase = createClient();
        const code = searchParams.get('code');
        const hashParams = getHashParams();

        if (code) {
          const { error: codeExchangeError } = await supabase.auth.exchangeCodeForSession(code);
          if (codeExchangeError) {
            throw codeExchangeError;
          }
        }

        const hashAccessToken = hashParams.get('access_token');
        const hashRefreshToken = hashParams.get('refresh_token');
        if (!code && hashAccessToken && hashRefreshToken) {
          const { error: hashSessionError } = await supabase.auth.setSession({
            access_token: hashAccessToken,
            refresh_token: hashRefreshToken,
          });

          if (hashSessionError) {
            throw hashSessionError;
          }

          window.history.replaceState(null, '', `${window.location.pathname}${window.location.search}`);
        }

        const { data, error: sessionError } = await supabase.auth.getSession();
        if (sessionError) {
          throw sessionError;
        }

        const session = data.session;
        const accessToken = session?.access_token;
        if (!accessToken) {
          throw new Error('Supabase session not found');
        }

        if (currentMode === 'register' && !role) {
          throw new Error('Please select whether you are joining as a customer, seller, or reseller before using social sign up.');
        }

        const payload = await exchangeSupabaseSession({
          accessToken,
          role,
          referralCode,
          mode: currentMode,
          name: session.user.user_metadata?.name || session.user.user_metadata?.full_name,
        });

        if (cancelled) {
          return;
        }

        login(payload.user, payload.token, payload.refreshToken);
        try {
          window.sessionStorage.removeItem('lofimart_pending_oauth');
        } catch {
          // ignore
        }
        toast.success(
          currentMode === 'register'
            ? `Welcome${payload.user?.name ? `, ${payload.user.name}` : ''}. Your account is ready.`
            : `Welcome back${payload.user?.name ? `, ${payload.user.name}` : ''}.`,
        );
        navigate(resolvePostAuthDestination(payload.user.role, redirectTarget), { replace: true });
      } catch (err: any) {
        if (!cancelled) {
          const { mapAuthMessage } = await import('@/lib/auth-ui');
          setError(mapAuthMessage(err.message || 'Authentication failed'));
        }
      }
    };

    void run();

    return () => {
      cancelled = true;
    };
  }, [login, navigate, searchParams]);

  return (
    <div className="min-h-[80vh] flex items-center justify-center px-4">
      <div className="max-w-md w-full bg-white p-8 rounded-2xl border border-black/5 shadow-xl text-center space-y-4">
        {error ? (
          <>
            <div className="mx-auto flex h-14 w-14 items-center justify-center rounded-full bg-rose-50 text-rose-600">
              <AlertCircle size={26} />
            </div>
            <h1 className="text-2xl font-bold">{mode === 'register' ? 'Sign-up could not be completed' : 'Sign-in failed'}</h1>
            <p className="text-sm text-gray-500">{error}</p>
            <div className="pt-2">
              <Link
                to={mode === 'register' ? '/register' : '/login'}
                className="inline-flex items-center gap-2 rounded-2xl bg-slate-950 px-4 py-3 text-sm font-semibold text-white transition hover:bg-slate-800"
              >
                <ArrowLeft size={16} />
                <span>{mode === 'register' ? 'Back to register' : 'Back to login'}</span>
              </Link>
            </div>
          </>
        ) : (
          <>
            <Loader2 className="animate-spin mx-auto" size={28} />
            <h1 className="text-2xl font-bold">{mode === 'register' ? 'Completing account setup' : 'Completing sign in'}</h1>
            <p className="text-sm text-gray-500">
              {mode === 'register'
                ? 'Please wait while we finish creating your account and secure your session.'
                : 'Please wait while we finish your Supabase login.'}
            </p>
          </>
        )}
      </div>
    </div>
  );
}

import type { Metadata, Viewport } from 'next';
import { Inter, Poppins, Noto_Sans_Bengali } from 'next/font/google';
import Script from 'next/script';
import '../index.css';
import { AppProviders } from '../features/shared/app/AppProviders';
import { AppChrome } from '../features/shared/app/AppChrome';
import MarketingAnalytics from '../features/shared/analytics/MarketingAnalytics';
import { ErrorBoundary } from '../components/ErrorBoundary';
import { cn } from "@/lib/utils";

const inter = Inter({
  subsets: ['latin'],
  display: 'swap',
  variable: '--font-inter',
  weight: ['400', '500', '600', '700'],
  fallback: ['system-ui', 'sans-serif'],
});

const poppins = Poppins({
  subsets: ['latin'],
  display: 'swap',
  variable: '--font-poppins',
  weight: ['500', '600', '700'],
  preload: false,
  fallback: ['Arial', 'sans-serif'],
});

const notoSansBengali = Noto_Sans_Bengali({
  subsets: ['bengali'],
  display: 'swap',
  variable: '--font-bengali',
  weight: ['400', '500', '600', '700'],
  preload: false,
  fallback: ['Inter', 'system-ui', 'sans-serif'],
});

export const viewport: Viewport = {
  width: 'device-width',
  initialScale: 1,
  maximumScale: 5,
  viewportFit: 'cover',
  themeColor: '#2563EB',
};

export const metadata: Metadata = {
  metadataBase: new URL(process.env.NEXT_PUBLIC_SITE_URL || 'https://lofimart.vercel.app'),
  title: {
    default: 'LofiMart | Smart Shopping for Bangladesh',
    template: '%s | LofiMart',
  },
  description: 'Shop fashion, electronics, groceries, and lifestyle essentials with fast delivery, trusted sellers, AI discovery, and a smoother checkout experience.',
  applicationName: 'LofiMart',
  manifest: '/manifest.json',
  keywords: [
    'Bangladesh ecommerce',
    'online shopping BD',
    'fashion in Bangladesh',
    'electronics online',
    'trusted delivery',
    'AI shopping assistant',
  ],
  icons: {
    icon: '/icon.svg',
    apple: '/icon.svg',
  },
  openGraph: {
    title: 'LofiMart | Smart Shopping for Bangladesh',
    description: 'Discover trusted products, fast delivery, AI-powered recommendations, and a polished buying experience built for Bangladesh.',
    siteName: 'LofiMart',
    type: 'website',
    url: '/',
  },
  alternates: {
    canonical: '/',
  },
  twitter: {
    card: 'summary_large_image',
    title: 'LofiMart | Smart Shopping for Bangladesh',
    description: 'Trusted sellers, curated collections, smooth checkout, and AI-powered shopping tools.',
  },
  appleWebApp: {
    capable: true,
    statusBarStyle: 'black-translucent',
    title: 'LofiMart',
  },
};

function getPreconnectOrigins() {
  const origins = new Set<string>();

  if (process.env.CLOUDINARY_CLOUD_NAME) {
    origins.add(`https://res.cloudinary.com`);
    origins.add(`https://api.cloudinary.com`);
    origins.add(`https://widget.cloudinary.com`);
  }

  const supabaseUrl = process.env.NEXT_PUBLIC_SUPABASE_URL;
  if (supabaseUrl) {
    try {
      origins.add(new URL(supabaseUrl).origin);
    } catch {
      // Ignore invalid local env during render; runtime validation handles production cases.
    }
  }

  return Array.from(origins);
}

function getStructuredData() {
  const siteUrl = process.env.NEXT_PUBLIC_SITE_URL || 'https://lofimart.vercel.app';

  return {
    '@context': 'https://schema.org',
    '@graph': [
      {
        '@type': 'Organization',
        '@id': `${siteUrl}/#organization`,
        name: 'LofiMart',
        url: siteUrl,
        logo: `${siteUrl}/icon.svg`,
        contactPoint: {
          '@type': 'ContactPoint',
          contactType: 'customer support',
          email: 'support@lofimart.com',
          areaServed: 'BD',
          availableLanguage: ['en', 'bn'],
        },
      },
      {
        '@type': 'WebSite',
        '@id': `${siteUrl}/#website`,
        name: 'LofiMart',
        url: siteUrl,
        publisher: {
          '@id': `${siteUrl}/#organization`,
        },
        potentialAction: {
          '@type': 'SearchAction',
          target: `${siteUrl}/search?q={search_term_string}`,
          'query-input': 'required name=search_term_string',
        },
      },
    ],
  };
}

export default function RootLayout({
  children,
}: Readonly<{
  children: React.ReactNode;
}>) {
  const preconnectOrigins = getPreconnectOrigins();
  const structuredData = getStructuredData();

  return (
    <html lang="en-BD" data-scroll-behavior="smooth" className={cn(inter.variable, poppins.variable, notoSansBengali.variable, "font-sans")}>
      <head>
        <Script
          id="lofimart-structured-data"
          type="application/ld+json"
          strategy="beforeInteractive"
          dangerouslySetInnerHTML={{ __html: JSON.stringify(structuredData) }}
        />
        {preconnectOrigins.map((origin) => (
          <link key={`${origin}-preconnect`} rel="preconnect" href={origin} crossOrigin="" />
        ))}
        {preconnectOrigins.map((origin) => (
          <link key={`${origin}-dns-prefetch`} rel="dns-prefetch" href={origin} />
        ))}
        {process.env.NODE_ENV === 'development' ? (
          <Script id="dev-clear-sw-cache" strategy="beforeInteractive">
            {`
              (function () {
                try {
                  var isLocalhost =
                    window.location.hostname === 'localhost' ||
                    window.location.hostname === '127.0.0.1';

                  if (!isLocalhost || !('serviceWorker' in navigator)) return;

                  navigator.serviceWorker.getRegistrations().then(function (registrations) {
                    return Promise.all(registrations.map(function (registration) {
                      return registration.unregister();
                    }));
                  }).catch(function () {});

                  if ('caches' in window) {
                    window.caches.keys().then(function (keys) {
                      return Promise.all(keys.map(function (key) {
                        return window.caches.delete(key);
                      }));
                    }).catch(function () {});
                  }
                } catch (error) {
                  // Development-only best effort cleanup.
                }
              })();
            `}
          </Script>
        ) : null}
      </head>
      <body>
        <ErrorBoundary>
          <MarketingAnalytics />
          <AppProviders>
            <AppChrome>{children}</AppChrome>
          </AppProviders>
        </ErrorBoundary>
      </body>
    </html>
  );
}

import React, { useEffect, useState } from 'react';
import { Plus, Trash2, Edit2, Loader2, Image as ImageIcon, ExternalLink, ToggleLeft, ToggleRight } from 'lucide-react';
import { useUser } from '../../../features/shared/state/UserContext';
import toast from '@/lib/toast';
import { Link } from '../../../lib/navigation';
import CloudinaryUpload from '@/features/shared/media/CloudinaryUpload';
import OptimizedImage from '@/features/shared/ui/OptimizedImage';
import { CenteredLoader, EmptyState, FormNotice } from '@/features/shared/ui/FeedbackState';

export const AdminBannersPage = () => {
  const { token } = useUser();
  const [banners, setBanners] = useState<any[]>([]);
  const [loading, setLoading] = useState(true);
  const [showModal, setShowModal] = useState(false);
  const [editingBanner, setEditingBanner] = useState<any>(null);
  const [deleteConfirmId, setDeleteConfirmId] = useState<number | null>(null);
  const [error, setError] = useState('');
  const [message, setMessage] = useState('');
  const [submitting, setSubmitting] = useState(false);
  const [formData, setFormData] = useState({
    title: '',
    subtitle: '',
    image: '',
    link: '',
    button_text: 'Shop Now'
  });

  const fetchBanners = async () => {
    try {
      setLoading(true);
      setError('');
      const response = await fetch('/api/admin/banners', {
        headers: { 'Authorization': `Bearer ${token}` }
      });
      const data = await response.json().catch(() => null);
      if (!response.ok) {
        throw new Error(data?.error || 'Failed to load banners');
      }
      setBanners(data);
    } catch (err) {
      const nextError = err instanceof Error ? err.message : 'Failed to load banners';
      toast.error(nextError);
      setError(nextError);
      setBanners([]);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    if (token) fetchBanners();
  }, [token]);

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    const url = editingBanner ? `/api/admin/banners/${editingBanner.id}` : '/api/admin/banners';
    const method = editingBanner ? 'PATCH' : 'POST';

    try {
      setSubmitting(true);
      setError('');
      setMessage('');
      const response = await fetch(url, {
        method,
        headers: {
          'Content-Type': 'application/json',
          'Authorization': `Bearer ${token}`
        },
        body: JSON.stringify(formData)
      });
      const data = await response.json().catch(() => null);
      if (!response.ok) {
        throw new Error(data?.error || 'Failed to save banner');
      }
      toast.success(editingBanner ? 'Banner updated' : 'Banner created');
      setMessage(editingBanner ? 'Banner updated successfully.' : 'Banner created successfully.');
      setShowModal(false);
      setEditingBanner(null);
      setFormData({ title: '', subtitle: '', image: '', link: '', button_text: 'Shop Now' });
      fetchBanners();
    } catch (err) {
      const nextError = err instanceof Error ? err.message : 'Failed to save banner';
      toast.error(nextError);
      setError(nextError);
    } finally {
      setSubmitting(false);
    }
  };

  const handleToggleActive = async (banner: any) => {
    try {
      const response = await fetch(`/api/admin/banners/${banner.id}`, {
        method: 'PATCH',
        headers: {
          'Content-Type': 'application/json',
          'Authorization': `Bearer ${token}`
        },
        body: JSON.stringify({ ...banner, is_active: !banner.is_active })
      });
      const data = await response.json().catch(() => null);
      if (!response.ok) {
        throw new Error(data?.error || 'Failed to update banner status');
      }
      toast.success(`Banner ${!banner.is_active ? 'activated' : 'deactivated'}`);
      fetchBanners();
    } catch (err) {
      toast.error(err instanceof Error ? err.message : 'Failed to update banner status');
    }
  };

  const handleDelete = async (id: number) => {
    try {
      const response = await fetch(`/api/admin/banners/${id}`, {
        method: 'DELETE',
        headers: { 'Authorization': `Bearer ${token}` }
      });
      const data = await response.json().catch(() => null);
      if (!response.ok) {
        throw new Error(data?.error || 'Failed to delete banner');
      }
      setDeleteConfirmId(null);
      toast.success('Banner deleted');
      fetchBanners();
    } catch (err) {
      toast.error(err instanceof Error ? err.message : 'Failed to delete banner');
    }
  };

  const handleEdit = (banner: any) => {
    setEditingBanner(banner);
    setFormData({
      title: banner.title,
      subtitle: banner.subtitle,
      image: banner.image,
      link: banner.link,
      button_text: banner.button_text
    });
    setShowModal(true);
  };

  if (loading) {
    return <CenteredLoader label="Loading banners..." className="min-h-[240px]" />;
  }

  return (
    <div className="space-y-6">
      {error ? <FormNotice tone="error">{error}</FormNotice> : null}
      {message ? <FormNotice tone="success">{message}</FormNotice> : null}
      <div className="flex justify-between items-center">
        <div>
          <h1 className="text-2xl font-bold">Banner Management</h1>
          <p className="text-sm text-gray-500">Manage homepage hero banners and promotions</p>
        </div>
        <button 
          onClick={() => {
            setEditingBanner(null);
            setFormData({ title: '', subtitle: '', image: '', link: '', button_text: 'Shop Now' });
            setShowModal(true);
          }}
          className="bg-primary text-white px-4 py-2 rounded-xl flex items-center space-x-2 hover:bg-primary/90 transition-colors"
        >
          <Plus size={20} />
          <span>Add Banner</span>
        </button>
      </div>

      <div className="grid grid-cols-1 gap-6">
        {banners.length === 0 ? (
          <EmptyState
            icon={<ImageIcon size={24} />}
            title="No banners have been created yet"
            description="Create a homepage banner to highlight campaigns, promotions, and seasonal hero content."
            tone="soft"
            className="py-12"
          />
        ) : banners.map((banner) => (
          <div key={banner.id} className="bg-white rounded-2xl border border-black/5 shadow-sm overflow-hidden flex flex-col md:flex-row group">
            <div className="md:w-1/3 aspect-video relative overflow-hidden bg-gray-100">
              <OptimizedImage src={banner.image} alt={banner.title} widthHint={960} heightHint={540} className="w-full h-full object-cover" />
              <div className="absolute inset-0 bg-black/40 opacity-0 group-hover:opacity-100 transition-opacity flex items-center justify-center space-x-4">
                <button 
                  onClick={() => handleEdit(banner)}
                  className="p-3 bg-white rounded-full text-gray-900 hover:scale-110 transition-transform"
                >
                  <Edit2 size={20} />
                </button>
                {deleteConfirmId === banner.id ? (
                  <div className="flex items-center gap-2 rounded-full bg-white px-3 py-2 text-xs font-semibold text-rose-700">
                    <span>Delete?</span>
                    <button
                      onClick={() => handleDelete(banner.id)}
                      className="rounded-full bg-rose-600 px-3 py-1 text-white transition hover:bg-rose-700"
                    >
                      Confirm
                    </button>
                    <button
                      onClick={() => setDeleteConfirmId(null)}
                      className="rounded-full border border-slate-200 px-3 py-1 text-slate-600 transition hover:bg-slate-50"
                    >
                      Cancel
                    </button>
                  </div>
                ) : (
                  <button 
                    onClick={() => setDeleteConfirmId(banner.id)}
                    className="p-3 bg-white rounded-full text-accent hover:scale-110 transition-transform"
                  >
                    <Trash2 size={20} />
                  </button>
                )}
              </div>
            </div>
            <div className="p-6 flex-1 flex flex-col justify-between">
              <div>
                <div className="flex justify-between items-start mb-2">
                  <h3 className="font-bold text-xl">{banner.title}</h3>
                  <button 
                    onClick={() => handleToggleActive(banner)}
                    className={`flex items-center space-x-2 text-sm font-medium ${banner.is_active ? 'text-emerald-600' : 'text-gray-400'}`}
                  >
                    {banner.is_active ? <ToggleRight size={24} /> : <ToggleLeft size={24} />}
                    <span>{banner.is_active ? 'Active' : 'Inactive'}</span>
                  </button>
                </div>
                <p className="text-sm text-gray-500 mb-4">{banner.subtitle}</p>
                <div className="flex items-center space-x-4 text-xs text-gray-400">
                  <span className="flex items-center space-x-1">
                    <ExternalLink size={12} />
                    <Link to={banner.link || '/shop'} className="hover:text-primary">
                      <span>Link: {banner.link}</span>
                    </Link>
                  </span>
                  <span>Button: {banner.button_text}</span>
                </div>
              </div>
            </div>
          </div>
        ))}
      </div>

      {showModal && (
        <div className="fixed inset-0 bg-black/50 flex items-center justify-center z-50 p-4">
          <div className="bg-white rounded-2xl p-8 w-full max-w-lg">
            <h2 className="text-xl font-bold mb-6">{editingBanner ? 'Edit Banner' : 'New Banner'}</h2>
            <form onSubmit={handleSubmit} className="space-y-4">
              <div>
                <label className="block text-sm font-medium text-gray-700 mb-1">Title</label>
                <input 
                  type="text" 
                  required
                  className="w-full border border-gray-200 rounded-xl px-4 py-2 text-sm"
                  value={formData.title}
                  onChange={(e) => setFormData({...formData, title: e.target.value})}
                />
              </div>
              <div>
                <label className="block text-sm font-medium text-gray-700 mb-1">Subtitle</label>
                <input 
                  type="text" 
                  required
                  className="w-full border border-gray-200 rounded-xl px-4 py-2 text-sm"
                  value={formData.subtitle}
                  onChange={(e) => setFormData({...formData, subtitle: e.target.value})}
                />
              </div>
              <div>
                <label className="block text-sm font-medium text-gray-700 mb-1">Banner Image</label>
                <input 
                  type="url" 
                  required
                  className="w-full border border-gray-200 rounded-xl px-4 py-2 text-sm"
                  value={formData.image}
                  onChange={(e) => setFormData({...formData, image: e.target.value})}
                  placeholder="Optional: paste an existing hosted image URL"
                />
                <div className="mt-2">
                  <CloudinaryUpload
                    label="Upload banner image"
                    helper="Pick a file directly. We will upload it and fill the image URL automatically."
                    onUploaded={(url) => setFormData({ ...formData, image: url })}
                  />
                </div>
              </div>
              <div className="grid grid-cols-2 gap-4">
                <div>
                  <label className="block text-sm font-medium text-gray-700 mb-1">Button Text</label>
                  <input 
                    type="text" 
                    required
                    className="w-full border border-gray-200 rounded-xl px-4 py-2 text-sm"
                    value={formData.button_text}
                    onChange={(e) => setFormData({...formData, button_text: e.target.value})}
                  />
                </div>
                <div>
                  <label className="block text-sm font-medium text-gray-700 mb-1">Link URL</label>
                  <input 
                    type="text" 
                    required
                    className="w-full border border-gray-200 rounded-xl px-4 py-2 text-sm"
                    value={formData.link}
                    onChange={(e) => setFormData({...formData, link: e.target.value})}
                  />
                </div>
              </div>
              <div className="flex space-x-4 pt-4">
                <button 
                  type="button"
                  onClick={() => setShowModal(false)}
                  disabled={submitting}
                  className="flex-1 px-4 py-2 border border-gray-200 rounded-xl text-sm font-medium hover:bg-gray-50 disabled:cursor-not-allowed disabled:opacity-60"
                >
                  Cancel
                </button>
                <button 
                  type="submit"
                  disabled={submitting}
                  className="flex-1 px-4 py-2 bg-primary text-white rounded-xl text-sm font-medium hover:bg-primary/90 disabled:cursor-not-allowed disabled:opacity-60"
                >
                  <span className="inline-flex items-center justify-center gap-2">
                    {submitting ? <Loader2 size={16} className="animate-spin" /> : null}
                    {submitting ? 'Saving...' : editingBanner ? 'Update Banner' : 'Create Banner'}
                  </span>
                </button>
              </div>
            </form>
          </div>
        </div>
      )}
    </div>
  );
};

import React, { useEffect, useMemo, useState } from 'react';
import {
  Edit2,
  FileText,
  Image as ImageIcon,
  Loader2,
  Plus,
  Search,
  Tag,
  Trash2,
} from 'lucide-react';
import { useUser } from '../../../features/shared/state/UserContext';
import toast from '@/lib/toast';
import CloudinaryUpload from '@/features/shared/media/CloudinaryUpload';
import OptimizedImage from '@/features/shared/ui/OptimizedImage';
import { Link } from '../../../lib/navigation';

type AdminBlogPost = {
  id: string;
  title: string;
  slug: string;
  excerpt?: string;
  category?: string;
  content: string;
  image?: string;
  seo_title?: string;
  seo_description?: string;
  author_name?: string;
  created_at?: string;
};

type BlogFormData = {
  title: string;
  slug: string;
  excerpt: string;
  category: string;
  content: string;
  image: string;
  seoTitle: string;
  seoDescription: string;
};

const emptyForm: BlogFormData = {
  title: '',
  slug: '',
  excerpt: '',
  category: 'Insights',
  content: '',
  image: '',
  seoTitle: '',
  seoDescription: '',
};

function buildSlug(title: string) {
  return title
    .toLowerCase()
    .trim()
    .replace(/\s+/g, '-')
    .replace(/[^\w-]+/g, '')
    .replace(/--+/g, '-');
}

export const AdminBlogPage = () => {
  const { token } = useUser();
  const [posts, setPosts] = useState<AdminBlogPost[]>([]);
  const [loading, setLoading] = useState(true);
  const [saving, setSaving] = useState(false);
  const [query, setQuery] = useState('');
  const [showModal, setShowModal] = useState(false);
  const [editingPost, setEditingPost] = useState<AdminBlogPost | null>(null);
  const [formData, setFormData] = useState<BlogFormData>(emptyForm);
  const [deleteConfirmId, setDeleteConfirmId] = useState('');

  const fetchPosts = async () => {
    try {
      const response = await fetch('/api/admin/blog', {
        headers: { Authorization: `Bearer ${token}` },
      });
      const data = await response.json().catch(() => null);
      if (!response.ok) {
        throw new Error(data?.error || 'Failed to load blog posts');
      }
      setPosts(Array.isArray(data) ? data : []);
    } catch (err) {
      toast.error(err instanceof Error ? err.message : 'Failed to load blog posts');
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    if (token) {
      void fetchPosts();
    }
  }, [token]);

  const filteredPosts = useMemo(() => {
    const term = query.trim().toLowerCase();
    if (!term) {
      return posts;
    }

    return posts.filter((post) =>
      `${post.title} ${post.category ?? ''} ${post.author_name ?? ''}`.toLowerCase().includes(term),
    );
  }, [posts, query]);

  const openCreateModal = () => {
    setEditingPost(null);
    setFormData(emptyForm);
    setShowModal(true);
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    const url = editingPost ? `/api/admin/blog/${editingPost.id}` : '/api/admin/blog';
    const method = editingPost ? 'PATCH' : 'POST';

    setSaving(true);
    try {
      const response = await fetch(url, {
        method,
        headers: {
          'Content-Type': 'application/json',
          Authorization: `Bearer ${token}`,
        },
        body: JSON.stringify(formData),
      });
      const payload = await response.json().catch(() => null);

      if (!response.ok) {
        throw new Error(payload?.error || 'Failed to save post');
      }

      toast.success(editingPost ? 'Post updated' : 'Post created');
      setShowModal(false);
      setEditingPost(null);
      setFormData(emptyForm);
      await fetchPosts();
    } catch (err) {
      toast.error(err instanceof Error ? err.message : 'Failed to save post');
    } finally {
      setSaving(false);
    }
  };

  const handleDelete = async (id: string) => {
    try {
      const response = await fetch(`/api/admin/blog/${id}`, {
        method: 'DELETE',
        headers: { Authorization: `Bearer ${token}` },
      });
      const payload = await response.json().catch(() => null);
      if (!response.ok) throw new Error(payload?.error || 'Delete failed');
      setDeleteConfirmId('');
      toast.success('Post deleted');
      await fetchPosts();
    } catch (err) {
      toast.error(err instanceof Error ? err.message : 'Failed to delete post');
    }
  };

  const handleEdit = (post: AdminBlogPost) => {
    setEditingPost(post);
    setFormData({
      title: post.title,
      slug: post.slug,
      excerpt: post.excerpt || '',
      category: post.category || 'Insights',
      content: post.content,
      image: post.image || '',
      seoTitle: post.seo_title || '',
      seoDescription: post.seo_description || '',
    });
    setShowModal(true);
  };

  if (loading) {
    return (
      <div className="flex h-64 items-center justify-center">
        <Loader2 className="animate-spin text-primary" size={32} />
      </div>
    );
  }

  return (
    <div className="space-y-6">
      <div className="flex flex-col gap-4 lg:flex-row lg:items-end lg:justify-between">
        <div>
          <h1 className="text-2xl font-bold text-slate-950">Blog Management</h1>
          <p className="text-sm text-slate-500">Create polished editorial content with category, excerpt, and SEO metadata.</p>
        </div>
        <button
          onClick={openCreateModal}
          className="inline-flex items-center gap-2 rounded-xl bg-primary px-4 py-2 text-white transition-colors hover:bg-primary/90"
        >
          <Plus size={18} />
          <span>New Post</span>
        </button>
      </div>

      <div className="relative max-w-md">
        <Search className="pointer-events-none absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" size={18} />
        <input
          value={query}
          onChange={(event) => setQuery(event.target.value)}
          placeholder="Search by title, category, or author"
          className="w-full rounded-2xl border border-slate-200 bg-white py-3 pl-10 pr-4 text-sm text-slate-900 outline-none transition focus:border-primary/30 focus:ring-4 focus:ring-primary/10"
        />
      </div>

      <div className="grid grid-cols-1 gap-6 xl:grid-cols-2">
        {filteredPosts.length === 0 ? (
          <div className="rounded-2xl border border-dashed border-slate-300 bg-white px-6 py-12 text-center text-slate-500 xl:col-span-2">
            No blog posts match the current search.
          </div>
        ) : filteredPosts.map((post) => (
          <div key={post.id} className="group overflow-hidden rounded-2xl border border-black/5 bg-white shadow-sm">
            <div className="relative aspect-video overflow-hidden bg-slate-100">
              {post.image ? (
                <OptimizedImage src={post.image} alt={post.title} widthHint={960} heightHint={540} className="h-full w-full object-cover transition duration-500 group-hover:scale-105" />
              ) : (
                <div className="flex h-full w-full items-center justify-center text-slate-300">
                  <ImageIcon size={48} />
                </div>
              )}
              <div className="absolute inset-0 flex items-center justify-center gap-4 bg-black/45 opacity-0 transition-opacity group-hover:opacity-100">
                <button
                  onClick={() => handleEdit(post)}
                  className="rounded-full bg-white p-3 text-slate-900 transition-transform hover:scale-110"
                >
                  <Edit2 size={20} />
                </button>
                {deleteConfirmId === post.id ? (
                  <div className="flex items-center gap-2 rounded-full bg-white px-3 py-2 text-xs font-semibold text-rose-700">
                    <span>Delete?</span>
                    <button
                      onClick={() => handleDelete(post.id)}
                      className="rounded-full bg-rose-600 px-3 py-1 text-white transition hover:bg-rose-700"
                    >
                      Confirm
                    </button>
                    <button
                      onClick={() => setDeleteConfirmId('')}
                      className="rounded-full border border-slate-200 px-3 py-1 text-slate-600 transition hover:bg-slate-50"
                    >
                      Cancel
                    </button>
                  </div>
                ) : (
                  <button
                    onClick={() => setDeleteConfirmId(post.id)}
                    className="rounded-full bg-white p-3 text-accent transition-transform hover:scale-110"
                  >
                    <Trash2 size={20} />
                  </button>
                )}
              </div>
            </div>
            <div className="space-y-4 p-6">
              <div className="flex flex-wrap items-center gap-2 text-xs font-medium text-slate-500">
                <span className="inline-flex items-center gap-1 rounded-full bg-primary/10 px-3 py-1 text-primary">
                  <Tag size={12} />
                  {post.category || 'Insights'}
                </span>
                <span>{post.created_at ? new Date(post.created_at).toLocaleDateString() : 'Draft'}</span>
              </div>
              <div>
                <h3 className="line-clamp-1 text-lg font-bold text-slate-950">{post.title}</h3>
                <p className="mt-2 line-clamp-2 text-sm text-slate-500">{post.excerpt || post.content}</p>
              </div>
              <div className="rounded-2xl border border-slate-200 bg-slate-50 p-4 text-sm text-slate-600">
                <p className="font-semibold text-slate-900">SEO title</p>
                <p className="mt-1 line-clamp-1">{post.seo_title || post.title}</p>
              </div>
              <div className="flex items-center justify-between text-xs text-slate-400">
                <span>By {post.author_name || 'Admin'}</span>
                <div className="flex items-center gap-3">
                  <Link to={`/blog/${post.slug}`} className="text-primary hover:underline">
                    Preview article
                  </Link>
                  <span>/{post.slug}</span>
                </div>
              </div>
            </div>
          </div>
        ))}
      </div>

      {showModal && (
        <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/50 p-4">
          <div className="max-h-[92vh] w-full max-w-3xl overflow-y-auto rounded-2xl bg-white p-8">
            <div className="mb-6 flex items-start justify-between gap-4">
              <div>
                <h2 className="text-xl font-bold text-slate-950">{editingPost ? 'Edit Post' : 'New Blog Post'}</h2>
                <p className="mt-1 text-sm text-slate-500">Structure the article for better discovery, sharing, and editorial quality.</p>
              </div>
              <Link to={formData.slug ? `/blog/${formData.slug}` : '/blog'} className="inline-flex items-center gap-2 rounded-xl border border-slate-200 px-3 py-2 text-sm font-medium text-slate-700 hover:bg-slate-50">
                <FileText size={16} />
                Preview
              </Link>
            </div>

            <form onSubmit={handleSubmit} className="space-y-5">
              <div className="grid gap-5 md:grid-cols-2">
                <div className="md:col-span-2">
                  <label className="mb-1 block text-sm font-medium text-slate-700">Title</label>
                  <input
                    type="text"
                    required
                    className="w-full rounded-xl border border-slate-200 px-4 py-3 text-sm"
                    value={formData.title}
                    onChange={(e) => {
                      const title = e.target.value;
                      setFormData((current) => ({
                        ...current,
                        title,
                        slug: editingPost ? current.slug : buildSlug(title),
                        seoTitle: current.seoTitle || title,
                      }));
                    }}
                  />
                </div>

                <div>
                  <label className="mb-1 block text-sm font-medium text-slate-700">Slug</label>
                  <input
                    type="text"
                    required
                    className="w-full rounded-xl border border-slate-200 bg-slate-50 px-4 py-3 text-sm"
                    value={formData.slug}
                    onChange={(e) => setFormData((current) => ({ ...current, slug: buildSlug(e.target.value) }))}
                  />
                </div>

                <div>
                  <label className="mb-1 block text-sm font-medium text-slate-700">Category</label>
                  <input
                    type="text"
                    className="w-full rounded-xl border border-slate-200 px-4 py-3 text-sm"
                    value={formData.category}
                    onChange={(e) => setFormData((current) => ({ ...current, category: e.target.value }))}
                    placeholder="Technology, Business, Lifestyle"
                  />
                </div>

                <div className="md:col-span-2">
                  <label className="mb-1 block text-sm font-medium text-slate-700">Excerpt</label>
                  <textarea
                    rows={3}
                    className="w-full rounded-xl border border-slate-200 px-4 py-3 text-sm"
                    value={formData.excerpt}
                    onChange={(e) => setFormData((current) => ({ ...current, excerpt: e.target.value }))}
                    placeholder="Short article summary for cards, previews, and featured sections"
                  />
                </div>

                <div className="md:col-span-2">
                  <label className="mb-1 block text-sm font-medium text-slate-700">Featured Image</label>
                  <input
                    type="url"
                    className="w-full rounded-xl border border-slate-200 px-4 py-3 text-sm"
                    value={formData.image}
                    onChange={(e) => setFormData((current) => ({ ...current, image: e.target.value }))}
                    placeholder="Optional: paste an existing hosted image URL"
                  />
                  <div className="mt-2">
                    <CloudinaryUpload
                      label="Upload featured image"
                      helper="Pick a file directly. We will upload it and fill the image URL automatically."
                      onUploaded={(url) => setFormData((current) => ({ ...current, image: url }))}
                    />
                  </div>
                </div>

                <div className="md:col-span-2">
                  <label className="mb-1 block text-sm font-medium text-slate-700">Content</label>
                  <textarea
                    required
                    rows={10}
                    className="w-full rounded-xl border border-slate-200 px-4 py-3 text-sm"
                    value={formData.content}
                    onChange={(e) => setFormData((current) => ({ ...current, content: e.target.value }))}
                  />
                </div>

                <div>
                  <label className="mb-1 block text-sm font-medium text-slate-700">SEO Title</label>
                  <input
                    type="text"
                    className="w-full rounded-xl border border-slate-200 px-4 py-3 text-sm"
                    value={formData.seoTitle}
                    onChange={(e) => setFormData((current) => ({ ...current, seoTitle: e.target.value }))}
                    placeholder="Meta title for search and sharing"
                  />
                </div>

                <div>
                  <label className="mb-1 block text-sm font-medium text-slate-700">SEO Description</label>
                  <textarea
                    rows={3}
                    className="w-full rounded-xl border border-slate-200 px-4 py-3 text-sm"
                    value={formData.seoDescription}
                    onChange={(e) => setFormData((current) => ({ ...current, seoDescription: e.target.value }))}
                    placeholder="Short description for search previews"
                  />
                </div>
              </div>

              <div className="rounded-2xl border border-slate-200 bg-slate-50 p-4 text-sm text-slate-600">
                <p className="font-semibold text-slate-900">Preview URL</p>
                <p className="mt-1">/blog/{formData.slug || 'your-article-slug'}</p>
              </div>

              <div className="flex gap-4 pt-2">
                <button
                  type="button"
                  onClick={() => setShowModal(false)}
                  className="flex-1 rounded-xl border border-slate-200 px-4 py-3 text-sm font-medium hover:bg-slate-50"
                >
                  Cancel
                </button>
                <button
                  type="submit"
                  disabled={saving}
                  className="flex-1 rounded-xl bg-primary px-4 py-3 text-sm font-medium text-white hover:bg-primary/90 disabled:opacity-60"
                >
                  {saving ? 'Saving...' : editingPost ? 'Update Post' : 'Publish Post'}
                </button>
              </div>
            </form>
          </div>
        </div>
      )}
    </div>
  );
};

import React, { useEffect, useMemo, useState } from 'react';
import { Plus, Trash2, Loader2, Tag, Layers, ListTree } from 'lucide-react';
import { useUser } from '../../../features/shared/state/UserContext';
import toast from '@/lib/toast';

interface Category { id: string; name: string; icon?: string }
interface Subcategory { id: string; category_id: string; name: string; icon?: string }
interface SubSub { id: string; subcategory_id: string; name: string }

export const AdminCategoriesPage = () => {
  const { token } = useUser();
  const [categories, setCategories] = useState<Category[]>([]);
  const [subcategories, setSubcategories] = useState<Subcategory[]>([]);
  const [subsubs, setSubsubs] = useState<SubSub[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState('');

  const [newCategory, setNewCategory] = useState({ name: '', icon: '' });
  const [newSub, setNewSub] = useState({ category_id: '', name: '', icon: '' });
  const [newSubSub, setNewSubSub] = useState({ subcategory_id: '', name: '' });
  const [categoryErrors, setCategoryErrors] = useState({ category: '', sub: '', subSub: '' });

  const fetchAll = async () => {
    setLoading(true);
    try {
      setError('');
      const authed = { headers: { Authorization: `Bearer ${token}` } } as RequestInit;
      const [cRes, sRes, ssRes] = await Promise.all([
        fetch('/api/admin/categories', authed),
        fetch('/api/admin/subcategories', authed),
        fetch('/api/admin/subsubcategories', authed),
      ]);
      const [categoriesData, subcategoriesData, subsubsData] = await Promise.all([
        cRes.json().catch(() => null),
        sRes.json().catch(() => null),
        ssRes.json().catch(() => null),
      ]);
      if (!cRes.ok || !sRes.ok || !ssRes.ok) {
        throw new Error(
          (categoriesData as any)?.error ||
          (subcategoriesData as any)?.error ||
          (subsubsData as any)?.error ||
          'Failed to load categories',
        );
      }
      setCategories(Array.isArray(categoriesData) ? categoriesData : []);
      setSubcategories(Array.isArray(subcategoriesData) ? subcategoriesData : []);
      setSubsubs(Array.isArray(subsubsData) ? subsubsData : []);
    } catch (err) {
      setCategories([]);
      setSubcategories([]);
      setSubsubs([]);
      setError(err instanceof Error ? err.message : 'Failed to load categories');
      toast.error(err instanceof Error ? err.message : 'Failed to load categories');
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => { if (token) fetchAll(); }, [token]);

  const handleAddCategory = async (e: React.FormEvent) => {
    e.preventDefault();
    const nextError = !newCategory.name.trim() ? 'Category name is required.' : '';
    setCategoryErrors((current) => ({ ...current, category: nextError }));
    if (nextError) return;

    const response = await fetch('/api/admin/categories', {
      method: 'POST', headers: { 'Content-Type': 'application/json', Authorization: `Bearer ${token}` },
      body: JSON.stringify({ ...newCategory, name: newCategory.name.trim() })
    });
    const data = await response.json().catch(() => ({}));
    if (!response.ok) {
      toast.error(data.error || 'Failed to add category');
      return;
    }

    toast.success('Category added');
    setNewCategory({ name: '', icon: '' });
    fetchAll();
  };

  const handleAddSub = async (e: React.FormEvent) => {
    e.preventDefault();
    const nextError = !newSub.category_id ? 'Select a parent category first.' : !newSub.name.trim() ? 'Subcategory name is required.' : '';
    setCategoryErrors((current) => ({ ...current, sub: nextError }));
    if (nextError) return;

    const response = await fetch('/api/admin/subcategories', {
      method: 'POST', headers: { 'Content-Type': 'application/json', Authorization: `Bearer ${token}` },
      body: JSON.stringify({ ...newSub, category_id: newSub.category_id, name: newSub.name.trim() })
    });
    const data = await response.json().catch(() => ({}));
    if (!response.ok) {
      toast.error(data.error || 'Failed to add subcategory');
      return;
    }

    toast.success('Subcategory added');
    setNewSub({ category_id: '', name: '', icon: '' });
    fetchAll();
  };

  const handleAddSubSub = async (e: React.FormEvent) => {
    e.preventDefault();
    const nextError = !newSubSub.subcategory_id ? 'Select a parent subcategory first.' : !newSubSub.name.trim() ? 'Sub-subcategory name is required.' : '';
    setCategoryErrors((current) => ({ ...current, subSub: nextError }));
    if (nextError) return;

    const response = await fetch('/api/admin/subsubcategories', {
      method: 'POST', headers: { 'Content-Type': 'application/json', Authorization: `Bearer ${token}` },
      body: JSON.stringify({ ...newSubSub, subcategory_id: newSubSub.subcategory_id, name: newSubSub.name.trim() })
    });
    const data = await response.json().catch(() => ({}));
    if (!response.ok) {
      toast.error(data.error || 'Failed to add sub-subcategory');
      return;
    }

    toast.success('Sub-subcategory added');
    setNewSubSub({ subcategory_id: '', name: '' });
    fetchAll();
  };

  const del = async (url: string) => {
    const response = await fetch(url, { method: 'DELETE', headers: { Authorization: `Bearer ${token}` } });
    const data = await response.json().catch(() => null);
    if (!response.ok) {
      toast.error(data?.error || 'Failed to delete item');
      return;
    }
    fetchAll();
  };

  const subsByCat = useMemo(() => {
    const map: Record<string, Subcategory[]> = {};
    subcategories.forEach(s => { (map[s.category_id] = map[s.category_id] || []).push(s); });
    return map;
  }, [subcategories]);

  const subsubsBySub = useMemo(() => {
    const map: Record<string, SubSub[]> = {};
    subsubs.forEach(s => { (map[s.subcategory_id] = map[s.subcategory_id] || []).push(s); });
    return map;
  }, [subsubs]);

  if (loading) return <div className="flex items-center justify-center h-64"><Loader2 className="animate-spin text-primary" size={32} /></div>;

  return (
    <div className="space-y-6">
      {error && (
        <div className="rounded-xl border border-amber-200 bg-amber-50 px-4 py-3 text-sm text-amber-800">
          {error}
        </div>
      )}
      <div className="flex justify-between items-center">
        <div>
          <h1 className="text-2xl font-bold">Category Management</h1>
          <p className="text-sm text-gray-500">Manage categories, subcategories, and sub-subcategories</p>
        </div>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
        <form onSubmit={handleAddCategory} className="bg-white p-6 rounded-2xl border border-black/5 shadow-sm space-y-4">
          <h3 className="font-bold flex items-center gap-2"><Tag size={16}/> Root Category</h3>
          <input className="w-full bg-bg-light border-none rounded-xl py-2 px-4 text-sm" placeholder="Name" value={newCategory.name} onChange={e=>{setNewCategory({...newCategory,name:e.target.value}); setCategoryErrors((current) => ({ ...current, category: '' }));}}/>
          {categoryErrors.category ? <p className="text-sm text-red-600">{categoryErrors.category}</p> : null}
          <input className="w-full bg-bg-light border-none rounded-xl py-2 px-4 text-sm" placeholder="Icon (optional)" value={newCategory.icon} onChange={e=>setNewCategory({...newCategory,icon:e.target.value})}/>
          <button type="submit" className="w-full btn-primary flex items-center justify-center gap-2 py-2"><Plus size={16}/>Add</button>
        </form>

        <form onSubmit={handleAddSub} className="bg-white p-6 rounded-2xl border border-black/5 shadow-sm space-y-4">
          <h3 className="font-bold flex items-center gap-2"><Layers size={16}/> Subcategory</h3>
          <select className="w-full bg-bg-light border-none rounded-xl py-2 px-4 text-sm" value={newSub.category_id} onChange={e=>setNewSub({...newSub,category_id:e.target.value})}>
            <option value="">Select parent category</option>
            {categories.map(c=> <option key={c.id} value={c.id}>{c.name}</option>)}
          </select>
          <input className="w-full bg-bg-light border-none rounded-xl py-2 px-4 text-sm" placeholder="Name" value={newSub.name} onChange={e=>{setNewSub({...newSub,name:e.target.value}); setCategoryErrors((current) => ({ ...current, sub: '' }));}}/>
          {categoryErrors.sub ? <p className="text-sm text-red-600">{categoryErrors.sub}</p> : null}
          <input className="w-full bg-bg-light border-none rounded-xl py-2 px-4 text-sm" placeholder="Icon (optional)" value={newSub.icon} onChange={e=>setNewSub({...newSub,icon:e.target.value})}/>
          <button type="submit" className="w-full btn-primary flex items-center justify-center gap-2 py-2"><Plus size={16}/>Add</button>
        </form>

        <form onSubmit={handleAddSubSub} className="bg-white p-6 rounded-2xl border border-black/5 shadow-sm space-y-4">
          <h3 className="font-bold flex items-center gap-2"><ListTree size={16}/> Sub-Subcategory</h3>
          <select className="w-full bg-bg-light border-none rounded-xl py-2 px-4 text-sm" value={newSubSub.subcategory_id} onChange={e=>setNewSubSub({...newSubSub,subcategory_id:e.target.value})}>
            <option value="">Select subcategory</option>
            {subcategories.map(s=> <option key={s.id} value={s.id}>{s.name}</option>)}
          </select>
          <input className="w-full bg-bg-light border-none rounded-xl py-2 px-4 text-sm" placeholder="Name" value={newSubSub.name} onChange={e=>{setNewSubSub({...newSubSub,name:e.target.value}); setCategoryErrors((current) => ({ ...current, subSub: '' }));}}/>
          {categoryErrors.subSub ? <p className="text-sm text-red-600">{categoryErrors.subSub}</p> : null}
          <button type="submit" className="w-full btn-primary flex items-center justify-center gap-2 py-2"><Plus size={16}/>Add</button>
        </form>
      </div>

      <div className="table-responsive overflow-hidden rounded-2xl border border-black/5 bg-white shadow-sm">
        <table className="w-full text-left">
          <thead className="bg-gray-50 text-xs font-bold text-gray-500 uppercase tracking-wider">
            <tr>
              <th className="px-6 py-3">Category</th>
              <th className="px-6 py-3">Subcategories</th>
              <th className="px-6 py-3">Sub-Subcategories</th>
              <th className="px-6 py-3 text-right">Actions</th>
            </tr>
          </thead>
          <tbody className="divide-y divide-gray-100 text-sm">
            {categories.map(cat => {
              const subs = subsByCat[cat.id] || [];
              return (
                <tr key={cat.id} className="align-top">
                  <td className="px-6 py-4 font-semibold">{cat.name}</td>
                  <td className="px-6 py-4 space-y-1">
                    {subs.length === 0 && <span className="text-gray-400 text-xs">None</span>}
                    {subs.map(sub => (
                      <div key={sub.id} className="flex items-center justify-between bg-gray-50 rounded-lg px-3 py-2">
                        <span>{sub.name}</span>
                        <div className="flex items-center gap-2">
                          <span className="text-[10px] uppercase text-gray-400">ID {sub.id}</span>
                          <button onClick={() => del(`/api/admin/subcategories/${sub.id}`)} className="p-1 text-gray-400 hover:text-accent"><Trash2 size={16}/></button>
                        </div>
                      </div>
                    ))}
                  </td>
                  <td className="px-6 py-4 space-y-1">
                    {subs.flatMap(sub => subsubsBySub[sub.id] || []).length === 0 && <span className="text-gray-400 text-xs">None</span>}
                    {subs.map(sub => (
                      <div key={sub.id} className="space-y-1">
                        {(subsubsBySub[sub.id] || []).map(ss => (
                          <div key={ss.id} className="flex items-center justify-between bg-gray-50 rounded-lg px-3 py-2">
                            <span>{ss.name}</span>
                            <div className="flex items-center gap-2">
                              <span className="text-[10px] uppercase text-gray-400">Sub {sub.id}</span>
                              <button onClick={() => del(`/api/admin/subsubcategories/${ss.id}`)} className="p-1 text-gray-400 hover:text-accent"><Trash2 size={16}/></button>
                            </div>
                          </div>
                        ))}
                      </div>
                    ))}
                  </td>
                  <td className="px-6 py-4 text-right">
                    <button onClick={() => del(`/api/admin/categories/${cat.id}`)} className="p-2 text-gray-400 hover:text-accent"><Trash2 size={18}/></button>
                  </td>
                </tr>
              );
            })}
          </tbody>
        </table>
      </div>
    </div>
  );
};

'use client';

import React, { useEffect, useMemo, useState } from 'react';
import toast from '@/lib/toast';
import { CheckCircle2, EyeOff, Loader2, MessageSquare, Search, ShieldCheck, SquarePen, XCircle } from 'lucide-react';
import { useUser } from '../../../features/shared/state/UserContext';

type AdminCommunityPost = {
  id: string;
  caption: string;
  topic: string;
  likes: number;
  comments: number;
  created_at: string;
  status: string;
  moderation_note?: string | null;
  user: {
    name: string;
    role: string;
  };
  product: {
    name: string;
    category: string;
  };
};

type AdminCommunityComment = {
  id: string;
  content: string;
  status: string;
  created_at: string;
  moderation_note?: string | null;
  post_id: string;
  post_excerpt: string;
  user: {
    name: string;
    role: string;
  };
};

type AdminCommunityReport = {
  id: string;
  post_id: string;
  reason: string;
  details?: string | null;
  status: string;
  created_at: string;
  post_excerpt: string;
  user: {
    name: string;
    role: string;
  };
};

export const AdminCommunityPage = () => {
  const { token } = useUser();
  const [loading, setLoading] = useState(true);
  const [posts, setPosts] = useState<AdminCommunityPost[]>([]);
  const [comments, setComments] = useState<AdminCommunityComment[]>([]);
  const [reports, setReports] = useState<AdminCommunityReport[]>([]);
  const [query, setQuery] = useState('');
  const [busyKey, setBusyKey] = useState<string | null>(null);
  const [focusedReportId, setFocusedReportId] = useState('');

  const loadModeration = async () => {
    if (!token) return;
    try {
      setLoading(true);
      const response = await fetch('/api/admin/community/posts', {
        headers: { Authorization: `Bearer ${token}` },
      });
      const data = await response.json();
      if (!response.ok) {
        throw new Error(data.error || 'Failed to load community moderation');
      }
      setPosts(Array.isArray(data.posts) ? data.posts : []);
      setComments(Array.isArray(data.comments) ? data.comments : []);
      setReports(Array.isArray(data.reports) ? data.reports : []);
    } catch (error: any) {
      toast.error(error?.message || 'Failed to load community moderation.');
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    void loadModeration();
  }, [token]);

  useEffect(() => {
    if (typeof window === 'undefined') return;
    const params = new URLSearchParams(window.location.search);
    const nextReport = params.get('report');
    if (nextReport) {
      setFocusedReportId(nextReport);
    }
  }, []);

  const filteredPosts = useMemo(() => {
    const term = query.trim().toLowerCase();
    if (!term) return posts;
    return posts.filter((post) =>
      `${post.user.name} ${post.user.role} ${post.caption} ${post.topic} ${post.product.name}`.toLowerCase().includes(term),
    );
  }, [posts, query]);

  const filteredComments = useMemo(() => {
    const term = query.trim().toLowerCase();
    if (!term) return comments;
    return comments.filter((comment) =>
      `${comment.user.name} ${comment.user.role} ${comment.content} ${comment.post_excerpt}`.toLowerCase().includes(term),
    );
  }, [comments, query]);

  const filteredReports = useMemo(() => {
    const term = query.trim().toLowerCase();
    if (!term) return reports;
    return reports.filter((report) =>
      `${report.user.name} ${report.user.role} ${report.reason} ${report.details ?? ''} ${report.post_excerpt}`.toLowerCase().includes(term),
    );
  }, [reports, query]);

  useEffect(() => {
    if (!focusedReportId || typeof window === 'undefined') return;
    window.requestAnimationFrame(() => {
      document.getElementById(`admin-community-report-${focusedReportId}`)?.scrollIntoView({
        behavior: 'smooth',
        block: 'center',
      });
    });
  }, [filteredReports.length, focusedReportId]);

  const moderatePost = async (postId: string, status: 'approved' | 'hidden' | 'rejected') => {
    if (!token) return;
    try {
      setBusyKey(`post-${postId}-${status}`);
      const response = await fetch(`/api/admin/community/posts/${postId}/moderate`, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          Authorization: `Bearer ${token}`,
        },
        body: JSON.stringify({ status }),
      });
      const data = await response.json();
      if (!response.ok) {
        throw new Error(data.error || 'Failed to update post');
      }
      setPosts((current) => current.map((post) => (post.id === postId ? { ...post, status } : post)));
      toast.success(`Post marked as ${status}.`);
    } catch (error: any) {
      toast.error(error?.message || 'Failed to moderate post.');
    } finally {
      setBusyKey(null);
    }
  };

  const moderateComment = async (commentId: string, status: 'visible' | 'hidden') => {
    if (!token) return;
    try {
      setBusyKey(`comment-${commentId}-${status}`);
      const response = await fetch(`/api/admin/community/comments/${commentId}/moderate`, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          Authorization: `Bearer ${token}`,
        },
        body: JSON.stringify({ status }),
      });
      const data = await response.json();
      if (!response.ok) {
        throw new Error(data.error || 'Failed to update comment');
      }
      setComments((current) => current.map((comment) => (comment.id === commentId ? { ...comment, status } : comment)));
      toast.success(`Comment marked as ${status}.`);
    } catch (error: any) {
      toast.error(error?.message || 'Failed to moderate comment.');
    } finally {
      setBusyKey(null);
    }
  };

  const reviewReport = async (reportId: string, status: 'open' | 'reviewed' | 'dismissed') => {
    if (!token) return;
    try {
      setBusyKey(`report-${reportId}-${status}`);
      const response = await fetch(`/api/admin/community/reports/${reportId}/review`, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          Authorization: `Bearer ${token}`,
        },
        body: JSON.stringify({ status }),
      });
      const data = await response.json();
      if (!response.ok) {
        throw new Error(data.error || 'Failed to update report');
      }
      setReports((current) => current.map((report) => (report.id === reportId ? { ...report, status } : report)));
      toast.success(`Report marked as ${status}.`);
    } catch (error: any) {
      toast.error(error?.message || 'Failed to review report.');
    } finally {
      setBusyKey(null);
    }
  };

  if (loading) {
    return (
      <div className="flex h-64 items-center justify-center">
        <Loader2 className="animate-spin text-primary" size={32} />
      </div>
    );
  }

  return (
    <div className="space-y-6">
      <div className="flex flex-col gap-4 rounded-[2rem] border border-slate-200 bg-white p-6 shadow-sm lg:flex-row lg:items-center lg:justify-between">
        <div>
          <p className="text-xs font-semibold uppercase tracking-[0.2em] text-primary">Community moderation</p>
          <h1 className="mt-2 text-3xl font-bold text-slate-950">Manage posts and discussions</h1>
          <p className="mt-2 text-sm leading-7 text-slate-500">
            Review community content, keep feed quality high, and hide anything that does not meet marketplace standards.
          </p>
        </div>
        <div className="relative w-full max-w-sm">
          <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" size={18} />
          <input
            value={query}
            onChange={(event) => setQuery(event.target.value)}
            placeholder="Search posts or comments"
            className="w-full rounded-2xl border border-slate-200 bg-slate-50 py-3 pl-10 pr-4 text-sm outline-none transition focus:border-primary/30 focus:bg-white focus:ring-4 focus:ring-primary/10"
          />
        </div>
      </div>

      <div className="grid gap-6 xl:grid-cols-[1.1fr_0.9fr]">
        <section className="space-y-4 rounded-[2rem] border border-slate-200 bg-white p-6 shadow-sm">
          <div className="flex items-center gap-2">
            <SquarePen className="h-5 w-5 text-primary" />
            <h2 className="text-xl font-bold text-slate-950">Posts</h2>
          </div>
          <div className="space-y-4">
            {filteredPosts.map((post) => (
              <div key={post.id} className="rounded-[1.5rem] border border-slate-200 bg-slate-50 p-4">
                <div className="flex flex-col gap-3 sm:flex-row sm:items-start sm:justify-between">
                  <div>
                    <div className="flex flex-wrap items-center gap-2">
                      <p className="font-bold text-slate-950">{post.user.name}</p>
                      <span className="dashboard-stat-chip bg-white text-slate-500 uppercase tracking-wide">
                        {post.user.role}
                      </span>
                      <span className="dashboard-stat-chip bg-emerald-50 text-emerald-700 uppercase tracking-wide">
                        {post.status}
                      </span>
                    </div>
                    <p className="mt-1 text-xs text-slate-500">{post.topic} â€¢ {post.product.name} â€¢ {new Date(post.created_at).toLocaleString()}</p>
                  </div>
                  <div className="flex flex-wrap gap-2">
                    <button
                      type="button"
                      onClick={() => void moderatePost(post.id, 'approved')}
                      disabled={busyKey === `post-${post.id}-approved`}
                      className="inline-flex items-center gap-2 rounded-xl bg-emerald-50 px-3 py-2 text-xs font-semibold text-emerald-700 transition hover:bg-emerald-100 disabled:opacity-60"
                    >
                      <CheckCircle2 size={14} />
                      Approve
                    </button>
                    <button
                      type="button"
                      onClick={() => void moderatePost(post.id, 'hidden')}
                      disabled={busyKey === `post-${post.id}-hidden`}
                      className="inline-flex items-center gap-2 rounded-xl bg-amber-50 px-3 py-2 text-xs font-semibold text-amber-700 transition hover:bg-amber-100 disabled:opacity-60"
                    >
                      <EyeOff size={14} />
                      Hide
                    </button>
                    <button
                      type="button"
                      onClick={() => void moderatePost(post.id, 'rejected')}
                      disabled={busyKey === `post-${post.id}-rejected`}
                      className="inline-flex items-center gap-2 rounded-xl bg-rose-50 px-3 py-2 text-xs font-semibold text-rose-700 transition hover:bg-rose-100 disabled:opacity-60"
                    >
                      <XCircle size={14} />
                      Reject
                    </button>
                  </div>
                </div>
                <p className="mt-4 text-sm leading-7 text-slate-700">{post.caption}</p>
                <div className="mt-4 flex flex-wrap gap-4 text-xs font-semibold text-slate-500">
                  <span>{post.likes} likes</span>
                  <span>{post.comments} comments</span>
                  <span>{post.product.category}</span>
                </div>
              </div>
            ))}
            {filteredPosts.length === 0 ? (
              <div className="rounded-[1.5rem] border border-dashed border-slate-300 px-6 py-12 text-center text-sm text-slate-500">
                No community posts matched your search.
              </div>
            ) : null}
          </div>
        </section>

        <div className="space-y-6">
          <section className="space-y-4 rounded-[2rem] border border-slate-200 bg-white p-6 shadow-sm">
            <div className="flex items-center gap-2">
              <MessageSquare className="h-5 w-5 text-primary" />
              <h2 className="text-xl font-bold text-slate-950">Comments</h2>
            </div>
            <div className="space-y-4">
              {filteredComments.map((comment) => (
                <div key={comment.id} className="rounded-[1.5rem] border border-slate-200 bg-slate-50 p-4">
                  <div className="flex flex-wrap items-center gap-2">
                    <p className="font-bold text-slate-950">{comment.user.name}</p>
                    <span className="dashboard-stat-chip bg-white text-slate-500 uppercase tracking-wide">
                      {comment.user.role}
                    </span>
                    <span className="dashboard-stat-chip bg-indigo-50 text-indigo-700 uppercase tracking-wide">
                      {comment.status}
                    </span>
                  </div>
                  <p className="mt-3 text-sm leading-7 text-slate-700">{comment.content}</p>
                  <p className="mt-3 text-xs text-slate-500">On post: {comment.post_excerpt || 'Community discussion'} </p>
                  <p className="mt-1 text-[11px] text-slate-400">{new Date(comment.created_at).toLocaleString()}</p>
                  <div className="mt-4 flex gap-2">
                    <button
                      type="button"
                      onClick={() => void moderateComment(comment.id, 'visible')}
                      disabled={busyKey === `comment-${comment.id}-visible`}
                      className="inline-flex items-center gap-2 rounded-xl bg-emerald-50 px-3 py-2 text-xs font-semibold text-emerald-700 transition hover:bg-emerald-100 disabled:opacity-60"
                    >
                      <ShieldCheck size={14} />
                      Show
                    </button>
                    <button
                      type="button"
                      onClick={() => void moderateComment(comment.id, 'hidden')}
                      disabled={busyKey === `comment-${comment.id}-hidden`}
                      className="inline-flex items-center gap-2 rounded-xl bg-amber-50 px-3 py-2 text-xs font-semibold text-amber-700 transition hover:bg-amber-100 disabled:opacity-60"
                    >
                      <EyeOff size={14} />
                      Hide
                    </button>
                  </div>
                </div>
              ))}
              {filteredComments.length === 0 ? (
                <div className="rounded-[1.5rem] border border-dashed border-slate-300 px-6 py-12 text-center text-sm text-slate-500">
                  No comments matched your search.
                </div>
              ) : null}
            </div>
          </section>

          <section className="space-y-4 rounded-[2rem] border border-slate-200 bg-white p-6 shadow-sm">
            <div className="flex items-center gap-2">
              <XCircle className="h-5 w-5 text-primary" />
              <h2 className="text-xl font-bold text-slate-950">Reports</h2>
            </div>
            <div className="space-y-4">
              {filteredReports.map((report) => (
                <div
                  id={`admin-community-report-${report.id}`}
                  key={report.id}
                  className={`rounded-[1.5rem] border border-slate-200 bg-slate-50 p-4 ${
                    report.id === focusedReportId ? 'border-indigo-300 ring-2 ring-indigo-200 bg-indigo-50/30' : ''
                  }`}
                >
                  <div className="flex flex-wrap items-center gap-2">
                    <p className="font-bold text-slate-950">{report.user.name}</p>
                    <span className="dashboard-stat-chip bg-white text-slate-500 uppercase tracking-wide">
                      {report.user.role}
                    </span>
                    <span className="dashboard-stat-chip bg-rose-50 text-rose-700 uppercase tracking-wide">
                      {report.status}
                    </span>
                  </div>
                  <p className="mt-3 text-sm font-semibold text-slate-900">Reason: {report.reason}</p>
                  {report.details ? <p className="mt-2 text-sm leading-7 text-slate-700">{report.details}</p> : null}
                  <p className="mt-3 text-xs text-slate-500">Reported post: {report.post_excerpt || 'Community discussion'}</p>
                  <p className="mt-1 text-[11px] text-slate-400">{new Date(report.created_at).toLocaleString()}</p>
                  <div className="mt-4 flex gap-2">
                    <button
                      type="button"
                      onClick={() => void reviewReport(report.id, 'reviewed')}
                      disabled={busyKey === `report-${report.id}-reviewed`}
                      className="inline-flex items-center gap-2 rounded-xl bg-emerald-50 px-3 py-2 text-xs font-semibold text-emerald-700 transition hover:bg-emerald-100 disabled:opacity-60"
                    >
                      Review
                    </button>
                    <button
                      type="button"
                      onClick={() => void reviewReport(report.id, 'dismissed')}
                      disabled={busyKey === `report-${report.id}-dismissed`}
                      className="inline-flex items-center gap-2 rounded-xl bg-slate-100 px-3 py-2 text-xs font-semibold text-slate-700 transition hover:bg-slate-200 disabled:opacity-60"
                    >
                      Dismiss
                    </button>
                  </div>
                </div>
              ))}
              {filteredReports.length === 0 ? (
                <div className="rounded-[1.5rem] border border-dashed border-slate-300 px-6 py-12 text-center text-sm text-slate-500">
                  No reports matched your search.
                </div>
              ) : null}
            </div>
          </section>
        </div>
      </div>
    </div>
  );
};

import React, { useEffect, useState } from 'react';
import { Ticket, Plus, Trash2, Loader2, Calendar } from 'lucide-react';
import { useUser } from '../../../features/shared/state/UserContext';
import { formatPrice } from '../../../lib/utils';
import toast from '@/lib/toast';
import { CenteredLoader, EmptyState, FormNotice } from '@/features/shared/ui/FeedbackState';

export const AdminCouponsPage = () => {
  const { token } = useUser();
  const [coupons, setCoupons] = useState<any[]>([]);
  const [loading, setLoading] = useState(true);
  const [showAddModal, setShowAddModal] = useState(false);
  const [error, setError] = useState('');
  const [message, setMessage] = useState('');
  const [submitting, setSubmitting] = useState(false);
  const [deleteConfirmId, setDeleteConfirmId] = useState<number | null>(null);
  const [formData, setFormData] = useState({
    code: '',
    discount_type: 'percentage',
    discount_value: 0,
    min_order_value: 0,
    expiry_date: ''
  });

  const fetchCoupons = async () => {
    setLoading(true);
    setError('');
    try {
      const response = await fetch('/api/admin/coupons', {
        headers: { 'Authorization': `Bearer ${token}` }
      });
      const data = await response.json().catch(() => null);
      if (!response.ok) {
        throw new Error(data?.error || 'Failed to load coupons');
      }
      setCoupons(data);
    } catch (err) {
      setCoupons([]);
      setError(err instanceof Error ? err.message : 'Failed to load coupons');
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    if (token) fetchCoupons();
  }, [token]);

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    try {
      setSubmitting(true);
      setError('');
      setMessage('');
      const response = await fetch('/api/admin/coupons', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'Authorization': `Bearer ${token}`
        },
        body: JSON.stringify(formData)
      });
      const data = await response.json().catch(() => null);
      if (!response.ok) {
        throw new Error(data?.error || 'Failed to create coupon');
      }
      toast.success('Coupon created successfully');
      setMessage('Coupon created successfully.');
      setShowAddModal(false);
      setFormData({
        code: '',
        discount_type: 'percentage',
        discount_value: 0,
        min_order_value: 0,
        expiry_date: ''
      });
      fetchCoupons();
    } catch (err) {
      const nextError = err instanceof Error ? err.message : 'Failed to create coupon';
      toast.error(nextError);
      setError(nextError);
    } finally {
      setSubmitting(false);
    }
  };

  const handleDelete = async (id: number) => {
    try {
      const response = await fetch(`/api/admin/coupons/${id}`, {
        method: 'DELETE',
        headers: { 'Authorization': `Bearer ${token}` }
      });
      const data = await response.json().catch(() => null);
      if (!response.ok) {
        throw new Error(data?.error || 'Failed to delete coupon');
      }
      setDeleteConfirmId(null);
      toast.success('Coupon deleted');
      fetchCoupons();
    } catch (err) {
      toast.error(err instanceof Error ? err.message : 'Failed to delete coupon');
    }
  };

  if (loading) {
    return <CenteredLoader label="Loading coupons..." className="min-h-[240px]" />;
  }

  return (
    <div className="space-y-6">
      {error ? <FormNotice tone="error">{error}</FormNotice> : null}
      {message ? <FormNotice tone="success">{message}</FormNotice> : null}
      <div className="flex justify-between items-center">
        <div>
          <h1 className="text-2xl font-bold">Coupon Management</h1>
          <p className="text-sm text-gray-500">Create and manage discount codes</p>
        </div>
        <button 
          onClick={() => setShowAddModal(true)}
          className="bg-primary text-white px-4 py-2 rounded-xl flex items-center space-x-2 hover:bg-primary/90 transition-colors"
        >
          <Plus size={20} />
          <span>Add Coupon</span>
        </button>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
        {coupons.map((coupon) => (
          <div key={coupon.id} className="bg-white p-6 rounded-2xl border border-black/5 shadow-sm relative group">
            {deleteConfirmId === coupon.id ? (
              <div className="absolute right-4 top-4 flex items-center gap-2 rounded-xl bg-white/95 px-3 py-2 text-xs font-semibold text-rose-700 shadow-sm">
                <span>Delete?</span>
                <button
                  onClick={() => handleDelete(coupon.id)}
                  className="rounded-lg bg-rose-600 px-2.5 py-1 text-white transition hover:bg-rose-700"
                >
                  Confirm
                </button>
                <button
                  onClick={() => setDeleteConfirmId(null)}
                  className="rounded-lg border border-slate-200 px-2.5 py-1 text-slate-600 transition hover:bg-slate-50"
                >
                  Cancel
                </button>
              </div>
            ) : (
              <button 
                onClick={() => setDeleteConfirmId(coupon.id)}
                className="absolute top-4 right-4 p-2 text-gray-400 hover:text-accent opacity-0 group-hover:opacity-100 transition-opacity"
              >
                <Trash2 size={18} />
              </button>
            )}
            <div className="flex items-center space-x-4 mb-4">
              <div className="p-3 bg-primary/10 rounded-xl text-primary">
                <Ticket size={24} />
              </div>
              <div>
                <h3 className="font-bold text-lg uppercase tracking-wider">{coupon.code}</h3>
                <p className="text-xs text-gray-500">
                  {coupon.discount_type === 'percentage' ? `${coupon.discount_value}% OFF` : `${formatPrice(coupon.discount_value)} OFF`}
                </p>
              </div>
            </div>
            <div className="space-y-2 text-sm text-gray-600">
              <div className="flex justify-between">
                <span>Min. Order:</span>
                <span className="font-bold">{formatPrice(coupon.min_order_value)}</span>
              </div>
              <div className="flex justify-between">
                <span>Expires:</span>
                <span className="flex items-center space-x-1">
                  <Calendar size={14} />
                  <span>{new Date(coupon.expiry_date).toLocaleDateString()}</span>
                </span>
              </div>
            </div>
          </div>
        ))}
        {coupons.length === 0 && !error ? (
          <EmptyState
            icon={<Ticket size={24} />}
            title="No coupons available yet"
            description="Create your first marketplace coupon to start running promotions and conversion campaigns."
            tone="soft"
            className="md:col-span-2 lg:col-span-3 py-12"
          />
        ) : null}
      </div>

      {showAddModal && (
        <div className="fixed inset-0 bg-black/50 flex items-center justify-center z-50 p-4">
          <div className="bg-white rounded-2xl p-8 w-full max-w-md">
            <h2 className="text-xl font-bold mb-6">Add New Coupon</h2>
            <form onSubmit={handleSubmit} className="space-y-4">
              <div>
                <label className="block text-sm font-medium text-gray-700 mb-1">Coupon Code</label>
                <input 
                  type="text" 
                  required
                  placeholder="e.g. SAVE20"
                  className="w-full border border-gray-200 rounded-xl px-4 py-2 text-sm"
                  value={formData.code}
                  onChange={(e) => setFormData({...formData, code: e.target.value.toUpperCase()})}
                />
              </div>
              <div className="grid grid-cols-2 gap-4">
                <div>
                  <label className="block text-sm font-medium text-gray-700 mb-1">Type</label>
                  <select 
                    className="w-full border border-gray-200 rounded-xl px-4 py-2 text-sm"
                    value={formData.discount_type}
                    onChange={(e) => setFormData({...formData, discount_type: e.target.value})}
                  >
                    <option value="percentage">Percentage</option>
                    <option value="fixed">Fixed Amount</option>
                  </select>
                </div>
                <div>
                  <label className="block text-sm font-medium text-gray-700 mb-1">Value</label>
                  <input 
                    type="number" 
                    required
                    min="0"
                    className="w-full border border-gray-200 rounded-xl px-4 py-2 text-sm"
                    value={formData.discount_value}
                    onChange={(e) => setFormData({...formData, discount_value: Number(e.target.value)})}
                  />
                </div>
              </div>
              <div>
                <label className="block text-sm font-medium text-gray-700 mb-1">Min. Order Value</label>
                  <input 
                    type="number" 
                    required
                    min="0"
                    className="w-full border border-gray-200 rounded-xl px-4 py-2 text-sm"
                    value={formData.min_order_value}
                    onChange={(e) => setFormData({...formData, min_order_value: Number(e.target.value)})}
                />
              </div>
              <div>
                <label className="block text-sm font-medium text-gray-700 mb-1">Expiry Date</label>
                  <input 
                    type="date" 
                    required
                    min={new Date().toISOString().split('T')[0]}
                    className="w-full border border-gray-200 rounded-xl px-4 py-2 text-sm"
                    value={formData.expiry_date}
                    onChange={(e) => setFormData({...formData, expiry_date: e.target.value})}
                />
              </div>
              <div className="flex space-x-4 pt-4">
                <button 
                  type="button"
                  onClick={() => setShowAddModal(false)}
                  disabled={submitting}
                  className="flex-1 px-4 py-2 border border-gray-200 rounded-xl text-sm font-medium hover:bg-gray-50 disabled:cursor-not-allowed disabled:opacity-60"
                >
                  Cancel
                </button>
                <button 
                  type="submit"
                  disabled={submitting}
                  className="flex-1 px-4 py-2 bg-primary text-white rounded-xl text-sm font-medium hover:bg-primary/90 disabled:cursor-not-allowed disabled:opacity-60"
                >
                  <span className="inline-flex items-center justify-center gap-2">
                    {submitting ? <Loader2 size={16} className="animate-spin" /> : null}
                    {submitting ? 'Creating...' : 'Create Coupon'}
                  </span>
                </button>
              </div>
            </form>
          </div>
        </div>
      )}
    </div>
  );
};

import React, { useEffect, useMemo, useState } from 'react';
import { CheckCircle2, Loader2, Plus, XCircle, Zap } from 'lucide-react';
import toast from '@/lib/toast';
import { useUser } from '../../../features/shared/state/UserContext';
import { formatPrice } from '../../../lib/utils';

type FlashSaleEntry = {
  id: string;
  seller_name?: string | null;
  sale_price: number;
  allocated_stock: number;
  status: string;
  note?: string | null;
  rejection_reason?: string | null;
  product?: {
    id: string;
    name: string;
    price: number;
    seller_name?: string;
  } | null;
};

type FlashSaleCampaign = {
  id: string;
  title: string;
  description?: string;
  banner_image?: string;
  starts_at: string;
  ends_at: string;
  status: string;
  entries?: FlashSaleEntry[];
};

const initialForm = {
  title: '',
  description: '',
  bannerImage: '',
  startsAt: '',
  endsAt: '',
  status: 'draft',
};

export const AdminFlashSalePage = () => {
  const { token } = useUser();
  const [campaigns, setCampaigns] = useState<FlashSaleCampaign[]>([]);
  const [form, setForm] = useState(initialForm);
  const [loading, setLoading] = useState(true);
  const [saving, setSaving] = useState(false);
  const [error, setError] = useState('');
  const [focusedEntryId, setFocusedEntryId] = useState('');

  const loadCampaigns = async () => {
    if (!token) {
      setError('Please log in as an admin to manage flash sale campaigns.');
      setLoading(false);
      return;
    }

    try {
      setLoading(true);
      setError('');
      const response = await fetch('/api/admin/flash-sale', {
        headers: { Authorization: `Bearer ${token}` },
      });
      const payload = await response.json().catch(() => null);
      if (!response.ok) {
        throw new Error(payload?.error || 'Failed to load flash sale campaigns');
      }
      setCampaigns(Array.isArray(payload) ? payload : []);
    } catch (requestError) {
      setCampaigns([]);
      setError(requestError instanceof Error ? requestError.message : 'Failed to load flash sale campaigns');
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    void loadCampaigns();
  }, [token]);

  useEffect(() => {
    if (typeof window === 'undefined') return;
    const params = new URLSearchParams(window.location.search);
    const nextEntry = params.get('entry');
    if (nextEntry) {
      setFocusedEntryId(nextEntry);
    }
  }, []);

  const activeCampaigns = useMemo(
    () => campaigns.filter((campaign) => ['live', 'published', 'scheduled', 'draft'].includes(campaign.status)),
    [campaigns],
  );

  useEffect(() => {
    if (!focusedEntryId || typeof window === 'undefined') return;
    window.requestAnimationFrame(() => {
      document.getElementById(`admin-flash-entry-${focusedEntryId}`)?.scrollIntoView({
        behavior: 'smooth',
        block: 'center',
      });
    });
  }, [campaigns, focusedEntryId]);

  const handleCreate = async (event: React.FormEvent) => {
    event.preventDefault();
    if (!token) return;

    try {
      setSaving(true);
      const response = await fetch('/api/admin/flash-sale', {
        method: 'POST',
        headers: {
          Authorization: `Bearer ${token}`,
          'Content-Type': 'application/json',
        },
        body: JSON.stringify(form),
      });
      const payload = await response.json().catch(() => null);
      if (!response.ok) {
        throw new Error(payload?.error || 'Failed to create flash sale campaign');
      }

      toast.success('Flash sale campaign created.');
      setForm(initialForm);
      await loadCampaigns();
    } catch (requestError) {
      toast.error(requestError instanceof Error ? requestError.message : 'Failed to create flash sale campaign');
    } finally {
      setSaving(false);
    }
  };

  const handleReview = async (entryId: string, status: 'approved' | 'rejected') => {
    if (!token) return;

    try {
      const response = await fetch(`/api/admin/flash-sale/entries/${entryId}/review`, {
        method: 'PATCH',
        headers: {
          Authorization: `Bearer ${token}`,
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({
          status,
          rejectionReason: status === 'rejected' ? 'Please adjust pricing or stock allocation and submit again.' : '',
        }),
      });
      const payload = await response.json().catch(() => null);
      if (!response.ok) {
        throw new Error(payload?.error || 'Failed to review flash sale entry');
      }

      toast.success(`Entry ${status}.`);
      await loadCampaigns();
    } catch (requestError) {
      toast.error(requestError instanceof Error ? requestError.message : 'Failed to review flash sale entry');
    }
  };

  if (loading) {
    return (
      <div className="flex min-h-[320px] items-center justify-center">
        <Loader2 className="animate-spin text-primary" size={32} />
      </div>
    );
  }

  return (
    <div className="space-y-6">
      <div className="rounded-[32px] border border-black/5 bg-white p-8 shadow-sm">
        <div className="space-y-2">
          <div className="inline-flex items-center gap-2 rounded-full bg-primary/10 px-3 py-1 text-xs font-bold uppercase tracking-[0.2em] text-primary">
            <Zap size={14} />
            Flash Sale Control
          </div>
          <h1 className="text-3xl font-bold tracking-tight">Marketplace flash sale campaigns</h1>
          <p className="max-w-3xl text-sm text-slate-600">
            Admin owns the campaign, sellers submit products for approval, and resellers promote the published event.
          </p>
        </div>
      </div>

      {error ? <div className="rounded-2xl border border-amber-200 bg-amber-50 px-4 py-3 text-sm text-amber-800">{error}</div> : null}

      <div className="grid gap-6 xl:grid-cols-[0.95fr_1.05fr]">
        <section className="rounded-[32px] border border-black/5 bg-white p-8 shadow-sm">
          <div className="mb-6">
            <h2 className="text-xl font-bold">Create campaign</h2>
            <p className="text-sm text-slate-500">Set the schedule and publish state before seller approvals start.</p>
          </div>

          <form onSubmit={handleCreate} className="space-y-4">
            <label className="space-y-2 text-sm">
              <span className="font-medium text-slate-700">Title</span>
              <input
                value={form.title}
                onChange={(event) => setForm((current) => ({ ...current, title: event.target.value }))}
                className="w-full rounded-2xl border border-slate-200 px-4 py-3 text-sm"
                required
              />
            </label>

            <label className="space-y-2 text-sm">
              <span className="font-medium text-slate-700">Description</span>
              <textarea
                value={form.description}
                onChange={(event) => setForm((current) => ({ ...current, description: event.target.value }))}
                rows={4}
                className="w-full rounded-2xl border border-slate-200 px-4 py-3 text-sm"
              />
            </label>

            <label className="space-y-2 text-sm">
              <span className="font-medium text-slate-700">Banner image URL</span>
              <input
                value={form.bannerImage}
                onChange={(event) => setForm((current) => ({ ...current, bannerImage: event.target.value }))}
                className="w-full rounded-2xl border border-slate-200 px-4 py-3 text-sm"
              />
            </label>

            <div className="grid gap-4 md:grid-cols-2">
              <label className="space-y-2 text-sm">
                <span className="font-medium text-slate-700">Starts at</span>
                <input
                  type="datetime-local"
                  value={form.startsAt}
                  onChange={(event) => setForm((current) => ({ ...current, startsAt: event.target.value }))}
                  className="w-full rounded-2xl border border-slate-200 px-4 py-3 text-sm"
                  required
                />
              </label>

              <label className="space-y-2 text-sm">
                <span className="font-medium text-slate-700">Ends at</span>
                <input
                  type="datetime-local"
                  value={form.endsAt}
                  onChange={(event) => setForm((current) => ({ ...current, endsAt: event.target.value }))}
                  className="w-full rounded-2xl border border-slate-200 px-4 py-3 text-sm"
                  required
                />
              </label>
            </div>

            <label className="space-y-2 text-sm">
              <span className="font-medium text-slate-700">Status</span>
              <select
                value={form.status}
                onChange={(event) => setForm((current) => ({ ...current, status: event.target.value }))}
                className="w-full rounded-2xl border border-slate-200 px-4 py-3 text-sm"
              >
                <option value="draft">Draft</option>
                <option value="scheduled">Scheduled</option>
                <option value="published">Published</option>
                <option value="live">Live</option>
                <option value="ended">Ended</option>
              </select>
            </label>

            <button
              type="submit"
              disabled={saving}
              className="inline-flex items-center gap-2 rounded-2xl bg-primary px-5 py-3 text-sm font-bold text-white transition hover:bg-primary/90 disabled:opacity-50"
            >
              {saving ? <Loader2 className="animate-spin" size={18} /> : <Plus size={18} />}
              <span>{saving ? 'Creating...' : 'Create campaign'}</span>
            </button>
          </form>
        </section>

        <section className="rounded-[32px] border border-black/5 bg-white p-8 shadow-sm">
          <div className="mb-6">
            <h2 className="text-xl font-bold">Campaigns and seller entries</h2>
            <p className="text-sm text-slate-500">Approve seller products before they appear on the public flash sale page.</p>
          </div>

          <div className="space-y-6">
            {activeCampaigns.length === 0 ? (
              <div className="rounded-2xl border border-dashed border-slate-200 bg-slate-50 px-4 py-10 text-center text-sm text-slate-500">
                No flash sale campaigns yet.
              </div>
            ) : (
              activeCampaigns.map((campaign) => (
                <div key={campaign.id} className="rounded-3xl border border-slate-100 bg-slate-50 p-5">
                  <div className="flex flex-col gap-3 md:flex-row md:items-start md:justify-between">
                    <div>
                      <h3 className="text-lg font-bold text-slate-900">{campaign.title}</h3>
                      <p className="mt-1 text-sm text-slate-500">
                        {new Date(campaign.starts_at).toLocaleString()} to {new Date(campaign.ends_at).toLocaleString()}
                      </p>
                    </div>
                    <span className="rounded-full bg-white px-3 py-1 text-xs font-bold uppercase tracking-[0.16em] text-slate-700">
                      {campaign.status}
                    </span>
                  </div>

                  <div className="mt-4 space-y-4">
                    {(campaign.entries || []).length === 0 ? (
                      <div className="rounded-2xl border border-dashed border-slate-200 bg-white px-4 py-6 text-center text-sm text-slate-500">
                        No seller entries submitted yet.
                      </div>
                    ) : (
                      (campaign.entries || []).map((entry) => (
                        <div
                          id={`admin-flash-entry-${entry.id}`}
                          key={entry.id}
                          className={`rounded-2xl border border-slate-200 bg-white p-4 ${
                            entry.id === focusedEntryId ? 'border-indigo-300 ring-2 ring-indigo-200 bg-indigo-50/30' : ''
                          }`}
                        >
                          <div className="flex flex-col gap-3 lg:flex-row lg:items-start lg:justify-between">
                            <div className="space-y-1">
                              <h4 className="font-semibold text-slate-900">{entry.product?.name || 'Product entry'}</h4>
                              <p className="text-sm text-slate-500">
                                Seller {entry.seller_name || entry.product?.seller_name || 'Unknown'} â€¢ Base {formatPrice(entry.product?.price || 0)} â€¢ Sale {formatPrice(entry.sale_price)}
                              </p>
                              <p className="text-sm text-slate-500">Allocated stock {entry.allocated_stock}</p>
                              {entry.note ? <p className="text-sm text-slate-600">{entry.note}</p> : null}
                              {entry.rejection_reason ? (
                                <div className="rounded-xl border border-rose-200 bg-rose-50 px-3 py-2 text-sm text-rose-700">
                                  {entry.rejection_reason}
                                </div>
                              ) : null}
                            </div>

                            <div className="flex flex-wrap items-center gap-2">
                              <span className="rounded-full bg-slate-100 px-3 py-1 text-xs font-bold uppercase tracking-[0.16em] text-slate-700">
                                {entry.status}
                              </span>
                              <button
                                onClick={() => void handleReview(entry.id, 'approved')}
                                className="inline-flex items-center gap-2 rounded-xl bg-emerald-600 px-3 py-2 text-xs font-bold text-white hover:bg-emerald-700"
                              >
                                <CheckCircle2 size={14} />
                                <span>Approve</span>
                              </button>
                              <button
                                onClick={() => void handleReview(entry.id, 'rejected')}
                                className="inline-flex items-center gap-2 rounded-xl bg-rose-600 px-3 py-2 text-xs font-bold text-white hover:bg-rose-700"
                              >
                                <XCircle size={14} />
                                <span>Reject</span>
                              </button>
                            </div>
                          </div>
                        </div>
                      ))
                    )}
                  </div>
                </div>
              ))
            )}
          </div>
        </section>
      </div>
    </div>
  );
};

import React, { useMemo, useEffect, useRef, useState } from 'react';
import { AlertTriangle, CheckCircle2, Download, Loader2, MapPinned, RefreshCw, Search, Truck } from 'lucide-react';
import { useUser } from '../../../features/shared/state/UserContext';

type Provider = {
  code: string;
  name: string;
  mode: 'manual' | 'api';
  setupStatus?: 'manual_ready' | 'api_ready' | 'missing_config';
  setupMessage?: string;
  supportsTrackingSync?: boolean;
};

type DiagnosticsPayload = {
  updatedAt: string;
  steadfastHealth?: {
    apiConfigured: boolean;
    webhookConfigured: boolean;
    baseUrl: string | null;
  };
  pathaoHealth?: {
    baseUrl: string | null;
    hasCachedToken: boolean;
    tokenType: string | null;
    issuedAt: string | null;
    expiresAt: string | null;
    expiresInSeconds: number | null;
    refreshTokenAvailable: boolean;
    linkedStoreCount: number;
    webhookConfigured: boolean;
  };
  pathaoReadiness?: {
    envChecks: Array<{
      key: string;
      label: string;
      ready: boolean;
    }>;
    envReady: boolean;
    warehouseBlockers: Array<{
      id: string;
      name: string;
      blockers: string[];
    }>;
    bookingCandidates: Array<{
      id: string;
      order_id: string;
      warehouse_name: string | null;
      courier_provider: string | null;
      tracking_id: string | null;
      status: string;
      blockers: string[];
    }>;
  };
  providers: Provider[];
  warehouseSummary: {
    total: number;
    areaMapped: number;
    storeLinked: number;
    shippingRulesReady: number;
    needsAttention: number;
  };
  shipmentSummary: {
    active: number;
    exceptions: number;
    pathaoSyncAttention: number;
    redxSyncAttention: number;
    steadfastSyncAttention: number;
  };
  warehouseHealth: Array<{
    id: string;
    name: string;
    city: string;
    pathao_store_id: number | null;
    mapping_ready: boolean;
    store_linked: boolean;
    shipping_rules_ready: boolean;
    inside_dhaka_fee: number | null;
    outside_dhaka_fee: number | null;
    inside_dhaka_eta: string | null;
    outside_dhaka_eta: string | null;
  }>;
  recentExceptions: Array<{
    id: string;
    order_id: string;
    customer_name: string | null;
    warehouse_name: string | null;
    warehouse_city: string | null;
    status: string;
    courier_provider: string | null;
    tracking_id: string | null;
    delivery_failure_reason: string | null;
    updated_at: string | null;
  }>;
  pathaoWatchlist: Array<{
    id: string;
    order_id: string;
    customer_name: string | null;
    warehouse_name: string | null;
    status: string;
    tracking_id: string | null;
    booking_reference: string | null;
    pathao_last_event: string | null;
    pathao_last_status_slug: string | null;
    pathao_last_sync_at: string | null;
    sync_age_hours: number | null;
  }>;
  redxWatchlist: Array<{
    id: string;
    order_id: string;
    customer_name: string | null;
    warehouse_name: string | null;
    status: string;
    tracking_id: string | null;
    booking_reference: string | null;
    redx_last_sync_at: string | null;
    sync_age_hours: number | null;
  }>;
};

type PathaoStoreRow = {
  store_id?: number;
  store_name?: string;
  store_address?: string;
  city_id?: number;
  zone_id?: number;
  is_active?: number;
  is_default_store?: boolean | number;
};

function asArray<T>(value: T[] | null | undefined): T[] {
  return Array.isArray(value) ? value : [];
}

function normalizeDiagnosticsPayload(payload: Partial<DiagnosticsPayload> | null): DiagnosticsPayload {
  const pathaoReadiness = payload?.pathaoReadiness;

  return {
    updatedAt: typeof payload?.updatedAt === 'string' ? payload.updatedAt : new Date().toISOString(),
    steadfastHealth: payload?.steadfastHealth,
    pathaoHealth: payload?.pathaoHealth,
    pathaoReadiness: pathaoReadiness
      ? {
          envChecks: asArray(pathaoReadiness.envChecks),
          envReady: Boolean(pathaoReadiness.envReady),
          warehouseBlockers: asArray(pathaoReadiness.warehouseBlockers),
          bookingCandidates: asArray(pathaoReadiness.bookingCandidates),
        }
      : {
          envChecks: [],
          envReady: false,
          warehouseBlockers: [],
          bookingCandidates: [],
        },
    providers: asArray(payload?.providers),
    warehouseSummary: {
      total: Number(payload?.warehouseSummary?.total || 0),
      areaMapped: Number(payload?.warehouseSummary?.areaMapped || 0),
      storeLinked: Number(payload?.warehouseSummary?.storeLinked || 0),
      shippingRulesReady: Number(payload?.warehouseSummary?.shippingRulesReady || 0),
      needsAttention: Number(payload?.warehouseSummary?.needsAttention || 0),
    },
    shipmentSummary: {
      active: Number(payload?.shipmentSummary?.active || 0),
      exceptions: Number(payload?.shipmentSummary?.exceptions || 0),
      pathaoSyncAttention: Number(payload?.shipmentSummary?.pathaoSyncAttention || 0),
      redxSyncAttention: Number(payload?.shipmentSummary?.redxSyncAttention || 0),
      steadfastSyncAttention: Number(payload?.shipmentSummary?.steadfastSyncAttention || 0),
    },
    warehouseHealth: asArray(payload?.warehouseHealth),
    recentExceptions: asArray(payload?.recentExceptions),
    pathaoWatchlist: asArray(payload?.pathaoWatchlist),
    redxWatchlist: asArray(payload?.redxWatchlist),
  };
}

export const AdminLogisticsPage = () => {
  const { token } = useUser();
  const [data, setData] = useState<DiagnosticsPayload | null>(null);
  const [loading, setLoading] = useState(true);
  const [refreshing, setRefreshing] = useState(false);
  const [error, setError] = useState('');
  const [searchTerm, setSearchTerm] = useState('');
  const [providerFilter, setProviderFilter] = useState('all');
  const [dateFrom, setDateFrom] = useState('');
  const [dateTo, setDateTo] = useState('');
  const [pathaoActionLoading, setPathaoActionLoading] = useState<string | null>(null);
  const [pathaoStores, setPathaoStores] = useState<PathaoStoreRow[]>([]);
  const [pathaoStoresLoaded, setPathaoStoresLoaded] = useState(false);
  const [pathaoResult, setPathaoResult] = useState('');
  const [pathaoPriceForm, setPathaoPriceForm] = useState({
    store_id: '',
    recipient_city: '',
    recipient_zone: '',
    item_weight: '0.5',
    delivery_type: '48',
    item_type: '2',
  });
  const [pathaoOrderForm, setPathaoOrderForm] = useState({
    store_id: '',
    merchant_order_id: '',
    recipient_name: '',
    recipient_phone: '',
    recipient_address: '',
    recipient_city: '',
    recipient_zone: '',
    recipient_area: '',
    delivery_type: '48',
    item_type: '2',
    item_quantity: '1',
    item_weight: '0.5',
    item_description: '',
    amount_to_collect: '0',
    special_instruction: '',
  });
  const [showDeferredOpsPanels, setShowDeferredOpsPanels] = useState(false);
  const deferredOpsRef = useRef<HTMLDivElement | null>(null);
  const [exceptionRenderCount, setExceptionRenderCount] = useState(16);
  const [pathaoWatchRenderCount, setPathaoWatchRenderCount] = useState(12);
  const [redxWatchRenderCount, setRedxWatchRenderCount] = useState(12);

  const runPathaoAction = async (key: string, handler: () => Promise<void>) => {
    try {
      setPathaoActionLoading(key);
      setPathaoResult('');
      await handler();
    } catch (actionError) {
      setPathaoResult(actionError instanceof Error ? actionError.message : 'Pathao action failed');
    } finally {
      setPathaoActionLoading(null);
    }
  };

  const loadDiagnostics = async (silent = false) => {
    if (!token) {
      setLoading(false);
      setError('Please log in as an admin to view logistics diagnostics.');
      setData(null);
      return;
    }

    try {
      if (silent) {
        setRefreshing(true);
      } else {
        setLoading(true);
      }
      setError('');
      const response = await fetch('/api/admin/logistics/diagnostics', {
        headers: { Authorization: `Bearer ${token}` },
      });
      const payload = await response.json().catch(() => null);
      if (!response.ok) {
        throw new Error(payload?.error || 'Failed to load logistics diagnostics');
      }
      setData(normalizeDiagnosticsPayload(payload));
    } catch (requestError) {
      setData(null);
      setError(requestError instanceof Error ? requestError.message : 'Failed to load logistics diagnostics');
    } finally {
      setLoading(false);
      setRefreshing(false);
    }
  };

  useEffect(() => {
    void loadDiagnostics();
  }, [token]);

  useEffect(() => {
    if (showDeferredOpsPanels) return;

    const target = deferredOpsRef.current;
    if (!target || typeof IntersectionObserver === 'undefined') {
      const timeoutId = window.setTimeout(() => setShowDeferredOpsPanels(true), 250);
      return () => window.clearTimeout(timeoutId);
    }

    const observer = new IntersectionObserver(
      (entries) => {
        if (entries.some((entry) => entry.isIntersecting)) {
          setShowDeferredOpsPanels(true);
          observer.disconnect();
        }
      },
      { rootMargin: '520px 0px' },
    );

    observer.observe(target);
    return () => observer.disconnect();
  }, [showDeferredOpsPanels]);

  const providerOptions = useMemo(() => {
    const values = new Set<string>();

    asArray(data?.recentExceptions).forEach((shipment) => {
      if (shipment.courier_provider) {
        values.add(shipment.courier_provider);
      }
    });
    asArray(data?.pathaoWatchlist).forEach(() => values.add('Pathao'));
    asArray(data?.redxWatchlist).forEach(() => values.add('RedX'));

    return Array.from(values).sort((left, right) => left.localeCompare(right));
  }, [data]);

  const matchesDateRange = (value?: string | null) => {
    if (!value) {
      return !dateFrom && !dateTo;
    }

    const date = new Date(value);
    const startDate = dateFrom ? new Date(`${dateFrom}T00:00:00`) : null;
    const endDate = dateTo ? new Date(`${dateTo}T23:59:59.999`) : null;
    if (startDate && date < startDate) {
      return false;
    }
    if (endDate && date > endDate) {
      return false;
    }
    return true;
  };

  const filteredExceptions = useMemo(() => {
    const needle = searchTerm.trim().toLowerCase();
    return asArray(data?.recentExceptions).filter((shipment) => {
      const providerName = shipment.courier_provider || 'Unassigned';
      const matchesProvider =
        providerFilter === 'all' || providerName.toLowerCase() === providerFilter.toLowerCase();

      return (
        matchesProvider &&
        matchesDateRange(shipment.updated_at) &&
        (
          !needle ||
          shipment.id.toLowerCase().includes(needle) ||
          shipment.order_id.toLowerCase().includes(needle) ||
          String(shipment.customer_name || '').toLowerCase().includes(needle) ||
          String(shipment.warehouse_name || '').toLowerCase().includes(needle) ||
          String(shipment.courier_provider || '').toLowerCase().includes(needle) ||
          String(shipment.tracking_id || '').toLowerCase().includes(needle) ||
          shipment.status.toLowerCase().includes(needle)
        )
      );
    });
  }, [data, searchTerm, providerFilter, dateFrom, dateTo]);

  const filteredPathaoWatchlist = useMemo(() => {
    const needle = searchTerm.trim().toLowerCase();
    if (providerFilter !== 'all' && providerFilter.toLowerCase() !== 'pathao') {
      return [];
    }
    return asArray(data?.pathaoWatchlist).filter((shipment) => {
      return (
        matchesDateRange(shipment.pathao_last_sync_at) &&
        (
          !needle ||
          shipment.id.toLowerCase().includes(needle) ||
          shipment.order_id.toLowerCase().includes(needle) ||
          String(shipment.customer_name || '').toLowerCase().includes(needle) ||
          String(shipment.warehouse_name || '').toLowerCase().includes(needle) ||
          String(shipment.tracking_id || '').toLowerCase().includes(needle) ||
          shipment.status.toLowerCase().includes(needle)
        )
      );
    });
  }, [data, searchTerm, providerFilter, dateFrom, dateTo]);

  const filteredRedxWatchlist = useMemo(() => {
    const needle = searchTerm.trim().toLowerCase();
    if (providerFilter !== 'all' && providerFilter.toLowerCase() !== 'redx') {
      return [];
    }
    return asArray(data?.redxWatchlist).filter((shipment) => {
      return (
        matchesDateRange(shipment.redx_last_sync_at) &&
        (
          !needle ||
          shipment.id.toLowerCase().includes(needle) ||
          shipment.order_id.toLowerCase().includes(needle) ||
          String(shipment.customer_name || '').toLowerCase().includes(needle) ||
          String(shipment.warehouse_name || '').toLowerCase().includes(needle) ||
          String(shipment.tracking_id || '').toLowerCase().includes(needle) ||
          shipment.status.toLowerCase().includes(needle)
        )
      );
    });
  }, [data, searchTerm, providerFilter, dateFrom, dateTo]);
  const renderedExceptions = useMemo(
    () => filteredExceptions.slice(0, exceptionRenderCount),
    [exceptionRenderCount, filteredExceptions],
  );
  const renderedPathaoWatchlist = useMemo(
    () => filteredPathaoWatchlist.slice(0, pathaoWatchRenderCount),
    [filteredPathaoWatchlist, pathaoWatchRenderCount],
  );
  const renderedRedxWatchlist = useMemo(
    () => filteredRedxWatchlist.slice(0, redxWatchRenderCount),
    [filteredRedxWatchlist, redxWatchRenderCount],
  );

  useEffect(() => {
    setExceptionRenderCount(16);
    setPathaoWatchRenderCount(12);
    setRedxWatchRenderCount(12);
  }, [searchTerm, providerFilter, dateFrom, dateTo]);

  const steadfastProvider = useMemo(
    () => data?.providers.find((provider) => provider.code === 'steadfast') || null,
    [data],
  );

  const steadfastExceptionCount = useMemo(
    () =>
      asArray(data?.recentExceptions).filter((shipment) =>
        String(shipment.courier_provider || '').toLowerCase().includes('steadfast'),
      ).length,
    [data],
  );

  const handleExport = () => {
    const rows = [
      ...filteredExceptions.map((shipment) => ({
        source: 'exception',
        shipment_id: shipment.id,
        order_id: shipment.order_id,
        courier_provider: shipment.courier_provider || '',
        tracking_id: shipment.tracking_id || '',
        warehouse_name: shipment.warehouse_name || '',
        customer_name: shipment.customer_name || '',
        status: shipment.status,
        note: shipment.delivery_failure_reason || '',
        reference_time: shipment.updated_at || '',
      })),
      ...filteredPathaoWatchlist.map((shipment) => ({
        source: 'pathao_watchlist',
        shipment_id: shipment.id,
        order_id: shipment.order_id,
        courier_provider: 'Pathao',
        tracking_id: shipment.tracking_id || '',
        warehouse_name: shipment.warehouse_name || '',
        customer_name: shipment.customer_name || '',
        status: shipment.status,
        note: shipment.booking_reference || '',
        reference_time: shipment.pathao_last_sync_at || '',
      })),
      ...filteredRedxWatchlist.map((shipment) => ({
        source: 'redx_watchlist',
        shipment_id: shipment.id,
        order_id: shipment.order_id,
        courier_provider: 'RedX',
        tracking_id: shipment.tracking_id || '',
        warehouse_name: shipment.warehouse_name || '',
        customer_name: shipment.customer_name || '',
        status: shipment.status,
        note: shipment.booking_reference || '',
        reference_time: shipment.redx_last_sync_at || '',
      })),
    ];

    if (!rows.length) {
      setError('No logistics records matched the current filters to export.');
      return;
    }

    const headers = Object.keys(rows[0]);
    const csv = [
      headers.join(','),
      ...rows.map((row) =>
        headers
          .map((header) => `"${String(row[header as keyof (typeof rows)[number]] ?? '').replaceAll('"', '""')}"`)
          .join(','),
      ),
    ].join('\n');

    const blob = new Blob([csv], { type: 'text/csv;charset=utf-8;' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    const stamp = new Date().toISOString().slice(0, 10);
    link.href = url;
    link.download = `admin-logistics-${stamp}.csv`;
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
    URL.revokeObjectURL(url);
  };

  const loadPathaoStores = async () => {
    if (!token) return;
    const response = await fetch('/api/logistics/pathao/stores', {
      headers: { Authorization: `Bearer ${token}` },
    });
    const payload = await response.json().catch(() => null);
    if (!response.ok) {
      throw new Error(payload?.error || 'Failed to load Pathao stores');
    }
    const rows = Array.isArray(payload?.data?.data) ? payload.data.data : [];
    setPathaoStores(rows);
    setPathaoStoresLoaded(true);
    setPathaoResult(`Loaded ${rows.length} Pathao store${rows.length === 1 ? '' : 's'}.`);
  };

  if (loading) {
    return (
      <div className="flex h-64 items-center justify-center">
        <Loader2 className="animate-spin text-primary" size={32} />
      </div>
    );
  }

  return (
    <div className="space-y-8">
      {error ? (
        <div className="rounded-xl border border-red-200 bg-red-50 p-4 text-sm text-red-700">
          {error}
        </div>
      ) : null}

      <div className="flex flex-col gap-4 md:flex-row md:items-end md:justify-between">
        <div>
          <p className="text-xs font-bold uppercase tracking-[0.24em] text-primary/70">Courier diagnostics</p>
          <h1 className="mt-2 text-3xl font-bold text-slate-950">Logistics readiness and shipment health</h1>
          <p className="mt-2 max-w-3xl text-sm leading-7 text-slate-500">
            Check provider setup, warehouse mapping coverage, delivery exceptions, and shipments that need sync attention before they become support issues.
          </p>
        </div>
        <button
          onClick={() => void loadDiagnostics(true)}
          className="inline-flex items-center justify-center gap-2 rounded-2xl border border-slate-200 bg-white px-4 py-3 text-sm font-semibold text-slate-700 transition hover:bg-slate-50"
        >
          {refreshing ? <Loader2 size={18} className="animate-spin" /> : <RefreshCw size={18} />}
          <span>Refresh diagnostics</span>
        </button>
      </div>

      <div className="flex flex-col gap-3 rounded-2xl border border-slate-200 bg-white p-4 shadow-sm md:flex-row md:flex-wrap md:items-center">
        <div className="relative min-w-[220px] flex-1">
          <Search className="pointer-events-none absolute left-3 top-1/2 h-4 w-4 -translate-y-1/2 text-slate-400" />
          <input
            type="text"
            value={searchTerm}
            onChange={(event) => setSearchTerm(event.target.value)}
            placeholder="Search shipment, tracking, warehouse..."
            className="w-full rounded-xl border border-slate-200 bg-white py-3 pl-9 pr-4 text-sm outline-none focus:ring-2 focus:ring-indigo-500/20 md:py-2"
          />
        </div>
        <select
          value={providerFilter}
          onChange={(event) => setProviderFilter(event.target.value)}
          className="w-full rounded-xl border border-slate-200 bg-white px-3 py-3 text-sm font-medium text-slate-600 outline-none focus:ring-2 focus:ring-indigo-500/20 md:w-auto md:py-2"
        >
          <option value="all">All providers</option>
          <option value="unassigned">Unassigned</option>
          {providerOptions.map((provider) => (
            <option key={provider} value={provider}>
              {provider}
            </option>
          ))}
        </select>
        <input
          type="date"
          value={dateFrom}
          onChange={(event) => setDateFrom(event.target.value)}
          className="w-full rounded-xl border border-slate-200 bg-white px-3 py-3 text-sm font-medium text-slate-600 outline-none focus:ring-2 focus:ring-indigo-500/20 md:w-auto md:py-2"
          aria-label="Logistics records from date"
        />
        <input
          type="date"
          value={dateTo}
          onChange={(event) => setDateTo(event.target.value)}
          className="w-full rounded-xl border border-slate-200 bg-white px-3 py-3 text-sm font-medium text-slate-600 outline-none focus:ring-2 focus:ring-indigo-500/20 md:w-auto md:py-2"
          aria-label="Logistics records to date"
        />
        <button
          onClick={() => {
            setSearchTerm('');
            setProviderFilter('all');
            setDateFrom('');
            setDateTo('');
          }}
          className="rounded-xl border border-slate-200 bg-white px-3 py-3 text-sm font-semibold text-slate-600 transition hover:bg-slate-50 md:py-2"
        >
          Clear
        </button>
        <button
          onClick={handleExport}
          className="inline-flex items-center justify-center gap-2 rounded-xl border border-slate-200 bg-white px-3 py-3 text-sm font-semibold text-slate-700 transition hover:bg-slate-50 md:py-2"
        >
          <Download size={16} />
          Export CSV
        </button>
      </div>

      <div className="grid grid-cols-2 gap-3 xl:grid-cols-6">
        <div className="rounded-2xl border border-black/5 bg-white p-4 shadow-sm md:p-5">
          <p className="text-xs font-bold uppercase tracking-wider text-gray-500">Providers ready</p>
          <p className="mt-2 text-xl font-bold text-slate-950 md:text-2xl">
            {data?.providers.filter((provider) => provider.setupStatus === 'api_ready').length || 0}
          </p>
          <p className="mt-1 text-xs text-gray-400">Direct API-capable courier providers</p>
        </div>
        <div className="rounded-2xl border border-black/5 bg-white p-4 shadow-sm md:p-5">
          <p className="text-xs font-bold uppercase tracking-wider text-gray-500">Warehouses mapped</p>
          <p className="mt-2 text-xl font-bold text-slate-950 md:text-2xl">{data?.warehouseSummary.areaMapped || 0}</p>
          <p className="mt-1 text-xs text-gray-400">Pickup locations with Pathao city, zone, and area</p>
        </div>
        <div className="rounded-2xl border border-black/5 bg-white p-4 shadow-sm md:p-5">
          <p className="text-xs font-bold uppercase tracking-wider text-gray-500">Exceptions</p>
          <p className="mt-2 text-xl font-bold text-rose-600 md:text-2xl">{data?.shipmentSummary.exceptions || 0}</p>
          <p className="mt-1 text-xs text-gray-400">Failed, returned, or cancelled shipments</p>
        </div>
        <div className="rounded-2xl border border-black/5 bg-white p-4 shadow-sm md:p-5">
          <p className="text-xs font-bold uppercase tracking-wider text-gray-500">Pathao sync attention</p>
          <p className="mt-2 text-xl font-bold text-amber-600 md:text-2xl">{data?.shipmentSummary.pathaoSyncAttention || 0}</p>
          <p className="mt-1 text-xs text-gray-400">Active Pathao shipments missing fresh sync</p>
        </div>
        <div className="rounded-2xl border border-black/5 bg-white p-4 shadow-sm md:p-5">
          <p className="text-xs font-bold uppercase tracking-wider text-gray-500">RedX sync attention</p>
          <p className="mt-2 text-xl font-bold text-red-600 md:text-2xl">{data?.shipmentSummary.redxSyncAttention || 0}</p>
          <p className="mt-1 text-xs text-gray-400">Active RedX shipments missing fresh sync</p>
        </div>
        <div className="rounded-2xl border border-black/5 bg-white p-4 shadow-sm md:p-5">
          <p className="text-xs font-bold uppercase tracking-wider text-gray-500">Steadfast sync attention</p>
          <p className="mt-2 text-xl font-bold text-blue-600 md:text-2xl">{data?.shipmentSummary.steadfastSyncAttention || 0}</p>
          <p className="mt-1 text-xs text-gray-400">Active Steadfast shipments missing fresh sync</p>
        </div>
      </div>

      <div ref={deferredOpsRef} className="space-y-8">
        {showDeferredOpsPanels ? (
          <>
      <section className="rounded-2xl border border-black/5 bg-white p-6 shadow-sm">
        <div className="flex items-center gap-3">
          <div className="flex h-11 w-11 items-center justify-center rounded-2xl bg-[#ef4444] text-base font-black uppercase tracking-[0.18em] text-white shadow-sm">
            P
          </div>
          <div>
            <p className="text-xs font-bold uppercase tracking-[0.24em] text-[#ef4444]">Pathao ops</p>
            <h2 className="text-lg font-bold text-slate-950">Pathao Courier token and store health</h2>
          </div>
        </div>
        <div className="mt-5 grid gap-4 md:grid-cols-4">
          <div className="rounded-2xl bg-slate-50 p-4">
            <p className="text-xs font-bold uppercase tracking-wider text-slate-500">Cached token</p>
            <p className={`mt-2 text-xl font-bold ${data?.pathaoHealth?.hasCachedToken ? 'text-emerald-700' : 'text-amber-700'}`}>
              {data?.pathaoHealth?.hasCachedToken ? 'Ready' : 'Missing'}
            </p>
          </div>
          <div className="rounded-2xl bg-slate-50 p-4">
            <p className="text-xs font-bold uppercase tracking-wider text-slate-500">Linked stores</p>
            <p className="mt-2 text-xl font-bold text-slate-950">{data?.pathaoHealth?.linkedStoreCount || 0}</p>
          </div>
          <div className="rounded-2xl bg-slate-50 p-4">
            <p className="text-xs font-bold uppercase tracking-wider text-slate-500">Webhook</p>
            <p className={`mt-2 text-xl font-bold ${data?.pathaoHealth?.webhookConfigured ? 'text-emerald-700' : 'text-amber-700'}`}>
              {data?.pathaoHealth?.webhookConfigured ? 'Configured' : 'Missing'}
            </p>
          </div>
          <div className="rounded-2xl bg-slate-50 p-4">
            <p className="text-xs font-bold uppercase tracking-wider text-slate-500">Token expires</p>
            <p className="mt-2 text-xl font-bold text-slate-950">
              {data?.pathaoHealth?.expiresInSeconds != null
                ? `${Math.max(0, Math.round(data.pathaoHealth.expiresInSeconds / 60))}m`
                : 'N/A'}
            </p>
          </div>
        </div>
        <div className="mt-4 grid gap-3 md:grid-cols-2">
          <div className="rounded-2xl border border-slate-100 bg-slate-50 p-4 text-sm text-slate-600">
            <p className="font-semibold text-slate-900">Base URL</p>
            <p className="mt-1 break-all">{data?.pathaoHealth?.baseUrl || 'Not configured'}</p>
          </div>
          <div className="rounded-2xl border border-slate-100 bg-slate-50 p-4 text-sm text-slate-600">
            <p className="font-semibold text-slate-900">Token metadata</p>
            <p className="mt-1">
              {data?.pathaoHealth?.issuedAt
                ? `Issued ${new Date(data.pathaoHealth.issuedAt).toLocaleString()}`
                : 'No cached Pathao token yet'}
            </p>
            <p className="mt-1">
              {data?.pathaoHealth?.refreshTokenAvailable ? 'Refresh token cached' : 'Refresh token unavailable'}
            </p>
          </div>
        </div>
      </section>

      <section className="rounded-2xl border border-black/5 bg-white p-6 shadow-sm">
        <div className="flex items-center justify-between gap-4">
          <div>
            <p className="text-xs font-bold uppercase tracking-[0.24em] text-[#ef4444]">Pathao go-live</p>
            <h2 className="mt-2 text-lg font-bold text-slate-950">Exact launch checklist and blockers</h2>
            <p className="mt-2 text-sm text-slate-500">
              This section shows what is still blocking live Pathao booking: env config, warehouse mapping, or shipment data.
            </p>
          </div>
          <span className={`rounded-full px-3 py-1 text-[10px] font-bold uppercase tracking-wider ${
            data?.pathaoReadiness?.envReady ? 'bg-emerald-100 text-emerald-800' : 'bg-amber-100 text-amber-800'
          }`}>
            {data?.pathaoReadiness?.envReady ? 'Env ready' : 'Env blockers'}
          </span>
        </div>
        <div className="mt-5 grid gap-6 xl:grid-cols-[0.8fr_1.1fr_1.1fr]">
          <div className="space-y-3">
            <h3 className="text-sm font-bold text-slate-900">Environment</h3>
            {asArray(data?.pathaoReadiness?.envChecks).map((check) => (
              <div key={check.key} className="flex items-center justify-between rounded-2xl border border-slate-100 bg-slate-50 px-4 py-3 text-sm">
                <span className="font-medium text-slate-700">{check.label}</span>
                <span className={`rounded-full px-2.5 py-1 text-[10px] font-bold uppercase tracking-wider ${
                  check.ready ? 'bg-emerald-100 text-emerald-800' : 'bg-amber-100 text-amber-800'
                }`}>
                  {check.ready ? 'Ready' : 'Missing'}
                </span>
              </div>
            ))}
          </div>
