export interface BodyMeasurements {
  height: number; // cm
  weight: number; // kg
  chest: number; // cm
  waist: number; // cm
  hips: number; // cm
  inseam: number; // cm
}

export interface SizePrediction {
  topSize: string;
  bottomSize: string;
  shoeSize: string;
  confidence: number;
  recommendations: string[];
  fitNotes: string;
}

interface UseSizePredictorReturn {
  measurements: BodyMeasurements | null;
  prediction: SizePrediction | null;
  isLoading: boolean;
  error: string | null;
  setMeasurements: (measurements: BodyMeasurements) => void;
  predictSize: () => Promise<void>;
  updateMeasurement: (key: keyof BodyMeasurements, value: number) => void;
  clearPrediction: () => void;
  getSizeChart: (brand: string) => Record<string, string[]>;
}

// Standard size charts for different brands/regions
const sizeCharts = {
  standard: {
    XS: ['85-90', '60-65', '85-90'],
    S: ['90-95', '65-70', '90-95'],
    M: ['95-100', '70-75', '95-100'],
    L: ['100-105', '75-80', '100-105'],
    XL: ['105-110', '80-85', '105-110'],
    XXL: ['110-115', '85-90', '110-115'],
  },
  european: {
    '32': ['85-90', '60-65', '85-90'],
    '34': ['90-95', '65-70', '90-95'],
    '36': ['95-100', '70-75', '95-100'],
    '38': ['100-105', '75-80', '100-105'],
    '40': ['105-110', '80-85', '105-110'],
    '42': ['110-115', '85-90', '110-115'],
  },
};

// AI Size Prediction Algorithm (simplified ML model)
const predictSizeAI = (measurements: BodyMeasurements): SizePrediction => {
  const bmi = measurements.weight / ((measurements.height / 100) ** 2);
  const avgMeasurement = (measurements.chest + measurements.waist + measurements.hips) / 3;

  let topSize = 'M';
  let bottomSize = 'M';
  let shoeSize = '8';
  let confidence = 0.85;

  // Determine top size based on chest and height
  if (measurements.chest < 90) {
    topSize = 'XS';
  } else if (measurements.chest < 95) {
    topSize = 'S';
  } else if (measurements.chest < 105) {
    topSize = 'M';
  } else if (measurements.chest < 115) {
    topSize = 'L';
  } else {
    topSize = 'XL';
  }

  // Determine bottom size based on waist and inseam
  if (measurements.waist < 65) {
    bottomSize = 'XS';
  } else if (measurements.waist < 70) {
    bottomSize = 'S';
  } else if (measurements.waist < 80) {
    bottomSize = 'M';
  } else if (measurements.waist < 85) {
    bottomSize = 'L';
  } else {
    bottomSize = 'XL';
  }

  // Estimate shoe size (US sizing)
  const shoeBaseSize = 6 + Math.round((measurements.height - 150) / 5);
  shoeSize = Math.max(5, Math.min(15, shoeBaseSize)).toString();

  // Adjust confidence based on how standard the measurements are
  if (bmi > 18.5 && bmi < 25) confidence = 0.92;
  else if (bmi > 25 && bmi < 30) confidence = 0.88;
  else confidence = 0.75;

  const recommendations = [];
  if (measurements.chest - measurements.waist > 20) {
    recommendations.push('Consider fitted styles to accentuate your shape');
  }
  if (measurements.hips > measurements.chest) {
    recommendations.push('Peplum styles and flared pants complement your figure');
  }
  if (measurements.height < 160) {
    recommendations.push('Vertical stripes and high-waisted bottoms elongate your frame');
  }
  if (bmi > 25) {
    recommendations.push('Dark colors and structured fabrics provide a slimming effect');
  }

  return {
    topSize,
    bottomSize,
    shoeSize,
    confidence,
    recommendations,
    fitNotes: `Based on your measurements, we recommend ${topSize} for tops and ${bottomSize} for bottoms. Always check brand-specific sizing guides as they may vary.`,
  };
};

export const useSizePredictor = (): UseSizePredictorReturn => {
  const [measurements, setMeasurementsState] = useState<BodyMeasurements | null>(null);
  const [prediction, setPrediction] = useState<SizePrediction | null>(null);
  const [isLoading, setIsLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const setMeasurements = useCallback((measurements: BodyMeasurements) => {
    // Validate measurements
    if (measurements.height < 130 || measurements.height > 230) {
      setError('Height should be between 130cm and 230cm');
      return;
    }
    if (measurements.weight < 30 || measurements.weight > 200) {
      setError('Weight should be between 30kg and 200kg');
      return;
    }

    setMeasurementsState(measurements);
    setError(null);
  }, []);

  const predictSize = useCallback(async () => {
    if (!measurements) {
      setError('Please set your measurements first');
      return;
    }

    setIsLoading(true);
    setError(null);

    try {
      // Simulate ML processing
      await new Promise((resolve) => setTimeout(resolve, 1200));

      // Run AI prediction
      const newPrediction = predictSizeAI(measurements);
      setPrediction(newPrediction);
    } catch (err) {
      setError('Failed to predict size');
      console.error(err);
    } finally {
      setIsLoading(false);
    }
  }, [measurements]);

  const updateMeasurement = useCallback(
    (key: keyof BodyMeasurements, value: number) => {
      setMeasurementsState((prev) =>
        prev
          ? {
              ...prev,
              [key]: value,
            }
          : null
      );
    },
    []
  );

  const clearPrediction = useCallback(() => {
    setPrediction(null);
    setError(null);
  }, []);

  const getSizeChart = useCallback((brand: string) => {
    return sizeCharts[brand as keyof typeof sizeCharts] || sizeCharts.standard;
  }, []);

  return {
    measurements,
    prediction,
    isLoading,
    error,
    setMeasurements,
    predictSize,
    updateMeasurement,
    clearPrediction,
    getSizeChart,
  };
};

import { useState, useCallback } from 'react';
import { v4 as uuidv4 } from 'uuid';

export interface VoiceCommand {
  text: string;
  type: 'search' | 'add-to-cart' | 'checkout' | 'navigate' | 'filter' | 'sort' | 'unknown';
  intent: string;
  confidence: number;
  id: string;
  timestamp: Date;
}

export interface VoiceCommerceSession {
  id: string;
  startTime: Date;
  commands: VoiceCommand[];
  cartItems: number;
  lastAction: string | null;
}

interface UseVoiceCommerceReturn {
  session: VoiceCommerceSession;
  isProcessing: boolean;
  lastCommand: VoiceCommand | null;
  error: string | null;
  processCommand: (text: string) => Promise<VoiceCommand>;
  startSession: () => void;
  endSession: () => void;
  clearHistory: () => void;
}

// NLP Intent Recognition Engine
const recognizeIntent = (text: string): { type: string; intent: string; confidence: number } => {
  const normalizedText = text.toLowerCase().trim();

  // Search intents
  if (normalizedText.match(/^(search|find|show|look for|find me).*/)) {
    const query = normalizedText.replace(/^(search|find|show|look for|find me)\s+/i, '');
    return {
      type: 'search',
      intent: query,
      confidence: 0.9,
    };
  }

  // Add to cart intents
  if (normalizedText.match(/(add|put|get|buy).*(cart|bag|basket)/i)) {
    return {
      type: 'add-to-cart',
      intent: 'add-current-product',
      confidence: 0.85,
    };
  }

  // Checkout intents
  if (normalizedText.match(/(checkout|pay|purchase|complete|order)/i)) {
    return {
      type: 'checkout',
      intent: 'proceed-to-checkout',
      confidence: 0.88,
    };
  }

  // Navigation intents
  if (normalizedText.match(/(go to|navigate|visit|show me|open).*(home|shop|cart|account|profile)/i)) {
    const target = normalizedText.match(/(home|shop|cart|account|profile)/i)?.[1] || 'home';
    return {
      type: 'navigate',
      intent: `navigate-to-${target}`,
      confidence: 0.87,
    };
  }

  // Filter intents
  if (normalizedText.match(/(filter|show|only|size|color|price|brand).*/i)) {
    const filterType = normalizedText.match(
      /(small|medium|large|red|blue|green|cheap|expensive|brand|under|over)/i
    )?.[1] || 'general';
    return {
      type: 'filter',
      intent: `filter-by-${filterType}`,
      confidence: 0.8,
    };
  }

  // Sort intents
  if (normalizedText.match(/(sort|order|arrange).*(price|new|popular|rating)/i)) {
    const sortBy = normalizedText.match(/(price|new|popular|rating)/i)?.[1] || 'popular';
    return {
      type: 'sort',
      intent: `sort-by-${sortBy}`,
      confidence: 0.82,
    };
  }

  // Unknown
  return {
    type: 'unknown',
    intent: normalizedText,
    confidence: 0.5,
  };
};

export const useVoiceCommerce = (): UseVoiceCommerceReturn => {
  const [session, setSession] = useState<VoiceCommerceSession>({
    id: uuidv4(),
    startTime: new Date(),
    commands: [],
    cartItems: 0,
    lastAction: null,
  });

  const [isProcessing, setIsProcessing] = useState(false);
  const [lastCommand, setLastCommand] = useState<VoiceCommand | null>(null);
  const [error, setError] = useState<string | null>(null);

  const processCommand = useCallback(
    async (text: string): Promise<VoiceCommand> => {
      if (!text || text.trim().length === 0) {
        setError('Empty command text');
        return {} as VoiceCommand;
      }

      setIsProcessing(true);
      setError(null);

      try {
        // Simulate NLP processing
        await new Promise((resolve) => setTimeout(resolve, 500));

        // Recognize intent
        const { type, intent, confidence } = recognizeIntent(text);

        // Create command object
        const command: VoiceCommand = {
          text,
          type: type as any,
          intent,
          confidence,
          id: uuidv4(),
          timestamp: new Date(),
        };

        // Update session
        setSession((prev) => ({
          ...prev,
          commands: [...prev.commands, command],
          lastAction: intent,
          cartItems: type === 'add-to-cart' ? prev.cartItems + 1 : prev.cartItems,
        }));

        setLastCommand(command);
        return command;
      } catch (err) {
        setError('Failed to process command');
        console.error(err);
        return {} as VoiceCommand;
      } finally {
        setIsProcessing(false);
      }
    },
    []
  );

  const startSession = useCallback(() => {
    setSession({
      id: uuidv4(),
      startTime: new Date(),
      commands: [],
      cartItems: 0,
      lastAction: null,
    });
    setLastCommand(null);
    setError(null);
  }, []);

  const endSession = useCallback(() => {
    setLastCommand(null);
    setError(null);
  }, []);

  const clearHistory = useCallback(() => {
    setSession((prev) => ({
      ...prev,
      commands: [],
      lastAction: null,
    }));
    setLastCommand(null);
  }, []);

  return {
    session,
    isProcessing,
    lastCommand,
    error,
    processCommand,
    startSession,
    endSession,
    clearHistory,
  };
};

import { useState, useCallback, useRef } from 'react';

interface VoiceSearchResult {
  transcript: string;
  confidence: number;
  isFinal: boolean;
}

interface UseVoiceSearchReturn {
  isListening: boolean;
  transcript: string;
  confidence: number;
  error: string | null;
  startListening: () => void;
  stopListening: () => void;
  resetTranscript: () => void;
  isSupported: boolean;
}

export const useVoiceSearch = (): UseVoiceSearchReturn => {
  const [isListening, setIsListening] = useState(false);
  const [transcript, setTranscript] = useState('');
  const [confidence, setConfidence] = useState(0);
  const [error, setError] = useState<string | null>(null);
  
  const recognitionRef = useRef<any>(null);
  const isSupported = 'webkitSpeechRecognition' in window || 'SpeechRecognition' in window;

  const startListening = useCallback(() => {
    if (!isSupported) {
      setError('Speech Recognition not supported in this browser');
      return;
    }

    setError(null);
    setTranscript('');
    setConfidence(0);

    const SpeechRecognition = (window as any).webkitSpeechRecognition || (window as any).SpeechRecognition;
    recognitionRef.current = new SpeechRecognition();
    
    recognitionRef.current.continuous = true;
    recognitionRef.current.interimResults = true;
    recognitionRef.current.lang = 'en-US';

    recognitionRef.current.onstart = () => {
      setIsListening(true);
    };

    recognitionRef.current.onresult = (event: any) => {
      let interimTranscript = '';
      let finalTranscript = '';
      let maxConfidence = 0;

      for (let i = event.resultIndex; i < event.results.length; i++) {
        const transcript = event.results[i][0].transcript;
        const conf = event.results[i][0].confidence;

        if (event.results[i].isFinal) {
          finalTranscript += transcript + ' ';
          maxConfidence = Math.max(maxConfidence, conf);
        } else {
          interimTranscript += transcript;
        }
      }

      if (interimTranscript) {
        setTranscript(interimTranscript);
      } else if (finalTranscript) {
        setTranscript(finalTranscript);
        setConfidence(maxConfidence);
      }
    };

    recognitionRef.current.onerror = (event: any) => {
      setError(`Speech recognition error: ${event.error}`);
      setIsListening(false);
    };

    recognitionRef.current.onend = () => {
      setIsListening(false);
    };

    recognitionRef.current.start();
  }, [isSupported]);

  const stopListening = useCallback(() => {
    if (recognitionRef.current) {
      recognitionRef.current.stop();
      setIsListening(false);
    }
  }, []);

  const resetTranscript = useCallback(() => {
    setTranscript('');
    setConfidence(0);
    setError(null);
  }, []);

  return {
    isListening,
    transcript,
    confidence,
    error,
    startListening,
    stopListening,
    resetTranscript,
    isSupported,
  };
};

