            </div>
            <div className="rounded-2xl border border-slate-200 bg-slate-50 px-4 py-3 text-sm text-slate-600">
              If you use this account on other devices, sign in again there with the new password.
            </div>
            <Link
              to="/login"
              className="inline-flex items-center gap-2 rounded-2xl bg-slate-950 px-5 py-3 text-sm font-semibold text-white transition hover:bg-slate-800"
            >
              Go to login <ArrowRight size={18} />
            </Link>
          </div>
        )}
      </div>
    </AuthShell>
  );
};

export default ResetPasswordPage;

import { prisma } from '../../../features/shared/services/database/prisma';
import type {
  CourierAdapter,
  CourierProviderView,
  ShipmentBookingInput,
  ShipmentBookingResult,
} from '../../../modules/logistics/contracts';
import {
  createPathaoOrder,
  createPathaoStore,
  getPathaoOrderInfo,
  listPathaoStores,
} from './pathaoClient';

function collectTrackingCandidates(value: unknown, candidates: string[] = []): string[] {
  if (!value || typeof value !== 'object') {
    return candidates;
  }

  if (Array.isArray(value)) {
    for (const item of value) {
      collectTrackingCandidates(item, candidates);
    }
    return candidates;
  }

  for (const [key, nestedValue] of Object.entries(value)) {
    const normalizedKey = key.toLowerCase();
    if (
      normalizedKey.includes('tracking') ||
      normalizedKey.includes('consignment') ||
      normalizedKey.includes('parcel_id') ||
      normalizedKey.includes('parcelid')
    ) {
      if (typeof nestedValue === 'string' && nestedValue.trim()) {
        candidates.push(nestedValue.trim());
      } else if (typeof nestedValue === 'number' && Number.isFinite(nestedValue)) {
        candidates.push(String(nestedValue));
      }
    }

    collectTrackingCandidates(nestedValue, candidates);
  }

  return candidates;
}

function extractTrackingId(payload: unknown) {
  const [firstMatch] = collectTrackingCandidates(payload);
  return firstMatch ?? null;
}

function normalizePhone(phone: string | null | undefined) {
  const raw = String(phone || '').replace(/\D+/g, '');
  if (raw.length === 11) return raw;
  if (raw.length === 13 && raw.startsWith('880')) return `0${raw.slice(3)}`;
  return '';
}

async function resolvePathaoStoreId(input: ShipmentBookingInput) {
  const warehouseId = input.pickupLocation?.warehouseId;
  if (!warehouseId) {
    throw new Error('Pathao booking requires a shipment pickup warehouse.');
  }

  const warehouse = await prisma.warehouse.findUnique({
    where: { id: warehouseId },
    select: {
      id: true,
      name: true,
      address: true,
      city: true,
      phone: true,
      contactName: true,
      secondaryContact: true,
      otpNumber: true,
      pathaoStoreId: true,
      pathaoCityId: true,
      pathaoZoneId: true,
      pathaoAreaId: true,
    },
  });

  if (!warehouse) {
    throw new Error('Shipment pickup warehouse was not found.');
  }

  if (warehouse.pathaoStoreId) {
    return {
      storeId: warehouse.pathaoStoreId,
      warehouse,
      created: false,
      storePayload: null,
      storeResponse: null,
    };
  }

  if (!warehouse.pathaoCityId || !warehouse.pathaoZoneId || !warehouse.pathaoAreaId) {
    throw new Error(`Warehouse "${warehouse.name}" is missing Pathao city, zone, or area mapping.`);
  }

  const phone = normalizePhone(warehouse.phone || input.pickupLocation?.phone);
  if (!phone) {
    throw new Error(`Warehouse "${warehouse.name}" needs a valid 11-digit contact number for Pathao.`);
  }

  const storePayload = {
    name: warehouse.name,
    contact_name: warehouse.contactName || input.pickupLocation?.contactName || warehouse.name,
    contact_number: phone,
    secondary_contact: normalizePhone(warehouse.secondaryContact || input.pickupLocation?.secondaryContact) || undefined,
    otp_number: normalizePhone(warehouse.otpNumber || input.pickupLocation?.otpNumber) || undefined,
    address: warehouse.address,
    city_id: warehouse.pathaoCityId,
    zone_id: warehouse.pathaoZoneId,
    area_id: warehouse.pathaoAreaId,
  };

  const storeResponse = await createPathaoStore(storePayload);
  const listedStores = await listPathaoStores();

  const storeCandidates = Array.isArray((listedStores as any)?.data?.data) ? (listedStores as any).data.data : [];
  const matchedStore = [...storeCandidates]
    .reverse()
    .find((store: any) =>
      String(store?.store_name || '').trim().toLowerCase() === warehouse.name.trim().toLowerCase() &&
      Number(store?.city_id || 0) === warehouse.pathaoCityId,
    );

  const storeId = Number(matchedStore?.store_id || 0);
  if (!storeId) {
    throw new Error('Pathao store created but store ID could not be resolved from the merchant store list.');
  }

  await prisma.warehouse.update({
    where: { id: warehouse.id },
    data: {
      pathaoStoreId: storeId,
    },
  });

  return {
    storeId,
    warehouse,
    created: true,
    storePayload,
    storeResponse: storeResponse as Record<string, unknown>,
  };
}

export class PathaoApiAdapter implements CourierAdapter {
  constructor(private readonly provider: CourierProviderView) {}

  getProvider(): CourierProviderView {
    return this.provider;
  }

  async bookShipment(input: ShipmentBookingInput): Promise<ShipmentBookingResult> {
    const resolved = await resolvePathaoStoreId(input);
    const recipientPhone = normalizePhone(input.customer.phone);

    if (!recipientPhone) {
      throw new Error('Recipient phone number must be a valid 11-digit Bangladeshi mobile number for Pathao.');
    }

    if (!input.customer.address || input.customer.address.trim().length < 10) {
      throw new Error('Recipient address must be at least 10 characters for Pathao booking.');
    }

    const quantity = Math.max(1, Number(input.parcel?.quantity || 1));
    const weightKg = Math.min(10, Math.max(0.5, Number(input.parcel?.weightKg || 0.5)));
    const itemType = input.parcel?.itemType || 2;
    const deliveryType = input.parcel?.deliveryType || 48;

    const orderPayload: Record<string, unknown> = {
      store_id: resolved.storeId,
      merchant_order_id: input.merchantReference,
      recipient_name: input.customer.name,
      recipient_phone: recipientPhone,
      recipient_secondary_phone: normalizePhone(input.customer.secondaryPhone) || undefined,
      recipient_address: input.customer.address,
      delivery_type: deliveryType,
      item_type: itemType,
      special_instruction: input.parcel?.specialInstruction || `Shipment ${input.shipmentId || input.orderId} generated from LofiMart marketplace.`,
      item_quantity: quantity,
      item_weight: weightKg.toFixed(1),
      item_description: input.parcel?.description || `Marketplace shipment for order ${input.orderId}`,
      amount_to_collect: Math.max(0, Math.round(Number(input.codAmount || 0))),
    };

    if (Number.isFinite(Number(input.customer.cityId)) && Number(input.customer.cityId) > 0) {
      orderPayload.recipient_city = Number(input.customer.cityId);
    }
    if (Number.isFinite(Number(input.customer.zoneId)) && Number(input.customer.zoneId) > 0) {
      orderPayload.recipient_zone = Number(input.customer.zoneId);
    }
    if (Number.isFinite(Number(input.customer.areaId)) && Number(input.customer.areaId) > 0) {
      orderPayload.recipient_area = Number(input.customer.areaId);
    }

    const responsePayload = await createPathaoOrder(orderPayload);
    const trackingId = extractTrackingId(responsePayload);

    if (!trackingId) {
      throw new Error('Pathao booking response did not include a consignment ID.');
    }

    let orderInfo: Record<string, unknown> | null = null;
    try {
      orderInfo = (await getPathaoOrderInfo(trackingId)) as Record<string, unknown>;
    } catch {
      orderInfo = null;
    }

    const deliveryFee = Number((responsePayload as any)?.data?.delivery_fee ?? (orderInfo as any)?.data?.delivery_fee ?? 0);

    return {
      providerCode: this.provider.code,
      providerName: this.provider.name,
      trackingId,
      bookingMode: 'api',
      status: 'pickup_requested',
      deliveryFee: Number.isFinite(deliveryFee) ? deliveryFee : null,
      notes: resolved.created
        ? `Pathao store synced from warehouse ${resolved.warehouse.name} and shipment booked successfully.`
        : `Shipment booked successfully through Pathao store ${resolved.storeId}.`,
      metadata: {
        storeId: resolved.storeId,
        storeCreatedOnDemand: resolved.created,
        storePayload: resolved.storePayload,
        storeResponse: resolved.storeResponse,
        orderPayload,
        orderResponse: responsePayload,
        orderInfo,
      },
    };
  }
}

import { getServerEnv } from '../../../lib/env';
import { ensureRedis } from '../../../features/shared/services/messaging/redis';

type PathaoTokenBundle = {
  tokenType: string;
  accessToken: string;
  refreshToken?: string | null;
  expiresIn: number;
  issuedAt: number;
};

type PathaoTokenGrantMode = 'password' | 'refresh_token';

export type PathaoStorePayload = {
  name: string;
  contact_name: string;
  contact_number: string;
  secondary_contact?: string;
  otp_number?: string;
  address: string;
  city_id: number;
  zone_id: number;
  area_id: number;
};

export type PathaoSingleOrderPayload = {
  store_id: number;
  merchant_order_id?: string;
  recipient_name: string;
  recipient_phone: string;
  recipient_secondary_phone?: string;
  recipient_address: string;
  recipient_city?: number;
  recipient_zone?: number;
  recipient_area?: number;
  delivery_type: 12 | 48;
  item_type: 1 | 2;
  special_instruction?: string;
  item_quantity: number;
  item_weight: number | string;
  item_description?: string;
  amount_to_collect: number;
};

export type PathaoBulkOrderPayload = {
  orders: PathaoSingleOrderPayload[];
};

const TOKEN_KEY_SUFFIX = 'logistics:pathao:oauth';
const DEFAULT_WEBHOOK_INTEGRATION_SECRET = 'f3992ecc-59da-4cbe-a049-a13da2018d51';

function normalizeUrl(baseUrl: string, endpoint: string) {
  if (/^https?:\/\//i.test(endpoint)) {
    return endpoint;
  }

  return `${baseUrl.replace(/\/+$/, '')}/${endpoint.replace(/^\/+/, '')}`;
}

function getTokenCacheKey() {
  const env = getServerEnv();
  const base = String(env.PATHAO_BASE_URL || '').trim().toLowerCase();
  const client = String(env.PATHAO_CLIENT_ID || '').trim().toLowerCase();
  return `${env.QUEUE_PREFIX}:${TOKEN_KEY_SUFFIX}:${base}:${client}`;
}

async function readTokenBundle(): Promise<PathaoTokenBundle | null> {
  const redis = await ensureRedis();
  const raw = await redis.get(getTokenCacheKey());

  if (!raw) return null;

  try {
    return JSON.parse(raw) as PathaoTokenBundle;
  } catch {
    return null;
  }
}

async function writeTokenBundle(bundle: PathaoTokenBundle) {
  const redis = await ensureRedis();
  const ttlSeconds = Math.max(60, Math.floor(bundle.expiresIn - 120));
  await redis.set(getTokenCacheKey(), JSON.stringify(bundle), 'EX', ttlSeconds);
}

async function clearTokenBundle() {
  const redis = await ensureRedis();
  await redis.del(getTokenCacheKey());
}

function isTokenFresh(bundle: PathaoTokenBundle | null) {
  if (!bundle?.accessToken) return false;
  const expiryMs = bundle.issuedAt + bundle.expiresIn * 1000;
  return expiryMs - Date.now() > 120000;
}

async function requestPathaoToken(payload: Record<string, unknown>) {
  const env = getServerEnv();
  const url = normalizeUrl(env.PATHAO_BASE_URL || '', '/aladdin/api/v1/issue-token');

  const response = await fetch(url, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify(payload),
  });

  const responsePayload = await response.json().catch(() => null);
  if (!response.ok) {
    const responseMessage =
      responsePayload && typeof responsePayload === 'object'
        ? String(
            (responsePayload as { message?: unknown; error?: unknown }).message ??
              (responsePayload as { message?: unknown; error?: unknown }).error ??
              '',
          )
        : '';
    const message = responseMessage || `Pathao token request failed with status ${response.status}`;

    throw new Error(message);
  }

  const tokenType = String((responsePayload as any)?.token_type || 'Bearer');
  const accessToken = String((responsePayload as any)?.access_token || '');
  const refreshToken = typeof (responsePayload as any)?.refresh_token === 'string' ? String((responsePayload as any).refresh_token) : null;
  const expiresIn = Number((responsePayload as any)?.expires_in || 0);

  if (!accessToken || !Number.isFinite(expiresIn) || expiresIn <= 0) {
    throw new Error('Pathao token response is missing access token metadata.');
  }

  const bundle: PathaoTokenBundle = {
    tokenType,
    accessToken,
    refreshToken,
    expiresIn,
    issuedAt: Date.now(),
  };

  await writeTokenBundle(bundle);
  return bundle;
}

export async function issuePathaoAccessToken(options?: {
  mode?: PathaoTokenGrantMode;
  refreshToken?: string | null;
  force?: boolean;
}) {
  const env = getServerEnv();
  const requestedMode = options?.mode;
  const refreshToken = options?.refreshToken;
  const force = options?.force === true;

  if (!force) {
    const existing = await readTokenBundle();
    if (isTokenFresh(existing) && requestedMode !== 'refresh_token' && requestedMode !== 'password') {
      return existing as PathaoTokenBundle;
    }

    if (requestedMode !== 'password' && (refreshToken || existing?.refreshToken)) {
      try {
        return await requestPathaoToken({
          client_id: env.PATHAO_CLIENT_ID,
          client_secret: env.PATHAO_CLIENT_SECRET,
          grant_type: 'refresh_token',
          refresh_token: refreshToken || existing?.refreshToken,
        });
      } catch {
        // Fall back to password grant below.
      }
    }
  }

  if (!env.PATHAO_CLIENT_ID || !env.PATHAO_CLIENT_SECRET || !env.PATHAO_USERNAME || !env.PATHAO_PASSWORD || !env.PATHAO_BASE_URL) {
    throw new Error('Pathao OAuth configuration is incomplete.');
  }

  return requestPathaoToken({
    client_id: env.PATHAO_CLIENT_ID,
    client_secret: env.PATHAO_CLIENT_SECRET,
    grant_type: 'password',
    username: env.PATHAO_USERNAME,
    password: env.PATHAO_PASSWORD,
  });
}

export async function getPathaoAccessToken() {
  return issuePathaoAccessToken();
}

export async function refreshPathaoAccessToken() {
  const existing = await readTokenBundle();
  await clearTokenBundle();
  return issuePathaoAccessToken({
    mode: existing?.refreshToken ? 'refresh_token' : 'password',
    refreshToken: existing?.refreshToken,
    force: true,
  });
}

async function doPathaoRequest<T = any>(endpoint: string, init?: RequestInit) {
  const env = getServerEnv();
  const token = await getPathaoAccessToken();
  const url = normalizeUrl(env.PATHAO_BASE_URL || '', endpoint);

  const response = await fetch(url, {
    ...init,
    headers: {
      'Content-Type': 'application/json; charset=UTF-8',
      Authorization: `${token.tokenType || 'Bearer'} ${token.accessToken}`,
      ...(init?.headers || {}),
    },
  });

  const payload = await response.json().catch(() => null);
  if (!response.ok) {
    const responseMessage =
      payload && typeof payload === 'object'
        ? String((payload as { message?: unknown; error?: unknown }).message ?? (payload as { message?: unknown; error?: unknown }).error ?? '')
        : '';
    const message = responseMessage || `Pathao request failed with status ${response.status}`;

    throw new Error(message);
  }

  return payload as T;
}

async function pathaoRequest<T = any>(endpoint: string, init?: RequestInit) {
  try {
    return await doPathaoRequest<T>(endpoint, init);
  } catch (error) {
    const message = error instanceof Error ? error.message.toLowerCase() : '';
    const shouldRetry =
      message.includes('401') ||
      message.includes('403') ||
      message.includes('unauthorized') ||
      message.includes('forbidden') ||
      message.includes('token');

    if (!shouldRetry) {
      throw error;
    }

    await clearTokenBundle();
    return doPathaoRequest<T>(endpoint, init);
  }
}

