        : {};

    const lastEvent = typeof metadata.pathaoLastEvent === 'string' ? metadata.pathaoLastEvent : null;
    const lastStatusSlug = typeof metadata.pathaoLastStatusSlug === 'string' ? metadata.pathaoLastStatusSlug : null;

    if (!lastEvent && !lastStatusSlug) return null;

    return {
      event: lastEvent ? lastEvent.replaceAll('_', ' ').replaceAll('.', ' ') : null,
      status: lastStatusSlug ? lastStatusSlug.replaceAll('_', ' ') : null,
    };
  };

  useEffect(() => {
    const fetchOrder = async () => {
      try {
        setError('');
        const response = await fetch(`/api/orders/${id}`, {
          headers: { Authorization: `Bearer ${token}` },
        });
        const data = await response.json().catch(() => null);
        if (!response.ok) throw new Error(data?.error || 'Failed to fetch order');

        if (typeof data.shipping_address === 'string') {
          data.shippingAddress = JSON.parse(data.shipping_address);
        } else {
          data.shippingAddress = data.shipping_address;
        }

        setOrder(data);
      } catch (err: any) {
        setError(err.message || 'Failed to fetch order');
        setOrder(null);
      } finally {
        setLoading(false);
      }
    };

    if (token && id) {
      fetchOrder();
    } else {
      setOrder(null);
      setLoading(false);
    }
  }, [token, id]);

  useEffect(() => {
    if (typeof window === 'undefined') return;

    const params = new URLSearchParams(window.location.search);
    const nextShipment = params.get('shipment');
    const nextReturnRequest = params.get('return');
    if (nextShipment) {
      setFocusedShipmentId(nextShipment);
    }
    if (nextReturnRequest) {
      setFocusedReturnRequestId(nextReturnRequest);
    }
  }, []);

  useEffect(() => {
    if (!order || !focusedShipmentId || typeof window === 'undefined') return;

    const matched = Array.isArray(order.shipments)
      ? order.shipments.find((shipment: any) => shipment.id === focusedShipmentId)
      : null;

    if (!matched) return;

    window.requestAnimationFrame(() => {
      document.getElementById(`customer-order-shipment-${matched.id}`)?.scrollIntoView({
        behavior: 'smooth',
        block: 'center',
      });
    });
  }, [order, focusedShipmentId]);

  useEffect(() => {
    if (!order?.return_request || !focusedReturnRequestId || typeof window === 'undefined') return;
    if (String(order.return_request.id) !== focusedReturnRequestId) return;

    window.requestAnimationFrame(() => {
      document.getElementById('customer-order-return-request')?.scrollIntoView({
        behavior: 'smooth',
        block: 'center',
      });
    });
  }, [order, focusedReturnRequestId]);

  if (loading) {
    return (
      <div className="flex items-center justify-center py-24">
        <Loader2 className="animate-spin text-primary" size={48} />
      </div>
    );
  }

  if (!order) {
    return (
      <div className="space-y-4 py-24 text-center">
        <p className="font-bold text-accent">{error || 'Order not found'}</p>
        <Link to="/account/orders" className="btn-primary inline-block px-8 py-2">
          Back to Orders
        </Link>
      </div>
    );
  }

  const canRequestReturn = ['delivered', 'returned'].includes(String(order.status));
  const canEditOrder = Boolean(order?.can_edit);
  const canCancelOrder = Boolean(order?.can_cancel);
  const customerActionBlockReason =
    typeof order?.customer_action_block_reason === 'string' ? order.customer_action_block_reason : '';

  const handleInvoiceDownload = async () => {
    try {
      setDownloadingInvoice(true);
      const response = await fetch(`/api/orders/${order.id}/invoice.pdf`, {
        headers: { Authorization: `Bearer ${token}` },
      });
      if (!response.ok) {
        const payload = await response.json().catch(() => null);
        throw new Error(payload?.error || 'Failed to download invoice');
      }

      const blob = await response.blob();
      const url = window.URL.createObjectURL(blob);
      const anchor = document.createElement('a');
      anchor.href = url;
      anchor.download = `invoice-${order.id}.pdf`;
      document.body.appendChild(anchor);
      anchor.click();
      anchor.remove();
      window.URL.revokeObjectURL(url);
      toast.success('PDF invoice downloaded successfully.');
    } catch (requestError) {
      toast.error(requestError instanceof Error ? requestError.message : 'Failed to download invoice');
    } finally {
      setDownloadingInvoice(false);
    }
  };

  const handleReturnRequest = async () => {
    if (!canRequestReturn) {
      toast.error('Return requests are available only after delivery.');
      return;
    }

    try {
      setSubmittingReturn(true);
      const response = await fetch(`/api/orders/${order.id}/return-request`, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          Authorization: `Bearer ${token}`,
        },
        body: JSON.stringify({ reason: returnReason }),
      });
      const payload = await response.json().catch(() => null);
      if (!response.ok) {
        throw new Error(payload?.error || 'Failed to submit return request');
      }

      setOrder((current: any) => ({
        ...current,
        return_request: payload.request,
      }));
      setReturnReason('');
      toast.success('Return request submitted for review.');
    } catch (requestError) {
      toast.error(requestError instanceof Error ? requestError.message : 'Failed to submit return request');
    } finally {
      setSubmittingReturn(false);
    }
  };

  const handleCancelOrder = async () => {
    if (!canCancelOrder) {
      toast.error(customerActionBlockReason || 'This order can no longer be cancelled.');
      return;
    }

    try {
      setCancellingOrder(true);
      const response = await fetch(`/api/orders/${order.id}/cancel`, {
        method: 'POST',
        headers: {
          Authorization: `Bearer ${token}`,
        },
      });
      const payload = await response.json().catch(() => null);
      if (!response.ok) {
        throw new Error(payload?.error || 'Failed to cancel order');
      }

      setOrder((current: any) => ({
        ...current,
        ...(payload?.order || {}),
      }));
      toast.success('Order cancelled successfully.');
    } catch (requestError) {
      toast.error(requestError instanceof Error ? requestError.message : 'Failed to cancel order');
    } finally {
      setCancellingOrder(false);
    }
  };

  const handleEditOrder = async () => {
    if (!canEditOrder) {
      toast.error(customerActionBlockReason || 'This order can no longer be edited.');
      return;
    }

    try {
      setEditingOrder(true);
      const response = await fetch(`/api/orders/${order.id}/edit`, {
        method: 'POST',
        headers: {
          Authorization: `Bearer ${token}`,
        },
      });
      const payload = await response.json().catch(() => null);
      if (!response.ok) {
        throw new Error(payload?.error || 'Failed to reopen order for editing');
      }

      if (!Array.isArray(payload?.cart_items) || payload.cart_items.length === 0) {
        throw new Error('This order could not be restored to your cart.');
      }

      replaceCart(payload.cart_items);
      toast.success('Order moved back to your cart for editing.');
      navigate('/cart');
    } catch (requestError) {
      toast.error(requestError instanceof Error ? requestError.message : 'Failed to reopen order for editing');
    } finally {
      setEditingOrder(false);
    }
  };

  return (
    <div className="space-y-8">
      {error && (
        <div className="rounded-xl border border-amber-200 bg-amber-50 px-4 py-3 text-sm text-amber-800">
          {error}
        </div>
      )}
      <div className="flex items-center space-x-4">
        <Link to="/account/orders" className="rounded-full p-2 transition-colors hover:bg-gray-100">
          <ChevronLeft size={24} />
        </Link>
        <div>
          <h1 className="text-2xl font-bold">Order Details</h1>
          <p className="text-sm text-gray-500">
            Order #{order.order_code || order.id} - Placed on {new Date(order.created_at).toLocaleDateString()}
          </p>
        </div>
      </div>

      <div className="grid grid-cols-1 gap-8 lg:grid-cols-3">
        <div className="space-y-8 lg:col-span-2">
          <div className="space-y-8 rounded-2xl border border-black/5 bg-white p-8 shadow-sm">
            <div className="flex items-center justify-between">
              <h3 className="text-lg font-bold">Order Status</h3>
              <span className="rounded-full bg-primary/10 px-3 py-1 text-xs font-bold uppercase tracking-wider text-primary">
                {String(order.status).replaceAll('_', ' ')}
              </span>
            </div>
            <div className="relative flex justify-between">
              <div className="absolute left-0 right-0 top-4 -z-0 h-0.5 bg-gray-100" />
              {shipmentSteps.map((step) => (
                <div key={step.label} className="relative z-10 flex flex-col items-center space-y-2">
                  <div className={`flex h-8 w-8 items-center justify-center rounded-full ${step.statuses.includes(order.status) ? 'bg-primary text-white' : 'border-2 border-gray-100 bg-white text-gray-300'}`}>
                    {step.icon}
                  </div>
                  <span className={`text-[10px] font-bold uppercase tracking-wider ${step.statuses.includes(order.status) ? 'text-gray-900' : 'text-gray-400'}`}>
                    {step.label}
                  </span>
                </div>
              ))}
            </div>
            <div className="rounded-2xl border border-primary/10 bg-primary/5 p-4">
              <div className="flex flex-col gap-3 md:flex-row md:items-center md:justify-between">
                <div className="space-y-1">
                  <p className="text-sm font-semibold text-slate-900">Need to change this order?</p>
                  <p className="text-sm text-slate-600">
                    You can edit or cancel until the seller accepts it and courier processing begins.
                  </p>
                  {!canEditOrder && customerActionBlockReason ? (
                    <p className="text-xs font-medium text-slate-500">{customerActionBlockReason}</p>
                  ) : null}
                </div>
                <div className="flex flex-col gap-2 sm:flex-row">
                  <button
                    onClick={() => void handleEditOrder()}
                    disabled={!canEditOrder || editingOrder || cancellingOrder}
                    className="inline-flex items-center justify-center rounded-2xl border border-slate-200 bg-white px-4 py-3 text-sm font-semibold text-slate-700 transition hover:bg-slate-50 disabled:cursor-not-allowed disabled:opacity-50"
                  >
                    {editingOrder ? <Loader2 size={16} className="animate-spin" /> : 'Edit order'}
                  </button>
                  <button
                    onClick={() => void handleCancelOrder()}
                    disabled={!canCancelOrder || cancellingOrder || editingOrder}
                    className="inline-flex items-center justify-center rounded-2xl border border-rose-200 bg-rose-50 px-4 py-3 text-sm font-semibold text-rose-700 transition hover:bg-rose-100 disabled:cursor-not-allowed disabled:opacity-50"
                  >
                    {cancellingOrder ? <Loader2 size={16} className="animate-spin" /> : 'Cancel order'}
                  </button>
                </div>
              </div>
            </div>
          </div>

          <div className="rounded-2xl border border-black/5 bg-white p-8 shadow-sm">
            <div className="flex items-center justify-between">
              <h3 className="text-lg font-bold">Courier & Tracking</h3>
              <Truck size={18} className="text-primary" />
            </div>

            <div className="mt-6 grid gap-4 sm:grid-cols-2">
              <div className="rounded-2xl bg-gray-50 p-5">
                <p className="text-xs font-bold uppercase tracking-wider text-gray-500">Courier provider</p>
                <p className="mt-2 text-sm font-bold text-gray-900">
                  {order.courier_provider || 'Will appear after pickup request'}
                </p>
              </div>
              <div className="rounded-2xl bg-gray-50 p-5">
                <p className="text-xs font-bold uppercase tracking-wider text-gray-500">Tracking ID</p>
                <p className="mt-2 flex items-center gap-2 text-sm font-bold text-gray-900">
                  <ScanLine size={16} className="text-primary" />
                  {order.tracking_id || 'Pending assignment'}
                </p>
              </div>
            </div>

            {order.delivery_failure_reason ? (
              <div className="mt-5 rounded-2xl border border-amber-200 bg-amber-50 px-4 py-3 text-sm text-amber-800">
                <div className="flex items-start gap-2">
                  <AlertTriangle size={18} className="mt-0.5 shrink-0" />
                  <div>
                    <p className="font-semibold">Delivery exception</p>
                    <p className="mt-1">{order.delivery_failure_reason}</p>
                    <Link
                      to={`/contact?subject=${encodeURIComponent('Delivery Support')}&message=${encodeURIComponent(
                        `I need help with delivery for order ${order.order_code || order.id}. Tracking ID: ${order.tracking_id || 'pending'}.`,
                      )}`}
                      className="mt-3 inline-flex text-sm font-semibold text-amber-800 underline-offset-4 hover:underline"
                    >
                      Contact support about this order
                    </Link>
                  </div>
                </div>
              </div>
            ) : null}

            {Array.isArray(order.shipments) && order.shipments.length > 0 ? (
              <div className="mt-6 space-y-3">
                <p className="text-xs font-bold uppercase tracking-wider text-gray-500">Shipment breakdown</p>
                {order.shipments.map((shipment: any) => {
                  const pathaoEventSummary = getPathaoEventSummary(shipment);

                  return (
                  <div
                    id={`customer-order-shipment-${shipment.id}`}
                    key={shipment.id}
                    className={`rounded-2xl border border-gray-100 bg-gray-50 p-4 ${
                      shipment.id === focusedShipmentId ? 'ring-2 ring-indigo-200 border-indigo-300 bg-indigo-50/40' : ''
                    }`}
                  >
                    <div className="flex flex-col gap-2 sm:flex-row sm:items-center sm:justify-between">
                      <div>
                        <p className="text-sm font-bold text-gray-900">Shipment #{String(shipment.id).slice(0, 8)}</p>
                        <p className="text-xs text-gray-500">
                          {shipment.warehouse_name || 'Seller pickup point'}
                          {shipment.warehouse_city ? ` • ${shipment.warehouse_city}` : ''}
                        </p>
                      </div>
                      <div className="text-sm font-semibold text-primary">
                        {String(shipment.status).replaceAll('_', ' ')}
                      </div>
                    </div>
                    <div className="mt-3 grid gap-3 sm:grid-cols-3 text-xs text-gray-600">
                      <p>Courier: <span className="font-semibold text-gray-900">{shipment.courier_provider || 'Pending'}</span></p>
                      <p>Tracking: <span className="font-semibold text-gray-900">{shipment.tracking_id || 'Pending'}</span></p>
                      <p>Items: <span className="font-semibold text-gray-900">{shipment.item_count || 0}</span></p>
                    </div>
                    {pathaoEventSummary ? (
                      <div className="mt-3 rounded-xl border border-rose-100 bg-rose-50 px-3 py-2 text-xs text-rose-800">
                        <span className="font-semibold">Courier event:</span>{' '}
                        {pathaoEventSummary.event || 'event pending'}
                        {pathaoEventSummary.status ? ` • ${pathaoEventSummary.status}` : ''}
                      </div>
                    ) : null}
                    <div className="mt-3 grid gap-2 text-xs text-gray-500 sm:grid-cols-2">
                      <div className="rounded-xl bg-white px-3 py-2">
                        Pickup requested: <span className="font-semibold text-gray-900">{shipment.pickup_requested_at ? new Date(shipment.pickup_requested_at).toLocaleString() : 'Pending'}</span>
                      </div>
                      <div className="rounded-xl bg-white px-3 py-2">
                        Picked up: <span className="font-semibold text-gray-900">{shipment.picked_up_at ? new Date(shipment.picked_up_at).toLocaleString() : 'Pending'}</span>
                      </div>
                      <div className="rounded-xl bg-white px-3 py-2">
                        Out for delivery: <span className="font-semibold text-gray-900">{shipment.out_for_delivery_at ? new Date(shipment.out_for_delivery_at).toLocaleString() : 'Pending'}</span>
                      </div>
                      <div className="rounded-xl bg-white px-3 py-2">
                        Delivered: <span className="font-semibold text-gray-900">{shipment.delivered_at ? new Date(shipment.delivered_at).toLocaleString() : 'Pending'}</span>
                      </div>
                    </div>
                    {Array.isArray(shipment.items) && shipment.items.length > 0 ? (
                      <div className="mt-3 rounded-2xl border border-gray-100 bg-white p-3">
                        <p className="text-xs font-bold uppercase tracking-wider text-gray-500">Products in this shipment</p>
                        <div className="mt-2 flex flex-wrap gap-2">
                          {shipment.items.map((item: any) => (
                            <span key={item.id} className="rounded-full bg-gray-50 px-3 py-1 text-xs text-gray-700">
                              {item.sku ? `${item.sku} • ` : ''}{item.name || 'Item'}{item.quantity ? ` x${item.quantity}` : ''}
                            </span>
                          ))}
                        </div>
                      </div>
                    ) : null}
                    {shipment.delivery_failure_reason ? (
                      <div className="mt-3 rounded-2xl border border-amber-200 bg-amber-50 px-4 py-3 text-xs text-amber-800">
                        Exception note: {shipment.delivery_failure_reason}
                      </div>
                    ) : null}
                  </div>
                  );
                })}
              </div>
            ) : null}
          </div>

          <div className="overflow-hidden rounded-2xl border border-black/5 bg-white shadow-sm">
            <div className="border-b border-gray-100 p-6">
              <h3 className="font-bold">Items in Order</h3>
            </div>
            <div className="divide-y divide-gray-100">
              {order.items.map((item: any) => (
                <div key={item.id} className="flex items-center space-x-4 p-6">
                  <OptimizedImage src={item.image} alt={item.name} widthHint={128} heightHint={128} className="h-16 w-16 rounded-lg bg-gray-100 object-cover" />
                  <div className="min-w-0 flex-1">
                    <p className="truncate text-sm font-bold">{item.name}</p>
                    {item.sku ? <p className="text-[11px] font-semibold text-slate-500">SKU: {item.sku}</p> : null}
                    {item.variant_summary ? <p className="text-[11px] font-medium text-primary">{item.variant_summary}</p> : null}
                    <p className="text-xs text-gray-500">
                      {item.quantity} x {formatPrice(item.price)}
                    </p>
                  </div>
                  <p className="text-sm font-bold">{formatPrice(item.price * item.quantity)}</p>
                </div>
              ))}
            </div>
            <div className="space-y-2 bg-gray-50 p-6">
              <div className="flex justify-between text-sm">
                <span className="text-gray-500">Subtotal</span>
                <span className="font-bold">{formatPrice(order.total)}</span>
              </div>
              <div className="flex justify-between text-sm">
                <span className="text-gray-500">Shipping</span>
                <span className="font-bold text-primary">Free</span>
              </div>
              <div className="flex justify-between border-t border-gray-200 pt-2 text-lg font-bold">
                <span>Total</span>
                <span className="text-primary">{formatPrice(order.total)}</span>
              </div>
            </div>
          </div>
        </div>

        <div className="space-y-8">
          <div
            id="customer-order-return-request"
            className={`space-y-4 rounded-2xl border border-black/5 bg-white p-6 shadow-sm ${
              order.return_request?.id && String(order.return_request.id) === focusedReturnRequestId
                ? 'ring-2 ring-indigo-200 border-indigo-300'
                : ''
            }`}
          >
            <h3 className="flex items-center space-x-2 font-bold">
              <MapPin size={18} className="text-primary" />
              <span>Shipping Address</span>
            </h3>
            <div className="space-y-1 text-sm text-gray-600">
              <p className="font-bold text-gray-900">{order.shippingAddress?.name}</p>
              <p>{order.shippingAddress?.phone}</p>
              <p>{order.shippingAddress?.address}</p>
              <p>{order.shippingAddress?.city}</p>
            </div>
          </div>

          <div className="space-y-4 rounded-2xl border border-black/5 bg-white p-6 shadow-sm">
            <h3 className="flex items-center space-x-2 font-bold">
              <CreditCard size={18} className="text-primary" />
              <span>Payment Method</span>
            </h3>
            <p className="text-sm font-bold text-gray-600">{order.payment_method}</p>
          </div>

          <button
            onClick={() => void handleInvoiceDownload()}
            disabled={downloadingInvoice}
            className="btn-primary flex w-full items-center justify-center gap-2 py-3 disabled:opacity-60"
          >
            {downloadingInvoice ? <Loader2 size={18} className="animate-spin" /> : <Download size={18} />}
            <span>Download Invoice</span>
          </button>
          <Link
            to={`/account/orders/${order.id}/invoice`}
            className="inline-flex w-full items-center justify-center gap-2 rounded-2xl border border-slate-200 bg-white px-4 py-3 text-sm font-semibold text-slate-700 transition hover:bg-slate-50"
          >
            <ExternalLink size={18} />
            <span>Open Printable Invoice</span>
          </Link>

          <div className="space-y-4 rounded-2xl border border-black/5 bg-white p-6 shadow-sm">
            <h3 className="flex items-center gap-2 font-bold">
              <RotateCcw size={18} className="text-primary" />
              <span>Return Request</span>
            </h3>

            {order.return_request ? (
              <div className="rounded-2xl border border-amber-200 bg-amber-50 p-4 text-sm text-amber-800">
                <p className="font-semibold">Return request status: {String(order.return_request.status).replaceAll('_', ' ')}</p>
                <p className="mt-2">{order.return_request.reason}</p>
                {order.return_request.resolution_note ? (
                  <p className="mt-3 rounded-xl bg-white/70 px-3 py-2 text-amber-900">
                    Team note: {order.return_request.resolution_note}
                  </p>
                ) : null}
              </div>
            ) : canRequestReturn ? (
              <>
                <p className="text-sm text-gray-500">
                  Received a damaged, incorrect, or unsuitable item? Submit a return request and the team will review it.
                </p>
                <textarea
                  rows={4}
                  value={returnReason}
                  onChange={(event) => setReturnReason(event.target.value)}
                  placeholder="Explain why you want to return this order"
                  className="w-full rounded-2xl border border-slate-200 bg-slate-50 px-4 py-3 text-sm outline-none transition focus:border-primary/30 focus:bg-white focus:ring-4 focus:ring-primary/10"
                />
                <button
                  onClick={() => void handleReturnRequest()}
                  disabled={submittingReturn || returnReason.trim().length < 10}
                  className="inline-flex w-full items-center justify-center gap-2 rounded-2xl border border-primary/15 bg-primary/5 px-4 py-3 text-sm font-semibold text-primary transition hover:bg-primary/10 disabled:cursor-not-allowed disabled:opacity-50"
                >
                  {submittingReturn ? <Loader2 size={18} className="animate-spin" /> : <RotateCcw size={18} />}
                  <span>Submit Return Request</span>
                </button>
              </>
            ) : (
              <p className="text-sm text-gray-500">
                Return requests are available after the order is delivered.
              </p>
            )}
            <Link
              to={`/contact?subject=${encodeURIComponent('Order Support')}&message=${encodeURIComponent(
                `I need help with order ${order.order_code || order.id}. Current status: ${String(order.status).replaceAll('_', ' ')}.`,
              )}`}
              className="inline-flex text-sm font-semibold text-primary underline-offset-4 hover:underline"
            >
              Contact support about this order
            </Link>
          </div>
        </div>
      </div>
    </div>
  );
};

import React, { useState, useEffect, useMemo } from 'react';
import { Package, Clock, ChevronRight, AlertCircle, Truck, Loader2 } from 'lucide-react';
import { formatPrice } from '../../../lib/utils';
import { Link, useNavigate } from '../../../lib/navigation';
import { useUser } from '../../../features/shared/state/UserContext';
import { useCart } from '../../../features/shop/state/CartContext';
import { ListCardSkeleton } from '@/features/shared/ui/DataSkeletons';
import { EmptyState } from '@/features/shared/ui/FeedbackState';
import toast from '@/lib/toast';

export const CustomerOrdersPage = () => {
  const [orders, setOrders] = useState<any[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState('');
  const [focusedOrderId, setFocusedOrderId] = useState('');
  const [editingOrderId, setEditingOrderId] = useState('');
  const [cancellingOrderId, setCancellingOrderId] = useState('');
  const { token } = useUser();
  const { replaceCart } = useCart();
  const navigate = useNavigate();

  useEffect(() => {
    const fetchOrders = async () => {
      try {
        setError('');
        const response = await fetch('/api/orders/my-orders', {
          headers: {
            Authorization: `Bearer ${token}`,
          },
        });
        const data = await response.json();
        if (!response.ok) throw new Error(data.error || 'Failed to fetch orders');
        setOrders(data);
      } catch (err: any) {
        setError(err.message);
        setOrders([]);
      } finally {
        setLoading(false);
      }
    };

    if (token) {
      fetchOrders();
    } else {
      setOrders([]);
      setLoading(false);
    }
  }, [token]);

  const getPathaoEventSummary = (shipment: any) => {
    const metadata =
      shipment?.shipment_metadata && typeof shipment.shipment_metadata === 'object'
        ? (shipment.shipment_metadata as Record<string, unknown>)
        : {};

    const lastEvent = typeof metadata.pathaoLastEvent === 'string' ? metadata.pathaoLastEvent : null;
    const lastStatusSlug = typeof metadata.pathaoLastStatusSlug === 'string' ? metadata.pathaoLastStatusSlug : null;

    if (!lastEvent && !lastStatusSlug) return null;

    return [lastEvent, lastStatusSlug]
      .filter(Boolean)
      .map((value) => String(value).replaceAll('_', ' ').replaceAll('.', ' '))
      .join(' â€¢ ');
  };

  const visibleOrders = useMemo(() => {
    if (!focusedOrderId) return orders;
    return orders.filter(
      (order) =>
        String(order.id) === focusedOrderId ||
        String(order.order_code || '').toLowerCase() === focusedOrderId.toLowerCase(),
    );
  }, [orders, focusedOrderId]);

  useEffect(() => {
    if (typeof window === 'undefined') return;

    const params = new URLSearchParams(window.location.search);
    const nextOrder = params.get('order');
    if (nextOrder) {
      setFocusedOrderId(nextOrder);
    }
  }, []);

  const handleCancelOrder = async (order: any) => {
    try {
      setCancellingOrderId(String(order.id));
      const response = await fetch(`/api/orders/${order.id}/cancel`, {
        method: 'POST',
        headers: {
          Authorization: `Bearer ${token}`,
        },
      });
      const payload = await response.json().catch(() => null);
      if (!response.ok) {
        throw new Error(payload?.error || 'Failed to cancel order');
      }

      setOrders((current) =>
        current.map((entry) =>
          String(entry.id) === String(order.id)
            ? {
                ...entry,
                ...(payload?.order || {}),
              }
            : entry,
        ),
      );
      toast.success('Order cancelled successfully.');
    } catch (requestError) {
      toast.error(requestError instanceof Error ? requestError.message : 'Failed to cancel order');
    } finally {
      setCancellingOrderId('');
    }
  };

  const handleEditOrder = async (order: any) => {
    try {
      setEditingOrderId(String(order.id));
      const response = await fetch(`/api/orders/${order.id}/edit`, {
        method: 'POST',
        headers: {
          Authorization: `Bearer ${token}`,
        },
      });
      const payload = await response.json().catch(() => null);
      if (!response.ok) {
        throw new Error(payload?.error || 'Failed to reopen order for editing');
      }

      if (!Array.isArray(payload?.cart_items) || payload.cart_items.length === 0) {
        throw new Error('This order could not be restored to your cart.');
      }

      replaceCart(payload.cart_items);
      toast.success('Order moved back to your cart for editing.');
      navigate('/cart');
    } catch (requestError) {
      toast.error(requestError instanceof Error ? requestError.message : 'Failed to reopen order for editing');
    } finally {
      setEditingOrderId('');
    }
  };

  if (loading) {
    return <ListCardSkeleton rows={5} />;
  }

  return (
    <div className="space-y-6">
      <h1 className="text-2xl font-bold">My Orders</h1>
      {error && (
        <div className="flex items-center space-x-2 rounded-xl border border-amber-200 bg-amber-50 px-4 py-3 text-amber-800">
          <AlertCircle size={20} />
          <span className="font-medium">{error}</span>
        </div>
      )}
      {visibleOrders.length === 0 ? (
        <EmptyState
          icon={<Package className="h-8 w-8" />}
          title="You haven't placed any orders yet"
          description="Your upcoming purchases, tracking updates, and delivery history will appear here."
          actions={
            <Link to="/shop" className="btn-primary inline-block px-8">
              Start Shopping
            </Link>
          }
        />
      ) : (
        <div className="space-y-4">
          {visibleOrders.map((order) => (
            <div
              id={`customer-order-${order.id}`}
              key={order.id}
              className={`flex flex-col gap-4 rounded-2xl border border-black/5 bg-white p-4 shadow-sm md:flex-row md:items-center md:justify-between md:p-6 ${
                String(order.id) === focusedOrderId ||
                String(order.order_code || '').toLowerCase() === focusedOrderId.toLowerCase()
                  ? 'border-indigo-300 bg-indigo-50/30 ring-2 ring-indigo-200'
                  : ''
              }`}
            >
              <div className="flex items-center space-x-3 md:space-x-4">
                <div className="rounded-xl bg-gray-50 p-2.5 md:p-3">
                  <Package className="text-gray-400" />
                </div>
                <div>
                  <p className="font-bold">Order #{order.order_code || order.id}</p>
                  <p className="text-sm text-gray-500">
                    Placed on {new Date(order.created_at).toLocaleDateString()}
                  </p>
                </div>
              </div>

              <div className="flex flex-col gap-4 sm:flex-row sm:items-center sm:justify-between md:gap-8">
                <div className="text-left">
                  <p className="mb-1 text-xs uppercase tracking-wider text-gray-500">Status</p>
                  <div className="flex items-center space-x-1 text-primary">
                    <Clock size={14} />
                    <span className="text-sm font-bold capitalize">
                      {String(order.status).replaceAll('_', ' ')}
                    </span>
                  </div>
                  {order.courier_provider || order.tracking_id ? (
                    <div className="mt-2 flex items-center space-x-1 text-[11px] text-gray-500">
                      <Truck size={12} />
                      <span>
                        {order.courier_provider || 'Courier'}
                        {order.tracking_id ? ` / ${order.tracking_id}` : ''}
                      </span>
                    </div>
                  ) : null}
                  {Array.isArray(order.shipments) && order.shipments.length > 0 ? (
                    <div className="mt-2 space-y-1">
                      <p className="text-[11px] text-gray-500">
                        {order.shipments.length} shipment{order.shipments.length > 1 ? 's' : ''} in this order
                      </p>
                      <div className="flex flex-wrap gap-1">
                        {order.shipments.slice(0, 3).map((shipment: any) => (
                          <span
                            key={shipment.id}
                            className="dashboard-stat-chip bg-slate-100 text-slate-600"
                          >
                            {shipment.warehouse_name || 'Pickup point'} /{' '}
                            {String(shipment.status).replaceAll('_', ' ')}
                          </span>
                        ))}
                      </div>
                      {getPathaoEventSummary(order.shipments[0]) ? (
                        <p className="text-[11px] text-rose-700">
                          Courier event: {getPathaoEventSummary(order.shipments[0])}
                        </p>
                      ) : null}
                    </div>
                  ) : null}
                  {Array.isArray(order.items) && order.items.length > 0 ? (
                    <div className="mt-2 flex flex-wrap gap-1">
                      {order.items.slice(0, 2).map((item: any) => (
                        <span
                          key={item.id}
                          className="dashboard-stat-chip bg-slate-100 text-slate-600"
                        >
                          {item.sku || 'SKU pending'}
                        </span>
                      ))}
                    </div>
                  ) : null}
                  {order.can_edit || order.can_cancel ? (
                    <div className="mt-3 flex flex-wrap items-center gap-2">
                      <span className="dashboard-stat-chip bg-emerald-50 text-emerald-700 uppercase tracking-wider">
                        Editable before seller accepts
                      </span>
                      {order.can_edit ? (
                        <button
                          onClick={() => void handleEditOrder(order)}
                          disabled={editingOrderId === String(order.id) || cancellingOrderId === String(order.id)}
                          className="inline-flex items-center justify-center rounded-xl border border-slate-200 bg-white px-3 py-2 text-[11px] font-semibold text-slate-700 transition hover:bg-slate-50 disabled:cursor-not-allowed disabled:opacity-50"
                        >
                          {editingOrderId === String(order.id) ? <Loader2 size={14} className="animate-spin" /> : 'Edit order'}
                        </button>
                      ) : null}
                      {order.can_cancel ? (
                        <button
                          onClick={() => void handleCancelOrder(order)}
                          disabled={cancellingOrderId === String(order.id) || editingOrderId === String(order.id)}
                          className="inline-flex items-center justify-center rounded-xl border border-rose-200 bg-rose-50 px-3 py-2 text-[11px] font-semibold text-rose-700 transition hover:bg-rose-100 disabled:cursor-not-allowed disabled:opacity-50"
                        >
                          {cancellingOrderId === String(order.id) ? <Loader2 size={14} className="animate-spin" /> : 'Cancel order'}
                        </button>
                      ) : null}
                    </div>
                  ) : null}
                  {!order.can_edit && !order.can_cancel && order.customer_action_block_reason ? (
                    <p className="mt-3 text-[11px] text-slate-500">{order.customer_action_block_reason}</p>
                  ) : null}
                </div>

                <div className="flex items-center justify-between sm:justify-start sm:gap-6">
                  <div className="text-left">
                    <p className="mb-1 text-xs uppercase tracking-wider text-gray-500">Total</p>
                    <p className="font-bold">{formatPrice(order.total)}</p>
                  </div>
                  <Link
                    to={`/account/orders/${order.id}`}
                    className="inline-flex items-center gap-2 rounded-xl border border-gray-200 px-3 py-2 text-xs font-semibold text-slate-700 transition hover:bg-gray-50"
                  >
                    <span>Open order</span>
                    <ChevronRight size={16} className="text-gray-400" />
                  </Link>
                </div>
              </div>
            </div>
          ))}
        </div>
      )}
    </div>
  );
};

import React from 'react';
import { useInventoryState } from '../../../features/inventory/state/InventoryContext';
import toast from '@/lib/toast';
import { useInventoryActions } from '@/features/inventory/hooks/useInventoryActions';

const PurchaseOrderList: React.FC = () => {
  const { purchaseOrders, warehouses, inventory, suppliers } = useInventoryState();
  const { createPO, cancelPO } = useInventoryActions();
  const [focusedProductId, setFocusedProductId] = React.useState('');
  const [focusedPurchaseOrderId, setFocusedPurchaseOrderId] = React.useState('');
  const [pendingCancelId, setPendingCancelId] = React.useState('');
  const [submitting, setSubmitting] = React.useState(false);
  const [poForm, setPoForm] = React.useState({
    supplierId: '',
    quantity: '',
    unitCost: '',
  });

  React.useEffect(() => {
    if (typeof window === 'undefined') return;

    const params = new URLSearchParams(window.location.search);
    const nextProductId = params.get('product');
    const nextSection = params.get('section');
    const nextPurchaseOrderId = params.get('po');

    if (nextProductId) {
      setFocusedProductId(nextProductId);
    }
    if (nextPurchaseOrderId) {
      setFocusedPurchaseOrderId(nextPurchaseOrderId);
    }

    if (nextSection === 'po' || nextProductId) {
      const timeoutId = window.setTimeout(() => {
        document.getElementById('inventory-po-section')?.scrollIntoView({
          behavior: 'smooth',
          block: 'start',
        });
      }, 150);

      return () => window.clearTimeout(timeoutId);
    }
  }, []);

  const contextualInventoryItem = React.useMemo(
    () => inventory.find((item) => String(item.productId) === focusedProductId),
    [focusedProductId, inventory],
  );

  const contextualWarehouse = React.useMemo(
    () => warehouses.find((warehouse) => warehouse.id === contextualInventoryItem?.warehouseId),
    [contextualInventoryItem?.warehouseId, warehouses],
  );

  React.useEffect(() => {
    if (!focusedPurchaseOrderId) return;

    const matched = purchaseOrders.find((purchaseOrder) => purchaseOrder.id === focusedPurchaseOrderId);
    if (!matched) return;

    const timeoutId = window.setTimeout(() => {
      document.getElementById(`inventory-po-${matched.id}`)?.scrollIntoView({
        behavior: 'smooth',
        block: 'center',
      });
    }, 120);

    return () => window.clearTimeout(timeoutId);
  }, [focusedPurchaseOrderId, purchaseOrders]);

  React.useEffect(() => {
    if (!suppliers[0]?.id) return;
    setPoForm((current) => (current.supplierId ? current : { ...current, supplierId: suppliers[0].id }));
  }, [suppliers]);

  React.useEffect(() => {
    if (!focusedProductId) return;
    setPoForm((current) => ({
      ...current,
      quantity: current.quantity || String(Math.max(contextualInventoryItem?.reorderLevel ?? 5, 1)),
    }));
  }, [contextualInventoryItem?.reorderLevel, focusedProductId]);

  const handleCreate = async () => {
    if (!focusedProductId) {
      toast.error('Open the restock workflow from a low-stock product first.');
      return;
    }
    if (!contextualInventoryItem?.warehouseId) {
      toast.error('This product is missing a warehouse link.');
      return;
    }

    const supplierId = poForm.supplierId.trim();
    const quantity = Number.parseInt(poForm.quantity, 10);
    const unitCost = Number(poForm.unitCost);
    if (!supplierId) {
      toast.error('Supplier is required.');
      return;
    }
    if (Number.isNaN(quantity) || quantity <= 0) {
      toast.error('Enter a valid restock quantity.');
      return;
    }
    if (Number.isNaN(unitCost) || unitCost < 0) {
      toast.error('Enter a valid estimated unit cost.');
      return;
    }

    try {
      setSubmitting(true);
      const created = await createPO({
        supplierId,
        warehouseId: contextualInventoryItem.warehouseId,
        items: [{ productId: focusedProductId, quantity, unitCost }],
        status: 'pending',
        expectedDelivery: undefined,
        createdAt: new Date().toISOString(),
        updatedAt: new Date().toISOString(),
      });
      setPoForm((current) => ({ ...current, quantity: '', unitCost: '' }));
      if (created?.id) {
        setFocusedPurchaseOrderId(created.id);
      }
      toast.success('Purchase order created.');
    } catch (error) {
      toast.error('Failed to create purchase order.');
    } finally {
      setSubmitting(false);
    }
  };

  const handleCancel = async (id: string) => {
    await cancelPO(id);
    setPendingCancelId('');
  };

  return (
    <div id="inventory-po-section" className="mt-6 p-4">
      <h2 className="mb-2 text-xl font-semibold">Purchase Orders</h2>
      {focusedProductId ? (
        <div className="mb-4 rounded-xl border border-amber-200 bg-amber-50 px-4 py-3 text-sm text-amber-800">
          <p className="font-semibold">Restock workflow ready for product {focusedProductId}</p>
          <p className="mt-1">
            {contextualWarehouse
              ? `Suggested pickup warehouse: ${contextualWarehouse.name}`
              : 'Select a supplier to create a purchase order for this product.'}
          </p>
          <div className="mt-3 flex flex-wrap gap-3 text-xs font-semibold">
            <a href="/admin/inventory?section=suppliers" className="text-slate-700 hover:text-primary hover:underline">
              Open suppliers
            </a>
            <a href={`/admin/inventory?product=${encodeURIComponent(focusedProductId)}`} className="text-slate-700 hover:text-primary hover:underline">
              Open stock row
            </a>
          </div>
        </div>
      ) : null}
      {focusedProductId ? (
        <div className="mb-4 grid gap-3 rounded-xl border border-slate-200 bg-slate-50 p-4 md:grid-cols-[1.2fr_1fr_1fr_auto]">
          <select
            value={poForm.supplierId}
            onChange={(event) => setPoForm((current) => ({ ...current, supplierId: event.target.value }))}
            className="rounded-xl border border-slate-200 bg-white px-4 py-3 text-sm"
          >
            <option value="">Select supplier</option>
            {suppliers.map((supplier) => (
              <option key={supplier.id} value={supplier.id}>
                {supplier.name}
              </option>
            ))}
          </select>
          <input
            value={poForm.quantity}
            onChange={(event) => setPoForm((current) => ({ ...current, quantity: event.target.value }))}
            className="rounded-xl border border-slate-200 bg-white px-4 py-3 text-sm"
            placeholder="Restock quantity"
          />
          <input
            value={poForm.unitCost}
            onChange={(event) => setPoForm((current) => ({ ...current, unitCost: event.target.value }))}
            className="rounded-xl border border-slate-200 bg-white px-4 py-3 text-sm"
            placeholder="Estimated unit cost"
          />
          <button
            className="rounded bg-slate-900 px-3 py-1 text-white disabled:opacity-60"
            onClick={() => void handleCreate()}
            disabled={submitting}
          >
            {submitting ? 'Creating...' : 'Create PO'}
          </button>
        </div>
      ) : (
        <p className="mb-4 rounded-xl border border-slate-200 bg-slate-50 px-4 py-3 text-sm text-slate-600">
          Open this section from a low-stock product or the restock queue to create a purchase order with the correct product and warehouse context.
        </p>
      )}
      {purchaseOrders.length === 0 ? (
        <p className="mt-4 text-gray-500">No purchase orders.</p>
      ) : (
        <ul className="mt-4 space-y-2">
          {purchaseOrders.map((purchaseOrder) => (
            <li
              id={`inventory-po-${purchaseOrder.id}`}
              key={purchaseOrder.id}
              className={`flex items-center justify-between rounded border p-2 transition-colors ${
                purchaseOrder.id === focusedPurchaseOrderId ? 'border-indigo-300 bg-indigo-50 ring-2 ring-indigo-200' : ''
              }`}
            >
              <span>
                PO #{purchaseOrder.id.slice(0, 8)} - {purchaseOrder.status}
              </span>
              {purchaseOrder.status !== 'cancelled' ? (
                pendingCancelId === purchaseOrder.id ? (
                  <div className="flex items-center gap-2 text-xs font-semibold">
                    <button className="text-red-600" onClick={() => void handleCancel(purchaseOrder.id)}>
                      Confirm cancel
                    </button>
                    <button className="text-slate-500" onClick={() => setPendingCancelId('')}>
                      Keep
                    </button>
                  </div>
                ) : (
                  <button className="text-red-600" onClick={() => setPendingCancelId(purchaseOrder.id)}>
                    Cancel
                  </button>
                )
              ) : null}
            </li>
          ))}
        </ul>
      )}
    </div>
  );
};

export default PurchaseOrderList;

import React, { useEffect, useMemo, useState } from 'react';
import { Building2, Loader2, MapPin, Phone, RefreshCw, Save, Store, Truck } from 'lucide-react';
import toast from '@/lib/toast';
import { useInventoryState } from '../../../features/inventory/state/InventoryContext';
import { useInventoryActions } from '@/features/inventory/hooks/useInventoryActions';
import { inventoryApi } from '@/features/inventory/services/inventoryApi';

type PathaoOption = {
  id: number;
  name: string;
  extra?: string;
};

type PathaoFormState = {
  contactName: string;
  secondaryContact: string;
  otpNumber: string;
  cityId: string;
  zoneId: string;
  areaId: string;
  storeId: string;
  insideDhakaFee: string;
  outsideDhakaFee: string;
  insideDhakaEta: string;
  outsideDhakaEta: string;
  freeShippingThresholdOverride: string;
};

const WarehouseList: React.FC = () => {
  const { warehouses } = useInventoryState();
  const { addWarehouse, removeWarehouse, loadAll } = useInventoryActions();
  const [selectedWarehouseId, setSelectedWarehouseId] = useState<string>('');
  const [newWarehouse, setNewWarehouse] = useState({
    name: '',
    address: '',
    city: 'Dhaka',
    postalCode: '1200',
  });
  const [creatingWarehouse, setCreatingWarehouse] = useState(false);
  const [pendingDeleteWarehouseId, setPendingDeleteWarehouseId] = useState('');
  const [form, setForm] = useState<PathaoFormState>({
    contactName: '',
    secondaryContact: '',
    otpNumber: '',
    cityId: '',
    zoneId: '',
    areaId: '',
    storeId: '',
    insideDhakaFee: '',
    outsideDhakaFee: '',
    insideDhakaEta: '1-2 business days',
    outsideDhakaEta: '2-4 business days',
    freeShippingThresholdOverride: '',
  });
  const [cities, setCities] = useState<PathaoOption[]>([]);
  const [zones, setZones] = useState<PathaoOption[]>([]);
  const [areas, setAreas] = useState<PathaoOption[]>([]);
  const [stores, setStores] = useState<PathaoOption[]>([]);
  const [loadingMeta, setLoadingMeta] = useState(false);
  const [saving, setSaving] = useState(false);
  const [creatingStore, setCreatingStore] = useState(false);
  const [focusedWarehouseId, setFocusedWarehouseId] = useState('');

  const handleAddWarehouse = async () => {
    const name = newWarehouse.name.trim();
    const address = newWarehouse.address.trim();
    const city = newWarehouse.city.trim() || 'Dhaka';
    const postalCode = newWarehouse.postalCode.trim() || '1200';
    if (!name) {
      toast.error('Warehouse name is required.');
      return;
    }
    if (!address) {
      toast.error('Warehouse address is required.');
      return;
    }

    const now = new Date().toISOString();
    try {
      setCreatingWarehouse(true);
      await addWarehouse({
        name,
        location: {
          address,
          city,
          country: 'Bangladesh',
          postalCode,
        },
        createdAt: now,
        updatedAt: now,
      });
      setNewWarehouse({
        name: '',
        address: '',
        city: 'Dhaka',
        postalCode: '1200',
      });
      toast.success('Warehouse created. Update its address and Pathao mapping next.');
    } catch {
      toast.error('Failed to create warehouse.');
    } finally {
      setCreatingWarehouse(false);
    }
  };

  const handleRemoveWarehouse = async (warehouseId: string) => {
    try {
      await removeWarehouse(warehouseId);
      toast.success('Warehouse removed.');
      setPendingDeleteWarehouseId('');
      if (selectedWarehouseId === warehouseId) {
        setSelectedWarehouseId('');
      }
    } catch {
      toast.error('Failed to remove warehouse.');
    }
  };

  const selectedWarehouse = useMemo(
    () => warehouses.find((warehouse) => warehouse.id === selectedWarehouseId) || warehouses[0] || null,
    [selectedWarehouseId, warehouses],
  );

  useEffect(() => {
    if (!selectedWarehouseId && warehouses[0]?.id) {
      setSelectedWarehouseId(warehouses[0].id);
    }
  }, [selectedWarehouseId, warehouses]);

  useEffect(() => {
    if (typeof window === 'undefined' || warehouses.length === 0) return;

    const warehouseId = new URLSearchParams(window.location.search).get('warehouse');
    if (!warehouseId) return;

    const matched = warehouses.find((warehouse) => warehouse.id === warehouseId);
    if (!matched) return;

    setSelectedWarehouseId(matched.id);
    setFocusedWarehouseId(matched.id);

    window.requestAnimationFrame(() => {
      document.getElementById(`admin-warehouse-${matched.id}`)?.scrollIntoView({
        behavior: 'smooth',
        block: 'center',
      });
    });
  }, [warehouses]);

  useEffect(() => {
    if (!selectedWarehouse) return;

    setForm({
      contactName: selectedWarehouse.contact?.name || '',
      secondaryContact: selectedWarehouse.contact?.secondaryPhone || '',
      otpNumber: selectedWarehouse.contact?.otpNumber || '',
      cityId: selectedWarehouse.pathao?.cityId ? String(selectedWarehouse.pathao.cityId) : '',
      zoneId: selectedWarehouse.pathao?.zoneId ? String(selectedWarehouse.pathao.zoneId) : '',
      areaId: selectedWarehouse.pathao?.areaId ? String(selectedWarehouse.pathao.areaId) : '',
      storeId: selectedWarehouse.pathao?.storeId ? String(selectedWarehouse.pathao.storeId) : '',
      insideDhakaFee: selectedWarehouse.shipping?.insideDhakaFee != null ? String(selectedWarehouse.shipping.insideDhakaFee) : '',
      outsideDhakaFee: selectedWarehouse.shipping?.outsideDhakaFee != null ? String(selectedWarehouse.shipping.outsideDhakaFee) : '',
      insideDhakaEta: selectedWarehouse.shipping?.insideDhakaEta || '1-2 business days',
      outsideDhakaEta: selectedWarehouse.shipping?.outsideDhakaEta || '2-4 business days',
      freeShippingThresholdOverride:
        selectedWarehouse.shipping?.freeShippingThresholdOverride != null
          ? String(selectedWarehouse.shipping.freeShippingThresholdOverride)
          : '',
    });
  }, [selectedWarehouse]);

  useEffect(() => {
    let ignore = false;

    const loadMeta = async () => {
      try {
        setLoadingMeta(true);
        const [cityPayload, storePayload] = await Promise.all([
          inventoryApi.fetchPathaoCities(),
          inventoryApi.fetchPathaoStores(),
        ]);

        if (ignore) return;

        const cityRows = Array.isArray(cityPayload?.data?.data) ? cityPayload.data.data : [];
        const storeRows = Array.isArray(storePayload?.data?.data) ? storePayload.data.data : [];

        setCities(cityRows.map((item: any) => ({ id: Number(item.city_id), name: String(item.city_name || '') })));
        setStores(
          storeRows.map((item: any) => ({
            id: Number(item.store_id),
            name: String(item.store_name || ''),
            extra: item.is_active === 1 ? 'active' : 'inactive',
          })),
        );
      } catch (error) {
        toast.error('Failed to load Pathao cities or stores.');
      } finally {
        if (!ignore) {
          setLoadingMeta(false);
        }
      }
    };

    void loadMeta();
    return () => {
      ignore = true;
    };
  }, []);

  useEffect(() => {
    let ignore = false;

    const loadZones = async () => {
      const cityId = Number(form.cityId);
      if (!Number.isFinite(cityId) || cityId <= 0) {
        setZones([]);
        return;
      }

      try {
        const payload = await inventoryApi.fetchPathaoZones(cityId);
        if (ignore) return;
        const rows = Array.isArray(payload?.data?.data) ? payload.data.data : [];
        setZones(rows.map((item: any) => ({ id: Number(item.zone_id), name: String(item.zone_name || '') })));
      } catch {
        if (!ignore) {
          setZones([]);
        }
      }
    };

    void loadZones();
    return () => {
      ignore = true;
    };
  }, [form.cityId]);

  useEffect(() => {
    let ignore = false;

    const loadAreas = async () => {
      const zoneId = Number(form.zoneId);
      if (!Number.isFinite(zoneId) || zoneId <= 0) {
        setAreas([]);
        return;
      }

      try {
        const payload = await inventoryApi.fetchPathaoAreas(zoneId);
        if (ignore) return;
        const rows = Array.isArray(payload?.data?.data) ? payload.data.data : [];
        setAreas(
          rows.map((item: any) => ({
            id: Number(item.area_id),
            name: String(item.area_name || '').trim(),
            extra: item.home_delivery_available ? 'home delivery' : 'pickup only',
          })),
        );
      } catch {
        if (!ignore) {
          setAreas([]);
        }
      }
    };

    void loadAreas();
    return () => {
      ignore = true;
    };
  }, [form.zoneId]);

  const handleSave = async () => {
    if (!selectedWarehouse) return;

    try {
      setSaving(true);
      await inventoryApi.updateWarehouse(selectedWarehouse.id, {
        name: selectedWarehouse.name,
        location: selectedWarehouse.location,
        contact: selectedWarehouse.contact,
        pathao: selectedWarehouse.pathao,
        shipping: {
          insideDhakaFee: form.insideDhakaFee ? Number(form.insideDhakaFee) : undefined,
          outsideDhakaFee: form.outsideDhakaFee ? Number(form.outsideDhakaFee) : undefined,
          insideDhakaEta: form.insideDhakaEta.trim() || undefined,
          outsideDhakaEta: form.outsideDhakaEta.trim() || undefined,
          freeShippingThresholdOverride: form.freeShippingThresholdOverride ? Number(form.freeShippingThresholdOverride) : undefined,
        },
        capacity: selectedWarehouse.capacity,
        createdAt: selectedWarehouse.createdAt,
        updatedAt: new Date().toISOString(),
      });
      await inventoryApi.updateWarehousePathaoConfig(selectedWarehouse.id, {
        contactName: form.contactName,
        secondaryContact: form.secondaryContact,
        otpNumber: form.otpNumber,
        cityId: form.cityId ? Number(form.cityId) : null,
        zoneId: form.zoneId ? Number(form.zoneId) : null,
        areaId: form.areaId ? Number(form.areaId) : null,
        storeId: form.storeId ? Number(form.storeId) : null,
      });
      await loadAll();
      toast.success('Warehouse courier and shipping configuration saved.');
    } catch (error: any) {
      toast.error(error?.response?.data?.error || 'Failed to save warehouse shipping configuration.');
    } finally {
      setSaving(false);
    }
  };

  const handleCreateStore = async () => {
    if (!selectedWarehouse) return;

    try {
      setCreatingStore(true);
      const payload = await inventoryApi.createPathaoStore({ warehouseId: selectedWarehouse.id });
      const nextStoreId = Number(payload?.store_id || 0);
      if (nextStoreId) {
        setForm((current) => ({ ...current, storeId: String(nextStoreId) }));
      }
      toast.success(nextStoreId ? `Pathao store created and linked: ${nextStoreId}` : 'Pathao store request sent successfully.');
    } catch (error: any) {
      toast.error(error?.response?.data?.error || 'Failed to create Pathao store.');
    } finally {
      setCreatingStore(false);
    }
  };

  if (warehouses.length === 0) {
    return (
      <div className="rounded-3xl border border-dashed border-slate-200 bg-white p-6 shadow-sm">
        <h2 className="text-xl font-semibold">Warehouses</h2>
        <p className="mt-3 text-sm text-slate-500">No warehouses configured yet.</p>
      </div>
    );
  }

  return (
    <div className="space-y-5 rounded-3xl border border-black/5 bg-white p-6 shadow-sm">
      <div className="flex flex-col gap-3 lg:flex-row lg:items-center lg:justify-between">
        <div>
          <h2 className="text-xl font-semibold">Warehouse and Pathao Mapping</h2>
          <p className="mt-1 text-sm text-slate-500">
            Link each seller pickup location with Pathao city, zone, area, and merchant store for live bookings.
          </p>
        </div>
        <div className="inline-flex items-center gap-2 rounded-full bg-rose-50 px-3 py-1 text-xs font-bold uppercase tracking-[0.16em] text-rose-600">
          <Truck size={14} />
          <span>Pathao Ready</span>
        </div>
      </div>

      <div className="flex justify-end">
        <div className="grid w-full gap-3 rounded-2xl border border-slate-200 bg-slate-50 p-4 md:grid-cols-[1.2fr_1.8fr_1fr_0.8fr_auto]">
          <input
            value={newWarehouse.name}
            onChange={(event) => setNewWarehouse((current) => ({ ...current, name: event.target.value }))}
            className="rounded-xl border border-slate-200 bg-white px-4 py-3 text-sm"
            placeholder="Warehouse name"
          />
          <input
            value={newWarehouse.address}
            onChange={(event) => setNewWarehouse((current) => ({ ...current, address: event.target.value }))}
            className="rounded-xl border border-slate-200 bg-white px-4 py-3 text-sm"
            placeholder="Pickup address"
          />
          <input
            value={newWarehouse.city}
            onChange={(event) => setNewWarehouse((current) => ({ ...current, city: event.target.value }))}
