              <label className="space-y-2 text-sm">
                <span className="font-medium text-slate-700">Secondary phone</span>
                <input
                  value={form.secondaryContact}
                  onChange={(event) => setForm((current) => ({ ...current, secondaryContact: event.target.value }))}
