                  value={form.zoneId}
                  onChange={(event) =>
                    setForm((current) => ({
                      ...current,
                      zoneId: event.target.value,
                      areaId: '',
                    }))
                  }
                  className="w-full rounded-2xl border border-slate-200 bg-white px-4 py-3 text-sm"
                >
                  <option value="">Select zone</option>
                  {zones.map((zone) => (
                    <option key={zone.id} value={zone.id}>
