              </label>
              <label className="space-y-2 text-sm">
                <span className="font-medium text-slate-700">Area</span>
                <select
                  value={form.areaId}
                  onChange={(event) => setForm((current) => ({ ...current, areaId: event.target.value }))}
                  className="w-full rounded-2xl border border-slate-200 bg-white px-4 py-3 text-sm"
                >
                  <option value="">Select area</option>
                  {areas.map((area) => (
                    <option key={area.id} value={area.id}>
                      {area.name} {area.extra ? `- ${area.extra}` : ''}
                    </option>
                  ))}
                </select>
              </label>
            </div>

            <div className="mt-5 rounded-2xl border border-rose-100 bg-white p-4 text-sm text-slate-600">
              <div className="flex items-center gap-2 font-semibold text-rose-600">
                <Store size={16} />
                <span>Pathao store sync</span>
              </div>
              <p className="mt-2">
                Save the city, zone, and area first. Then you can auto-create a Pathao store directly from this warehouse and link the returned `store_id`.
              </p>
            </div>

            <div className="mt-5 rounded-2xl border border-sky-100 bg-white p-4">
              <div className="flex items-center gap-2 font-semibold text-sky-700">
                <Truck size={16} />
                <span>Shipping rules</span>
              </div>
              <p className="mt-2 text-sm text-slate-600">
                Configure warehouse-specific delivery fee and ETA so checkout can show a more realistic preview.
              </p>
              <div className="mt-4 grid gap-4 md:grid-cols-2">
                <label className="space-y-2 text-sm">
                  <span className="font-medium text-slate-700">Inside Dhaka fee (BDT)</span>
                  <input
                    value={form.insideDhakaFee}
                    onChange={(event) => setForm((current) => ({ ...current, insideDhakaFee: event.target.value }))}
                    className="w-full rounded-2xl border border-slate-200 bg-white px-4 py-3 text-sm"
                    placeholder="60"
                  />
                </label>
                <label className="space-y-2 text-sm">
                  <span className="font-medium text-slate-700">Outside Dhaka fee (BDT)</span>
                  <input
                    value={form.outsideDhakaFee}
                    onChange={(event) => setForm((current) => ({ ...current, outsideDhakaFee: event.target.value }))}
                    className="w-full rounded-2xl border border-slate-200 bg-white px-4 py-3 text-sm"
                    placeholder="120"
                  />
                </label>
                <label className="space-y-2 text-sm">
                  <span className="font-medium text-slate-700">Inside Dhaka ETA</span>
                  <input
                    value={form.insideDhakaEta}
                    onChange={(event) => setForm((current) => ({ ...current, insideDhakaEta: event.target.value }))}
                    className="w-full rounded-2xl border border-slate-200 bg-white px-4 py-3 text-sm"
                    placeholder="1-2 business days"
                  />
                </label>
                <label className="space-y-2 text-sm">
                  <span className="font-medium text-slate-700">Outside Dhaka ETA</span>
                  <input
                    value={form.outsideDhakaEta}
                    onChange={(event) => setForm((current) => ({ ...current, outsideDhakaEta: event.target.value }))}
                    className="w-full rounded-2xl border border-slate-200 bg-white px-4 py-3 text-sm"
                    placeholder="2-4 business days"
                  />
                </label>
                <label className="space-y-2 text-sm md:col-span-2">
                  <span className="font-medium text-slate-700">Free shipping threshold override (BDT)</span>
                  <input
                    value={form.freeShippingThresholdOverride}
                    onChange={(event) => setForm((current) => ({ ...current, freeShippingThresholdOverride: event.target.value }))}
                    className="w-full rounded-2xl border border-slate-200 bg-white px-4 py-3 text-sm"
                    placeholder="Leave blank to use marketplace default"
                  />
                </label>
              </div>
            </div>

            <div className="mt-5 flex flex-wrap gap-3">
              <button
                type="button"
                onClick={() => void handleSave()}
                disabled={saving}
                className="inline-flex items-center gap-2 rounded-2xl bg-slate-900 px-4 py-3 text-sm font-bold text-white hover:bg-slate-800 disabled:opacity-50"
              >
                {saving ? <Loader2 className="animate-spin" size={16} /> : <Save size={16} />}
                <span>{saving ? 'Saving...' : 'Save warehouse config'}</span>
              </button>
              <button
                type="button"
                onClick={() => void handleCreateStore()}
                disabled={creatingStore || !form.cityId || !form.zoneId || !form.areaId}
                className="inline-flex items-center gap-2 rounded-2xl bg-rose-600 px-4 py-3 text-sm font-bold text-white hover:bg-rose-700 disabled:opacity-50"
              >
                {creatingStore ? <Loader2 className="animate-spin" size={16} /> : <Store size={16} />}
                <span>{creatingStore ? 'Creating store...' : 'Create Pathao store'}</span>
              </button>
            </div>

            {loadingMeta ? (
              <div className="mt-4 inline-flex items-center gap-2 text-xs font-medium text-slate-500">
                <Loader2 className="animate-spin" size={14} />
                <span>Loading Pathao reference data...</span>
              </div>
            ) : null}
          </div>
        ) : null}
      </div>
    </div>
  );
};

export default WarehouseList;

import { useInventoryDispatch } from '../../../features/inventory/state/InventoryContext';
import { inventoryApi } from '@/features/inventory/services/inventoryApi';
import { Warehouse, Supplier, InventoryItem, PurchaseOrder } from '../../../types/inventory';

export function useInventoryActions() {
  const dispatch = useInventoryDispatch();

  const loadAll = async () => {
    dispatch({ type: 'SET_LOADING', payload: true });
    try {
      const [warehouses, suppliers, inventory, purchaseOrders] = await Promise.all([
        inventoryApi.fetchWarehouses(),
        inventoryApi.fetchSuppliers(),
        inventoryApi.fetchInventory(),
        inventoryApi.fetchPurchaseOrders(),
      ]);
      dispatch({
        type: 'SET_ALL',
        payload: {
          warehouses,
          suppliers,
          inventory,
          purchaseOrders,
        },
      });
    } catch (err: any) {
      dispatch({ type: 'SET_ERROR', payload: err.message });
    } finally {
      dispatch({ type: 'SET_LOADING', payload: false });
    }
  };

  const addWarehouse = async (warehouse: Omit<Warehouse, 'id'>) => {
    const createdWarehouse = await inventoryApi.createWarehouse(warehouse);
    dispatch({ type: 'ADD_WAREHOUSE', payload: createdWarehouse });
  };

  const removeWarehouse = async (id: string) => {
    await inventoryApi.deleteWarehouse(id);
    dispatch({ type: 'REMOVE_WAREHOUSE', payload: { id } });
  };

  const addSupplier = async (supplier: Supplier) => {
    await inventoryApi.createSupplier(supplier);
    dispatch({ type: 'ADD_SUPPLIER', payload: supplier });
  };

  const addInventoryItem = async (item: InventoryItem) => {
    await inventoryApi.createInventoryItem(item);
    dispatch({ type: 'ADD_INVENTORY_ITEM', payload: item });
  };

  const adjustQuantity = async (id: string, delta: number) => {
    await inventoryApi.adjustInventoryQuantity(id, delta);
    dispatch({ type: 'ADJUST_INVENTORY_QUANTITY', payload: { id, delta } });
  };

  const createPO = async (po: Omit<PurchaseOrder, 'id'>) => {
    const created = await inventoryApi.createPurchaseOrder(po);
    dispatch({ type: 'CREATE_PO', payload: created });
    return created;
  };

  const cancelPO = async (id: string) => {
    await inventoryApi.cancelPurchaseOrder(id);
    dispatch({ type: 'CANCEL_PO', payload: { id } });
  };

  return {
    loadAll,
    addWarehouse,
    removeWarehouse,
    addSupplier,
    addInventoryItem,
    adjustQuantity,
    createPO,
    cancelPO,
  };
}

import { useEffect, useState } from 'react';
import { useInventoryDispatch } from '../../../features/inventory/state/InventoryContext';

type SyncStatus = 'idle' | 'connecting' | 'live' | 'local' | 'error';

// Lightweight real-time sync helper.
// In Next.js, client-exposed env vars must be prefixed with NEXT_PUBLIC_.
// If NEXT_PUBLIC_INVENTORY_WS isn't set, we fall back to a small runtime endpoint.
export function useInventorySync(enabled: boolean = true) {
  const dispatch = useInventoryDispatch();
  const [status, setStatus] = useState<SyncStatus>('idle');

  useEffect(() => {
    if (!enabled) {
      setStatus('idle');
      return;
    }

    let cancelled = false;
    let hadError = false;

    const resolveWsUrl = async (): Promise<string | null> => {
      const fromEnv = process.env.NEXT_PUBLIC_INVENTORY_WS;
      if (typeof fromEnv === 'string' && fromEnv.trim()) return fromEnv.trim();

      try {
        const res = await fetch('/api/config/public', {
          method: 'GET',
          headers: { Accept: 'application/json' },
          cache: 'no-store',
        });
        if (!res.ok) return null;
        const data = (await res.json()) as
          | { inventoryWs?: unknown }
          | { ok?: boolean; data?: { inventoryWs?: unknown } };
        const inventoryWs =
          typeof (data as { inventoryWs?: unknown }).inventoryWs === 'string'
            ? (data as { inventoryWs?: string }).inventoryWs
            : (data as { data?: { inventoryWs?: unknown } }).data?.inventoryWs;

        return typeof inventoryWs === 'string' && inventoryWs.trim()
          ? inventoryWs.trim()
          : null;
      } catch {
        return null;
      }
    };

    // When no WS endpoint is configured, keep local state responsive without pretending a live feed exists.
    let timer: ReturnType<typeof setInterval> | undefined;
    let ws: WebSocket | undefined;

    (async () => {
      const wsUrl = await resolveWsUrl();

      if (cancelled) return;

      if (!wsUrl) {
        setStatus('local');
        timer = setInterval(() => {
          // keep reducers warm; no data mutation to avoid test flakiness
          dispatch({ type: 'SET_LOADING', payload: false });
        }, 15000);
        return;
      }

      setStatus('connecting');
      ws = new WebSocket(wsUrl);

      ws.onopen = () => {
        if (!cancelled) setStatus('live');
      };

      ws.onmessage = (event) => {
        try {
          const message = JSON.parse(event.data);
          switch (message.type) {
            case 'inventory_update':
              dispatch({ type: 'UPDATE_INVENTORY_ITEM', payload: message.payload });
              break;
            case 'warehouse_update':
              dispatch({ type: 'UPDATE_WAREHOUSE', payload: message.payload });
              break;
            case 'supplier_update':
              dispatch({ type: 'UPDATE_SUPPLIER', payload: message.payload });
              break;
            case 'purchase_order_update':
              dispatch({ type: 'UPDATE_PO', payload: message.payload });
              break;
            case 'stock':
              dispatch({
                type: 'UPDATE_INVENTORY_ITEM',
                payload: { id: message.productId, stock: message.stock } as any,
              });
              break;
            default:
              break;
          }
        } catch (err) {
          console.error('Failed to parse inventory sync message', err);
          hadError = true;
          setStatus('error');
        }
      };

      ws.onerror = (err) => {
        console.error('Inventory sync error', err);
        hadError = true;
        setStatus('error');
      };

      ws.onclose = () => {
        if (!cancelled && !hadError) setStatus('idle');
      };
    })();

    return () => {
      cancelled = true;
      if (timer) clearInterval(timer);
      try {
        ws?.close();
      } catch {
        // ignore
      }
    };
  }, [dispatch, enabled]);

  return { status };
}

import api from '../../../lib/api';
import { Warehouse, Supplier, InventoryItem, PurchaseOrder } from '../../../types/inventory';

const CACHE_TTL = 5 * 60 * 1000; // 5min

function getBrowserStorage() {
  if (typeof globalThis === 'undefined' || !('localStorage' in globalThis)) {
    return null;
  }

  return globalThis.localStorage;
}

// Helper: Cache with TTL
const getCached = async (key: string): Promise<any> => {
  const storage = getBrowserStorage();
  const cached = storage?.getItem(`inventory_${key}`);
  if (cached) {
    const { data, timestamp } = JSON.parse(cached);
    if (Date.now() - timestamp < CACHE_TTL) return data;
  }
  return null;
};

const setCached = (key: string, data: any) => {
  const storage = getBrowserStorage();
  storage?.setItem(`inventory_${key}`, JSON.stringify({
    data,
    timestamp: Date.now()
  }));
};

const clearCached = (key: string) => {
  const storage = getBrowserStorage();
  storage?.removeItem(`inventory_${key}`);
};

const silentFallback = <T,>(fallback: T): T => fallback;

export const inventoryApi = {
  async fetchWarehouses(): Promise<Warehouse[]> {
    try {
      const cached = await getCached('warehouses');
      if (cached) return cached;
      
      const res = await api.get('/admin/inventory/warehouses');
      setCached('warehouses', res.data);
      return res.data;
    } catch {
      return silentFallback([]);
    }
  },

  async createWarehouse(warehouse: Omit<Warehouse, 'id'>): Promise<Warehouse> {
    const res = await api.post('/admin/inventory/warehouses', warehouse);
    clearCached('warehouses');
    return res.data;
  },

  async updateWarehouse(warehouseId: string, warehouse: Omit<Warehouse, 'id'>): Promise<Warehouse> {
    const res = await api.patch(`/admin/inventory/warehouses/${warehouseId}`, warehouse);
    clearCached('warehouses');
    return res.data;
  },

  async deleteWarehouse(id: string): Promise<void> {
    await api.delete(`/admin/inventory/warehouses/${id}`);
    clearCached('warehouses');
  },

  async updateWarehousePathaoConfig(
    warehouseId: string,
