interface TrackingStep {
  label: string;
  date: string;
  completed: boolean;
}

interface ShipmentItem {
  id: string;
  name?: string;
  sku?: string | null;
  quantity?: number;
}

interface TrackingShipment {
  id: string;
  status: string;
  item_count?: number;
