                <div>
                  <p className={`font-bold ${step.completed ? 'text-gray-900' : 'text-gray-400'}`}>{step.label}</p>
                  <p className="text-sm text-gray-500">{step.date}</p>
                </div>
              </div>
            ))}
          </div>
        </motion.div>
      )}
    </div>
  );
};

import React, { useEffect, useMemo, useState } from 'react';
import { ArrowDownLeft, ArrowUpRight, CreditCard, Download, Loader2, Wallet } from 'lucide-react';
import toast from '@/lib/toast';
import { formatPrice } from '../../../lib/utils';
import { useUser } from '../../../features/shared/state/UserContext';

interface ResellerCommission {
  id: string;
  amount: number;
  status: string;
  product_id?: string | null;
  order_id?: string | null;
  created_at?: string;
}

interface ResellerPayout {
  id: string;
  amount: number;
  status: string;
  created_at: string;
}

interface EarningsData {
  availableBalance: number;
  totalEarned: number;
  pendingAmount: number;
  nextPayout: number;
  commissions: ResellerCommission[];
}

const emptyData: EarningsData = {
  availableBalance: 0,
  totalEarned: 0,
  pendingAmount: 0,
  nextPayout: 0,
  commissions: [],
};

export const ResellerEarnings = () => {
  const { token } = useUser();
  const [loading, setLoading] = useState(true);
  const [data, setData] = useState<EarningsData>(emptyData);
  const [payouts, setPayouts] = useState<ResellerPayout[]>([]);
  const [requesting, setRequesting] = useState(false);
  const [amount, setAmount] = useState('');
  const [note, setNote] = useState('');
  const [error, setError] = useState('');

  useEffect(() => {
    const fetchEarnings = async () => {
      if (!token) {
        setError('Please log in as a reseller to view earnings and request payouts.');
        setLoading(false);
        return;
      }

      try {
        setLoading(true);
        setError('');

        const [earningsRes, payoutsRes] = await Promise.all([
          fetch('/api/reseller/earnings', { headers: { Authorization: `Bearer ${token}` } }),
          fetch('/api/reseller/payouts', { headers: { Authorization: `Bearer ${token}` } }),
        ]);

        const earnings = (await earningsRes.json().catch(() => null)) as EarningsData | null;
        const payoutRows = (await payoutsRes.json().catch(() => null)) as ResellerPayout[] | null;
        if (!earningsRes.ok || !payoutsRes.ok) {
          throw new Error((earnings as any)?.error || (payoutRows as any)?.error || 'Failed to load reseller earnings');
        }
        if (!earnings) {
          throw new Error('Failed to load reseller earnings');
        }
        setData({ ...emptyData, ...earnings, commissions: earnings.commissions ?? [] });
        setPayouts(Array.isArray(payoutRows) ? payoutRows : []);
      } catch (fetchError) {
        setError(
          fetchError instanceof Error
            ? fetchError.message
            : 'Live earnings could not be loaded right now. Please try again shortly.',
        );
        setData(emptyData);
        setPayouts([]);
      } finally {
        setLoading(false);
      }
    };

    void fetchEarnings();
  }, [token]);

  const transactions = useMemo(() => data.commissions ?? [], [data.commissions]);

  const requestPayout = async () => {
    const numericAmount = Number(amount);
    if (!token) {
      setError('Please log in as a reseller first.');
      return;
    }
    if (!numericAmount || numericAmount < 500) {
      setError('Minimum payout request is 500.');
      return;
    }

    setRequesting(true);
    setError('');
    try {
      const response = await fetch('/api/reseller/payout-request', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          Authorization: `Bearer ${token}`,
        },
        body: JSON.stringify({ amount: numericAmount, notes: note }),
      });

      if (!response.ok) {
        const payload = await response.json().catch(() => ({}));
        throw new Error(payload.error || 'Failed to request payout');
      }

      setPayouts((current) => [
        {
          id: `local-${Date.now()}`,
          amount: numericAmount,
          status: 'pending',
          created_at: new Date().toISOString(),
        },
        ...current,
      ]);
      setAmount('');
      setNote('');
      toast.success('Payout request submitted.');
    } catch (requestError) {
      setError(requestError instanceof Error ? requestError.message : 'Failed to request payout');
    } finally {
      setRequesting(false);
    }
  };

  const handleExportCsv = () => {
    if (transactions.length === 0) {
      toast.error('No commission history is available to export.');
      return;
    }

    const rows = [
      ['Transaction ID', 'Created', 'Product', 'Order', 'Amount', 'Status'],
      ...transactions.map((transaction) => [
        transaction.id,
        transaction.created_at ? new Date(transaction.created_at).toLocaleString() : '-',
        transaction.product_id ?? '-',
        transaction.order_id ?? '-',
        String(transaction.amount),
        transaction.status,
      ]),
    ];
    const csv = rows.map((row) => row.map((value) => `"${String(value).replace(/"/g, '""')}"`).join(',')).join('\n');
    const blob = new Blob([csv], { type: 'text/csv;charset=utf-8;' });
    const objectUrl = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.href = objectUrl;
    link.download = 'reseller-earnings.csv';
    link.click();
    URL.revokeObjectURL(objectUrl);
  };

  if (loading) {
    return (
      <div className="flex justify-center p-12">
        <Loader2 className="animate-spin text-primary" />
      </div>
    );
  }

  return (
    <div className="space-y-8">
      {error ? (
        <div className="rounded-xl border border-amber-200 bg-amber-50 p-4 text-sm text-amber-800">
          {error}
        </div>
      ) : null}

      <div className="flex flex-col gap-4 md:flex-row md:items-center md:justify-between">
        <div>
          <h1 className="text-2xl font-bold tracking-tight">Earnings & Payouts</h1>
          <p className="text-gray-500">Track your commissions and manage reseller withdrawals.</p>
        </div>
        <div className="flex flex-col gap-2 md:flex-row md:items-center">
          <input
            type="number"
            min="0"
            value={amount}
            onChange={(event) => setAmount(event.target.value)}
            placeholder="Payout amount"
            className="rounded-xl border bg-gray-50 px-4 py-2 text-sm"
          />
          <input
            type="text"
            value={note}
            onChange={(event) => setNote(event.target.value)}
            placeholder="Note (optional)"
            className="rounded-xl border bg-gray-50 px-4 py-2 text-sm"
          />
          <button
            onClick={() => void requestPayout()}
            disabled={!amount || requesting}
            className="flex items-center gap-2 rounded-2xl bg-primary px-6 py-3 font-bold text-white shadow-lg shadow-primary/20 transition-all hover:bg-primary/90 disabled:opacity-50"
          >
            <CreditCard size={18} />
            <span>{requesting ? 'Requesting...' : 'Request Payout'}</span>
          </button>
        </div>
      </div>

      <div className="grid grid-cols-1 gap-6 lg:grid-cols-3">
        <div className="lg:col-span-2 overflow-hidden rounded-[40px] bg-gradient-to-br from-primary to-indigo-700 p-8 text-white shadow-xl">
          <p className="mb-2 text-sm font-medium text-primary-foreground/80">Available Balance</p>
          <h2 className="mb-8 text-4xl font-bold">{formatPrice(data.availableBalance)}</h2>
          <div className="flex gap-8">
            <div>
              <p className="mb-1 text-xs uppercase tracking-wider text-primary-foreground/60">
                Total Earned
              </p>
              <p className="text-lg font-bold">{formatPrice(data.totalEarned)}</p>
            </div>
            <div>
              <p className="mb-1 text-xs uppercase tracking-wider text-primary-foreground/60">
                Pending
              </p>
              <p className="text-lg font-bold">{formatPrice(data.pendingAmount)}</p>
            </div>
          </div>
        </div>

        <div className="flex flex-col justify-between rounded-[40px] border border-black/5 bg-white p-8 shadow-sm">
          <div>
            <div className="mb-4 flex h-12 w-12 items-center justify-center rounded-2xl bg-emerald-50 text-emerald-600">
              <Wallet size={24} />
            </div>
            <h3 className="mb-1 text-lg font-bold">Next Payout</h3>
            <p className="text-sm text-gray-500">Pending payout requests awaiting review.</p>
          </div>
          <div className="border-t border-gray-50 pt-4">
            <p className="text-2xl font-bold text-emerald-600">{formatPrice(data.nextPayout || 0)}</p>
            <p className="text-xs text-gray-400">Minimum payout: {formatPrice(500)}</p>
          </div>
        </div>
      </div>

      <div className="overflow-hidden rounded-3xl border border-black/5 bg-white shadow-sm">
        <div className="flex items-center justify-between border-b border-gray-50 p-6">
          <h3 className="text-lg font-bold">Payout Requests</h3>
          <span className="text-xs text-gray-500">Latest</span>
        </div>
        <div className="overflow-x-auto">
          <table className="w-full text-left">
            <thead>
              <tr className="bg-gray-50/50">
                <th className="px-6 py-4 text-xs font-bold uppercase tracking-wider text-gray-500">Amount</th>
                <th className="px-6 py-4 text-xs font-bold uppercase tracking-wider text-gray-500">Status</th>
                <th className="px-6 py-4 text-xs font-bold uppercase tracking-wider text-gray-500">Requested</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-gray-50">
              {payouts.length === 0 ? (
                <tr>
                  <td colSpan={3} className="px-6 py-4 text-sm text-gray-500">
                    No payout requests yet.
                  </td>
                </tr>
              ) : (
                payouts.map((payout) => (
                  <tr key={payout.id}>
                    <td className="px-6 py-4 text-sm font-bold">{formatPrice(payout.amount)}</td>
                    <td className="px-6 py-4 text-xs font-bold uppercase">
                      <span
                        className={`rounded-full px-2 py-1 ${
                          payout.status === 'paid'
                            ? 'bg-emerald-100 text-emerald-800'
                            : 'bg-orange-100 text-orange-800'
                        }`}
                      >
                        {payout.status}
                      </span>
                    </td>
                    <td className="px-6 py-4 text-sm text-gray-500">
                      {new Date(payout.created_at).toLocaleString()}
                    </td>
                  </tr>
                ))
              )}
            </tbody>
          </table>
        </div>
      </div>

      <div className="overflow-hidden rounded-3xl border border-black/5 bg-white shadow-sm">
        <div className="flex flex-col gap-4 border-b border-gray-50 p-6 md:flex-row md:items-center md:justify-between">
          <h3 className="text-lg font-bold">Commission History</h3>
          <button
            onClick={handleExportCsv}
            className="inline-flex items-center gap-2 rounded-xl bg-gray-50 px-4 py-2 text-sm font-bold text-gray-600 transition-all hover:bg-gray-100"
          >
            <Download size={18} />
            Export CSV
          </button>
        </div>
        <div className="overflow-x-auto">
          <table className="w-full text-left">
            <thead>
              <tr className="bg-gray-50/50">
                <th className="px-6 py-4 text-xs font-bold uppercase tracking-wider text-gray-500">Transaction</th>
                <th className="px-6 py-4 text-xs font-bold uppercase tracking-wider text-gray-500">Date</th>
                <th className="px-6 py-4 text-xs font-bold uppercase tracking-wider text-gray-500">Amount</th>
                <th className="px-6 py-4 text-xs font-bold uppercase tracking-wider text-gray-500">Status</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-gray-50">
              {transactions.length === 0 ? (
                <tr>
                  <td colSpan={4} className="px-6 py-12 text-center text-sm text-gray-500">
                    No commission records yet.
                  </td>
                </tr>
              ) : (
                transactions.map((transaction) => (
                  <tr key={transaction.id} className="hover:bg-gray-50/50 transition-colors">
                    <td className="px-6 py-4">
                      <div className="flex items-center gap-3">
                        <div className="flex h-10 w-10 items-center justify-center rounded-full bg-emerald-50 text-emerald-600">
                          {transaction.amount >= 0 ? <ArrowUpRight size={20} /> : <ArrowDownLeft size={20} />}
                        </div>
                        <div>
                          <p className="text-sm font-bold">
                            {transaction.order_id ? `Order ${transaction.order_id}` : `Product ${transaction.product_id || '-'}`}
                          </p>
                          <p className="text-xs text-gray-500">Commission</p>
                        </div>
                      </div>
                    </td>
                    <td className="px-6 py-4 text-sm text-gray-500">
                      {transaction.created_at ? new Date(transaction.created_at).toLocaleDateString() : '-'}
                    </td>
                    <td className="px-6 py-4 text-sm font-bold text-emerald-600">
                      +{formatPrice(transaction.amount)}
                    </td>
                    <td className="px-6 py-4">
                      <span
                        className={`rounded-full px-2 py-1 text-[10px] font-bold uppercase tracking-wider ${
                          transaction.status === 'paid'
                            ? 'bg-emerald-100 text-emerald-800'
                            : 'bg-orange-100 text-orange-800'
                        }`}
                      >
                        {transaction.status}
                      </span>
                    </td>
                  </tr>
                ))
              )}
            </tbody>
          </table>
        </div>
      </div>
    </div>
  );
};

"use client";

import React, { useEffect, useMemo, useState } from 'react';
import { ArrowRight, CheckCircle2, Loader2, Share2, Sparkles, Store, Wallet } from 'lucide-react';
import toast from '@/lib/toast';
import { Link } from '../../../lib/navigation';
import { useUser } from '../../../features/shared/state/UserContext';
import { CenteredLoader, FormNotice } from '@/features/shared/ui/FeedbackState';

type ResellerStep = {
  id: string;
  title: string;
  description: string;
  completed: boolean;
  status: string;
  action_path: string;
};

type ResellerOnboardingPayload = {
  summary: {
    completed_steps: number;
    total_steps: number;
    progress_percent: number;
  };
  steps: ResellerStep[];
  next_step?: ResellerStep | null;
  metrics?: {
    referral_clicks: number;
    products_added: number;
    payout_method_count: number;
  };
};

export const ResellerOnboardingPage = () => {
  const { token } = useUser();
  const [loading, setLoading] = useState(true);
  const [saving, setSaving] = useState(false);
  const [error, setError] = useState('');
  const [message, setMessage] = useState('');
  const [status, setStatus] = useState<ResellerOnboardingPayload | null>(null);
  const [profileForm, setProfileForm] = useState({ name: '', phone: '', bio: '' });
  const [storefrontForm, setStorefrontForm] = useState({
    storefront_headline: '',
    storefront_accent_color: '#D946EF',
    storefront_custom_domain: '',
    storefront_published: false,
  });

  const loadOnboarding = async () => {
    if (!token) return;
    setLoading(true);
    setError('');

    try {
      const [statusRes, profileRes, storefrontRes] = await Promise.all([
        fetch('/api/reseller/onboarding-status', { headers: { Authorization: `Bearer ${token}` } }),
        fetch('/api/users/profile', { headers: { Authorization: `Bearer ${token}` } }),
        fetch('/api/reseller/storefront-settings', { headers: { Authorization: `Bearer ${token}` } }),
      ]);

      const statusPayload = await statusRes.json().catch(() => null);
      const profilePayload = await profileRes.json().catch(() => null);
      const storefrontPayload = await storefrontRes.json().catch(() => null);

      if (!statusRes.ok) throw new Error(statusPayload?.error || 'Failed to load reseller onboarding status');
      if (!profileRes.ok) throw new Error(profilePayload?.error || 'Failed to load reseller profile');
      if (!storefrontRes.ok) throw new Error(storefrontPayload?.error || 'Failed to load reseller storefront settings');

      setStatus(statusPayload);
      setProfileForm({
        name: profilePayload?.user?.name || '',
        phone: profilePayload?.user?.phone || '',
        bio: profilePayload?.user?.bio || '',
      });
      setStorefrontForm({
        storefront_headline: storefrontPayload?.storefront_headline || '',
        storefront_accent_color: storefrontPayload?.storefront_accent_color || '#D946EF',
        storefront_custom_domain: storefrontPayload?.storefront_custom_domain || '',
        storefront_published: Boolean(storefrontPayload?.storefront_published),
      });
    } catch (requestError) {
      setError(requestError instanceof Error ? requestError.message : 'Failed to load onboarding');
      setStatus(null);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    void loadOnboarding();
  }, [token]);

  const completionLabel = useMemo(() => {
    if (!status) return 'Not started';
    return `${status.summary.completed_steps}/${status.summary.total_steps} completed`;
  }, [status]);

  const saveQuickStart = async (event: React.FormEvent) => {
    event.preventDefault();
    if (!token) return;

    try {
      setSaving(true);
      setError('');
      setMessage('');

      const [profileRes, storefrontRes] = await Promise.all([
        fetch('/api/users/profile', {
          method: 'PATCH',
          headers: {
            'Content-Type': 'application/json',
            Authorization: `Bearer ${token}`,
          },
          body: JSON.stringify(profileForm),
        }),
        fetch('/api/reseller/storefront-settings', {
          method: 'PATCH',
          headers: {
            'Content-Type': 'application/json',
            Authorization: `Bearer ${token}`,
          },
          body: JSON.stringify(storefrontForm),
        }),
      ]);

      const profilePayload = await profileRes.json().catch(() => null);
      const storefrontPayload = await storefrontRes.json().catch(() => null);
      if (!profileRes.ok) throw new Error(profilePayload?.error || 'Failed to save reseller profile');
      if (!storefrontRes.ok) throw new Error(storefrontPayload?.error || 'Failed to save reseller storefront');

      setMessage('Reseller basics saved. Next, add products, setup payout, and start promoting.');
      toast.success('Reseller onboarding basics saved.');
      await loadOnboarding();
    } catch (requestError) {
      const nextError = requestError instanceof Error ? requestError.message : 'Failed to save onboarding';
      setError(nextError);
      toast.error(nextError);
    } finally {
      setSaving(false);
    }
  };

  if (loading) {
    return <CenteredLoader label="Loading reseller onboarding..." className="min-h-[300px]" />;
  }

  return (
    <div className="space-y-8">
      <div className="rounded-3xl border border-border bg-[linear-gradient(135deg,rgba(217,70,239,0.10),rgba(15,23,42,0.05))] p-6 shadow-sm sm:p-8">
        <div className="flex flex-col gap-5 lg:flex-row lg:items-center lg:justify-between">
          <div>
            <p className="section-kicker text-fuchsia-600/80">Reseller onboarding</p>
            <h1 className="mt-2 text-2xl font-bold tracking-tight">Build your reseller shop and earning flow</h1>
            <p className="mt-2 max-w-2xl text-sm text-muted-foreground">
              Complete your reseller identity, activate link sharing, add products, and prepare payout from one guided workflow.
            </p>
          </div>
          <div className="rounded-3xl border border-border bg-white/80 px-5 py-4 shadow-sm">
            <p className="text-xs font-semibold uppercase tracking-wide text-muted-foreground">Completion</p>
            <p className="mt-2 text-3xl font-bold text-foreground">{status?.summary.progress_percent || 0}%</p>
            <p className="mt-1 text-sm text-muted-foreground">{completionLabel}</p>
          </div>
        </div>
      </div>

      {error ? <FormNotice tone="error">{error}</FormNotice> : null}
      {message ? <FormNotice tone="success">{message}</FormNotice> : null}

      <div className="grid gap-4 md:grid-cols-3">
        <div className="metric-card">
          <p className="text-xs font-semibold uppercase tracking-wide text-muted-foreground">Referral clicks</p>
          <p className="mt-2 text-2xl font-bold">{status?.metrics?.referral_clicks || 0}</p>
        </div>
        <div className="metric-card">
          <p className="text-xs font-semibold uppercase tracking-wide text-muted-foreground">Products added</p>
          <p className="mt-2 text-2xl font-bold">{status?.metrics?.products_added || 0}</p>
        </div>
        <div className="metric-card">
          <p className="text-xs font-semibold uppercase tracking-wide text-muted-foreground">Payout methods</p>
          <p className="mt-2 text-2xl font-bold">{status?.metrics?.payout_method_count || 0}</p>
        </div>
      </div>

      <form onSubmit={saveQuickStart} className="surface-card p-6 sm:p-8">
        <div className="mb-6 flex items-start gap-3">
          <Sparkles className="mt-0.5 text-fuchsia-600" size={20} />
          <div>
            <h2 className="text-xl font-bold">Quick start basics</h2>
            <p className="mt-1 text-sm text-muted-foreground">
              Save your reseller profile and storefront basics before you move into catalog, promotions, and payout setup.
            </p>
          </div>
        </div>

        <div className="grid gap-4 md:grid-cols-2">
          <label className="space-y-2">
            <span className="text-sm font-semibold text-foreground">Full name</span>
            <input value={profileForm.name} onChange={(e) => setProfileForm((c) => ({ ...c, name: e.target.value }))} className="w-full rounded-2xl border border-border bg-background px-4 py-3 text-sm outline-none transition focus:border-primary" />
          </label>
          <label className="space-y-2">
            <span className="text-sm font-semibold text-foreground">Phone number</span>
            <input value={profileForm.phone} onChange={(e) => setProfileForm((c) => ({ ...c, phone: e.target.value }))} className="w-full rounded-2xl border border-border bg-background px-4 py-3 text-sm outline-none transition focus:border-primary" />
          </label>
          <label className="space-y-2 md:col-span-2">
            <span className="text-sm font-semibold text-foreground">Reseller bio</span>
            <textarea rows={3} value={profileForm.bio} onChange={(e) => setProfileForm((c) => ({ ...c, bio: e.target.value }))} className="w-full rounded-2xl border border-border bg-background px-4 py-3 text-sm outline-none transition focus:border-primary" />
          </label>
          <label className="space-y-2">
            <span className="text-sm font-semibold text-foreground">Storefront headline</span>
            <input value={storefrontForm.storefront_headline} onChange={(e) => setStorefrontForm((c) => ({ ...c, storefront_headline: e.target.value }))} className="w-full rounded-2xl border border-border bg-background px-4 py-3 text-sm outline-none transition focus:border-primary" />
          </label>
          <label className="space-y-2">
            <span className="text-sm font-semibold text-foreground">Accent color</span>
            <div className="flex items-center gap-3 rounded-2xl border border-border bg-background px-4 py-3">
              <input type="color" value={storefrontForm.storefront_accent_color} onChange={(e) => setStorefrontForm((c) => ({ ...c, storefront_accent_color: e.target.value }))} className="h-10 w-12 rounded-lg border-0 bg-transparent p-0" />
              <input value={storefrontForm.storefront_accent_color} onChange={(e) => setStorefrontForm((c) => ({ ...c, storefront_accent_color: e.target.value }))} className="min-w-0 flex-1 bg-transparent text-sm outline-none" />
            </div>
          </label>
          <label className="space-y-2 md:col-span-2">
            <span className="text-sm font-semibold text-foreground">Custom domain</span>
            <input value={storefrontForm.storefront_custom_domain} onChange={(e) => setStorefrontForm((c) => ({ ...c, storefront_custom_domain: e.target.value }))} className="w-full rounded-2xl border border-border bg-background px-4 py-3 text-sm outline-none transition focus:border-primary" />
          </label>
        </div>

        <label className="mt-4 flex items-start gap-3 rounded-2xl border border-border bg-secondary/30 px-4 py-4">
          <input type="checkbox" checked={storefrontForm.storefront_published} onChange={(e) => setStorefrontForm((c) => ({ ...c, storefront_published: e.target.checked }))} className="mt-1 h-4 w-4 rounded border-border text-primary focus:ring-primary" />
          <span>
            <span className="block text-sm font-semibold text-foreground">Publish storefront when ready</span>
            <span className="mt-1 block text-xs text-muted-foreground">Turn this on when your branding and catalog are ready for public promotion.</span>
          </span>
        </label>

        <div className="mt-6 flex flex-wrap items-center justify-between gap-3">
          <p className="text-xs text-muted-foreground">Use this page for fast setup, then continue with catalog, promotions, payout, and settings from the linked steps below.</p>
          <button type="submit" disabled={saving} className="inline-flex items-center gap-2 rounded-full bg-slate-950 px-5 py-3 text-sm font-semibold text-white transition hover:bg-slate-800 disabled:cursor-not-allowed disabled:opacity-60">
            {saving ? <Loader2 className="animate-spin" size={16} /> : null}
            {saving ? 'Saving...' : 'Save onboarding basics'}
          </button>
        </div>
      </form>

      <div className="grid gap-4 xl:grid-cols-2">
        {(status?.steps || []).map((step) => (
          <div key={step.id} className="surface-card p-5">
            <div className="flex items-start justify-between gap-3">
              <div className="min-w-0">
                <div className="flex items-center gap-2">
                  {step.completed ? <CheckCircle2 size={18} className="text-emerald-600" /> : step.id === 'promotion' || step.id === 'referral' ? <Share2 size={18} className="text-fuchsia-600" /> : step.id === 'payout' ? <Wallet size={18} className="text-fuchsia-600" /> : <Store size={18} className="text-fuchsia-600" />}
                  <h3 className="text-base font-bold text-foreground">{step.title}</h3>
                </div>
                <p className="mt-2 text-sm text-muted-foreground">{step.description}</p>
              </div>
              <span className={`rounded-full px-3 py-1 text-[11px] font-bold uppercase tracking-wide ${step.completed ? 'bg-emerald-100 text-emerald-700' : 'bg-amber-100 text-amber-700'}`}>{step.completed ? 'Complete' : 'Pending'}</span>
            </div>
            <div className="mt-4 rounded-2xl bg-secondary/40 px-4 py-3 text-sm text-slate-700">{step.status}</div>
            <div className="mt-4 flex items-center justify-between gap-3">
              <p className="text-xs text-muted-foreground">{step.completed ? 'You can reopen this step any time to refine your reseller setup.' : 'Finish this step to move closer to live selling and payout readiness.'}</p>
              <Link to={step.action_path} className="inline-flex items-center gap-2 rounded-full border border-border px-4 py-2 text-xs font-semibold text-slate-700 transition hover:border-primary/20 hover:text-primary">
                Open
                <ArrowRight size={14} />
              </Link>
            </div>
          </div>
        ))}
      </div>
    </div>
  );
};

export default ResellerOnboardingPage;

import React, { useEffect, useState } from 'react';
import { DollarSign, Loader2, Share2, ShoppingBag, TrendingUp, Users, Zap } from 'lucide-react';
import { useUser } from '../../../features/shared/state/UserContext';
import { formatPrice } from '../../../lib/utils';
import { Link } from '../../../lib/navigation';

type ResellerStatCard = {
  label: string;
  value: string;
  helper: string;
  icon: React.ReactNode;
};

export const ResellerOverview = () => {
  const { token, user } = useUser();
  const [loading, setLoading] = useState(true);
  const [stats, setStats] = useState<ResellerStatCard[]>([]);
  const [error, setError] = useState('');
  const [referralCode, setReferralCode] = useState('');
  const [referralClicks, setReferralClicks] = useState(0);
  const [onboarding, setOnboarding] = useState<any>(null);

  useEffect(() => {
    const fetchStats = async () => {
      try {
        if (!token) {
          setError('Please log in as a reseller to see live stats.');
          setLoading(false);
          return;
        }

        const response = await fetch('/api/reseller/stats', {
          headers: { Authorization: `Bearer ${token}` },
        });
        const data = await response.json().catch(() => null);

        if (!response.ok) {
          throw new Error(data?.error || 'Unable to load reseller stats.');
        }

        setReferralCode(data.referralCode || '');
        setReferralClicks(Number(data.referralClicks || 0));
        setStats([
          { label: 'Total Earnings', value: formatPrice(data.totalEarnings), helper: 'Paid commissions cleared', icon: <DollarSign className="text-primary" /> },
          { label: 'Pending Earnings', value: formatPrice(data.pendingEarnings || 0), helper: 'Awaiting settlement', icon: <TrendingUp className="text-accent" /> },
          { label: 'Products Shared', value: String(data.productsShared || 0), helper: 'Catalog items promoted', icon: <Share2 className="text-primary" /> },
          { label: 'Successful Referrals', value: String(data.successfulReferrals || 0), helper: 'Orders completed from your links', icon: <Users className="text-accent" /> },
          { label: 'Conversion Rate', value: data.conversionRate || '0%', helper: 'Referral orders vs link clicks', icon: <Zap className="text-primary" /> },
        ]);
        setError('');

        const onboardingResponse = await fetch('/api/reseller/onboarding-status', {
          headers: { Authorization: `Bearer ${token}` },
        });
        if (onboardingResponse.ok) {
          const onboardingPayload = await onboardingResponse.json().catch(() => null);
          setOnboarding(onboardingPayload);
        } else {
          setOnboarding(null);
        }
      } catch (fetchError) {
        setError(fetchError instanceof Error ? fetchError.message : 'Unable to load live stats.');
        setStats([]);
        setReferralCode('');
        setReferralClicks(0);
        setOnboarding(null);
      } finally {
        setLoading(false);
      }
    };

    void fetchStats();
  }, [token]);

  if (loading) {
    return (
      <div className="flex h-64 items-center justify-center">
        <Loader2 className="animate-spin text-primary" size={32} />
      </div>
    );
  }

  return (
    <div className="space-y-8">
      <div className="rounded-3xl border border-border bg-[linear-gradient(135deg,rgba(245,158,11,0.06),rgba(37,99,235,0.06))] p-8 shadow-sm">
        <h1 className="text-2xl font-bold tracking-tight">Reseller Dashboard</h1>
        <p className="text-muted-foreground">Welcome back, {user?.name}. Here&apos;s what&apos;s happening with your network.</p>
      </div>

      {error && (
        <div className="rounded-xl border border-accent/20 bg-accent/10 p-4 text-sm text-accent">
          {error}
        </div>
      )}

      {onboarding && Number(onboarding.summary?.progress_percent || 0) < 100 ? (
        <div className="rounded-3xl border border-border bg-white p-5 shadow-sm sm:p-6">
          <div className="flex flex-col gap-4 lg:flex-row lg:items-center lg:justify-between">
            <div>
              <p className="section-kicker text-fuchsia-600/80">Reseller onboarding</p>
              <h2 className="mt-2 text-xl font-bold">Complete the setup that makes your reseller shop earn-ready</h2>
              <p className="mt-2 text-sm text-muted-foreground">
                {onboarding.summary?.completed_steps || 0}/{onboarding.summary?.total_steps || 0} onboarding steps complete.
                {onboarding.next_step?.title ? ` Next: ${onboarding.next_step.title}.` : ''}
              </p>
            </div>
            <div className="flex flex-wrap items-center gap-3">
              <div className="rounded-2xl bg-secondary/60 px-4 py-3 text-sm">
                <span className="font-bold text-foreground">{onboarding.summary?.progress_percent || 0}%</span>{' '}
                <span className="text-muted-foreground">complete</span>
              </div>
              <Link
                to={onboarding.next_step?.action_path || '/reseller-dashboard/onboarding'}
                className="rounded-full bg-slate-950 px-4 py-2 text-sm font-semibold text-white transition hover:bg-slate-800"
              >
                Continue setup
              </Link>
            </div>
          </div>
        </div>
      ) : null}

      <div className="grid grid-cols-1 gap-6 md:grid-cols-2 lg:grid-cols-4">
        {stats.map((stat, index) => (
          <div key={stat.label} className="rounded-3xl border border-border bg-card p-6 shadow-sm">
            <div className="mb-4 flex items-center justify-between">
              <div className="rounded-2xl bg-secondary p-3">{stat.icon}</div>
              <div className="rounded-lg bg-primary/10 px-2 py-1 text-xs font-bold text-primary">
                Live
              </div>
            </div>
            <p className="mb-1 text-sm text-muted-foreground">{stat.label}</p>
            <h3 className="text-2xl font-bold">{stat.value}</h3>
            <p className="mt-2 text-xs text-muted-foreground">{stat.helper}</p>
          </div>
        ))}
      </div>

      <div className="grid grid-cols-1 gap-8 lg:grid-cols-2">
        <div className="rounded-3xl border border-border bg-card p-8 shadow-sm">
          <h3 className="mb-6 text-lg font-bold">Referral Summary</h3>
          <div className="space-y-6">
            <div className="flex items-center justify-between py-2">
              <div className="flex items-center gap-4">
                <div className="flex h-10 w-10 items-center justify-center rounded-full bg-primary/10 text-primary">
                  <ShoppingBag size={20} />
                </div>
                <div>
                  <p className="text-sm font-bold">Referral code</p>
                  <p className="text-xs text-muted-foreground">{referralCode || 'Code will appear after activation'}</p>
                </div>
              </div>
              <p className="text-sm font-bold text-primary">{referralCode || '-'}</p>
            </div>

            <div className="flex items-center justify-between py-2">
              <div className="flex items-center gap-4">
                <div className="flex h-10 w-10 items-center justify-center rounded-full bg-primary/10 text-primary">
                  <TrendingUp size={20} />
                </div>
                <div>
                  <p className="text-sm font-bold">Referral clicks</p>
                  <p className="text-xs text-muted-foreground">Tracked from your shared links</p>
                </div>
              </div>
              <p className="text-sm font-bold text-primary">{referralClicks}</p>
            </div>

            <div className="flex items-center justify-between py-2">
              <div className="flex items-center gap-4">
                <div className="flex h-10 w-10 items-center justify-center rounded-full bg-primary/10 text-primary">
                  <Users size={20} />
                </div>
                <div>
                  <p className="text-sm font-bold">Network health</p>
                  <p className="text-xs text-muted-foreground">Based on active referrals and shared catalog coverage</p>
                </div>
              </div>
              <p className="text-sm font-bold text-primary">{stats.find((item) => item.label === 'Successful Referrals')?.value || '0'}</p>
            </div>
          </div>
        </div>

        <div className="rounded-3xl border border-border bg-card p-8 shadow-sm">
          <h3 className="mb-6 text-lg font-bold">Performance Snapshot</h3>
          <div className="grid gap-4 md:grid-cols-2">
            {stats.length === 0 ? (
              <div className="rounded-2xl border border-dashed border-border p-4 text-sm text-muted-foreground md:col-span-2">
                Live reseller performance will appear here once data is available.
              </div>
            ) : (
              stats.map((stat) => (
                <div key={stat.label} className="rounded-2xl border border-border bg-background/70 p-4">
                  <p className="text-xs uppercase tracking-wider text-muted-foreground">{stat.label}</p>
                  <p className="mt-2 text-xl font-bold">{stat.value}</p>
                </div>
              ))
            )}
          </div>
        </div>
      </div>
    </div>
  );
};

"use client";

import React from 'react';
import { Link } from '../../../lib/navigation';
import { cn } from '../../../lib/utils';
import { Tooltip, TooltipContent, TooltipProvider, TooltipTrigger } from '@/features/shared/ui/tooltip';
import {
  Bell,
  ChevronRight,
  ChevronsUpDown,
  LogOut,
  Menu,
  Package,
  PanelLeftClose,
  PanelLeftOpen,
  Search,
  Settings,
  Store,
  User,
  X,
} from 'lucide-react';

type SellerMenuItem = {
  icon: React.ReactNode;
  label: string;
  path: string;
};

type SellerMenuSection = {
  title: string;
  items: SellerMenuItem[];
};

type SellerMobileHeaderAction = {
  label: string;
  path: string;
  icon: React.ReactNode;
};

interface SellerDashboardShellProps {
  children: React.ReactNode;
  collapsed: boolean;
  setCollapsed: React.Dispatch<React.SetStateAction<boolean>>;
  mobileOpen: boolean;
  setMobileOpen: React.Dispatch<React.SetStateAction<boolean>>;
  pageLabel: string;
  sellerSearch: string;
  setSellerSearch: React.Dispatch<React.SetStateAction<string>>;
  onSearchSubmit: (event: React.FormEvent<HTMLFormElement>) => void;
  quickAccessBadgeCount: number;
  sellerWorkspaceName: string;
  sellerWorkspaceSubtitle: string;
  sellerInitials: string;
  avatarUrl?: string | null;
  currentSections: SellerMenuSection[];
  pathname: string;
  badges: Record<string, number>;
  sectionBadgeTotals: Record<string, number>;
  activeSectionTitles: string[];
  collapsedSections: string[];
  toggleSection: (title: string) => void;
  sellerFooterOpen: boolean;
  setSellerFooterOpen: React.Dispatch<React.SetStateAction<boolean>>;
  sellerFooterRef: React.RefObject<HTMLDivElement | null>;
  mobileHeaderActions: SellerMobileHeaderAction[];
  onNavigate: (path: string) => void;
  onLogout: () => void;
}

export function SellerDashboardShell({
  children,
  collapsed,
  setCollapsed,
  mobileOpen,
  setMobileOpen,
  pageLabel,
  sellerSearch,
  setSellerSearch,
  onSearchSubmit,
  quickAccessBadgeCount,
  sellerWorkspaceName,
  sellerWorkspaceSubtitle,
  sellerInitials,
  avatarUrl,
  currentSections,
  pathname,
  badges,
  sectionBadgeTotals,
  activeSectionTitles,
  collapsedSections,
  toggleSection,
  sellerFooterOpen,
  setSellerFooterOpen,
  sellerFooterRef,
  mobileHeaderActions,
  onNavigate,
  onLogout,
}: SellerDashboardShellProps) {
  const [dashboardManageMode, setDashboardManageMode] = React.useState(true);

  const renderBrandMark = (compact = false) => (
    <Link to="/seller/dashboard" className={cn('flex min-w-0 items-center gap-2.5', compact ? 'justify-center' : '')}>
      <span className="flex aspect-square size-8 items-center justify-center rounded-xl bg-primary text-white shadow-sm">
        <Package size={15} />
      </span>
      {!compact ? (
        <span className="min-w-0 leading-tight">
          <span className="block truncate text-sm font-black tracking-tight text-slate-950">{sellerWorkspaceName}</span>
          <span className="block truncate text-[10px] font-bold uppercase tracking-[0.22em] text-slate-500">
            Seller Dashboard
          </span>
        </span>
      ) : null}
    </Link>
  );

  React.useEffect(() => {
    if (typeof window === 'undefined') return;

    const syncDashboardMode = () => {
      setDashboardManageMode(window.localStorage.getItem('amarshop_seller_dashboard_manage_mode') === 'true');
    };

    syncDashboardMode();
    window.addEventListener('seller-dashboard-mode-change', syncDashboardMode);
    window.addEventListener('storage', syncDashboardMode);

    return () => {
      window.removeEventListener('seller-dashboard-mode-change', syncDashboardMode);
      window.removeEventListener('storage', syncDashboardMode);
    };
  }, []);

  const switchDashboardMode = React.useCallback(
    (nextManageMode: boolean) => {
      if (typeof window !== 'undefined') {
        window.localStorage.setItem('amarshop_seller_dashboard_manage_mode', nextManageMode ? 'true' : 'false');
        window.dispatchEvent(new Event('seller-dashboard-mode-change'));
      }
      setDashboardManageMode(nextManageMode);
      if (pathname !== '/seller/dashboard') {
        onNavigate('/seller/dashboard');
      }
    },
    [onNavigate, pathname],
  );

  const renderCollapsedSellerLink = (item: SellerMenuItem, isActive: boolean, badgeCount: number) => (
    <Tooltip>
      <TooltipTrigger
        render={
          <Link
            to={item.path}
            className={cn(
              'seller-nav-link seller-nav-link--collapsed group relative flex w-full items-center justify-center rounded-md px-2 py-2 text-xs font-medium transition-all',
              isActive ? 'seller-nav-link--active text-slate-950' : 'text-muted-foreground',
            )}
          >
            <span className="dashboard-nav-link__icon h-8 w-8 shrink-0">{item.icon}</span>
            {badgeCount > 0 ? (
              <span className="absolute right-2 top-2 inline-flex h-2.5 w-2.5 rounded-full bg-primary" />
            ) : null}
          </Link>
        }
      />
      <TooltipContent side="right">{item.label}</TooltipContent>
    </Tooltip>
  );

  const renderCollapsedSellerSectionButton = (
    section: SellerMenuSection,
    isActive: boolean,
    badgeCount: number,
  ) => (
    <Tooltip>
      <TooltipTrigger
        render={
          <button
            type="button"
            onClick={() => {
              if (!collapsed) toggleSection(section.title);
            }}
            className={cn(
              'seller-nav-link seller-nav-link--collapsed group relative flex w-full items-center justify-center rounded-md px-2 py-2 text-xs font-medium transition-all',
              isActive ? 'seller-nav-link--active text-slate-950' : 'text-muted-foreground',
            )}
          >
            <span className="dashboard-nav-link__icon h-8 w-8 shrink-0">{section.items[0]?.icon ?? <Store size={14} />}</span>
            {badgeCount > 0 ? (
              <span className="absolute right-2 top-2 inline-flex h-2.5 w-2.5 rounded-full bg-primary" />
            ) : null}
          </button>
        }
      />
      <TooltipContent side="right">{section.title}</TooltipContent>
    </Tooltip>
  );

  const renderSellerSidebar = () => (
    <div className="seller-sidebar-shell flex h-full max-h-[calc(100vh-56px)] min-h-0 flex-col overflow-hidden py-0">
      <div className="flex h-[56px] shrink-0 items-center border-b border-slate-200 px-4">
        {!collapsed ? renderBrandMark(false) : renderBrandMark(true)}
      </div>

      <div className="flex-1 min-h-0 overflow-y-auto overflow-x-hidden px-2 pb-3 scrollbar-thin scrollbar-track-transparent scrollbar-thumb-slate-200">
        <div className="space-y-2.5">
          {currentSections.map((section) => (
            <div key={section.title} className="space-y-1.5">
              {section.items.length === 1 ? (
                (() => {
                  const item = section.items[0];
                  const isActive = pathname === item.path;
                  const badgeCount = Number(badges[item.path] || 0);
                  return (
                    collapsed ? renderCollapsedSellerLink(item, isActive, badgeCount) : (
                      <Link
                        to={item.path}
                        className={cn(
                          'seller-nav-link seller-nav-link--row group relative flex h-8 w-full items-center gap-2 rounded-md px-3 text-xs font-medium transition-all',
                          isActive ? 'seller-nav-link--active text-slate-950' : 'text-muted-foreground',
                        )}
                      >
                        <span className="dashboard-nav-link__icon h-8 w-8 shrink-0">{item.icon}</span>
                        <span className="dashboard-nav-link__label flex-1">{item.label}</span>
                        {badgeCount > 0 ? (
                          <span className="inline-flex min-w-[1.5rem] items-center justify-center rounded-full bg-slate-100 px-2 py-0.5 text-[11px] font-bold text-slate-500">
                            {badgeCount > 99 ? '99+' : badgeCount}
                          </span>
                        ) : null}
                      </Link>
                    )
                  );
                })()
              ) : (
                <>
                  {collapsed ? renderCollapsedSellerSectionButton(
                    section,
                    activeSectionTitles.includes(section.title),
                    Number(sectionBadgeTotals[section.title] || 0),
                  ) : (
                    <button
                      type="button"
                      onClick={() => {
                        if (!collapsed) toggleSection(section.title);
                      }}
                      className={cn(
                        'seller-nav-link seller-nav-link--row group relative flex h-8 w-full items-center gap-2 rounded-md px-3 text-left text-xs font-medium transition-all',
                        activeSectionTitles.includes(section.title) ? 'seller-nav-link--active text-slate-950' : 'text-muted-foreground',
                      )}
                    >
                      <span className="dashboard-nav-link__icon h-8 w-8 shrink-0">{section.items[0]?.icon ?? <Store size={14} />}</span>
                      <span className="dashboard-nav-link__label flex-1">{section.title}</span>
                      {Number(sectionBadgeTotals[section.title] || 0) > 0 ? (
                        <span className="inline-flex min-w-[1.5rem] items-center justify-center rounded-full bg-slate-100 px-2 py-0.5 text-[11px] font-bold text-slate-500">
                          {sectionBadgeTotals[section.title] > 99 ? '99+' : sectionBadgeTotals[section.title]}
                        </span>
                      ) : null}
                      <ChevronRight
                        size={12}
                        className={cn(
                          'ml-auto transition-transform duration-200',
                          collapsedSections.includes(section.title) ? '' : 'rotate-90',
                        )}
                      />
                    </button>
                  )}

                  {!collapsed && !collapsedSections.includes(section.title) ? (
                    <div className="ml-4 pl-2">
                      {section.items.map((item) => {
                        const itemActive = pathname === item.path;
                        const badgeCount = Number(badges[item.path] || 0);
                        return (
                          <Link
                            key={`${section.title}-${item.label}-${item.path}`}
                            to={item.path}
                            className={cn(
                              'seller-sub-nav-link flex h-7 items-center gap-2 rounded-md px-2 text-[11px] transition',
                              itemActive ? 'bg-slate-100 font-semibold text-slate-950' : 'text-slate-500 hover:bg-slate-50 hover:text-slate-900',
                            )}
                          >
                            <span className="flex-1 truncate">{item.label}</span>
                            {badgeCount > 0 ? (
                              <span className="inline-flex min-w-[1.25rem] items-center justify-center rounded-full bg-slate-100 px-1.5 py-0.5 text-[10px] font-bold text-slate-500">
                                {badgeCount > 99 ? '99+' : badgeCount}
                              </span>
                            ) : null}
                          </Link>
                        );
                      })}
                    </div>
                  ) : null}
                </>
              )}
            </div>
          ))}
        </div>
      </div>

      <div ref={sellerFooterRef} className="relative border-t border-slate-200 px-2 py-2">
        {!collapsed ? (
          <div className="rounded-lg">
            <button
              type="button"
              onClick={() => setSellerFooterOpen((current) => !current)}
              className={cn(
                'seller-footer-trigger flex w-full items-center gap-3 rounded-lg px-2 py-2 text-left transition',
                sellerFooterOpen ? 'bg-slate-100 text-slate-950' : 'hover:bg-slate-100',
              )}
            >
              {avatarUrl ? (
                <img
                  src={avatarUrl}
                  alt={sellerWorkspaceName}
                  className="h-8 w-8 rounded-lg border border-slate-200 object-cover"
                  loading="eager"
                  referrerPolicy="no-referrer"
                />
              ) : (
                <div className="flex h-8 w-8 items-center justify-center rounded-lg bg-slate-100 text-[10px] font-bold text-slate-700">
                  {sellerInitials}
                </div>
              )}
              <div className="min-w-0 flex-1 text-left text-sm leading-tight">
                <span className="block truncate font-semibold text-slate-900">{sellerWorkspaceName}</span>
                <span className="block truncate text-xs text-slate-500">{sellerWorkspaceSubtitle}</span>
              </div>
              <ChevronsUpDown size={16} className="text-slate-400" />
            </button>

            {sellerFooterOpen ? (
              <div className="seller-footer-menu absolute inset-x-2 bottom-[calc(100%+0.5rem)] z-30 rounded-lg border border-slate-200 bg-white p-1 shadow-[0_18px_40px_-28px_rgba(15,23,42,0.28)]">
                <div className="flex items-center gap-2 px-1 py-1.5 text-left text-sm">
                  {avatarUrl ? (
                    <img
                      src={avatarUrl}
                      alt={sellerWorkspaceName}
                      className="h-8 w-8 rounded-lg border border-slate-200 object-cover"
                      loading="eager"
                      referrerPolicy="no-referrer"
                    />
                  ) : (
                    <div className="flex h-8 w-8 items-center justify-center rounded-lg bg-slate-100 text-[10px] font-bold text-slate-700">
                      {sellerInitials}
                    </div>
                  )}
                  <div className="min-w-0 flex-1 leading-tight">
                    <span className="block truncate font-semibold text-slate-900">{sellerWorkspaceName}</span>
                    <span className="block truncate text-xs text-slate-500">{sellerWorkspaceSubtitle}</span>
                  </div>
                </div>
                <div className="my-1 border-t border-slate-200" />
                <button
                  type="button"
                  onClick={() => onNavigate('/seller/settings')}
                  className="seller-footer-menu__item flex w-full items-center gap-2 rounded-md px-1.5 py-1.5 text-xs font-medium text-slate-600 transition hover:bg-slate-100 hover:text-slate-900"
                >
                  <User size={16} />
                  <span>Account</span>
                </button>
                <button
                  type="button"
                  onClick={() => onNavigate('/seller/settings')}
                  className="seller-footer-menu__item flex w-full items-center gap-2 rounded-md px-1.5 py-1.5 text-xs font-medium text-slate-600 transition hover:bg-slate-100 hover:text-slate-900"
                >
                  <Settings size={16} />
                  <span>Settings</span>
                </button>
                <button
                  type="button"
                  onClick={() => onNavigate('/seller/notifications')}
                  className="seller-footer-menu__item flex w-full items-center gap-2 rounded-md px-1.5 py-1.5 text-xs font-medium text-slate-600 transition hover:bg-slate-100 hover:text-slate-900"
                >
                  <Bell size={16} />
                  <span>Notifications</span>
                </button>
                <button
                  type="button"
                  onClick={onLogout}
                  className="seller-footer-menu__item flex w-full items-center gap-2 rounded-md px-1.5 py-1.5 text-xs font-medium text-slate-600 transition hover:bg-slate-100 hover:text-rose-600"
                >
                  <LogOut size={16} />
                  <span>Log out</span>
                </button>
              </div>
            ) : null}
          </div>
        ) : (
          <button
            type="button"
            onClick={() => onNavigate('/seller/settings')}
            className="mx-auto flex h-9 w-9 items-center justify-center rounded-lg text-slate-600 transition hover:bg-slate-100"
            aria-label="Seller account"
          >
            {avatarUrl ? (
              <img
                src={avatarUrl}
                alt={sellerWorkspaceName}
                className="h-8 w-8 rounded-lg border border-slate-200 object-cover"
                loading="eager"
                referrerPolicy="no-referrer"
              />
            ) : (
              <div className="flex h-8 w-8 items-center justify-center rounded-lg bg-slate-100 text-[10px] font-bold text-slate-700">
                {sellerInitials}
              </div>
            )}
          </button>
        )}
      </div>
    </div>
  );

  return (
    <TooltipProvider>
      <div className="dashboard-shell seller-app-shell">
      <div className="seller-topbar-shell">
        <div className="seller-topbar-shell__row flex h-[56px] items-center gap-2 bg-white">
          <div className="flex w-full items-center gap-2 px-4 md:px-6">
            <button
              type="button"
              onClick={() => setMobileOpen(true)}
              className="seller-mobile-trigger inline-flex h-8 w-8 items-center justify-center rounded-md text-slate-700 transition hover:bg-slate-100 lg:hidden"
              aria-label="Open seller dashboard menu"
            >
              <Menu size={17} />
            </button>
            <button
              type="button"
              onClick={() => setCollapsed((current) => !current)}
              className="hidden h-9 w-9 items-center justify-center rounded-lg text-slate-700 transition hover:bg-slate-100 lg:inline-flex"
              aria-label={collapsed ? 'Expand sidebar' : 'Collapse sidebar'}
            >
              {collapsed ? <PanelLeftOpen size={16} /> : <PanelLeftClose size={16} />}
            </button>
            <div className="mr-2 hidden h-4 w-px bg-slate-200 lg:block" />
            <div className="hidden lg:block">{renderBrandMark(false)}</div>
            <div className="ml-2 hidden h-4 w-px bg-slate-200 lg:block" />

            <form onSubmit={onSearchSubmit} className="hidden max-w-[300px] min-w-0 flex-1 md:block">
              <label className="relative block">
                <Search className="pointer-events-none absolute left-3 top-1/2 h-3.5 w-3.5 -translate-y-1/2 text-muted-foreground" size={14} />
                <input
                  type="search"
                  value={sellerSearch}
                  onChange={(event) => setSellerSearch(event.target.value)}
                  placeholder="Search products, orders or customers..."
                  className="h-9 w-full rounded-lg border-none bg-[#f4f4f4] pl-9 pr-4 text-xs text-slate-700 outline-none transition placeholder:text-slate-400 focus:ring-1 focus:ring-primary/30"
                />
              </label>
            </form>

            <div className="ml-auto flex items-center gap-3 md:gap-4">
              <p className="hidden h-8 items-center rounded-full border border-slate-200 bg-slate-50 px-3 text-xs font-bold uppercase tracking-wide text-slate-600 lg:inline-flex">
                Dashboard
              </p>
            <div className="hidden items-center rounded-full border border-slate-200 bg-slate-50 p-1 md:inline-flex">
                <button
                  type="button"
                  onClick={() => switchDashboardMode(false)}
                  className={cn(
                    'inline-flex items-center gap-2 rounded-full px-3 py-1.5 text-xs font-semibold transition',
                    !dashboardManageMode ? 'bg-white text-slate-950 shadow-sm' : 'text-slate-600 hover:text-slate-900',
                  )}
                >
                  <Store size={14} />
                  Storefront Mode
                </button>
                <button
                  type="button"
                  onClick={() => switchDashboardMode(true)}
                  className={cn(
                    'inline-flex items-center gap-2 rounded-full px-3 py-1.5 text-xs font-semibold transition',
                    dashboardManageMode ? 'bg-slate-950 text-white shadow-sm' : 'text-slate-600 hover:text-slate-900',
                  )}
                >
                  <Package size={14} />
                  Manage Mode
                </button>
              </div>
              <Link
                to="/seller/notifications"
                className="relative inline-flex h-8 w-8 items-center justify-center rounded-md text-slate-600 transition hover:bg-slate-100 hover:text-primary"
                title="Notifications"
              >
                <Bell size={16} />
                {quickAccessBadgeCount > 0 ? (
                  <span className="absolute -right-1 -top-1 inline-flex min-w-[1rem] items-center justify-center rounded-full border border-white bg-red-500 px-1 py-0.5 text-[10px] font-bold leading-none text-white">
                    {quickAccessBadgeCount > 99 ? '99+' : quickAccessBadgeCount}
                  </span>
                ) : null}
              </Link>
              <div className="flex items-center gap-2.5 border-l border-slate-200 pl-3 md:gap-3 md:pl-4">
                <div className="hidden text-right sm:block">
                  <div className="text-[11px] font-bold leading-none text-slate-950">{sellerWorkspaceName}</div>
                  <div className="mt-1 text-[10px] leading-none text-slate-500">Premium Seller</div>
                </div>
                {avatarUrl ? (
                  <img
                    src={avatarUrl}
                    alt={sellerWorkspaceName}
                    className="h-7 w-7 rounded-lg border border-slate-200 object-cover"
                    loading="eager"
                    referrerPolicy="no-referrer"
                  />
                ) : (
                  <span className="flex h-7 w-7 items-center justify-center rounded-lg border border-slate-200 bg-white text-[10px] font-bold text-slate-700">
                    {sellerInitials}
                  </span>
                )}
              </div>
            </div>
          </div>
        </div>

        <div className="seller-mobile-toolbar border-t border-slate-200 px-4 py-3 md:hidden">
          <form onSubmit={onSearchSubmit} className="mb-3">
            <label className="relative block">
              <Search className="pointer-events-none absolute left-3 top-1/2 h-3.5 w-3.5 -translate-y-1/2 text-muted-foreground" size={14} />
              <input
                type="search"
                value={sellerSearch}
                onChange={(event) => setSellerSearch(event.target.value)}
                placeholder="Search products, orders or customers..."
                className="h-9 w-full rounded-md border-none bg-[#f4f4f4] pl-9 pr-4 text-xs text-slate-700 outline-none transition focus:ring-1 focus:ring-primary/30"
              />
            </label>
          </form>
          <div className="dashboard-chip-scroll flex gap-2 overflow-x-auto pb-1">
            {mobileHeaderActions.map((action) => {
              const active = pathname === action.path;
              return (
                <Link
                  key={action.path}
                  to={action.path}
                  className={cn('mobile-action-chip shrink-0', active ? 'mobile-action-chip--active' : '')}
                >
                  {action.icon}
                  <span>{action.label}</span>
                </Link>
              );
            })}
          </div>
        </div>
      </div>

      <div className="seller-app-frame">
        <aside className={cn('seller-sidebar-wrap hidden h-[calc(100vh-56px)] self-start transition-all duration-300 lg:sticky lg:top-0 lg:block lg:overflow-hidden', collapsed ? 'lg:w-[72px]' : 'lg:w-[220px]')}>
          <div className="h-full">{renderSellerSidebar()}</div>
        </aside>

        <main className="seller-main-content">{children}</main>
      </div>

      {mobileOpen ? (
        <div className="fixed inset-0 z-50 lg:hidden">
          <button
            type="button"
            aria-label="Close dashboard menu"
            onClick={() => setMobileOpen(false)}
            className="absolute inset-0 bg-slate-950/45 backdrop-blur-[2px]"
          />
          <div className="absolute inset-y-0 left-0 w-[18rem] max-w-[88vw] p-0">
            <div className="seller-sidebar-shell flex h-full flex-col rounded-none shadow-none">
              <div className="flex h-[56px] items-center justify-between border-b border-slate-200 bg-white px-4">
                <div className="min-w-0">
                  <h2 className="truncate text-sm font-black text-slate-950">LofiMart</h2>
                  <p className="mt-1 truncate text-[10px] font-bold uppercase tracking-[0.18em] text-slate-500">Seller Dashboard</p>
                </div>
                <button
                  type="button"
                  onClick={() => setMobileOpen(false)}
                  className="inline-flex h-8 w-8 items-center justify-center rounded-md text-slate-700 transition hover:bg-slate-100"
                  aria-label="Close dashboard menu"
                >
                  <X size={17} />
                </button>
              </div>
              <div className="min-h-0 flex-1 overflow-y-auto bg-white p-0">{renderSellerSidebar()}</div>
            </div>
          </div>
        </div>
      ) : null}
      </div>
    </TooltipProvider>
  );
}

import React, { useEffect, useMemo, useRef, useState } from 'react';
import { AlertTriangle, CheckCircle, Download, Filter, Loader2, MapPin, Search, Truck, Undo2, XCircle } from 'lucide-react';
import { useUser } from '../../../features/shared/state/UserContext';
import { formatPrice } from '../../../lib/utils';
import NotificationContainer, { useNotification } from '@/features/shared/animations/NotificationContainer';

interface SellerShipment {
  id: string;
  order_id: string;
  warehouse_id?: string | null;
  order_created_at?: string;
  shipping_address?: string | Record<string, unknown> | null;
  total: number;
  item_count?: number;
  warehouse_name?: string | null;
  warehouse_city?: string | null;
  payment_method: string;
  status: string;
  courier_provider?: string | null;
  tracking_id?: string | null;
  shipment_metadata?: Record<string, unknown> | null;
}

interface CourierPartner {
  code: string;
  name: string;
  mode: 'manual' | 'api';
  supportsCod: boolean;
  supportsTrackingSync: boolean;
  supportsPickupBooking: boolean;
  setupStatus?: 'manual_ready' | 'api_ready' | 'missing_config';
  setupMessage?: string;
  brandColor?: string;
  shortLabel?: string;
}

interface SellerPathaoReadiness {
  updatedAt: string;
  envReady: boolean;
  warehouseBlockers: Array<{
    id: string;
    name: string;
    blockers: string[];
  }>;
  bookingCandidates: Array<{
    id: string;
    order_id: string;
    warehouse_id: string | null;
    warehouse_name: string | null;
    courier_provider: string | null;
    tracking_id: string | null;
    status: string;
    blockers: string[];
  }>;
}

const managedStatuses = [
  'pending',
  'processing',
  'packed',
  'ready_for_pickup',
  'pickup_requested',
  'picked_up',
  'in_transit',
  'out_for_delivery',
];

const historyStatuses = ['delivered', 'delivery_failed', 'returned', 'cancelled'];
const exceptionStatuses = ['delivery_failed', 'returned', 'cancelled'];
const sellerCourierViews = ['all', 'active', 'exceptions', 'history'] as const;
type SellerCourierView = (typeof sellerCourierViews)[number];

export const SellerCourierManagement = () => {
  const { token, user } = useUser();
  const [shipments, setShipments] = useState<SellerShipment[]>([]);
  const [courierPartners, setCourierPartners] = useState<CourierPartner[]>([]);
  const [pathaoReadiness, setPathaoReadiness] = useState<SellerPathaoReadiness | null>(null);
  const [loadingPathaoReadiness, setLoadingPathaoReadiness] = useState(false);
  const [loading, setLoading] = useState(true);
  const [apiReady, setApiReady] = useState(false);
  const [selectedProvider, setSelectedProvider] = useState<Record<string, string>>({});
  const [updatingShipmentId, setUpdatingShipmentId] = useState('');
  const [searchTerm, setSearchTerm] = useState('');
  const [view, setView] = useState<SellerCourierView>('all');
  const [providerFilter, setProviderFilter] = useState('all');
  const [dateFrom, setDateFrom] = useState('');
  const [dateTo, setDateTo] = useState('');
  const [error, setError] = useState('');
  const [focusedShipmentId, setFocusedShipmentId] = useState('');
  const [showDeferredGuidance, setShowDeferredGuidance] = useState(false);
  const deferredGuidanceRef = useRef<HTMLDivElement | null>(null);
  const [activeRenderCount, setActiveRenderCount] = useState(24);
  const [historyRenderCount, setHistoryRenderCount] = useState(20);
  const { notifications, removeNotification, success, info } = useNotification();

  const loadShipments = async () => {
    if (!token) {
      setError('Please log in as a seller to manage courier bookings.');
      setLoading(false);
      return;
    }

    try {
      setLoading(true);
      setError('');
      const response = await fetch('/api/seller/shipments', {
        headers: { Authorization: `Bearer ${token}` },
      });

      const payload = await response.json().catch(() => null);
      if (!response.ok) {
        throw new Error(payload?.error || 'Failed to load seller shipments');
      }

      const nextShipments = (Array.isArray(payload) ? payload : []) as SellerShipment[];
      setShipments(nextShipments);
      setApiReady(true);
    } catch (loadError) {
      setShipments([]);
      setApiReady(false);
      setError(
        loadError instanceof Error
          ? loadError.message
          : 'Live courier-ready shipments could not be loaded right now. Please try again shortly.',
      );
    } finally {
      setLoading(false);
    }
  };

  const loadPathaoReadiness = async () => {
    if (!token) return;

    try {
      setLoadingPathaoReadiness(true);
      const response = await fetch('/api/seller/logistics/pathao-readiness', {
        headers: { Authorization: `Bearer ${token}` },
      });
      const payload = await response.json().catch(() => null);

      if (!response.ok) {
        throw new Error(payload?.error || 'Failed to load Pathao readiness.');
      }

      setPathaoReadiness(payload as SellerPathaoReadiness);
    } catch {
      setPathaoReadiness(null);
    } finally {
      setLoadingPathaoReadiness(false);
    }
  };

  useEffect(() => {
    void loadShipments();
    void loadPathaoReadiness();
  }, [token]);

  useEffect(() => {
    fetch('/api/logistics/providers', { cache: 'no-store' })
      .then((response) => response.json())
      .then((data) => {
        setCourierPartners(Array.isArray(data) ? data : []);
      })
      .catch(() => {
        setCourierPartners([]);
      });
  }, []);

  useEffect(() => {
    if (typeof window === 'undefined') return;

    const params = new URLSearchParams(window.location.search);
    const nextSearch = params.get('search');
    if (nextSearch) {
      setSearchTerm(nextSearch);
    }
  }, []);

  useEffect(() => {
    if (showDeferredGuidance) return;

    const target = deferredGuidanceRef.current;
    if (!target || typeof IntersectionObserver === 'undefined') {
      const timeoutId = window.setTimeout(() => setShowDeferredGuidance(true), 250);
      return () => window.clearTimeout(timeoutId);
    }

    const observer = new IntersectionObserver(
      (entries) => {
        if (entries.some((entry) => entry.isIntersecting)) {
          setShowDeferredGuidance(true);
          observer.disconnect();
        }
      },
      { rootMargin: '480px 0px' },
    );

    observer.observe(target);
    return () => observer.disconnect();
  }, [showDeferredGuidance]);

  const handleStatusUpdate = async (shipmentId: string, nextStatus: string) => {
    if (!token) return;

    setUpdatingShipmentId(shipmentId);

    try {
      const response = await fetch(`/api/shipments/${shipmentId}/status`, {
        method: 'PATCH',
        headers: {
          Authorization: `Bearer ${token}`,
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({ status: nextStatus }),
      });
      const payload = await response.json().catch(() => null);

      if (!response.ok) {
        throw new Error(payload?.error || 'Failed to update shipment status');
      }

      setShipments((current) =>
        current.map((shipment) => (shipment.id === shipmentId ? { ...shipment, status: nextStatus } : shipment)),
      );

      success(`Shipment ${shipmentId.slice(0, 8)} moved to ${nextStatus.replaceAll('_', ' ')}.`, 3600);
    } catch (requestError) {
      info(
        requestError instanceof Error ? requestError.message : 'Shipment status could not be updated right now.',
        3600,
      );
    } finally {
      setUpdatingShipmentId('');
    }
  };

  const handleRequestPickup = async (shipmentId: string) => {
    const providerCode = selectedProvider[shipmentId] || courierPartners[0]?.code || 'pathao';

    if (!token) return;
    setUpdatingShipmentId(shipmentId);

    try {
      const response = await fetch('/api/seller/courier/bookings', {
        method: 'POST',
        headers: {
          Authorization: `Bearer ${token}`,
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({
          shipmentId,
          providerCode,
        }),
      });
      const payload = await response.json().catch(() => null);

      if (!response.ok) {
        throw new Error(payload?.error || 'Failed to request pickup');
      }

      setShipments((current) =>
        current.map((shipment) =>
          shipment.id === shipmentId
            ? {
                ...shipment,
                status: payload?.shipment?.status || 'pickup_requested',
                courier_provider: payload?.shipment?.courier_provider || payload?.booking?.providerName || providerCode,
                tracking_id: payload?.shipment?.tracking_id || payload?.booking?.trackingId || null,
              }
            : shipment,
        ),
      );
      success(
        `${payload?.booking?.providerName || providerCode} pickup requested for shipment ${shipmentId.slice(0, 8)}. Tracking ID: ${payload?.booking?.trackingId || 'pending'}`,
        3600,
      );
    } catch (requestError) {
      info(requestError instanceof Error ? requestError.message : 'Pickup request failed right now.', 3600);
    } finally {
      setUpdatingShipmentId('');
    }
  };

  const handlePathaoSync = async (shipmentId: string) => {
    if (!token) return;
    setUpdatingShipmentId(shipmentId);

    try {
      const response = await fetch(`/api/logistics/pathao/shipments/${shipmentId}/sync`, {
        method: 'POST',
        headers: {
          Authorization: `Bearer ${token}`,
        },
      });
      const payload = await response.json().catch(() => null);

      if (!response.ok) {
        throw new Error(payload?.error || 'Failed to sync Pathao shipment');
      }

      setShipments((current) =>
        current.map((shipment) => (shipment.id === shipmentId ? { ...shipment, ...(payload?.shipment || {}) } : shipment)),
      );
      success(`Pathao sync completed for shipment ${shipmentId.slice(0, 8)}.`, 3200);
    } catch (requestError) {
      info(requestError instanceof Error ? requestError.message : 'Pathao sync failed right now.', 3600);
    } finally {
      setUpdatingShipmentId('');
    }
  };

  const handlePathaoOrderInfo = async (consignmentId: string) => {
    if (!token) return;
    const trimmedId = String(consignmentId || '').trim();
    if (!trimmedId) {
      info('This shipment does not have a Pathao consignment or tracking ID yet.', 3200);
      return;
    }

    setUpdatingShipmentId(trimmedId);

    try {
      const response = await fetch(`/api/logistics/pathao/orders/${encodeURIComponent(trimmedId)}/info`, {
        headers: {
          Authorization: `Bearer ${token}`,
        },
      });
      const payload = await response.json().catch(() => null);

      if (!response.ok) {
        throw new Error(payload?.error || 'Failed to load Pathao order info');
      }

      const orderInfo = payload?.data || payload;
      success(
        `Pathao order ${orderInfo?.consignment_id || trimmedId}: ${String(orderInfo?.order_status || orderInfo?.order_status_slug || 'status unavailable')}.`,
        4200,
      );
    } catch (requestError) {
      info(requestError instanceof Error ? requestError.message : 'Pathao order info could not be loaded.', 3600);
    } finally {
      setUpdatingShipmentId('');
    }
  };

  const handleRedxSync = async (shipmentId: string) => {
    if (!token) return;
    setUpdatingShipmentId(shipmentId);

    try {
      const response = await fetch(`/api/logistics/redx/shipments/${shipmentId}/sync`, {
        method: 'POST',
        headers: {
          Authorization: `Bearer ${token}`,
        },
      });
      const payload = await response.json().catch(() => null);

      if (!response.ok) {
        throw new Error(payload?.error || 'Failed to sync RedX shipment');
      }

      setShipments((current) =>
        current.map((shipment) => (shipment.id === shipmentId ? { ...shipment, ...(payload?.shipment || {}) } : shipment)),
      );
      success(`RedX sync completed for shipment ${shipmentId.slice(0, 8)}.`, 3200);
    } catch (requestError) {
      info(requestError instanceof Error ? requestError.message : 'RedX sync failed right now.', 3600);
    } finally {
      setUpdatingShipmentId('');
    }
  };

  const handleSteadfastSync = async (shipmentId: string) => {
    if (!token) return;
    setUpdatingShipmentId(shipmentId);

    try {
      const response = await fetch(`/api/logistics/steadfast/shipments/${shipmentId}/sync`, {
        method: 'POST',
        headers: {
          Authorization: `Bearer ${token}`,
        },
      });
      const payload = await response.json().catch(() => null);

      if (!response.ok) {
        throw new Error(payload?.error || 'Failed to sync Steadfast shipment');
      }

      setShipments((current) =>
        current.map((shipment) => (shipment.id === shipmentId ? { ...shipment, ...(payload?.shipment || {}) } : shipment)),
      );
      success(`Steadfast sync completed for shipment ${shipmentId.slice(0, 8)}.`, 3200);
    } catch (requestError) {
      info(requestError instanceof Error ? requestError.message : 'Steadfast sync failed right now.', 3600);
    } finally {
      setUpdatingShipmentId('');
    }
  };

  const visibleShipments = useMemo(
    () =>
      shipments.filter((shipment) => {
        const needle = searchTerm.toLowerCase();
        const shipmentDate = shipment.order_created_at ? new Date(shipment.order_created_at) : null;
        const startDate = dateFrom ? new Date(`${dateFrom}T00:00:00`) : null;
        const endDate = dateTo ? new Date(`${dateTo}T23:59:59.999`) : null;
        const matchesProvider =
          providerFilter === 'all' ||
          String(shipment.courier_provider || 'unassigned').toLowerCase() === providerFilter.toLowerCase();
        const matchesStartDate = !startDate || !shipmentDate || shipmentDate >= startDate;
        const matchesEndDate = !endDate || !shipmentDate || shipmentDate <= endDate;

        return (
          matchesProvider &&
          matchesStartDate &&
          matchesEndDate &&
          (
            shipment.id.toLowerCase().includes(needle) ||
            shipment.status.toLowerCase().includes(needle) ||
            String(shipment.order_id || '').toLowerCase().includes(needle) ||
            String(shipment.warehouse_name || '').toLowerCase().includes(needle) ||
            String(shipment.courier_provider || '').toLowerCase().includes(needle) ||
            String(shipment.tracking_id || '').toLowerCase().includes(needle)
          )
        );
      }),
    [shipments, searchTerm, providerFilter, dateFrom, dateTo],
  );

  const viewScopedShipments = useMemo(() => {
    if (view === 'active') {
      return visibleShipments.filter((shipment) => managedStatuses.includes(shipment.status));
    }

    if (view === 'exceptions') {
      return visibleShipments.filter((shipment) => exceptionStatuses.includes(shipment.status));
    }

    if (view === 'history') {
      return visibleShipments.filter((shipment) => historyStatuses.includes(shipment.status));
    }

    return visibleShipments;
  }, [view, visibleShipments]);

  const activeShipments = useMemo(
    () => viewScopedShipments.filter((shipment) => managedStatuses.includes(shipment.status)),
    [viewScopedShipments],
  );

  const shipmentHistory = useMemo(
    () => viewScopedShipments.filter((shipment) => historyStatuses.includes(shipment.status)),
    [viewScopedShipments],
  );
  const renderedActiveShipments = useMemo(
    () => activeShipments.slice(0, activeRenderCount),
    [activeRenderCount, activeShipments],
  );
  const renderedShipmentHistory = useMemo(
    () => shipmentHistory.slice(0, historyRenderCount),
    [historyRenderCount, shipmentHistory],
  );

  useEffect(() => {
    setActiveRenderCount(24);
    setHistoryRenderCount(20);
  }, [searchTerm, providerFilter, dateFrom, dateTo, view]);

  useEffect(() => {
    const needle = searchTerm.trim().toLowerCase();
    if (!needle) {
      setFocusedShipmentId('');
      return;
    }

    const firstMatch = viewScopedShipments[0];
    if (!firstMatch) {
      setFocusedShipmentId('');
      return;
    }

    setFocusedShipmentId(firstMatch.id);

    if (typeof window !== 'undefined') {
      window.requestAnimationFrame(() => {
        document.getElementById(`seller-shipment-${firstMatch.id}`)?.scrollIntoView({
          behavior: 'smooth',
          block: 'center',
        });
      });
    }
  }, [searchTerm, viewScopedShipments]);

  const shipmentSummary = useMemo(() => {
    const delivered = shipments.filter((shipment) => shipment.status === 'delivered').length;
    const failed = shipments.filter((shipment) => shipment.status === 'delivery_failed').length;
    const returned = shipments.filter((shipment) => shipment.status === 'returned').length;

    return {
      total: shipments.length,
      active: shipments.filter((shipment) => managedStatuses.includes(shipment.status)).length,
      delivered,
      exceptionRate: shipments.length > 0 ? Math.round(((failed + returned) / shipments.length) * 100) : 0,
    };
  }, [shipments]);

  const providerOptions = useMemo(() => {
    const providerSet = new Set<string>();

    shipments.forEach((shipment) => {
      if (shipment.courier_provider && courierPartners.some((partner) => partner.code === String(shipment.courier_provider).toLowerCase())) {
        providerSet.add(shipment.courier_provider);
      }
    });

    return Array.from(providerSet).sort((left, right) => left.localeCompare(right));
  }, [shipments]);

  const parseAddress = (rawAddress?: string | Record<string, unknown> | null) => {
    if (!rawAddress) {
      return { city: 'Unknown', fullName: 'Customer' };
    }

    try {
      if (typeof rawAddress === 'string') {
        return JSON.parse(rawAddress) as { city?: string; fullName?: string };
      }

      return rawAddress as { city?: string; fullName?: string };
    } catch {
      return { city: 'Unknown', fullName: 'Customer' };
    }
  };

  const getPathaoEventSummary = (shipment: SellerShipment) => {
    const metadata =
      shipment.shipment_metadata && typeof shipment.shipment_metadata === 'object'
        ? (shipment.shipment_metadata as Record<string, unknown>)
        : {};

    const lastEvent = typeof metadata.pathaoLastEvent === 'string' ? metadata.pathaoLastEvent : null;
    const lastStatusSlug = typeof metadata.pathaoLastStatusSlug === 'string' ? metadata.pathaoLastStatusSlug : null;

    if (!lastEvent && !lastStatusSlug) return null;

    return {
      event: lastEvent ? lastEvent.replaceAll('_', ' ').replaceAll('.', ' ') : null,
      status: lastStatusSlug ? lastStatusSlug.replaceAll('_', ' ') : null,
    };
  };

  const handleExport = () => {
    const rows = viewScopedShipments.map((shipment) => {
      const address = parseAddress(shipment.shipping_address);
      return {
        shipment_id: shipment.id,
        order_id: shipment.order_id,
        status: shipment.status,
        courier_provider: shipment.courier_provider || '',
        tracking_id: shipment.tracking_id || '',
        warehouse_name: shipment.warehouse_name || '',
        warehouse_city: shipment.warehouse_city || '',
        destination_city: address.city || '',
        customer_name: address.fullName || '',
        payment_method: shipment.payment_method || '',
        item_count: shipment.item_count || 0,
        total: shipment.total,
        created_at: shipment.order_created_at || '',
      };
    });

    if (rows.length === 0) {
      info('No shipments matched the current courier filters.', 2600);
      return;
    }

    const headers = Object.keys(rows[0]);
    const csv = [
      headers.join(','),
      ...rows.map((row) =>
        headers
          .map((header) => {
            const value = String(row[header as keyof (typeof rows)[number]] ?? '');
            return `"${value.replaceAll('"', '""')}"`;
          })
          .join(','),
      ),
    ].join('\n');

    const blob = new Blob([csv], { type: 'text/csv;charset=utf-8;' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    const stamp = new Date().toISOString().slice(0, 10);

    link.href = url;
    link.download = `seller-courier-${view}-${stamp}.csv`;
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
    URL.revokeObjectURL(url);
    success(`Exported ${rows.length} courier shipment records.`, 2600);
  };

  const getProviderByCode = (code?: string | null) =>
    courierPartners.find((partner) => partner.code === String(code || '').toLowerCase()) || null;

  const getProviderBookingHint = (providerCode?: string | null) => {
    const normalizedCode = String(providerCode || '').toLowerCase();
    if (normalizedCode === 'steadfast') {
      return 'Book the parcel from the Steadfast merchant panel first, then save and follow the shipment from this queue.';
    }

    if (normalizedCode === 'paperfly') {
      return 'Use the Paperfly merchant workflow, then keep the tracking ID and milestone updates synced here.';
    }

    if (normalizedCode === 'pathao') {
      return 'Pathao can auto-book when API config and pickup mapping are complete. Otherwise use the manual merchant flow.';
    }

    if (normalizedCode === 'redx') {
      return 'RedX can auto-book when credentials are configured. Manual tracking still works as a safe fallback.';
    }

    return 'Use the courier merchant workflow, save the tracking ID, and keep shipment milestones updated here.';
  };

  const renderProviderSyncAction = (shipment: SellerShipment, busy: boolean) => {
    const isPathaoShipment = String(shipment.courier_provider || '').toLowerCase().includes('pathao');
    const isRedxShipment = String(shipment.courier_provider || '').toLowerCase().includes('redx');
    const isSteadfastShipment = String(shipment.courier_provider || '').toLowerCase().includes('steadfast');

    if (!isPathaoShipment && !courierPartners.some((partner) => partner.code === String(shipment.courier_provider).toLowerCase())) {
      return null;
    }

    if (isPathaoShipment) {
      return (
        <>
          <button
            onClick={() => void handlePathaoSync(shipment.id)}
            disabled={busy}
            className="rounded-lg border border-rose-200 bg-rose-50 px-3 py-1.5 text-[10px] font-bold text-rose-700 transition hover:bg-rose-100 disabled:opacity-50"
          >
            {busy ? 'Syncing...' : 'Sync Pathao'}
          </button>
          {shipment.tracking_id ? (
            <button
              onClick={() => void handlePathaoOrderInfo(shipment.tracking_id || '')}
              disabled={busy}
              className="rounded-lg border border-amber-200 bg-amber-50 px-3 py-1.5 text-[10px] font-bold text-amber-700 transition hover:bg-amber-100 disabled:opacity-50"
            >
              {busy ? 'Loading...' : 'Order Info'}
            </button>
          ) : null}
        </>
      );
    }

    if (isRedxShipment) {
      return (
        <button
          onClick={() => void handleRedxSync(shipment.id)}
          disabled={busy}
          className="rounded-lg border border-red-200 bg-red-50 px-3 py-1.5 text-[10px] font-bold text-red-700 transition hover:bg-red-100 disabled:opacity-50"
        >
          {busy ? 'Syncing...' : 'Sync RedX'}
        </button>
      );
    }

    if (isSteadfastShipment) {
      return (
        <button
          onClick={() => void handleSteadfastSync(shipment.id)}
          disabled={busy}
          className="rounded-lg border border-blue-200 bg-blue-50 px-3 py-1.5 text-[10px] font-bold text-blue-700 transition hover:bg-blue-100 disabled:opacity-50"
        >
          {busy ? 'Syncing...' : 'Sync Steadfast'}
        </button>
      );
    }

    return null;
  };

  const renderAction = (shipment: SellerShipment) => {
    const busy = updatingShipmentId === shipment.id;
    const isPathaoShipment = String(shipment.courier_provider || '').toLowerCase().includes('pathao');
    const isSteadfastShipment = String(shipment.courier_provider || '').toLowerCase().includes('steadfast');

    if (shipment.status === 'pending' || shipment.status === 'processing') {
      return (
        <button
          onClick={() => void handleStatusUpdate(shipment.id, 'packed')}
          disabled={busy}
          className="rounded-lg bg-slate-900 px-3 py-1.5 text-[10px] font-bold text-white transition hover:bg-slate-800 disabled:opacity-50"
        >
          {busy ? 'Saving...' : 'Mark Packed'}
        </button>
      );
    }

    if (shipment.status === 'packed') {
      return (
        <button
          onClick={() => void handleStatusUpdate(shipment.id, 'ready_for_pickup')}
          disabled={busy}
          className="rounded-lg bg-indigo-600 px-3 py-1.5 text-[10px] font-bold text-white transition hover:bg-indigo-700 disabled:opacity-50"
        >
          {busy ? 'Saving...' : 'Ready for Pickup'}
        </button>
      );
    }

    if (shipment.status === 'ready_for_pickup') {
      const selectedCode = selectedProvider[shipment.id] || courierPartners[0]?.code || 'pathao';
      const selectedPartner = getProviderByCode(selectedCode);
      return (
        <div className="space-y-2">
          <div className="flex items-center gap-2">
            <select
              value={selectedCode}
              onChange={(event) =>
                setSelectedProvider((current) => ({ ...current, [shipment.id]: event.target.value }))
              }
              className="rounded-lg border border-gray-200 bg-white px-3 py-1.5 text-[10px] font-bold text-gray-600"
            >
              {courierPartners.map((partner) => (
                <option key={partner.code} value={partner.code}>
                  {partner.name}
                </option>
              ))}
            </select>
            <button
              onClick={() => void handleRequestPickup(shipment.id)}
              disabled={busy}
              className="rounded-lg bg-emerald-600 px-3 py-1.5 text-[10px] font-bold text-white transition hover:bg-emerald-700 disabled:opacity-50"
            >
              {busy ? 'Saving...' : selectedCode === 'pathao' ? 'Book in Pathao' : 'Request Pickup'}
            </button>
          </div>
          <div className="rounded-lg border border-slate-200 bg-slate-50 px-3 py-2 text-[11px] text-slate-600">
            <span className="font-bold text-slate-800">{selectedPartner?.name || 'Courier'}:</span>{' '}
            {selectedPartner?.setupMessage || getProviderBookingHint(selectedCode)}
          </div>
          {selectedCode === 'pathao' ? (
            <div className="rounded-lg border border-rose-100 bg-rose-50 px-3 py-2 text-[11px] text-rose-800">
              Pathao auto-booking works best when this shipment's pickup location already has a linked store, city, zone, and area mapping.
            </div>
          ) : null}
        </div>
      );
    }

    if (shipment.status === 'pickup_requested') {
      return (
        <div className="space-y-2">
          <div className="flex flex-wrap items-center gap-2">
            <button
              onClick={() => void handleStatusUpdate(shipment.id, 'picked_up')}
              disabled={busy}
              className="rounded-lg border border-gray-200 bg-white px-3 py-1.5 text-[10px] font-bold text-gray-700 transition hover:bg-gray-50 disabled:opacity-50"
            >
              {busy ? 'Saving...' : 'Mark Picked Up'}
            </button>
            {renderProviderSyncAction(shipment, busy)}
          </div>
          {isSteadfastShipment ? (
            <div className="rounded-lg border border-blue-100 bg-blue-50 px-3 py-2 text-[11px] text-blue-800">
              Finish the Steadfast merchant-panel update first, then continue shipment milestones from here.
            </div>
          ) : null}
        </div>
      );
    }

    if (shipment.status === 'picked_up') {
      return (
        <div className="flex flex-wrap items-center gap-2">
          <button
            onClick={() => void handleStatusUpdate(shipment.id, 'in_transit')}
            disabled={busy}
            className="rounded-lg border border-gray-200 bg-white px-3 py-1.5 text-[10px] font-bold text-gray-700 transition hover:bg-gray-50 disabled:opacity-50"
          >
            {busy ? 'Saving...' : 'Start Transit'}
          </button>
          {renderProviderSyncAction(shipment, busy)}
          </div>
      );
    }

    if (shipment.status === 'in_transit') {
      return (
        <div className="flex flex-wrap items-center gap-2">
          <button
            onClick={() => void handleStatusUpdate(shipment.id, 'out_for_delivery')}
            disabled={busy}
            className="rounded-lg border border-gray-200 bg-white px-3 py-1.5 text-[10px] font-bold text-gray-700 transition hover:bg-gray-50 disabled:opacity-50"
          >
            {busy ? 'Saving...' : 'Out for Delivery'}
          </button>
          {renderProviderSyncAction(shipment, busy)}
          </div>
      );
    }

    if (shipment.status === 'out_for_delivery') {
      return (
        <div className="flex flex-wrap items-center gap-2">
          <button
            onClick={() => void handleStatusUpdate(shipment.id, 'delivered')}
            disabled={busy}
            className="rounded-lg bg-emerald-600 px-3 py-1.5 text-[10px] font-bold text-white transition hover:bg-emerald-700 disabled:opacity-50"
          >
            {busy ? 'Saving...' : 'Mark Delivered'}
          </button>
          {renderProviderSyncAction(shipment, busy)}
          </div>
      );
    }

    return <div className="text-xs font-bold text-emerald-600">Handled</div>;
  };

  if (loading) {
    return (
      <div className="flex items-center justify-center h-64">
        <Loader2 className="animate-spin text-primary" size={32} />
      </div>
    );
  }

  return (
    <div className="space-y-8">
      <NotificationContainer notifications={notifications} onClose={removeNotification} />

      {user?.seller_status !== 'approved' ? (
        <div className="rounded-xl border border-amber-200 bg-amber-50 p-4 text-sm text-amber-800">
          Courier booking is locked until admin approves your seller account. You can still complete pickup setup and logistics readiness from this page.
        </div>
      ) : null}

      {error ? (
        <div className="rounded-xl border border-amber-200 bg-amber-50 p-4 text-sm text-amber-800">
          {error}
        </div>
      ) : null}

      <div className="flex flex-col gap-4 md:flex-row md:items-center md:justify-between">
        <div>
          <h1 className="text-2xl font-bold tracking-tight text-gray-900">Courier & Shipping</h1>
          <p className="text-gray-500">Handle shipment pickup from different seller locations and warehouses.</p>
        </div>
        <div className="flex flex-wrap items-center gap-3">
          <div className="flex items-center gap-2 rounded-xl border border-gray-200 bg-white px-4 py-2 shadow-sm">
            <div className={`h-2 w-2 rounded-full ${apiReady ? 'bg-emerald-500 animate-pulse' : 'bg-amber-500'}`} />
            <span className="text-xs font-bold text-gray-600">
              {apiReady ? 'Shipment flow live' : 'Live shipment data unavailable'}
            </span>
          </div>
        </div>
      </div>

      <div className="grid grid-cols-2 gap-3 md:grid-cols-4">
        {courierPartners.map((partner) => (
          <div
            key={partner.code}
            className="flex items-center gap-3 rounded-2xl border border-gray-100 bg-white p-3 shadow-sm md:p-4"
          >
            <div
              className="flex h-10 w-10 items-center justify-center rounded-xl font-bold text-white"
              style={{ backgroundColor: partner.brandColor || '#0f172a' }}
            >
              {partner.shortLabel || partner.name.slice(0, 2).toUpperCase()}
            </div>
            <div>
              <p className="text-sm font-bold">{partner.name}</p>
              <p className="text-[10px] text-gray-400">
                {partner.setupStatus === 'api_ready'
                  ? 'API config ready'
                  : partner.setupStatus === 'missing_config'
                    ? 'Config needed for API mode'
                    : 'Manual pickup workflow'}
              </p>
            </div>
          </div>
        ))}
      </div>

      <div className="grid grid-cols-2 gap-3 xl:grid-cols-4">
        <div className="rounded-2xl border border-black/5 bg-white p-4 shadow-sm md:p-5">
          <p className="text-xs font-bold uppercase tracking-wider text-gray-500">Total Shipments</p>
          <p className="mt-2 text-xl font-bold text-slate-900 md:text-2xl">{shipmentSummary.total}</p>
        </div>
        <div className="rounded-2xl border border-black/5 bg-white p-4 shadow-sm md:p-5">
          <p className="text-xs font-bold uppercase tracking-wider text-gray-500">Active Queue</p>
          <p className="mt-2 text-xl font-bold text-indigo-700 md:text-2xl">{shipmentSummary.active}</p>
        </div>
        <div className="rounded-2xl border border-black/5 bg-white p-4 shadow-sm md:p-5">
          <p className="text-xs font-bold uppercase tracking-wider text-gray-500">Delivered</p>
          <p className="mt-2 text-xl font-bold text-emerald-700 md:text-2xl">{shipmentSummary.delivered}</p>
        </div>
        <div className="rounded-2xl border border-black/5 bg-white p-4 shadow-sm md:p-5">
          <p className="text-xs font-bold uppercase tracking-wider text-gray-500">Exception Rate</p>
          <p className="mt-2 text-xl font-bold text-amber-700 md:text-2xl">{shipmentSummary.exceptionRate}%</p>
        </div>
      </div>

      <div ref={deferredGuidanceRef} className="space-y-6">
        {showDeferredGuidance ? (
          <>
      <div className="rounded-3xl border border-indigo-100 bg-indigo-50/60 p-5 text-sm text-indigo-900">
        <p className="font-semibold">Recommended courier flow</p>
        <p className="mt-1">
          processing -&gt; packed -&gt; ready_for_pickup -&gt; pickup_requested -&gt; picked_up -&gt; in_transit -&gt; out_for_delivery -&gt; delivered
        </p>
      </div>

      <section className="rounded-[32px] border border-rose-100 bg-white p-5 shadow-sm md:p-6">
        <div className="flex flex-col gap-3 md:flex-row md:items-start md:justify-between">
          <div>
            <p className="text-xs font-bold uppercase tracking-[0.24em] text-rose-600">Pathao readiness</p>
            <h2 className="mt-2 text-lg font-bold text-slate-950">Seller-side booking blockers</h2>
            <p className="mt-2 text-sm text-slate-500">
              See which pickup locations or shipment details still need work before reliable Pathao auto-booking.
            </p>
          </div>
          <button
            type="button"
            onClick={() => void loadPathaoReadiness()}
            disabled={loadingPathaoReadiness}
            className="inline-flex items-center gap-2 rounded-2xl border border-slate-200 bg-white px-4 py-3 text-sm font-semibold text-slate-700 transition hover:bg-slate-50 disabled:opacity-50"
          >
            <Loader2 className={`h-4 w-4 ${loadingPathaoReadiness ? 'animate-spin' : 'hidden'}`} />
            <span>{loadingPathaoReadiness ? 'Refreshing...' : 'Refresh readiness'}</span>
          </button>
        </div>

        <div className="mt-5 grid gap-6 xl:grid-cols-[0.95fr_1.05fr]">
          <div className="space-y-3">
            <div className="flex items-center justify-between gap-3">
              <h3 className="text-sm font-bold text-slate-900">Pickup location blockers</h3>
              <span className={`rounded-full px-2.5 py-1 text-[10px] font-bold uppercase tracking-wider ${
                pathaoReadiness?.envReady ? 'bg-emerald-100 text-emerald-800' : 'bg-amber-100 text-amber-800'
              }`}>
                {pathaoReadiness?.envReady ? 'Env ready' : 'Env check needed'}
              </span>
            </div>
            {pathaoReadiness?.warehouseBlockers.length ? (
              pathaoReadiness.warehouseBlockers.map((warehouse) => (
                <div key={warehouse.id} className="rounded-2xl border border-amber-100 bg-amber-50 p-4">
                  <div className="flex items-center justify-between gap-3">
                    <p className="font-semibold text-slate-900">{warehouse.name}</p>
                    <a
                      href={`/seller/pickup-locations?warehouse=${encodeURIComponent(warehouse.id)}`}
                      className="text-[11px] font-semibold text-slate-700 hover:text-primary"
                    >
                      Fix now
                    </a>
                  </div>
                  <div className="mt-3 flex flex-wrap gap-2">
                    {warehouse.blockers.map((blocker) => (
                      <span
                        key={blocker}
                        className="rounded-full border border-amber-200 bg-white px-2.5 py-1 text-[10px] font-bold text-amber-800"
                      >
                        {blocker}
                      </span>
                    ))}
                  </div>
                </div>
              ))
            ) : (
              <div className="rounded-2xl border border-emerald-100 bg-emerald-50 p-4 text-sm text-emerald-800">
                Pickup locations look good for Pathao mapping right now.
              </div>
            )}
          </div>

          <div className="space-y-3">
            <h3 className="text-sm font-bold text-slate-900">Shipment booking dry-run</h3>
            {pathaoReadiness?.bookingCandidates.length ? (
              pathaoReadiness.bookingCandidates.map((shipment) => (
                <div
                  key={shipment.id}
                  className={`rounded-2xl border p-4 ${
                    shipment.blockers.length ? 'border-amber-100 bg-amber-50' : 'border-emerald-100 bg-emerald-50'
                  }`}
                >
                  <div className="flex items-center justify-between gap-3">
                    <div>
                      <p className="font-semibold text-slate-900">Shipment #{shipment.id.slice(0, 8)}</p>
                      <p className="mt-1 text-sm text-slate-600">
                        Order {shipment.order_id} • {shipment.warehouse_name || 'Warehouse pending'}
                      </p>
                    </div>
                    <a
                      href={`/seller/courier?search=${encodeURIComponent(shipment.tracking_id || shipment.id)}`}
                      className="text-[11px] font-semibold text-slate-700 hover:text-primary"
                    >
                      Open shipment
                    </a>
                  </div>
                  <div className="mt-3 flex flex-wrap gap-2">
                    {shipment.blockers.length ? (
                      shipment.blockers.map((blocker) => (
                        <span
                          key={blocker}
                          className="rounded-full border border-amber-200 bg-white px-2.5 py-1 text-[10px] font-bold text-amber-800"
                        >
                          {blocker}
                        </span>
                      ))
                    ) : (
                      <span className="rounded-full border border-emerald-200 bg-white px-2.5 py-1 text-[10px] font-bold text-emerald-700">
                        Ready for Pathao booking
                      </span>
                    )}
                  </div>
                </div>
              ))
            ) : (
              <div className="rounded-2xl border border-slate-200 bg-slate-50 p-4 text-sm text-slate-600">
                No active seller shipments need a Pathao dry-run check right now.
              </div>
            )}
          </div>
        </div>
      </section>

          </>
        ) : (
          <div className="grid gap-4 md:grid-cols-2">
            <div className="h-28 animate-pulse rounded-3xl border border-indigo-100 bg-indigo-50/60" />
            <div className="h-64 animate-pulse rounded-[32px] border border-rose-100 bg-white shadow-sm" />
          </div>
        )}
      </div>

      <div className="overflow-hidden rounded-[32px] border border-gray-100 bg-white shadow-sm">
        <div className="mobile-sticky-toolbar flex flex-col gap-4 border-b border-gray-50 bg-gray-50/50 p-4 md:p-6 xl:flex-row xl:items-center xl:justify-between">
          <div>
            <h3 className="font-bold">Live Shipment Queue</h3>
            <div className="mt-3 flex flex-wrap gap-2">
              {sellerCourierViews.map((option) => (
                <button
                  key={option}
                  onClick={() => setView(option)}
                  className={`rounded-full px-3 py-1.5 text-[11px] font-bold capitalize transition ${
                    view === option
                      ? 'bg-slate-900 text-white'
                      : 'border border-gray-200 bg-white text-gray-600 hover:border-indigo-200 hover:text-indigo-700'
                  }`}
                >
                  {option === 'all'
                    ? 'All'
                    : option === 'active'
                      ? 'Active'
                      : option === 'exceptions'
                        ? 'Exceptions'
                        : 'History'}
                </button>
              ))}
            </div>
          </div>
          <div className="flex flex-col gap-2 sm:flex-row sm:flex-wrap sm:items-center">
            <div className="relative w-full sm:w-auto">
              <Search className="absolute left-3 top-1/2 -translate-y-1/2 h-4 w-4 text-gray-400" />
              <input
                type="text"
                placeholder="Search shipment, tracking, warehouse..."
                value={searchTerm}
                onChange={(event) => setSearchTerm(event.target.value)}
                className="w-full rounded-xl border border-gray-200 bg-white py-3 pl-9 pr-4 text-xs outline-none focus:ring-2 focus:ring-indigo-500/20 sm:w-64 sm:py-2"
              />
            </div>
            <select
              value={providerFilter}
              onChange={(event) => setProviderFilter(event.target.value)}
              className="w-full rounded-xl border border-gray-200 bg-white px-3 py-3 text-xs font-semibold text-gray-600 outline-none focus:ring-2 focus:ring-indigo-500/20 sm:w-auto sm:py-2"
            >
              <option value="all">All couriers</option>
              <option value="unassigned">Unassigned</option>
              {providerOptions.map((provider) => (
                <option key={provider} value={provider}>
                  {provider}
                </option>
              ))}
            </select>
            <input
              type="date"
              value={dateFrom}
              onChange={(event) => setDateFrom(event.target.value)}
              className="w-full rounded-xl border border-gray-200 bg-white px-3 py-3 text-xs font-semibold text-gray-600 outline-none focus:ring-2 focus:ring-indigo-500/20 sm:w-auto sm:py-2"
              aria-label="Filter shipments from date"
            />
            <input
              type="date"
              value={dateTo}
              onChange={(event) => setDateTo(event.target.value)}
              className="w-full rounded-xl border border-gray-200 bg-white px-3 py-3 text-xs font-semibold text-gray-600 outline-none focus:ring-2 focus:ring-indigo-500/20 sm:w-auto sm:py-2"
              aria-label="Filter shipments to date"
            />
            <button
              onClick={() => info('Search by shipment ID, tracking ID, status, warehouse, courier, or date range.', 2600)}
              className="rounded-xl border border-gray-200 bg-white p-3 text-gray-400 hover:text-indigo-600 sm:p-2"
            >
              <Filter className="h-4 w-4" />
            </button>
            <button
              onClick={() => {
                setSearchTerm('');
                setProviderFilter('all');
                setDateFrom('');
                setDateTo('');
                setView('all');
              }}
              className="rounded-xl border border-gray-200 bg-white px-3 py-3 text-xs font-bold text-gray-600 transition hover:border-indigo-200 hover:text-indigo-700 sm:py-2"
            >
              Clear
            </button>
            <button
              onClick={handleExport}
              className="inline-flex items-center justify-center gap-2 rounded-xl border border-gray-200 bg-white px-3 py-3 text-xs font-bold text-gray-600 transition hover:border-indigo-200 hover:text-indigo-700 sm:py-2"
            >
              <Download className="h-4 w-4" />
              Export CSV
            </button>
          </div>
        </div>

        <div className="overflow-x-auto">
          <table className="w-full text-left">
            <thead>
              <tr className="border-b border-gray-50 text-[10px] uppercase tracking-widest text-gray-400">
                <th className="px-6 py-4 font-bold">Shipment</th>
                <th className="px-6 py-4 font-bold">Pickup & Destination</th>
                <th className="px-6 py-4 font-bold">Payment</th>
                <th className="px-6 py-4 font-bold">Current Stage</th>
                <th className="px-6 py-4 font-bold">Next Action</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-gray-50">
              {renderedActiveShipments.length > 0 ? (
                renderedActiveShipments.map((shipment) => {
                  const address = parseAddress(shipment.shipping_address);
                  const pathaoEventSummary = getPathaoEventSummary(shipment);
                  const focused = shipment.id === focusedShipmentId;
                  return (
                    <tr
                      id={`seller-shipment-${shipment.id}`}
                      key={shipment.id}
                      className={`transition-colors hover:bg-gray-50/50 ${
                        focused ? 'bg-indigo-50 ring-2 ring-inset ring-indigo-200' : ''
                      }`}
                    >
                      <td className="px-6 py-6">
                        <p className="mb-1 text-sm font-bold">Shipment #{String(shipment.id).slice(0, 8)}</p>
                        <p className="text-xs text-gray-400">Order #{String(shipment.order_id).slice(0, 10)}</p>
                        <p className="mt-1 text-[11px] text-gray-400">
