        </p>
      </div>
      <div className="space-y-4 px-5 py-5">
        <div className="grid grid-cols-1 gap-3 sm:grid-cols-2">
            <div className="rounded-xl bg-secondary/40 px-4 py-4">
            <p className="text-xs font-bold uppercase tracking-[0.18em] text-slate-500">Products live</p>
            <p className="mt-2 text-2xl font-black text-slate-950">{productCount}</p>
          </div>
            <div className="rounded-xl bg-secondary/40 px-4 py-4">
            <p className="text-xs font-bold uppercase tracking-[0.18em] text-slate-500">Status</p>
            <p className="mt-2 text-sm font-bold text-slate-950">{publishReady ? 'Ready to promote' : 'Needs setup'}</p>
          </div>
        </div>
        <div className="flex flex-wrap gap-2">
          {storefrontPath ? (
            <Link
              to={storefrontPath}
              className="inline-flex items-center gap-2 rounded-full bg-slate-950 px-4 py-2 text-xs font-semibold text-white transition hover:bg-slate-800"
            >
              <Eye size={14} />
              Open storefront
            </Link>
          ) : null}
          <Link
            to="/seller/settings"
            className="inline-flex items-center gap-2 rounded-full border border-border px-4 py-2 text-xs font-semibold text-slate-700 transition hover:border-primary/20 hover:text-primary"
          >
            <Settings2 size={14} />
            Update branding
          </Link>
        </div>
      </div>
    </div>
  );
}

function SellerStorefrontPreview({
  storeName,
  bannerUrl,
  avatarUrl,
  headline,
  storefrontSlug,
  products,
  bestSellers,
  flashSaleEntries,
  coupons,
}: {
  storeName: string;
  bannerUrl?: string | null;
  avatarUrl?: string | null;
  headline?: string | null;
  storefrontSlug?: string | null;
  products: Product[];
  bestSellers: Product[];
  flashSaleEntries: FlashSaleEntry[];
  coupons: SellerCoupon[];
}) {
  const storefrontPath = storefrontSlug ? `/store/${storefrontSlug}` : '';
  const latestProducts = useMemo(() => products.slice(0, 8), [products]);
  const featuredProducts = useMemo(
    () => (bestSellers.length > 0 ? bestSellers.slice(0, 4) : products.slice(0, 4)),
    [bestSellers, products],
  );
  const flashProducts = useMemo(
    () =>
      flashSaleEntries
        .filter((entry) => ['approved', 'live', 'published'].includes(String(entry.status || '').toLowerCase()) && entry.product)
        .slice(0, 4),
    [flashSaleEntries],
  );
  const previewCoupons = useMemo(() => coupons.slice(0, 3), [coupons]);

  return (
    <div className="space-y-8">
      <section className="overflow-hidden rounded-[2rem] border border-border bg-white shadow-sm">
        <div className="relative min-h-[260px] overflow-hidden bg-slate-950">
          {bannerUrl ? (
            <OptimizedImage
              src={bannerUrl}
              alt={`${storeName} storefront banner`}
              eager
              widthHint={1600}
              heightHint={640}
              className="absolute inset-0 h-full w-full object-cover"
            />
          ) : null}
          <div
            className="absolute inset-0"
            style={{
              background: bannerUrl
                ? 'linear-gradient(180deg, rgba(2, 6, 23, 0.08), rgba(2, 6, 23, 0.62))'
                : 'linear-gradient(135deg, rgba(15, 23, 42, 0.92), rgba(15, 118, 110, 0.82))',
            }}
          />
          {!bannerUrl ? (
            <div className="absolute inset-0 flex items-center justify-center text-sm font-semibold text-white/75">
              Upload a storefront banner from settings to preview it here.
            </div>
          ) : null}
          <div className="relative flex min-h-[260px] flex-col justify-between gap-5 px-5 py-5 text-white sm:px-6 sm:py-6">
            <div className="flex items-start justify-between gap-4">
              <span className="inline-flex items-center gap-2 rounded-full border border-white/15 bg-white/10 px-3 py-1 section-kicker backdrop-blur">
                <Store size={14} />
                Uploaded storefront banner
              </span>
              {storefrontPath ? (
                <Link
                  to={storefrontPath}
                  className="inline-flex items-center gap-2 rounded-full border border-white/20 bg-white/10 px-4 py-2 text-xs font-semibold text-white backdrop-blur transition hover:bg-white/15"
                >
                  <Eye size={14} />
                  Open storefront
                </Link>
              ) : null}
            </div>

            <div className="flex items-end gap-4">
              <div className="flex h-16 w-16 items-center justify-center overflow-hidden rounded-[1.25rem] border border-white/15 bg-white/10 text-2xl font-bold uppercase backdrop-blur">
                {avatarUrl ? (
                  <OptimizedImage
                    src={avatarUrl}
                    alt={storeName}
                    eager
                    widthHint={160}
                    heightHint={160}
                    className="h-full w-full object-cover"
                  />
                ) : (
                  storeName[0] || 'S'
                )}
              </div>
              <div className="min-w-0">
                <h2 className="truncate text-2xl font-bold sm:text-3xl">{storeName}</h2>
                <p className="mt-2 max-w-3xl text-sm leading-6 text-white/84 sm:text-base">
                  {headline || 'Your public storefront preview appears here exactly where shoppers first notice your brand.'}
                </p>
                <p className="mt-2 text-xs font-semibold uppercase tracking-[0.2em] text-white/70">
                  {storefrontPath ? `Public shop: ${storefrontPath}` : 'Public shop link not set yet'}
                </p>
              </div>
            </div>
          </div>
        </div>
      </section>

      {previewCoupons.length > 0 ? (
        <section className="rounded-[2rem] border border-border bg-white p-6 shadow-sm">
          <div className="mb-5 flex flex-col gap-3 sm:flex-row sm:items-end sm:justify-between">
            <div>
              <p className="section-kicker text-primary/70">Store promotions</p>
              <h2 className="mt-2 text-2xl font-bold text-slate-950">Coupons customers can use now</h2>
            </div>
            <Link to="/seller/marketing" className="text-sm font-semibold text-primary hover:text-primary-dark">
              Manage coupons
            </Link>
          </div>
          <div className="grid gap-4 lg:grid-cols-3">
            {previewCoupons.map((coupon) => {
              const discountLabel =
                coupon.discount_type === 'percentage'
                  ? `${coupon.discount_value}% off`
                  : `${formatPrice(coupon.discount_value)} off`;
              return (
                <div key={coupon.id} className="rounded-[1.5rem] border border-border bg-secondary/20 p-5">
                  <div className="flex items-start justify-between gap-4">
                    <div>
                      <p className="text-xs font-bold uppercase tracking-[0.22em] text-primary/70">Coupon code</p>
                      <h3 className="mt-2 text-xl font-black tracking-[0.16em] text-slate-950">{coupon.code}</h3>
                    </div>
                    <button
                      type="button"
                      onClick={() => {
                        void (async () => {
                          const copied = await copyText(coupon.code);
                          if (copied) {
                            toast.success(`Coupon ${coupon.code} copied.`);
                            return;
                          }
                          toast.error('Could not copy this coupon on this device.');
                        })();
                      }}
                      className="inline-flex items-center gap-1 rounded-full border border-border bg-white px-3 py-1.5 text-xs font-semibold text-slate-700 transition hover:border-primary/20 hover:text-primary"
                    >
                      <Copy size={13} />
                      Copy
                    </button>
                  </div>
                  <p className="mt-4 text-base font-semibold text-slate-900">{discountLabel}</p>
                  <div className="mt-3 space-y-1 text-sm text-slate-500">
                    <p>Minimum order: {formatPrice(coupon.min_order_value)}</p>
                    <p>Valid until: {new Date(coupon.expiry_date).toLocaleDateString()}</p>
                  </div>
                </div>
              );
            })}
          </div>
        </section>
      ) : null}

      {flashProducts.length > 0 ? (
        <section className="rounded-[2rem] border border-border bg-white p-6 shadow-sm">
          <div className="mb-5 flex flex-col gap-3 sm:flex-row sm:items-end sm:justify-between">
            <div>
              <p className="inline-flex items-center gap-2 section-kicker text-accent/80">
                <Zap size={14} className="fill-accent text-accent" />
                Flash sale
              </p>
              <h2 className="mt-2 text-2xl font-bold text-slate-950">Approved sale picks</h2>
            </div>
            <Link to="/seller/flash-sale" className="text-sm font-semibold text-primary hover:text-primary-dark">
              Manage flash sale
            </Link>
          </div>
          <div className="grid grid-cols-1 gap-5 sm:grid-cols-2 md:grid-cols-4">
            {flashProducts.map((entry) => (
              <ProductCard key={entry.id} product={entry.product as Product} />
            ))}
          </div>
        </section>
      ) : null}

      <section className="rounded-[2rem] border border-border bg-white p-6 shadow-sm">
        <div className="mb-5 flex flex-col gap-3 sm:flex-row sm:items-end sm:justify-between">
          <div>
            <p className="section-kicker text-primary/70">Featured products</p>
            <h2 className="mt-2 text-2xl font-bold text-slate-950">Storefront highlights</h2>
          </div>
          <Link to="/seller/products" className="text-sm font-semibold text-primary hover:text-primary-dark">
            See full catalog
          </Link>
        </div>
        <div className="grid grid-cols-1 gap-5 sm:grid-cols-2 md:grid-cols-4">
          {featuredProducts.length === 0 ? (
            <div className="col-span-full rounded-2xl border border-dashed border-border bg-secondary/30 px-4 py-10 text-center text-sm text-muted-foreground">
              Add products to see your storefront preview cards here.
            </div>
          ) : (
            featuredProducts.map((product) => <ProductCard key={product.id} product={product} />)
          )}
        </div>
      </section>

      <section className="rounded-[2rem] border border-border bg-white p-6 shadow-sm">
        <div className="mb-5 flex flex-col gap-3 sm:flex-row sm:items-end sm:justify-between">
          <div>
            <p className="section-kicker text-primary/70">Latest products</p>
            <h2 className="mt-2 text-2xl font-bold text-slate-950">Newest catalog entries</h2>
          </div>
          <Link to="/seller/products/add" className="text-sm font-semibold text-primary hover:text-primary-dark">
            Add another product
          </Link>
        </div>
        <div className="grid grid-cols-1 gap-5 sm:grid-cols-2 md:grid-cols-4">
          {latestProducts.length === 0 ? (
            <div className="col-span-full rounded-2xl border border-dashed border-border bg-secondary/30 px-4 py-10 text-center text-sm text-muted-foreground">
              Your latest products will appear here once you add them.
            </div>
          ) : (
            latestProducts.map((product) => <ProductCard key={product.id} product={product} />)
          )}
        </div>
      </section>

    </div>
  );
}

function SellerDashboardManageView({
  stats,
  insights,
  onboarding,
  products,
  user,
}: {
  stats: SellerStatsResponse;
  insights: SellerDashboardInsights;
  onboarding: SellerOnboardingStatus | null;
  products: Product[];
  user: ReturnType<typeof useUser>['user'];
}) {
  const salesSeriesValues = useMemo(
    () => insights.salesSeries.map((item) => Number(item.revenue || 0)),
    [insights.salesSeries],
  );

  const todaySales = salesSeriesValues[salesSeriesValues.length - 1] || 0;
  const previousSales = salesSeriesValues[salesSeriesValues.length - 2] || 0;
  const lowStockCount = insights.lowStockProducts.length;
  const storeHealthScore = useMemo(() => {
    const onboardingScore = Number(onboarding?.summary?.progress_percent || 0);
    const stockPenalty = Math.min(lowStockCount * 4, 24);
    const shipmentPenalty = insights.activeShipments > 12 ? 10 : insights.activeShipments > 6 ? 5 : 0;
    return Math.max(42, Math.min(100, onboardingScore - stockPenalty - shipmentPenalty + 18));
  }, [insights.activeShipments, lowStockCount, onboarding?.summary?.progress_percent]);

  const publishReady = Number(onboarding?.summary?.progress_percent || 0) >= 100;
  const pendingOrders = Math.max(0, insights.activeShipments - insights.deliveredShipments);
  const onboardingProgress = Number(onboarding?.summary?.progress_percent || 0);
  const onboardingChecklist = useMemo(() => {
    const checklist: Array<{ label: string; done: boolean }> = [
      { label: 'Branding complete', done: onboardingProgress >= 25 },
      { label: 'Products published', done: stats.totalProducts > 0 },
      { label: 'Payout / courier ready', done: publishReady || insights.activeShipments > 0 },
    ];

    if (onboarding?.approval?.status === 'approved') {
      checklist[0] = { label: 'Seller approval granted', done: true };
    }

    return checklist;
  }, [insights.activeShipments, onboarding?.approval?.status, onboardingProgress, publishReady, stats.totalProducts]);

  const statCards = useMemo(
    (): SellerKpiConfig[] => [
      {
        label: 'Revenue',
        value: formatPrice(stats.totalEarnings),
        trend: formatTrendValue(todaySales, previousSales),
        trendTone: todaySales >= previousSales ? 'good' : 'warning',
        icon: <DollarSign size={18} />,
        chart: salesSeriesValues.slice(-6),
      },
      {
        label: 'Orders',
        value: String(stats.totalOrders),
        trend: `${insights.recentShipments.length} recent`,
        trendTone: 'neutral',
        icon: <ShoppingBag size={18} />,
        chart: insights.recentShipments.slice(-6).map((shipment) => Number(shipment.total || 0)),
      },
      {
        label: 'Active products',
        value: String(stats.totalProducts),
        trend: lowStockCount > 0 ? `${lowStockCount} low stock` : 'Catalog healthy',
        trendTone: lowStockCount > 0 ? 'warning' : 'good',
        icon: <Package size={18} />,
        chart: products.slice(0, 6).map((product) => Number(product.stock || 0)),
      },
      {
        label: 'Pending shipment',
        value: String(insights.activeShipments),
        trend: `${insights.deliveredShipments} delivered`,
        trendTone: 'neutral',
        icon: <Truck size={18} />,
        chart: [insights.activeShipments, pendingOrders, insights.deliveredShipments, insights.activeShipments, pendingOrders],
      },
      {
        label: 'Store health',
        value: `${storeHealthScore}%`,
        trend: publishReady ? 'Live-ready' : 'Setup in progress',
        trendTone: publishReady ? 'good' : 'warning',
        icon: <TrendingUp size={18} />,
        chart: [storeHealthScore - 8, storeHealthScore - 4, storeHealthScore],
      },
      {
        label: 'Repeat momentum',
        value: stats.totalOrders > 0 ? `${Math.min(68, 12 + stats.topProducts.length * 7)}%` : '0%',
        trend: stats.topProducts.length > 0 ? 'Top products converting' : 'Needs order history',
        trendTone: stats.topProducts.length > 0 ? 'good' : 'neutral',
        icon: <Zap size={18} />,
        chart: stats.topProducts.slice(0, 6).map((product) => Number(product.sales || 0)),
      },
    ],
    [
      insights.activeShipments,
      insights.deliveredShipments,
      insights.recentShipments,
      lowStockCount,
      pendingOrders,
      previousSales,
      products,
      publishReady,
      salesSeriesValues,
      stats.totalEarnings,
      stats.totalOrders,
      stats.totalProducts,
      stats.topProducts,
      storeHealthScore,
      todaySales,
    ],
  );

  const criticalLowStockItem = useMemo(
    () => insights.lowStockProducts.find((item) => item.stock <= 2) ?? insights.lowStockProducts[0] ?? null,
    [insights.lowStockProducts],
  );

  const alerts = useMemo(() => {
    const nextAlerts: Array<{
      id: string;
      tone: 'critical' | 'warning' | 'info' | 'success';
      title: string;
      description: string;
      cta?: React.ReactNode;
    }> = [];

    if (onboarding && Number(onboarding.summary?.progress_percent || 0) < 100) {
      nextAlerts.push({
        id: 'onboarding',
        tone: 'info',
        title: 'Finish store setup before scaling traffic',
        description: `${onboarding.summary?.completed_steps || 0}/${onboarding.summary?.total_steps || 0} onboarding steps complete.${onboarding.next_step?.title ? ` Next: ${onboarding.next_step.title}.` : ''}`,
        cta: (
          <Link
            to={onboarding.next_step?.action_path || '/seller/onboarding'}
            className="inline-flex items-center gap-2 rounded-full bg-white px-3 py-1.5 text-xs font-semibold text-slate-700 transition hover:text-primary"
          >
            Continue setup
            <ArrowRight size={13} />
          </Link>
        ),
      });
    }

    if (criticalLowStockItem) {
      nextAlerts.push({
        id: 'stock',
        tone: criticalLowStockItem.stock <= 2 ? 'critical' : 'warning',
        title: `${criticalLowStockItem.name} needs a stock decision`,
        description: `Only ${criticalLowStockItem.stock} unit${criticalLowStockItem.stock === 1 ? '' : 's'} left${criticalLowStockItem.warehouse_name ? ` in ${criticalLowStockItem.warehouse_name}` : ''}.`,
        cta: (
          <Link
            to={`/seller/products/edit/${encodeURIComponent(String(criticalLowStockItem.id))}`}
            className="inline-flex items-center gap-2 rounded-full bg-white px-3 py-1.5 text-xs font-semibold text-slate-700 transition hover:text-primary"
          >
            Update stock
            <ArrowRight size={13} />
          </Link>
        ),
      });
    }

    if (insights.activeShipments > 0) {
      nextAlerts.push({
        id: 'shipments',
        tone: 'success',
        title: `${insights.activeShipments} shipment${insights.activeShipments === 1 ? '' : 's'} currently moving`,
        description: `${pendingOrders} orders still need active fulfillment attention across courier and packing.`,
        cta: (
          <Link
            to="/seller/courier"
            className="inline-flex items-center gap-2 rounded-full bg-white px-3 py-1.5 text-xs font-semibold text-slate-700 transition hover:text-primary"
          >
            Open courier panel
            <ArrowRight size={13} />
          </Link>
        ),
      });
    }

    return nextAlerts.slice(0, 4);
  }, [criticalLowStockItem, insights.activeShipments, onboarding, pendingOrders]);

  const todayPriorities = useMemo((): SellerPriorityItem[] => {
    const queue: SellerPriorityItem[] = [];

    if (pendingOrders > 0) {
      queue.push({
        id: 'pending-orders',
        tone: pendingOrders > 6 ? 'critical' : 'warning',
        title: `${pendingOrders} order${pendingOrders === 1 ? '' : 's'} waiting for fulfillment`,
        description:
          pendingOrders > 6
            ? 'Packing and courier attention is building up. Clear this queue before adding more campaign pressure.'
            : 'A small fulfillment queue is active. Review fresh orders before they age.',
        to: '/seller/orders',
        ctaLabel: 'Open orders',
      });
    }

    if (criticalLowStockItem) {
      queue.push({
        id: 'stock-queue',
        tone: criticalLowStockItem.stock <= 2 ? 'critical' : 'warning',
        title: `${criticalLowStockItem.name} is close to selling out`,
        description: `Only ${criticalLowStockItem.stock} unit${criticalLowStockItem.stock === 1 ? '' : 's'} left${criticalLowStockItem.warehouse_name ? ` in ${criticalLowStockItem.warehouse_name}` : ''}.`,
        to: `/seller/products/edit/${encodeURIComponent(String(criticalLowStockItem.id))}`,
        ctaLabel: 'Fix stock',
      });
    }

    if (!publishReady) {
      queue.push({
        id: 'publish-ready',
        tone: 'info',
        title: 'Storefront still needs setup before scaling traffic',
        description: onboarding?.next_step?.title
          ? `Next best step: ${onboarding.next_step.title}.`
          : 'Complete branding and onboarding to improve storefront trust.',
        to: onboarding?.next_step?.action_path || '/seller/onboarding',
        ctaLabel: 'Continue setup',
      });
    }

    if (insights.activeShipments > 0 && insights.activeShipments > insights.deliveredShipments + 3) {
      queue.push({
        id: 'courier-pressure',
        tone: 'warning',
        title: 'Courier workload is heavier than delivered throughput',
        description: 'Review pickup-needed and delayed shipments before promoting more inventory.',
        to: '/seller/courier',
        ctaLabel: 'Check courier',
      });
    }

    if (queue.length === 0) {
      queue.push({
        id: 'healthy-store',
        tone: 'success',
        title: 'Operations are stable right now',
        description: 'No urgent seller bottlenecks detected. This is a good moment to add products or run promotions.',
        to: '/seller/marketing',
        ctaLabel: 'Grow sales',
      });
    }

    return queue.slice(0, 4);
  }, [criticalLowStockItem, insights.activeShipments, insights.deliveredShipments, onboarding, pendingOrders, publishReady]);

  const healthBreakdown = useMemo((): SellerHealthItem[] => {
    return [
      {
        id: 'publish',
        label: 'Publish readiness',
        value: publishReady ? 'Ready' : `${Number(onboarding?.summary?.progress_percent || 0)}% complete`,
        tone: publishReady ? 'good' : 'warning',
      },
      {
        id: 'inventory',
        label: 'Inventory risk',
        value: lowStockCount === 0 ? 'Healthy' : `${lowStockCount} item${lowStockCount === 1 ? '' : 's'} low`,
        tone: lowStockCount === 0 ? 'good' : criticalLowStockItem?.stock && criticalLowStockItem.stock <= 2 ? 'critical' : 'warning',
      },
      {
        id: 'courier',
        label: 'Courier load',
        value: insights.activeShipments === 0 ? 'Calm' : `${insights.activeShipments} active`,
        tone:
          insights.activeShipments > insights.deliveredShipments + 4
            ? 'warning'
            : insights.activeShipments === 0
              ? 'good'
              : 'good',
      },
    ];
  }, [criticalLowStockItem?.stock, insights.activeShipments, insights.deliveredShipments, lowStockCount, onboarding?.summary?.progress_percent, publishReady]);

  const intelligence = useMemo(
    () =>
      buildSellerDashboardIntelligence({
        stats,
        insights,
        onboarding,
        products,
      }),
    [insights, onboarding, products, stats],
  );

  const aiInsights = intelligence.aiInsights;
  const recentOrderLikeShipments = useMemo(() => insights.recentShipments.slice(0, 5), [insights.recentShipments]);
  const storeName = user?.store_name || user?.name || 'Your storefront';
  const storeIdentityInitial = storeName.trim().charAt(0).toUpperCase() || 'S';
  const overviewBannerUrl = typeof user?.storefront_banner_url === 'string' ? user.storefront_banner_url.trim() : '';
  const executiveSummary = intelligence.executiveSummary;

  return (
    <div className="space-y-6">
      <section className="overflow-hidden rounded-[1.75rem] border border-border bg-white shadow-none">
        <div className="relative overflow-hidden px-5 py-6 sm:px-6 sm:py-6">
          {overviewBannerUrl ? (
            <OptimizedImage
              src={overviewBannerUrl}
              alt={`${storeName} overview banner`}
              eager
              widthHint={1600}
              heightHint={520}
              className="absolute inset-0 h-full w-full object-cover"
            />
          ) : null}
          <div
            className="absolute inset-0"
            style={{
              background: overviewBannerUrl
                ? 'linear-gradient(135deg, rgba(248,250,252,0.92), rgba(244,247,250,0.84))'
                : 'radial-gradient(circle_at_top_left,rgba(37,99,235,0.12),transparent 28%),linear-gradient(135deg,rgba(248,250,252,0.98),rgba(240,244,254,0.94))',
            }}
          />
          <div className="absolute inset-y-0 right-0 hidden w-[32%] bg-[linear-gradient(180deg,rgba(15,23,42,0.02),rgba(15,23,42,0.06))] xl:block" />
          <div className="relative grid gap-5 xl:grid-cols-[1.45fr_0.95fr]">
            <div className="space-y-5">
              <div className="inline-flex items-center gap-2 rounded-full border border-emerald-200 bg-emerald-50 px-3 py-1.5 text-[11px] font-bold uppercase tracking-[0.22em] text-emerald-700">
                <TrendingUp size={13} />
                Merchant command center
              </div>
              <div className="flex items-start gap-4">
                <div className="flex h-16 w-16 shrink-0 items-center justify-center rounded-[1.25rem] bg-slate-950 text-xl font-bold text-white shadow-[0_16px_30px_-20px_rgba(15,23,42,0.55)]">
                  {storeIdentityInitial}
                </div>
                <div className="min-w-0">
                  <p className="section-kicker text-primary/70">Operational control center</p>
                  <h1 className="mt-2 max-w-3xl text-2xl font-bold tracking-tight text-slate-950 sm:text-3xl">
                    {storeName}, here is your business pulse for today
                  </h1>
                  <p className="mt-3 max-w-3xl text-sm text-slate-600 sm:text-base">
                    {executiveSummary}
                  </p>
                  <div className="mt-4 flex flex-wrap items-center gap-2 text-xs text-slate-500">
                    <span className="rounded-full bg-white/90 px-3 py-1.5 font-semibold text-slate-700">
                      Seller workspace
                    </span>
                    <span className="rounded-full bg-white/90 px-3 py-1.5 font-semibold text-slate-700">
                      {stats.totalProducts} live product{stats.totalProducts === 1 ? '' : 's'}
                    </span>
                    <span className="rounded-full bg-white/90 px-3 py-1.5 font-semibold text-slate-700">
                      {stats.totalOrders} processed order{stats.totalOrders === 1 ? '' : 's'}
                    </span>
                  </div>
                </div>
              </div>

              <div className="flex flex-wrap gap-2.5">
                <SellerSignalPill label="Live status" value={publishReady ? 'Ready to promote' : 'Setup incomplete'} tone={publishReady ? 'good' : 'warning'} />
                <SellerSignalPill label="Today sales" value={formatPrice(todaySales)} tone={todaySales >= previousSales ? 'good' : 'neutral'} />
                <SellerSignalPill label="Pending queue" value={`${pendingOrders} orders`} tone={pendingOrders > 6 ? 'critical' : pendingOrders > 0 ? 'warning' : 'good'} />
                <SellerSignalPill label="Inventory risk" value={lowStockCount === 0 ? 'Healthy' : `${lowStockCount} low stock`} tone={lowStockCount === 0 ? 'good' : criticalLowStockItem?.stock && criticalLowStockItem.stock <= 2 ? 'critical' : 'warning'} />
              </div>

              <div className="grid gap-3 sm:grid-cols-2 xl:grid-cols-4">
                {intelligence.quickActions.map((action) => (
                  <QuickActionLink key={action.title} to={action.to} icon={<Package size={18} />} title={action.title} description={action.description} />
                ))}
              </div>
            </div>

            <div className="space-y-3">
              <div className="rounded-[1.25rem] border border-white/70 bg-white/90 p-4 shadow-none backdrop-blur">
                <div className="flex items-start justify-between gap-4">
                  <div>
                    <p className="text-[11px] font-bold uppercase tracking-[0.18em] text-slate-500">Overview grade</p>
                    <p className="mt-2 text-3xl font-bold text-slate-950">{storeHealthScore}%</p>
                    <p className="mt-2 max-w-xs text-xs text-slate-500">
                      Composite store readiness across publish setup, inventory pressure, and courier flow.
                    </p>
                  </div>
                  <div className="flex h-14 w-14 items-center justify-center rounded-full border-4 border-emerald-100 bg-emerald-50 text-sm font-bold text-emerald-700">
                    {publishReady ? 'A' : storeHealthScore >= 60 ? 'B' : 'C'}
                  </div>
                </div>
              </div>

              <div className="rounded-[1.25rem] border border-white/70 bg-white/90 p-4 shadow-none backdrop-blur">
                <div className="flex items-start justify-between gap-4">
                  <div>
                    <p className="text-[11px] font-bold uppercase tracking-[0.18em] text-slate-500">Next best move</p>
                    <p className="mt-2 text-sm font-bold text-slate-950">
                      {intelligence.focusAction.title}
                    </p>
                    <p className="mt-2 max-w-xs text-xs text-slate-500">
                      {intelligence.focusAction.description}
                    </p>
                  </div>
                  <div className="rounded-full bg-slate-950 px-3 py-1 text-[10px] font-bold uppercase tracking-[0.18em] text-white">
                    Focus now
                  </div>
                </div>
              </div>

              <div className="rounded-[1.25rem] border border-white/70 bg-white/90 p-4 shadow-none backdrop-blur">
                <div className="flex items-start justify-between gap-4">
                  <div>
                    <p className="text-[11px] font-bold uppercase tracking-[0.18em] text-slate-500">Onboarding progress</p>
                    <p className="mt-2 text-sm font-bold text-slate-950">
                      {onboardingProgress >= 100 ? 'Seller setup complete' : `${onboardingProgress}% complete`}
                    </p>
                    <p className="mt-2 max-w-xs text-xs text-slate-500">
                      {onboarding?.next_step?.title
                        ? `Next: ${onboarding.next_step.title}`
                        : 'Complete your profile, publish products, and connect operations to unlock more traffic.'}
                    </p>
                  </div>
                  <div className="flex h-14 w-14 items-center justify-center rounded-full border-4 border-emerald-100 bg-emerald-50 text-sm font-bold text-emerald-700">
                    {Math.round(onboardingProgress)}%
                  </div>
                </div>
                <div className="mt-4">
                  <ProgressBar value={onboardingProgress} tone={publishReady ? 'good' : onboardingProgress > 50 ? 'warning' : 'critical'} />
                </div>
                <div className="mt-4 space-y-2">
                  {onboardingChecklist.map((item) => (
                    <div key={item.label} className="flex items-center gap-2 text-xs font-medium text-slate-600">
                      <span
                        className={`inline-flex h-5 w-5 items-center justify-center rounded-full ${
                          item.done ? 'bg-emerald-100 text-emerald-700' : 'bg-slate-100 text-slate-400'
                        }`}
                      >
                        {item.done ? <CheckCircle2 size={12} /> : <Clock3 size={12} />}
                      </span>
                      <span className={item.done ? 'text-slate-700 line-through decoration-slate-300' : 'text-slate-700'}>{item.label}</span>
                    </div>
                  ))}
                </div>
              </div>

              <div className="grid gap-3 sm:grid-cols-2 xl:grid-cols-2">
                <SellerHeroMetric
                  label="Today sales"
                  value={formatPrice(todaySales)}
                  hint={`${formatTrendValue(todaySales, previousSales)} vs previous period`}
                />
                <SellerHeroMetric
                  label="Pending orders"
                  value={String(pendingOrders)}
                  hint="Orders still needing active fulfillment"
                />
                <SellerHeroMetric
                  label="Store health"
                  value={`${storeHealthScore}%`}
                  hint="Readiness across setup, stock, and courier flow"
                />
                <SellerHeroMetric
                  label="Publish status"
                  value={publishReady ? 'Ready to promote' : 'Setup incomplete'}
                  hint={publishReady ? 'Your storefront is in a launchable state.' : 'Finish remaining onboarding tasks to improve trust.'}
                />
              </div>
            </div>
          </div>
        </div>
      </section>

      <div className="grid gap-4 xl:grid-cols-[1.4fr_0.9fr]">
        <section className="rounded-xl border border-border bg-white p-5 shadow-none sm:p-6">
          <SectionHeading
            eyebrow="Today's priorities"
            title="Priority queue"
            description="A smart action stack generated from fulfillment pressure, stock movement, and launch readiness."
          />
          <div className="grid gap-4 lg:grid-cols-2">
            {todayPriorities.map((item) => (
              <SellerPriorityCard key={item.id} item={item} />
            ))}
          </div>
        </section>

        <section className="rounded-xl border border-border bg-white p-5 shadow-none">
          <SectionHeading eyebrow="Health check" title="Operating health" />
          <div className="space-y-3">
            {intelligence.healthSignals.map((item) => {
              const toneClass =
                item.tone === 'critical'
                  ? 'bg-rose-50 text-rose-700'
                  : item.tone === 'warning'
                    ? 'bg-amber-50 text-amber-700'
                    : 'bg-emerald-50 text-emerald-700';

              return (
                <div key={item.label} className="flex items-center justify-between gap-3 rounded-xl bg-secondary/30 px-4 py-3">
                  <div>
                    <p className="text-xs font-bold uppercase tracking-[0.16em] text-slate-500">{item.label}</p>
                    <p className="mt-1 text-sm font-semibold text-slate-950">{item.value}</p>
                  </div>
                  <span className={`inline-flex rounded-full px-3 py-1 text-[11px] font-bold uppercase tracking-[0.14em] ${toneClass}`}>
                    {item.tone}
                  </span>
                </div>
              );
            })}
          </div>
          <div className="mt-4 rounded-xl border border-border bg-white px-4 py-4 text-sm text-slate-600">
            {intelligence.focusAction.tone === 'success'
              ? 'Your operations are healthy and ready for growth. This is a strong window to launch new offers or expand the catalog.'
              : 'The dashboard is highlighting the next practical action to keep operations healthy and conversions flowing.'}
          </div>
        </section>
      </div>

      <div className="grid gap-4 md:grid-cols-2 xl:grid-cols-3">
        {statCards.map((stat) => (
          <SellerKpiCard
            key={stat.label}
            label={stat.label}
            value={stat.value}
            trend={stat.trend}
            trendTone={stat.trendTone}
            icon={stat.icon}
            chart={stat.chart}
          />
        ))}
      </div>

      <div className="grid gap-4 xl:grid-cols-[1.6fr_1fr]">
        <div className="space-y-6">
          <section className="rounded-xl border border-border bg-white p-5 shadow-none sm:p-6">
            <SectionHeading
              eyebrow="Sales graph"
              title="Performance trend"
              description="Track seller revenue momentum without leaving the home workspace."
              action={
                <Link to="/seller/earnings" className="text-sm font-semibold text-primary hover:text-primary-dark">
                  Open earnings
                </Link>
              }
            />
            <SalesPerformanceChart data={insights.salesSeries} />
          </section>

          <section className="rounded-xl border border-border bg-white p-5 shadow-none sm:p-6">
            <SectionHeading
              eyebrow="Operational alerts"
              title="What needs action next"
              description="Fast seller decisions for stock, courier, and setup issues."
            />
            <div className="grid gap-4 lg:grid-cols-2">
              {alerts.length === 0 ? (
                <div className="rounded-2xl border border-dashed border-border bg-secondary/30 px-4 py-10 text-center text-sm text-muted-foreground lg:col-span-2">
                  No urgent seller alerts right now. Your store operations look stable.
                </div>
              ) : (
                alerts.map((alert) => (
                  <OperationalAlertCard
                    key={alert.id}
                    tone={alert.tone}
                    title={alert.title}
                    description={alert.description}
                    cta={alert.cta}
                  />
                ))
              )}
            </div>
          </section>

          <section className="rounded-xl border border-border bg-white p-5 shadow-none sm:p-6">
            <SectionHeading
              eyebrow="Low stock alerts"
              title="Inventory pressure"
              description="Review low stock products and jump straight into restock actions."
              action={
                <div className="flex flex-wrap items-center justify-end gap-2">
                  <span className="rounded-full bg-accent/10 px-3 py-1 text-xs font-bold text-accent">
                    {insights.lowStockProducts.length} low stock
                  </span>
                  <Link
                    to="/seller/products"
                    className="rounded-full border border-border px-3 py-1 text-xs font-semibold text-slate-600 transition hover:border-primary/20 hover:text-primary"
                  >
                    Open products
                  </Link>
                </div>
              }
            />
            <div className="grid grid-cols-1 gap-4 md:grid-cols-2 xl:grid-cols-3">
              {insights.lowStockProducts.length === 0 ? (
                <div className="rounded-2xl border border-dashed border-border p-4 text-sm text-muted-foreground md:col-span-2 xl:col-span-3">
                  No products are currently below the low-stock threshold.
                </div>
              ) : (
                insights.lowStockProducts.map((item) => (
                  <div key={item.id} className="rounded-xl border border-border bg-secondary/70 p-4">
                    <div className="flex items-center gap-2 mb-2">
                      <AlertTriangle className={`w-4 h-4 ${item.stock <= 2 ? 'text-accent' : 'text-primary'}`} />
                      <span className={`text-[10px] font-bold uppercase ${item.stock <= 2 ? 'text-accent' : 'text-primary'}`}>
                        {item.stock <= 2 ? 'Critical' : 'Low'} Stock
                      </span>
                    </div>
                    <p className="text-sm font-bold truncate mb-1">{item.name}</p>
                    <p className="text-xs text-muted-foreground">Only {item.stock} units left</p>
                    {item.warehouse_name ? (
                      <p className="mt-1 text-[11px] font-medium text-slate-500">Pickup point: {item.warehouse_name}</p>
                    ) : null}
                    <div className="mt-3 flex flex-wrap gap-3 text-[11px] font-semibold">
                      <Link
                        to={`/seller/products?search=${encodeURIComponent(String(item.id))}&product=${encodeURIComponent(String(item.id))}`}
                        className="text-primary hover:underline"
                      >
                        Open product
                      </Link>
                      <Link
                        to={`/seller/products/edit/${encodeURIComponent(String(item.id))}`}
                        className="text-slate-600 hover:text-primary hover:underline"
                      >
                        Edit stock
                      </Link>
                      <Link
                        to={
                          item.warehouse_id
                            ? `/seller/pickup-locations?warehouse=${encodeURIComponent(String(item.warehouse_id))}`
                            : '/seller/pickup-locations'
                        }
                        className="text-slate-600 hover:text-primary hover:underline"
                      >
                        Open pickup point
                      </Link>
                    </div>
                  </div>
                ))
              )}
            </div>
          </section>
        </div>

        <div className="space-y-6">
          <SellerStorefrontMiniCard
            storeName={storeName}
            storefrontSlug={user?.storefront_slug}
            productCount={stats.totalProducts}
            publishReady={publishReady}
          />

          <section className="rounded-xl border border-border bg-white p-5 shadow-none">
            <SectionHeading eyebrow="Recent orders" title="Latest fulfillment activity" />
            <div className="space-y-4">
              {recentOrderLikeShipments.length === 0 ? (
                <p className="text-sm text-muted-foreground">No shipment activity yet.</p>
              ) : (
                recentOrderLikeShipments.map((shipment) => (
                  <div key={shipment.id} className="flex items-center justify-between gap-3 rounded-xl bg-secondary/30 px-4 py-4">
                    <div className="flex min-w-0 items-center gap-3">
                      <div className="flex h-10 w-10 shrink-0 items-center justify-center rounded-xl bg-white">
                        <ShoppingBag size={18} className="text-primary" />
                      </div>
                      <div className="min-w-0">
                        <p className="truncate text-sm font-bold text-slate-950">Order #{shipment.order_id || shipment.id.slice(0, 8)}</p>
                        <p className="mt-1 flex items-center gap-1 text-xs text-muted-foreground">
                          <Clock3 size={12} />
                          {new Date(shipment.created_at).toLocaleString()}
                        </p>
                      </div>
                    </div>
                    <div>
                      <p className="text-right text-sm font-bold text-primary">{formatPrice(shipment.total)}</p>
                      <p className="mt-1 text-right text-[10px] font-bold uppercase tracking-[0.16em] text-slate-500">
                        {shipment.status.replaceAll('_', ' ')}
                      </p>
                    </div>
                  </div>
                ))
              )}
            </div>
            <div className="mt-5 rounded-xl bg-primary/10 px-4 py-3 text-sm font-medium text-primary">
              {stats.totalOrders} total order{stats.totalOrders === 1 ? '' : 's'} processed across your storefront.
            </div>
          </section>

          <section className="rounded-xl border border-border bg-white p-5 shadow-none">
            <SectionHeading eyebrow="Courier health" title="Logistics snapshot" />
            <div className="grid grid-cols-1 gap-3 sm:grid-cols-2">
              <div className="rounded-xl bg-secondary/30 px-4 py-4">
                <p className="text-xs font-bold uppercase tracking-[0.18em] text-slate-500">Active shipments</p>
                <p className="mt-2 text-2xl font-black text-slate-950">{insights.activeShipments}</p>
              </div>
              <div className="rounded-xl bg-secondary/30 px-4 py-4">
                <p className="text-xs font-bold uppercase tracking-[0.18em] text-slate-500">Delivered</p>
                <p className="mt-2 text-2xl font-black text-slate-950">{insights.deliveredShipments}</p>
              </div>
            </div>
            <div className="mt-4 rounded-xl border border-border bg-white px-4 py-4 text-sm text-slate-600">
              {insights.activeShipments === 0
                ? 'No active courier movement right now. New pickups and shipment events will appear here.'
                : insights.activeShipments > insights.deliveredShipments
                  ? 'Courier workload is still active. Review pickup-needed and delayed orders before promoting more products.'
                  : 'Courier movement looks healthy. Delivered shipments are keeping pace with active fulfillment.'}
            </div>
            <div className="mt-4 flex flex-wrap gap-2">
              <Link
                to="/seller/courier"
                className="inline-flex items-center gap-2 rounded-full bg-slate-950 px-4 py-2 text-xs font-semibold text-white transition hover:bg-slate-800"
              >
                <Truck size={14} />
                Open courier panel
              </Link>
              <Link
                to="/seller/pickup-locations"
                className="inline-flex items-center gap-2 rounded-full border border-border px-4 py-2 text-xs font-semibold text-slate-700 transition hover:border-primary/20 hover:text-primary"
              >
                <Store size={14} />
                Pickup locations
              </Link>
            </div>
          </section>

          <section className="rounded-xl border border-border bg-white p-5 shadow-none">
            <SectionHeading eyebrow="AI insights" title="Suggested next moves" />
            <div className="space-y-3">
              {aiInsights.length === 0 ? (
                <p className="rounded-xl bg-secondary/30 px-4 py-4 text-sm text-muted-foreground">
                  More seller recommendations will appear as orders, inventory, and shipment history grow.
                </p>
              ) : (
                aiInsights.map((insight) => (
                  <div key={insight} className="rounded-xl bg-secondary/30 px-4 py-4 text-sm text-slate-700">
                    {insight}
                  </div>
                ))
              )}
            </div>
          </section>
        </div>
      </div>

      <section className="rounded-xl border border-border bg-white p-5 shadow-none sm:p-6">
        <SectionHeading
          eyebrow="Top products"
          title="Your strongest catalog movers"
          description="Keep an eye on the products already earning trust and revenue."
        />
        {stats.topProducts.length === 0 ? (
          <p className="text-sm text-muted-foreground">Your best-performing products will appear here once orders start coming in.</p>
        ) : (
          <div className="grid gap-4 md:grid-cols-2 xl:grid-cols-3">
            {stats.topProducts.map((product, index) => (
              <SellerTopProductCard key={product.id} product={product} rank={index + 1} />
            ))}
          </div>
        )}
      </section>
    </div>
  );
}

export const SellerDashboard = () => {
  const { token, user } = useUser();
  const [manageMode, setManageMode] = useState(false);
  const [stats, setStats] = useState<SellerStatsResponse>({
    totalProducts: 0,
    totalOrders: 0,
    totalEarnings: 0,
    topProducts: [],
  });
  const [products, setProducts] = useState<Product[]>([]);
  const [flashSaleEntries, setFlashSaleEntries] = useState<FlashSaleEntry[]>([]);
  const [coupons, setCoupons] = useState<SellerCoupon[]>([]);
  const [insights, setInsights] = useState<SellerDashboardInsights>(emptyInsights);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState('');
  const [onboarding, setOnboarding] = useState<SellerOnboardingStatus | null>(null);

  useEffect(() => {
    if (typeof window === 'undefined') return;
    const syncManageMode = () => {
      setManageMode(window.localStorage.getItem(manageModeStorageKey) === 'true');
    };

    syncManageMode();
    window.addEventListener('seller-dashboard-mode-change', syncManageMode);

    return () => {
      window.removeEventListener('seller-dashboard-mode-change', syncManageMode);
    };
  }, []);

  useEffect(() => {
    if (typeof window === 'undefined') return;
    window.localStorage.setItem(manageModeStorageKey, manageMode ? 'true' : 'false');
  }, [manageMode]);

  useEffect(() => {
    const fetchDashboard = async () => {
      if (!token) {
        setError('Please log in as a seller to view your store performance.');
        setLoading(false);
        return;
      }

      try {
        setLoading(true);
        setError('');

        const [statsResult, insightsResult, onboardingResult, productsResult, flashResult, couponsResult] = await Promise.allSettled([
          fetch('/api/seller/stats', {
            headers: { Authorization: `Bearer ${token}` },
          }),
          fetch('/api/seller/dashboard-insights', {
            headers: { Authorization: `Bearer ${token}` },
          }),
          fetch('/api/seller/onboarding-status', {
            headers: { Authorization: `Bearer ${token}` },
          }),
          fetch('/api/seller/products', {
            headers: { Authorization: `Bearer ${token}` },
          }),
          fetch('/api/seller/flash-sale', {
            headers: { Authorization: `Bearer ${token}` },
          }),
          fetch('/api/seller/coupons', {
            headers: { Authorization: `Bearer ${token}` },
          }),
        ]);

        if (statsResult.status !== 'fulfilled') {
          throw new Error('Failed to load seller stats');
        }

        const statsPayload = await statsResult.value.json().catch(() => null);
        if (!statsResult.value.ok) {
          throw new Error(statsPayload?.error || 'Failed to load seller stats');
        }

        setStats({
          totalProducts: Number(statsPayload.totalProducts || 0),
          totalOrders: Number(statsPayload.totalOrders || 0),
          totalEarnings: Number(statsPayload.totalEarnings || 0),
          topProducts: Array.isArray(statsPayload.topProducts) ? statsPayload.topProducts : [],
        });

        if (insightsResult.status === 'fulfilled' && insightsResult.value.ok) {
          const insightsPayload = (await insightsResult.value.json()) as SellerDashboardInsights;
          setInsights({
            salesSeries: Array.isArray(insightsPayload.salesSeries) ? insightsPayload.salesSeries : [],
            lowStockProducts: Array.isArray(insightsPayload.lowStockProducts) ? insightsPayload.lowStockProducts : [],
            recentShipments: Array.isArray(insightsPayload.recentShipments) ? insightsPayload.recentShipments : [],
            activeShipments: Number(insightsPayload.activeShipments || 0),
            deliveredShipments: Number(insightsPayload.deliveredShipments || 0),
          });
        } else {
          setInsights(emptyInsights);
        }

        if (onboardingResult.status === 'fulfilled' && onboardingResult.value.ok) {
          const onboardingPayload = (await onboardingResult.value.json()) as SellerOnboardingStatus;
          setOnboarding(onboardingPayload);
        } else {
          setOnboarding(null);
        }

        if (productsResult.status === 'fulfilled' && productsResult.value.ok) {
          const productsPayload = await productsResult.value.json().catch(() => []);
          setProducts(Array.isArray(productsPayload) ? productsPayload : []);
        } else {
          setProducts([]);
        }

        if (flashResult.status === 'fulfilled' && flashResult.value.ok) {
          const flashPayload = (await flashResult.value.json().catch(() => null)) as SellerFlashSaleResponse | null;
          setFlashSaleEntries(Array.isArray(flashPayload?.entries) ? flashPayload!.entries! : []);
        } else {
          setFlashSaleEntries([]);
        }

        if (couponsResult.status === 'fulfilled' && couponsResult.value.ok) {
          const couponsPayload = await couponsResult.value.json().catch(() => []);
          setCoupons(Array.isArray(couponsPayload) ? couponsPayload : []);
        } else {
          setCoupons([]);
        }
      } catch (fetchError) {
        setError(fetchError instanceof Error ? fetchError.message : 'Unable to load seller dashboard.');
        setStats({
          totalProducts: 0,
          totalOrders: 0,
          totalEarnings: 0,
          topProducts: [],
        });
        setProducts([]);
        setFlashSaleEntries([]);
        setCoupons([]);
        setInsights(emptyInsights);
        setOnboarding(null);
      } finally {
        setLoading(false);
      }
    };

    void fetchDashboard();
  }, [token]);

  const bestSellerProducts = useMemo(() => {
    if (stats.topProducts.length === 0 || products.length === 0) {
      return [];
    }

    const productMap = new Map(products.map((product) => [String(product.id), product]));
    return stats.topProducts
      .map((item) => productMap.get(String(item.id)))
      .filter((item): item is Product => Boolean(item))
      .slice(0, 4);
  }, [products, stats.topProducts]);

  if (loading) {
    return (
      <div className="flex h-64 items-center justify-center">
        <Loader2 className="animate-spin text-primary" size={32} />
      </div>
    );
  }

  const storeName = user?.store_name || user?.name || 'Your storefront';

  return (
    <div className="space-y-8">
      {error ? (
        <div className="rounded-xl border border-amber-200 bg-amber-50 p-4 text-sm text-amber-800">
          {error}
        </div>
      ) : null}

      {onboarding?.approval ? (
        <div className="rounded-xl border border-border bg-white p-5 shadow-none">
          <div className="flex flex-col gap-4 lg:flex-row lg:items-start lg:justify-between">
            <div>
              <p className="section-kicker text-primary/70">Approval status</p>
              <h2 className="mt-1.5 text-lg font-bold text-slate-950">
                {String(onboarding.approval.status || 'draft').replaceAll('_', ' ')}
              </h2>
              <p className="mt-2 text-sm text-muted-foreground">
                {onboarding.approval.status === 'approved'
                  ? 'Your seller account is approved. Publishing, orders, courier booking, and payouts are unlocked.'
                  : onboarding.approval.status === 'rejected'
                    ? onboarding.approval.rejection_reason || 'Your seller account needs updates before it can be approved again.'
                    : onboarding.approval.status === 'suspended'
                      ? onboarding.approval.suspension_reason || 'Your live seller privileges are suspended right now.'
                      : onboarding.approval.can_submit_for_review
                        ? 'Everything required for review is ready. Submit your seller account from onboarding to move into the review queue.'
                        : 'You can keep setting up your store and drafting products, but selling stays locked until admin approval.'}
              </p>
            </div>
            <div className="rounded-2xl bg-secondary/40 px-4 py-3 text-sm text-slate-700 lg:min-w-[260px]">
              <p className="font-semibold text-slate-950">Missing requirements</p>
              <p className="mt-1 text-xs text-muted-foreground">
                {onboarding.approval.missing_requirements?.length
                  ? onboarding.approval.missing_requirements.map((item) => item.label).join(', ')
                  : 'No missing requirements right now.'}
              </p>
              <Link to="/seller/onboarding" className="mt-3 inline-flex items-center gap-2 text-xs font-semibold text-primary">
                Open onboarding
                <ArrowRight size={14} />
              </Link>
            </div>
          </div>
        </div>
      ) : null}

      {manageMode ? (
        <SellerDashboardManageView stats={stats} insights={insights} onboarding={onboarding} products={products} user={user} />
      ) : (
        <SellerStorefrontPreview
          storeName={storeName}
          bannerUrl={user?.storefront_banner_url}
          avatarUrl={user?.avatar_url}
          headline={user?.storefront_headline || user?.bio}
          storefrontSlug={user?.storefront_slug}
          products={products}
          bestSellers={bestSellerProducts}
          flashSaleEntries={flashSaleEntries}
          coupons={coupons}
        />
      )}
    </div>
  );
};

import React, { useEffect, useMemo, useState } from 'react';
import { Loader2, Send, Zap } from 'lucide-react';
import toast from '@/lib/toast';
import { useUser } from '../../../features/shared/state/UserContext';
import { formatPrice } from '../../../lib/utils';

type SellerProduct = {
  id: string;
  name: string;
  price: number;
  stock: number;
};

type FlashSaleCampaign = {
  id: string;
  title: string;
  description?: string;
  starts_at: string;
  ends_at: string;
  status: string;
};

type FlashSaleEntry = {
  id: string;
  campaign_id: string;
  product_id: string;
  sale_price: number;
  allocated_stock: number;
  status: string;
  note?: string | null;
  rejection_reason?: string | null;
  product?: {
    id: string;
    name: string;
    price: number;
  } | null;
};

const initialForm = {
  campaignId: '',
  productId: '',
  salePrice: '',
  allocatedStock: '',
  note: '',
};

export const SellerFlashSalePage = () => {
  const { token, user } = useUser();
  const sellerApproved = user?.seller_status === 'approved';
  const [campaigns, setCampaigns] = useState<FlashSaleCampaign[]>([]);
  const [entries, setEntries] = useState<FlashSaleEntry[]>([]);
  const [products, setProducts] = useState<SellerProduct[]>([]);
  const [loading, setLoading] = useState(true);
  const [saving, setSaving] = useState(false);
  const [error, setError] = useState('');
  const [form, setForm] = useState(initialForm);
  const [focusedEntryId, setFocusedEntryId] = useState('');

  const loadData = async () => {
    if (!token) {
      setError('Please log in as a seller to manage flash sale submissions.');
      setLoading(false);
      return;
    }

    try {
      setLoading(true);
      setError('');

      const [campaignResponse, productResponse] = await Promise.all([
        fetch('/api/seller/flash-sale', {
          headers: { Authorization: `Bearer ${token}` },
        }),
        fetch('/api/seller/products', {
          headers: { Authorization: `Bearer ${token}` },
        }),
      ]);

      const campaignPayload = await campaignResponse.json().catch(() => null);
      const productPayload = await productResponse.json().catch(() => null);

      if (!campaignResponse.ok) {
        throw new Error(campaignPayload?.error || 'Failed to load flash sale campaigns');
      }

      if (!productResponse.ok) {
        throw new Error(productPayload?.error || 'Failed to load seller products');
      }

      setCampaigns(Array.isArray(campaignPayload?.campaigns) ? campaignPayload.campaigns : []);
      setEntries(Array.isArray(campaignPayload?.entries) ? campaignPayload.entries : []);
      setProducts(Array.isArray(productPayload) ? productPayload : []);
    } catch (requestError) {
      setError(requestError instanceof Error ? requestError.message : 'Failed to load flash sale workspace');
      setCampaigns([]);
      setEntries([]);
      setProducts([]);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    void loadData();
  }, [token]);

  useEffect(() => {
    if (typeof window === 'undefined') return;
    const params = new URLSearchParams(window.location.search);
    const nextEntry = params.get('entry');
    if (nextEntry) {
      setFocusedEntryId(nextEntry);
    }
  }, []);

  const eligibleCampaigns = useMemo(
    () => campaigns.filter((campaign) => ['draft', 'scheduled', 'live', 'published'].includes(campaign.status)),
    [campaigns],
  );

  useEffect(() => {
    if (!focusedEntryId || typeof window === 'undefined') return;
    window.requestAnimationFrame(() => {
      document.getElementById(`seller-flash-entry-${focusedEntryId}`)?.scrollIntoView({
        behavior: 'smooth',
        block: 'center',
      });
    });
  }, [entries, focusedEntryId]);

  const handleSubmit = async (event: React.FormEvent) => {
    event.preventDefault();
    if (!token) return;

    try {
      setSaving(true);
      const response = await fetch('/api/seller/flash-sale/entries', {
        method: 'POST',
        headers: {
          Authorization: `Bearer ${token}`,
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({
          campaignId: form.campaignId,
          productId: form.productId,
          salePrice: Number(form.salePrice),
          allocatedStock: Number(form.allocatedStock || 0),
          note: form.note,
        }),
      });

      const payload = await response.json().catch(() => null);
      if (!response.ok) {
        throw new Error(payload?.error || 'Failed to submit flash sale product');
      }

      toast.success('Flash sale product submitted for review.');
      setForm(initialForm);
      await loadData();
    } catch (requestError) {
      toast.error(requestError instanceof Error ? requestError.message : 'Failed to submit flash sale product');
    } finally {
      setSaving(false);
    }
  };

  if (loading) {
    return (
      <div className="flex min-h-[320px] items-center justify-center">
        <Loader2 className="animate-spin text-primary" size={32} />
      </div>
    );
  }

  return (
    <div className="space-y-6">
      <div className="rounded-[32px] border border-black/5 bg-white p-8 shadow-sm">
        <div className="flex flex-col gap-4 lg:flex-row lg:items-start lg:justify-between">
          <div className="space-y-2">
            <div className="inline-flex items-center gap-2 rounded-full bg-primary/10 px-3 py-1 text-xs font-bold uppercase tracking-[0.2em] text-primary">
              <Zap size={14} />
              Flash Sale Seller Desk
            </div>
            <h1 className="text-3xl font-bold tracking-tight">Submit your best products for campaign approval</h1>
            <p className="max-w-3xl text-sm text-slate-600">
              Admin creates the campaign, you submit products with committed stock and sale pricing, and approved items go
              live on the marketplace flash sale page.
            </p>
          </div>
        </div>
      </div>

      {error ? <div className="rounded-2xl border border-amber-200 bg-amber-50 px-4 py-3 text-sm text-amber-800">{error}</div> : null}
      {!sellerApproved ? (
        <div className="rounded-2xl border border-amber-200 bg-amber-50 px-4 py-3 text-sm text-amber-800">
          Flash sale submissions unlock after seller approval. You can prepare products now, but campaign submission stays locked.
        </div>
      ) : null}

      <div className="grid gap-6 xl:grid-cols-[1.1fr_0.9fr]">
        <section className="rounded-[32px] border border-black/5 bg-white p-8 shadow-sm">
          <div className="mb-6">
            <h2 className="text-xl font-bold">Submit Product</h2>
            <p className="text-sm text-slate-500">Pick an admin campaign, choose your product, and set the offer details.</p>
          </div>

          <form onSubmit={handleSubmit} className="space-y-4">
            <div className="grid gap-4 md:grid-cols-2">
              <label className="space-y-2 text-sm">
                <span className="font-medium text-slate-700">Campaign</span>
                <select
                  value={form.campaignId}
                  onChange={(event) => setForm((current) => ({ ...current, campaignId: event.target.value }))}
                  className="w-full rounded-2xl border border-slate-200 px-4 py-3 text-sm"
                  required
                  disabled={!sellerApproved}
                >
                  <option value="">Select a campaign</option>
                  {eligibleCampaigns.map((campaign) => (
                    <option key={campaign.id} value={campaign.id}>
                      {campaign.title} ({campaign.status})
                    </option>
                  ))}
                </select>
              </label>

              <label className="space-y-2 text-sm">
                <span className="font-medium text-slate-700">Product</span>
                <select
                  value={form.productId}
                  onChange={(event) => setForm((current) => ({ ...current, productId: event.target.value }))}
                  className="w-full rounded-2xl border border-slate-200 px-4 py-3 text-sm"
                  required
                  disabled={!sellerApproved}
                >
                  <option value="">Select your product</option>
                  {products.map((product) => (
                    <option key={product.id} value={product.id}>
                      {product.name} ({formatPrice(product.price)})
                    </option>
                  ))}
                </select>
              </label>
            </div>

            <div className="grid gap-4 md:grid-cols-2">
              <label className="space-y-2 text-sm">
                <span className="font-medium text-slate-700">Flash sale price</span>
                <input
                  type="number"
                  min="1"
                  step="0.01"
                  value={form.salePrice}
                  onChange={(event) => setForm((current) => ({ ...current, salePrice: event.target.value }))}
                  className="w-full rounded-2xl border border-slate-200 px-4 py-3 text-sm"
                required
                disabled={!sellerApproved}
                />
              </label>

              <label className="space-y-2 text-sm">
                <span className="font-medium text-slate-700">Allocated stock</span>
                <input
                  type="number"
                  min="0"
                  step="1"
                  value={form.allocatedStock}
                  onChange={(event) => setForm((current) => ({ ...current, allocatedStock: event.target.value }))}
                  className="w-full rounded-2xl border border-slate-200 px-4 py-3 text-sm"
                />
              </label>
            </div>

            <label className="space-y-2 text-sm">
              <span className="font-medium text-slate-700">Seller note</span>
              <textarea
                value={form.note}
                onChange={(event) => setForm((current) => ({ ...current, note: event.target.value }))}
                rows={4}
                disabled={!sellerApproved}
                className="w-full rounded-2xl border border-slate-200 px-4 py-3 text-sm"
                placeholder="Mention stock commitment, hero variants, or any approval notes."
              />
            </label>

            <button
              type="submit"
              disabled={saving || !sellerApproved}
              className="inline-flex items-center gap-2 rounded-2xl bg-primary px-5 py-3 text-sm font-bold text-white transition hover:bg-primary/90 disabled:opacity-50"
            >
              {saving ? <Loader2 className="animate-spin" size={18} /> : <Send size={18} />}
              <span>{saving ? 'Submitting...' : 'Submit for approval'}</span>
            </button>
          </form>
        </section>

        <section className="rounded-[32px] border border-black/5 bg-white p-8 shadow-sm">
          <div className="mb-6">
            <h2 className="text-xl font-bold">Your submissions</h2>
            <p className="text-sm text-slate-500">Approved items go live, rejected items return with admin feedback.</p>
          </div>

          <div className="space-y-4">
            {entries.length === 0 ? (
              <div className="rounded-2xl border border-dashed border-slate-200 bg-slate-50 px-4 py-10 text-center text-sm text-slate-500">
                No seller submissions yet.
              </div>
            ) : (
              entries.map((entry) => (
                <div
                  id={`seller-flash-entry-${entry.id}`}
                  key={entry.id}
                  className={`rounded-3xl border border-slate-100 bg-slate-50 px-5 py-4 ${
                    entry.id === focusedEntryId ? 'border-indigo-300 ring-2 ring-indigo-200 bg-indigo-50/30' : ''
                  }`}
                >
                  <div className="flex flex-col gap-3 md:flex-row md:items-start md:justify-between">
                    <div className="space-y-1">
                      <h3 className="font-semibold text-slate-900">{entry.product?.name || 'Product submission'}</h3>
                      <p className="text-sm text-slate-500">
                        Flash price {formatPrice(entry.sale_price)} â€¢ Allocated stock {entry.allocated_stock}
                      </p>
                    </div>
                    <span className="rounded-full bg-white px-3 py-1 text-xs font-bold uppercase tracking-[0.16em] text-slate-700">
                      {entry.status}
                    </span>
                  </div>
                  {entry.note ? <p className="mt-3 text-sm text-slate-600">{entry.note}</p> : null}
                  {entry.rejection_reason ? (
                    <div className="mt-3 rounded-2xl border border-rose-200 bg-rose-50 px-3 py-2 text-sm text-rose-700">
                      {entry.rejection_reason}
                    </div>
                  ) : null}
                </div>
              ))
            )}
          </div>
        </section>
      </div>
    </div>
  );
};

import React, { useEffect, useState } from 'react';
import toast from '@/lib/toast';
import { Calendar, Copy, Loader2, Plus, Tag, Trash2 } from 'lucide-react';
import { useUser } from '../../../features/shared/state/UserContext';
import { formatPrice } from '../../../lib/utils';
import { Link } from '../../../lib/navigation';
import { copyText } from '../../../lib/browser-actions';

type SellerCoupon = {
  id: string;
  code: string;
  discount_type: string;
  discount_value: number;
  min_order_value: number;
  expiry_date: string;
};

export const SellerMarketingCenter = () => {
  const { token } = useUser();
  const [coupons, setCoupons] = useState<SellerCoupon[]>([]);
  const [loading, setLoading] = useState(true);
  const [saving, setSaving] = useState(false);
  const [deleteConfirmId, setDeleteConfirmId] = useState('');
  const [formData, setFormData] = useState({
    code: '',
    discount_type: 'percentage',
    discount_value: 0,
    min_order_value: 0,
    expiry_date: '',
  });

  const fetchCoupons = async () => {
    if (!token) return;
    try {
      setLoading(true);
      const response = await fetch('/api/seller/coupons', {
        headers: { Authorization: `Bearer ${token}` },
      });
      const payload = await response.json().catch(() => null);
      if (!response.ok) {
        throw new Error(payload?.error || 'Failed to load seller coupons');
      }
      setCoupons(Array.isArray(payload) ? payload : []);
    } catch (error: unknown) {
      setCoupons([]);
      toast.error(error instanceof Error ? error.message : 'Failed to load seller coupons');
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    void fetchCoupons();
  }, [token]);

  const createCoupon = async (event: React.FormEvent) => {
    event.preventDefault();
    if (!token) return;

    try {
      setSaving(true);
      const response = await fetch('/api/seller/coupons', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          Authorization: `Bearer ${token}`,
        },
        body: JSON.stringify(formData),
      });
      const payload = await response.json().catch(() => null);
      if (!response.ok) {
        throw new Error(payload?.error || 'Failed to create seller coupon');
      }
      toast.success('Seller coupon created.');
      setFormData({
        code: '',
        discount_type: 'percentage',
        discount_value: 0,
        min_order_value: 0,
        expiry_date: '',
      });
      void fetchCoupons();
    } catch (error: unknown) {
      toast.error(error instanceof Error ? error.message : 'Failed to create seller coupon');
    } finally {
      setSaving(false);
    }
  };

  const deleteCoupon = async (couponId: string) => {
    if (!token) return;
    try {
      const response = await fetch(`/api/seller/coupons/${couponId}`, {
        method: 'DELETE',
        headers: {
          Authorization: `Bearer ${token}`,
        },
      });
      const payload = await response.json().catch(() => null);
      if (!response.ok) {
        throw new Error(payload?.error || 'Failed to delete seller coupon');
      }
      setDeleteConfirmId('');
      toast.success('Seller coupon deleted.');
      void fetchCoupons();
    } catch (error: unknown) {
      toast.error(error instanceof Error ? error.message : 'Failed to delete seller coupon');
    }
  };

  if (loading) {
    return (
      <div className="flex h-64 items-center justify-center">
        <Loader2 className="animate-spin text-primary" size={32} />
      </div>
    );
  }

  return (
    <div className="space-y-8">
      <div className="flex flex-col gap-4 md:flex-row md:items-center md:justify-between">
        <div>
          <h1 className="text-2xl font-bold tracking-tight">Marketing Center</h1>
          <p className="text-gray-500">Manage seller-only coupons and pair them with your storefront, flash sale, and product promotions.</p>
        </div>
        <Link
          to="/seller/settings"
          className="inline-flex items-center gap-2 rounded-2xl border border-border px-4 py-3 text-sm font-semibold text-slate-700 transition hover:bg-secondary"
        >
          <Tag size={16} />
          Open storefront settings
        </Link>
      </div>

      <div className="grid gap-6 xl:grid-cols-[0.9fr_1.1fr]">
        <section className="rounded-[32px] border border-gray-100 bg-white p-4 shadow-sm md:p-8">
          <h2 className="text-lg font-bold">Create seller coupon</h2>
          <p className="mt-2 text-sm text-gray-500">These codes appear on your public seller storefront and apply only when the cart stays inside your store.</p>
          <form onSubmit={createCoupon} className="mt-6 space-y-4">
            <div>
              <label className="mb-1 block text-sm font-medium text-gray-700">Coupon code</label>
              <input
                required
                value={formData.code}
                onChange={(event) => setFormData((current) => ({ ...current, code: event.target.value.toUpperCase() }))}
                className="w-full rounded-2xl border border-gray-200 px-4 py-3 text-sm outline-none focus:border-primary"
                placeholder="SELLER10"
              />
            </div>
            <div className="grid grid-cols-1 gap-3 sm:grid-cols-2 sm:gap-4">
              <div>
                <label className="mb-1 block text-sm font-medium text-gray-700">Discount type</label>
                <select
                  value={formData.discount_type}
                  onChange={(event) => setFormData((current) => ({ ...current, discount_type: event.target.value }))}
                  className="w-full rounded-2xl border border-gray-200 px-4 py-3 text-sm outline-none focus:border-primary"
                >
                  <option value="percentage">Percentage</option>
                  <option value="fixed">Fixed amount</option>
                </select>
              </div>
              <div>
                <label className="mb-1 block text-sm font-medium text-gray-700">Value</label>
                <input
                  type="number"
                  min="0"
                  required
                  value={formData.discount_value}
                  onChange={(event) => setFormData((current) => ({ ...current, discount_value: Number(event.target.value) }))}
                  className="w-full rounded-2xl border border-gray-200 px-4 py-3 text-sm outline-none focus:border-primary"
                />
              </div>
            </div>
            <div className="grid grid-cols-1 gap-3 sm:grid-cols-2 sm:gap-4">
              <div>
                <label className="mb-1 block text-sm font-medium text-gray-700">Min order value</label>
                <input
                  type="number"
                  min="0"
                  required
                  value={formData.min_order_value}
                  onChange={(event) => setFormData((current) => ({ ...current, min_order_value: Number(event.target.value) }))}
                  className="w-full rounded-2xl border border-gray-200 px-4 py-3 text-sm outline-none focus:border-primary"
                />
              </div>
              <div>
                <label className="mb-1 block text-sm font-medium text-gray-700">Expiry date</label>
                <input
                  type="date"
                  required
                  min={new Date().toISOString().split('T')[0]}
                  value={formData.expiry_date}
                  onChange={(event) => setFormData((current) => ({ ...current, expiry_date: event.target.value }))}
                  className="w-full rounded-2xl border border-gray-200 px-4 py-3 text-sm outline-none focus:border-primary"
                />
              </div>
            </div>
            <button
              type="submit"
              disabled={saving}
              className="inline-flex items-center gap-2 rounded-2xl bg-slate-950 px-5 py-3 text-sm font-semibold text-white transition hover:bg-slate-800 disabled:opacity-60"
            >
              {saving ? <Loader2 className="animate-spin" size={16} /> : <Plus size={16} />}
              Create coupon
            </button>
          </form>
        </section>

        <section className="rounded-[32px] border border-gray-100 bg-white p-4 shadow-sm md:p-8">
          <div className="flex flex-col gap-3 md:flex-row md:items-center md:justify-between">
            <div>
              <h2 className="text-lg font-bold">Your storefront coupons</h2>
              <p className="mt-1 text-sm text-gray-500">Live codes your customers can copy from your `/store/[slug]` page.</p>
            </div>
            <span className="rounded-full bg-primary/10 px-3 py-1 text-xs font-bold text-primary">
              {coupons.length} active
            </span>
          </div>

          <div className="mt-6 space-y-4">
            {coupons.length === 0 ? (
              <div className="rounded-2xl border border-dashed border-gray-200 bg-gray-50 px-6 py-12 text-center text-sm text-gray-500">
                No seller coupons yet. Create one to boost your own storefront conversion.
              </div>
            ) : (
              coupons.map((coupon) => (
                <div key={coupon.id} className="rounded-3xl border border-gray-100 bg-secondary/20 p-5">
                  <div className="flex flex-col gap-4 sm:flex-row sm:items-start sm:justify-between">
                    <div>
                      <div className="flex flex-wrap items-center gap-3">
                        <p className="text-lg font-black tracking-[0.18em] text-slate-950">{coupon.code}</p>
                        <button
                          type="button"
                          onClick={async () => {
                            const copied = await copyText(coupon.code);
                            if (copied) {
                              toast.success(`Copied ${coupon.code}`);
                              return;
                            }
                            toast.error('Could not copy this coupon on this device.');
                          }}
                          className="inline-flex items-center gap-1 rounded-full border border-border px-3 py-1 text-xs font-semibold text-slate-700 transition hover:bg-white"
                        >
                          <Copy size={13} />
                          Copy
                        </button>
                      </div>
                      <p className="mt-2 text-sm text-slate-600">
                        {coupon.discount_type === 'percentage' ? `${coupon.discount_value}% off` : `${formatPrice(coupon.discount_value)} off`}
                      </p>
                      <div className="mt-3 flex flex-wrap gap-4 text-xs text-slate-500">
                        <span>Min order {formatPrice(coupon.min_order_value)}</span>
                        <span className="inline-flex items-center gap-1">
                          <Calendar size={13} />
                          {new Date(coupon.expiry_date).toLocaleDateString()}
                        </span>
                      </div>
                    </div>
                    {deleteConfirmId === coupon.id ? (
                      <div className="flex items-center gap-2">
                        <button
                          type="button"
                          onClick={() => void deleteCoupon(coupon.id)}
                          className="rounded-xl bg-rose-600 px-3 py-2 text-xs font-semibold text-white transition hover:bg-rose-700"
                        >
                          Confirm delete
                        </button>
                        <button
                          type="button"
                          onClick={() => setDeleteConfirmId('')}
                          className="rounded-xl border border-border px-3 py-2 text-xs font-semibold text-slate-600 transition hover:bg-white"
                        >
                          Cancel
                        </button>
                      </div>
                    ) : (
                      <button
                        type="button"
                        onClick={() => setDeleteConfirmId(coupon.id)}
                        className="inline-flex items-center gap-2 rounded-xl border border-border px-3 py-2 text-xs font-semibold text-slate-700 transition hover:bg-white"
                      >
                        <Trash2 size={14} />
                        Remove
                      </button>
                    )}
                  </div>
                </div>
              ))
            )}
          </div>
        </section>
      </div>
    </div>
  );
};

export default SellerMarketingCenter;

import React, { useEffect, useMemo, useState } from 'react';
import { Bell, Loader2, ShieldCheck, Tag, Wallet, BadgeCheck, Users, Zap, Package, Truck } from 'lucide-react';
import toast from '@/lib/toast';
import { Link, useNavigate } from '../../../lib/navigation';
import { useUser } from '../../../features/shared/state/UserContext';
import { SellerEmptyState, SellerPageHeader, SellerStatCard } from '@/features/seller/components/SellerPageHeader';

type NotificationItem = {
  id: string;
  type: string;
  title: string;
  message: string;
  action_url?: string | null;
  read_at?: string | null;
  created_at?: string;
};

const sellerNotificationIconByType: Record<string, React.ReactNode> = {
  order_update: <Package className="h-5 w-5" />,
  inventory: <Package className="h-5 w-5" />,
  payout: <Wallet className="h-5 w-5" />,
  verification: <BadgeCheck className="h-5 w-5" />,
  marketing: <Tag className="h-5 w-5" />,
  community: <Users className="h-5 w-5" />,
  flash_sale: <Zap className="h-5 w-5" />,
  courier: <Truck className="h-5 w-5" />,
  security: <ShieldCheck className="h-5 w-5" />,
  account_action: <ShieldCheck className="h-5 w-5" />,
};

function refreshDashboardBadges() {
  if (typeof window === 'undefined') return;
  window.dispatchEvent(new CustomEvent('dashboard-badges:refresh'));
}

export const SellerNotificationsPage = () => {
  const { token } = useUser();
  const navigate = useNavigate();
  const [items, setItems] = useState<NotificationItem[]>([]);
  const [loading, setLoading] = useState(true);
  const [focusedNotificationId, setFocusedNotificationId] = useState('');

  const unreadCount = useMemo(() => items.filter((item) => !item.read_at).length, [items]);

  const loadNotifications = async (options?: { silent?: boolean }) => {
    if (!token) {
      setItems([]);
      setLoading(false);
      return;
    }

    if (!options?.silent) {
      setLoading(true);
    }

    try {
      const response = await fetch(`/api/notifications?ts=${Date.now()}`, {
        headers: {
          Authorization: `Bearer ${token}`,
          'Cache-Control': 'no-cache',
          Pragma: 'no-cache',
        },
        cache: 'no-store',
      });

      const payload = await response.json().catch(() => null);
      if (!response.ok) {
        throw new Error(payload?.error || 'Failed to load seller notifications');
      }

      setItems(Array.isArray(payload) ? payload : []);
    } catch (error) {
      toast.error(error instanceof Error ? error.message : 'Failed to load seller notifications.');
      setItems([]);
    } finally {
      if (!options?.silent) {
        setLoading(false);
      }
      refreshDashboardBadges();
    }
  };

  useEffect(() => {
    void loadNotifications();
  }, [token]);

  useEffect(() => {
    if (!token) return;

    const intervalId = window.setInterval(() => {
      void loadNotifications({ silent: true });
    }, 60000);

    return () => window.clearInterval(intervalId);
  }, [token]);

  useEffect(() => {
    if (typeof window === 'undefined') return;

    const params = new URLSearchParams(window.location.search);
    const nextNotification = params.get('notification');
    if (nextNotification) {
      setFocusedNotificationId(nextNotification);
    }
  }, []);

  useEffect(() => {
    if (!focusedNotificationId) return;

    const matched = items.find((item) => item.id === focusedNotificationId);
    if (!matched) return;

    window.requestAnimationFrame(() => {
      document.getElementById(`seller-notification-${matched.id}`)?.scrollIntoView({
        behavior: 'smooth',
        block: 'center',
      });
    });
  }, [focusedNotificationId, items]);

  const markNotificationRead = async (notificationId: string) => {
    if (!token) {
      return false;
    }

    const response = await fetch(`/api/notifications/${notificationId}/read`, {
      method: 'PATCH',
      headers: {
        Authorization: `Bearer ${token}`,
      },
    });

    if (!response.ok) {
      toast.error('Could not update this notification right now.');
      return false;
    }

    setItems((current) =>
      current.map((item) =>
        item.id === notificationId ? { ...item, read_at: item.read_at || new Date().toISOString() } : item,
      ),
    );
    refreshDashboardBadges();
    return true;
  };

  const markAllRead = async () => {
    if (!token || unreadCount === 0) {
      return;
    }

    const response = await fetch('/api/notifications/read-all', {
      method: 'POST',
      headers: {
        Authorization: `Bearer ${token}`,
      },
    });

    if (!response.ok) {
      toast.error('Could not update notifications right now.');
      return;
    }

    setItems((current) => current.map((item) => ({ ...item, read_at: item.read_at || new Date().toISOString() })));
    refreshDashboardBadges();
    toast.success('All seller notifications marked as read.');
  };

  const openNotification = async (item: NotificationItem) => {
    if (!item.read_at) {
      await markNotificationRead(item.id);
    }

    if (item.action_url) {
      navigate(item.action_url);
    }
  };

  if (loading) {
    return (
      <div className="flex h-64 items-center justify-center">
        <Loader2 className="animate-spin text-primary" size={32} />
      </div>
    );
  }

  return (
    <div className="space-y-6">
      <SellerPageHeader
        eyebrow="Seller inbox"
        title="Notifications"
        description="Track order alerts, payout checks, courier issues, storefront tasks, and seller-side action prompts from one inbox."
        actions={
          <>
            <Link
              to="/seller/settings?section=notifications"
              className="inline-flex h-11 items-center justify-center rounded-xl border border-slate-200 bg-white px-4 text-sm font-semibold text-slate-700 transition hover:border-primary/20 hover:text-primary"
            >
              Notification Settings
            </Link>
            <button
              type="button"
              onClick={() => void markAllRead()}
              className="inline-flex h-11 items-center justify-center rounded-xl bg-slate-950 px-4 text-sm font-semibold text-white transition hover:bg-slate-800 disabled:opacity-60"
              disabled={unreadCount === 0}
            >
              Mark All Read
            </button>
          </>
        }
      />

      <div className="grid gap-4 md:grid-cols-3">
        <SellerStatCard label="Unread" value={unreadCount} tone={unreadCount > 0 ? 'warning' : 'success'} />
        <SellerStatCard label="Total Alerts" value={items.length} />
        <SellerStatCard
          label="Actionable"
          value={items.filter((item) => Boolean(item.action_url)).length}
          tone="default"
        />
      </div>

      <section className="overflow-hidden rounded-[2rem] border border-black/5 bg-white shadow-sm">
        {items.length === 0 ? (
          <div className="p-6">
            <SellerEmptyState message="No seller notifications yet. Order updates, payout reminders, and courier alerts will appear here." />
          </div>
        ) : (
          <div className="divide-y divide-slate-100">
            {items.map((item) => (
              <div
                id={`seller-notification-${item.id}`}
                key={item.id}
                className={`flex flex-col gap-4 px-6 py-5 md:flex-row md:items-start md:justify-between ${
                  item.id === focusedNotificationId
                    ? 'bg-indigo-50 ring-2 ring-inset ring-indigo-200'
                    : item.read_at
                      ? 'bg-white'
                      : 'bg-primary/5'
                }`}
              >
                <div className="flex min-w-0 flex-1 gap-4">
                  <div className="flex h-12 w-12 shrink-0 items-center justify-center rounded-2xl bg-slate-100 text-slate-700">
                    {sellerNotificationIconByType[item.type] ?? <Bell className="h-5 w-5" />}
                  </div>
                  <div className="min-w-0 flex-1">
                    <div className="flex flex-col gap-2 sm:flex-row sm:items-start sm:justify-between">
                      <div className="min-w-0">
                        <h3 className="text-sm font-semibold text-slate-950">{item.title}</h3>
                        <p className="mt-2 text-sm leading-6 text-slate-600">{item.message}</p>
                      </div>
                      <span className="shrink-0 text-xs text-slate-400">
                        {item.created_at ? new Date(item.created_at).toLocaleString() : 'No timestamp'}
                      </span>
                    </div>
                    <div className="mt-3 flex flex-wrap items-center gap-3">
                      {item.action_url ? (
                        <button
                          type="button"
                          onClick={() => void openNotification(item)}
                          className="text-sm font-semibold text-primary hover:text-primary-dark"
                        >
                          Open action
                        </button>
                      ) : null}
                      {!item.read_at ? (
                        <button
                          type="button"
                          onClick={() => void markNotificationRead(item.id)}
                          className="text-sm font-semibold text-slate-600 hover:text-slate-900"
                        >
                          Mark as read
                        </button>
                      ) : null}
                      {item.action_url ? (
                        <Link to={item.action_url} className="text-xs text-slate-400 hover:text-slate-600">
                          {item.action_url}
                        </Link>
                      ) : null}
                    </div>
                  </div>
                </div>
              </div>
            ))}
          </div>
        )}
      </section>
    </div>
  );
};

export default SellerNotificationsPage;

"use client";

import React, { useEffect, useMemo, useState } from 'react';
import { ArrowRight, CheckCircle2, Loader2, MapPin, ShieldCheck, Store, Wallet } from 'lucide-react';
import toast from '@/lib/toast';
import { Link } from '../../../lib/navigation';
import { useUser } from '../../../features/shared/state/UserContext';
import { CenteredLoader, FormNotice } from '@/features/shared/ui/FeedbackState';

type OnboardingStep = {
  id: string;
  title: string;
  description: string;
  completed: boolean;
  status: string;
  action_path: string;
};

type OnboardingStatusPayload = {
  seller?: {
    id: string;
    name?: string | null;
    email?: string | null;
    phone?: string | null;
    store_name?: string | null;
    storefront_slug?: string | null;
    seller_status?: string | null;
    submitted_for_review_at?: string | null;
    approved_at?: string | null;
    rejection_reason?: string | null;
    suspension_reason?: string | null;
  };
  summary: {
    completed_steps: number;
    total_steps: number;
    progress_percent: number;
    ready_for_live_booking: boolean;
    ready_for_admin_review: boolean;
    ready_for_payout: boolean;
    ready_for_storefront_publish: boolean;
  };
  steps: OnboardingStep[];
  next_step?: OnboardingStep | null;
  pickups?: {
    total: number;
    linked_courier_store_count: number;
  };
  verification?: {
    status: string;
    rejection_reason?: string | null;
  } | null;
  approval?: {
    status: string;
    submitted_for_review_at?: string | null;
    approved_at?: string | null;
    rejection_reason?: string | null;
    suspension_reason?: string | null;
    requirements: Array<{ id: string; label: string; completed: boolean }>;
    missing_requirements: Array<{ id: string; label: string; completed: boolean }>;
    can_submit_for_review: boolean;
  } | null;
};

type ProfileResponse = {
  user?: {
    name?: string | null;
    phone?: string | null;
    bio?: string | null;
    store_name?: string | null;
  };
};

type StorefrontResponse = {
  storefront_slug?: string;
  storefront_headline?: string;
  storefront_accent_color?: string;
  storefront_published?: boolean;
};

const emptyStatus: OnboardingStatusPayload = {
  summary: {
    completed_steps: 0,
    total_steps: 0,
    progress_percent: 0,
    ready_for_live_booking: false,
    ready_for_admin_review: false,
    ready_for_payout: false,
    ready_for_storefront_publish: false,
  },
  steps: [],
  next_step: null,
  pickups: {
    total: 0,
    linked_courier_store_count: 0,
  },
  verification: null,
};

export const SellerOnboardingPage = () => {
  const { token, user, setUser } = useUser();
  const [loading, setLoading] = useState(true);
  const [saving, setSaving] = useState(false);
  const [message, setMessage] = useState('');
  const [error, setError] = useState('');
  const [submittingReview, setSubmittingReview] = useState(false);
  const [status, setStatus] = useState<OnboardingStatusPayload>(emptyStatus);
  const [profileForm, setProfileForm] = useState({
    name: '',
    phone: '',
    store_name: '',
    bio: '',
  });
  const [storefrontForm, setStorefrontForm] = useState({
    storefront_slug: '',
    storefront_headline: '',
    storefront_accent_color: '#0F766E',
    storefront_published: false,
  });

  const loadOnboarding = async () => {
    if (!token) return;

    setLoading(true);
    setError('');

    try {
      const [statusRes, profileRes, storefrontRes] = await Promise.all([
        fetch('/api/seller/onboarding-status', {
          headers: { Authorization: `Bearer ${token}` },
        }),
        fetch('/api/users/profile', {
          headers: { Authorization: `Bearer ${token}` },
        }),
        fetch('/api/seller/storefront-settings', {
          headers: { Authorization: `Bearer ${token}` },
        }),
      ]);

      const statusPayload = await statusRes.json().catch(() => null);
      const profilePayload = await profileRes.json().catch(() => null);
      const storefrontPayload = await storefrontRes.json().catch(() => null);

      if (!statusRes.ok) {
        throw new Error(statusPayload?.error || 'Failed to load seller onboarding status');
      }
      if (!profileRes.ok) {
        throw new Error(profilePayload?.error || 'Failed to load seller profile');
      }
      if (!storefrontRes.ok) {
        throw new Error(storefrontPayload?.error || 'Failed to load seller storefront settings');
      }

      const safeProfile = profilePayload as ProfileResponse;
      const safeStorefront = storefrontPayload as StorefrontResponse;

      setStatus(statusPayload as OnboardingStatusPayload);
      setProfileForm({
        name: safeProfile?.user?.name || '',
        phone: safeProfile?.user?.phone || '',
        store_name: safeProfile?.user?.store_name || '',
        bio: safeProfile?.user?.bio || '',
      });
      setStorefrontForm({
        storefront_slug: safeStorefront?.storefront_slug || '',
        storefront_headline: safeStorefront?.storefront_headline || '',
        storefront_accent_color: safeStorefront?.storefront_accent_color || '#0F766E',
        storefront_published: Boolean(safeStorefront?.storefront_published),
      });
    } catch (requestError) {
      setError(requestError instanceof Error ? requestError.message : 'Failed to load onboarding');
      setStatus(emptyStatus);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    void loadOnboarding();
  }, [token]);

  const completionLabel = useMemo(() => {
    const completed = status.summary.completed_steps;
    const total = status.summary.total_steps;
    return total > 0 ? `${completed}/${total} completed` : 'Not started';
  }, [status.summary.completed_steps, status.summary.total_steps]);

  const saveQuickStart = async (event: React.FormEvent) => {
    event.preventDefault();
    if (!token) return;

    try {
      setSaving(true);
      setError('');
      setMessage('');

      const [profileRes, storefrontRes] = await Promise.all([
        fetch('/api/users/profile', {
          method: 'PATCH',
          headers: {
            'Content-Type': 'application/json',
            Authorization: `Bearer ${token}`,
          },
          body: JSON.stringify({
            name: profileForm.name,
            phone: profileForm.phone,
            store_name: profileForm.store_name,
            bio: profileForm.bio,
          }),
        }),
        fetch('/api/seller/storefront-settings', {
          method: 'PATCH',
          headers: {
            'Content-Type': 'application/json',
            Authorization: `Bearer ${token}`,
          },
          body: JSON.stringify({
            storefront_slug: storefrontForm.storefront_slug,
            storefront_headline: storefrontForm.storefront_headline,
            storefront_accent_color: storefrontForm.storefront_accent_color,
            storefront_published: storefrontForm.storefront_published,
          }),
        }),
      ]);

      const profilePayload = await profileRes.json().catch(() => null);
      const storefrontPayload = await storefrontRes.json().catch(() => null);

      if (!profileRes.ok) {
        throw new Error(profilePayload?.error || 'Failed to save seller profile');
      }
      if (!storefrontRes.ok) {
        throw new Error(storefrontPayload?.error || 'Failed to save storefront settings');
      }

      setMessage('Your onboarding basics were saved. Continue with pickup, verification, and payout to go fully live.');
      toast.success('Seller onboarding basics saved.');
      await loadOnboarding();
    } catch (requestError) {
      const nextError = requestError instanceof Error ? requestError.message : 'Failed to save onboarding';
      setError(nextError);
      toast.error(nextError);
    } finally {
      setSaving(false);
    }
  };

  const submitForReview = async () => {
    if (!token) return;

    try {
      setSubmittingReview(true);
      setError('');
      setMessage('');

      const response = await fetch('/api/seller/submit-for-review', {
        method: 'POST',
        headers: {
          Authorization: `Bearer ${token}`,
        },
      });
      const payload = await response.json().catch(() => null);
      if (!response.ok) {
        throw new Error(payload?.error || 'Failed to submit seller account for review');
      }

      toast.success('Submitted for admin review.');
      setMessage('Your seller account was submitted for review. You can keep editing onboarding details while admin reviews it.');
      if (user) {
        setUser({
          ...user,
          seller_status: payload?.seller_status || 'pending_review',
        });
      }
      await loadOnboarding();
    } catch (requestError) {
      const nextError = requestError instanceof Error ? requestError.message : 'Failed to submit seller account for review';
      setError(nextError);
      toast.error(nextError);
    } finally {
      setSubmittingReview(false);
    }
  };

  if (loading) {
    return <CenteredLoader label="Loading seller onboarding..." className="min-h-[300px]" />;
  }

  return (
    <div className="space-y-8">
      <div className="rounded-3xl border border-border bg-[linear-gradient(135deg,rgba(37,99,235,0.08),rgba(15,23,42,0.05))] p-6 shadow-sm sm:p-8">
        <div className="flex flex-col gap-5 lg:flex-row lg:items-center lg:justify-between">
          <div>
            <p className="section-kicker text-primary/70">Seller onboarding</p>
            <h1 className="mt-2 text-2xl font-bold tracking-tight">Set up your store the smart way</h1>
            <p className="mt-2 max-w-2xl text-sm text-muted-foreground">
              Complete your store identity, pickup readiness, verification, and payout setup from one guided workflow.
            </p>
          </div>
          <div className="rounded-3xl border border-border bg-white/80 px-5 py-4 shadow-sm">
            <p className="text-xs font-semibold uppercase tracking-wide text-muted-foreground">Completion</p>
            <p className="mt-2 text-3xl font-bold text-foreground">{status.summary.progress_percent}%</p>
            <p className="mt-1 text-sm text-muted-foreground">{completionLabel}</p>
          </div>
        </div>
      </div>

      {error ? <FormNotice tone="error">{error}</FormNotice> : null}
      {message ? <FormNotice tone="success">{message}</FormNotice> : null}

      <div className="grid gap-4 md:grid-cols-2 xl:grid-cols-4">
        <div className="metric-card">
          <p className="text-xs font-semibold uppercase tracking-wide text-muted-foreground">Pickup points</p>
          <p className="mt-2 text-2xl font-bold">{status.pickups?.total || 0}</p>
          <p className="mt-1 text-sm text-muted-foreground">Total seller pickup locations</p>
        </div>
        <div className="metric-card">
          <p className="text-xs font-semibold uppercase tracking-wide text-muted-foreground">Courier linked</p>
          <p className="mt-2 text-2xl font-bold">{status.pickups?.linked_courier_store_count || 0}</p>
          <p className="mt-1 text-sm text-muted-foreground">Pickup points mapped to courier store</p>
        </div>
        <div className="metric-card">
          <p className="text-xs font-semibold uppercase tracking-wide text-muted-foreground">Verification</p>
          <p className="mt-2 text-2xl font-bold capitalize">{status.verification?.status || 'none'}</p>
          <p className="mt-1 text-sm text-muted-foreground">Current KYC review state</p>
        </div>
        <div className="metric-card">
          <p className="text-xs font-semibold uppercase tracking-wide text-muted-foreground">Next step</p>
          <p className="mt-2 text-lg font-bold">{status.next_step?.title || 'All set'}</p>
          <p className="mt-1 text-sm text-muted-foreground">{status.next_step?.status || 'Your seller onboarding is in a good state.'}</p>
        </div>
      </div>

      <div className="surface-card p-6 sm:p-8">
        <div className="flex flex-col gap-5 lg:flex-row lg:items-start lg:justify-between">
          <div>
            <p className="section-kicker text-primary/70">Approval workflow</p>
            <h2 className="mt-2 text-xl font-bold tracking-tight">Seller approval status</h2>
            <p className="mt-2 max-w-2xl text-sm text-muted-foreground">
              Finish the required onboarding items, then submit your account for admin review. You can keep creating draft products while you wait.
            </p>
            <div className="mt-4 flex flex-wrap gap-2">
              <span className="rounded-full bg-slate-100 px-3 py-1 text-xs font-bold uppercase tracking-wide text-slate-700">
                {String(status.approval?.status || status.seller?.seller_status || 'draft').replaceAll('_', ' ')}
              </span>
              {status.approval?.submitted_for_review_at ? (
                <span className="rounded-full bg-amber-50 px-3 py-1 text-xs font-semibold text-amber-700">
                  Submitted {new Date(status.approval.submitted_for_review_at).toLocaleDateString()}
                </span>
              ) : null}
              {status.approval?.approved_at ? (
                <span className="rounded-full bg-emerald-50 px-3 py-1 text-xs font-semibold text-emerald-700">
                  Approved {new Date(status.approval.approved_at).toLocaleDateString()}
                </span>
              ) : null}
            </div>
          </div>
          <div className="rounded-3xl border border-border bg-white/80 p-5 shadow-sm lg:max-w-sm">
            <p className="text-xs font-semibold uppercase tracking-wide text-muted-foreground">Review gate</p>
            <p className="mt-2 text-sm text-slate-700">
              {status.approval?.can_submit_for_review
                ? 'All required onboarding checkpoints are complete. You can submit now.'
                : 'Complete every required checklist item below before review can be submitted.'}
            </p>
            <button
              type="button"
              onClick={submitForReview}
              disabled={!status.approval?.can_submit_for_review || submittingReview}
              className="mt-4 inline-flex items-center gap-2 rounded-full bg-slate-950 px-5 py-3 text-sm font-semibold text-white transition hover:bg-slate-800 disabled:cursor-not-allowed disabled:opacity-60"
            >
              {submittingReview ? <Loader2 className="animate-spin" size={16} /> : null}
              {submittingReview ? 'Submitting...' : 'Submit for review'}
            </button>
          </div>
        </div>

        {status.approval?.rejection_reason ? (
          <div className="mt-5 rounded-2xl border border-rose-200 bg-rose-50 px-4 py-3 text-sm text-rose-700">
            Rejection reason: {status.approval.rejection_reason}
          </div>
        ) : null}
        {status.approval?.suspension_reason ? (
          <div className="mt-5 rounded-2xl border border-rose-200 bg-rose-50 px-4 py-3 text-sm text-rose-700">
            Suspension reason: {status.approval.suspension_reason}
          </div>
        ) : null}

        <div className="mt-6 grid gap-3 md:grid-cols-2 xl:grid-cols-3">
          {(status.approval?.requirements || []).map((requirement) => (
            <div key={requirement.id} className="rounded-2xl border border-border bg-secondary/20 px-4 py-3">
              <p className="text-sm font-semibold text-foreground">{requirement.label}</p>
              <p className={`mt-1 text-xs font-semibold ${requirement.completed ? 'text-emerald-700' : 'text-amber-700'}`}>
                {requirement.completed ? 'Complete' : 'Missing'}
              </p>
            </div>
          ))}
        </div>
      </div>

      <form id="storefront" onSubmit={saveQuickStart} className="surface-card p-6 sm:p-8">
        <div className="mb-6 flex items-start gap-3">
          <Store className="mt-0.5 text-primary" size={20} />
          <div>
            <h2 className="text-xl font-bold">Quick start basics</h2>
            <p className="mt-1 text-sm text-muted-foreground">
              Save the essentials that power your seller profile and public storefront before you move to courier and compliance.
            </p>
          </div>
        </div>

        <div className="grid gap-4 md:grid-cols-2">
          <label className="space-y-2">
            <span className="text-sm font-semibold text-foreground">Full name</span>
            <input
              value={profileForm.name}
              onChange={(event) => setProfileForm((current) => ({ ...current, name: event.target.value }))}
              className="w-full rounded-2xl border border-border bg-background px-4 py-3 text-sm outline-none transition focus:border-primary"
              placeholder="Seller full name"
            />
          </label>
          <label className="space-y-2">
            <span className="text-sm font-semibold text-foreground">Phone number</span>
            <input
              value={profileForm.phone}
              onChange={(event) => setProfileForm((current) => ({ ...current, phone: event.target.value }))}
              className="w-full rounded-2xl border border-border bg-background px-4 py-3 text-sm outline-none transition focus:border-primary"
              placeholder="01XXXXXXXXX"
            />
          </label>
          <label className="space-y-2">
            <span className="text-sm font-semibold text-foreground">Store name</span>
            <input
              value={profileForm.store_name}
              onChange={(event) => setProfileForm((current) => ({ ...current, store_name: event.target.value }))}
              className="w-full rounded-2xl border border-border bg-background px-4 py-3 text-sm outline-none transition focus:border-primary"
              placeholder="Dhaka Main Fashion"
            />
          </label>
          <label className="space-y-2">
            <span className="text-sm font-semibold text-foreground">Storefront slug</span>
            <input
              value={storefrontForm.storefront_slug}
              onChange={(event) =>
                setStorefrontForm((current) => ({
                  ...current,
                  storefront_slug: event.target.value.toLowerCase().replace(/[^a-z0-9-]/g, '-'),
                }))
              }
              className="w-full rounded-2xl border border-border bg-background px-4 py-3 text-sm outline-none transition focus:border-primary"
              placeholder="dhaka-main-fashion"
            />
          </label>
          <label className="space-y-2 md:col-span-2">
            <span className="text-sm font-semibold text-foreground">Store bio</span>
            <textarea
              rows={3}
              value={profileForm.bio}
              onChange={(event) => setProfileForm((current) => ({ ...current, bio: event.target.value }))}
              className="w-full rounded-2xl border border-border bg-background px-4 py-3 text-sm outline-none transition focus:border-primary"
              placeholder="Tell customers what you sell, where you dispatch from, and what makes your store trustworthy."
            />
          </label>
          <label className="space-y-2">
            <span className="text-sm font-semibold text-foreground">Storefront headline</span>
            <input
              value={storefrontForm.storefront_headline}
              onChange={(event) => setStorefrontForm((current) => ({ ...current, storefront_headline: event.target.value }))}
              className="w-full rounded-2xl border border-border bg-background px-4 py-3 text-sm outline-none transition focus:border-primary"
              placeholder="Original products, fast dispatch, and seller-direct support."
            />
          </label>
          <label className="space-y-2">
            <span className="text-sm font-semibold text-foreground">Accent color</span>
            <div className="flex items-center gap-3 rounded-2xl border border-border bg-background px-4 py-3">
              <input
                type="color"
                value={storefrontForm.storefront_accent_color}
                onChange={(event) => setStorefrontForm((current) => ({ ...current, storefront_accent_color: event.target.value }))}
                className="h-10 w-12 rounded-lg border-0 bg-transparent p-0"
              />
              <input
                value={storefrontForm.storefront_accent_color}
                onChange={(event) => setStorefrontForm((current) => ({ ...current, storefront_accent_color: event.target.value }))}
                className="min-w-0 flex-1 bg-transparent text-sm outline-none"
                placeholder="#0F766E"
              />
            </div>
          </label>
        </div>

        <label className="mt-4 flex items-start gap-3 rounded-2xl border border-border bg-secondary/30 px-4 py-4">
          <input
            type="checkbox"
            checked={storefrontForm.storefront_published}
            onChange={(event) => setStorefrontForm((current) => ({ ...current, storefront_published: event.target.checked }))}
            disabled={status.approval?.status !== 'approved'}
            className="mt-1 h-4 w-4 rounded border-border text-primary focus:ring-primary"
          />
          <span>
            <span className="block text-sm font-semibold text-foreground">Publish storefront when ready</span>
              <span className="mt-1 block text-xs text-muted-foreground">
              {status.approval?.status === 'approved'
                ? 'Turn this on when your store basics, pickup setup, and support details are ready to be seen publicly.'
                : 'Publishing stays locked until admin approves your seller account.'}
              </span>
            </span>
          </label>

        <div className="mt-6 flex flex-wrap items-center justify-between gap-3">
          <p className="text-xs text-muted-foreground">
            Need deeper branding controls? You can still use the full store settings page for banner, custom domain, and advanced storefront controls.
          </p>
          <button
            type="submit"
            disabled={saving}
            className="inline-flex items-center gap-2 rounded-full bg-slate-950 px-5 py-3 text-sm font-semibold text-white transition hover:bg-slate-800 disabled:cursor-not-allowed disabled:opacity-60"
          >
            {saving ? <Loader2 className="animate-spin" size={16} /> : null}
            {saving ? 'Saving...' : 'Save onboarding basics'}
          </button>
        </div>
      </form>

      <div className="grid gap-4 xl:grid-cols-2">
        {status.steps.map((step) => (
          <div key={step.id} className="surface-card p-5">
            <div className="flex items-start justify-between gap-3">
              <div className="min-w-0">
                <div className="flex items-center gap-2">
                  {step.completed ? (
                    <CheckCircle2 size={18} className="text-emerald-600" />
                  ) : step.id === 'pickup' ? (
                    <MapPin size={18} className="text-primary" />
                  ) : step.id === 'verification' ? (
                    <ShieldCheck size={18} className="text-primary" />
                  ) : step.id === 'payout' ? (
                    <Wallet size={18} className="text-primary" />
                  ) : (
                    <Store size={18} className="text-primary" />
                  )}
                  <h3 className="text-base font-bold text-foreground">{step.title}</h3>
                </div>
                <p className="mt-2 text-sm text-muted-foreground">{step.description}</p>
              </div>
              <span
                className={`rounded-full px-3 py-1 text-[11px] font-bold uppercase tracking-wide ${
                  step.completed ? 'bg-emerald-100 text-emerald-700' : 'bg-amber-100 text-amber-700'
                }`}
              >
                {step.completed ? 'Complete' : 'Pending'}
              </span>
            </div>

            <div className="mt-4 rounded-2xl bg-secondary/40 px-4 py-3 text-sm text-slate-700">
              {step.status}
            </div>

            <div className="mt-4 flex items-center justify-between gap-3">
              <p className="text-xs text-muted-foreground">
                {step.completed ? 'You can still reopen this step to refine or update details.' : 'Finish this step to raise your seller readiness score.'}
              </p>
              <Link
                to={step.action_path}
                className="inline-flex items-center gap-2 rounded-full border border-border px-4 py-2 text-xs font-semibold text-slate-700 transition hover:border-primary/20 hover:text-primary"
              >
                Open
                <ArrowRight size={14} />
              </Link>
            </div>
          </div>
        ))}
      </div>
    </div>
  );
};

export default SellerOnboardingPage;

import React, { useEffect, useMemo, useState } from 'react';
import { Search, Download, Loader2, Clock3, Truck, CheckCircle2, AlertTriangle } from 'lucide-react';
import { formatPrice } from '../../../lib/utils';
import { useUser } from '../../../features/shared/state/UserContext';
import { Link } from '../../../lib/navigation';
import { SellerEmptyState, SellerPageHeader, SellerStatCard } from '@/features/seller/components/SellerPageHeader';

export const SellerOrdersPage = () => {
  const { token } = useUser();
  const [orders, setOrders] = useState<any[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState('');
  const [search, setSearch] = useState('');
  const [activeTab, setActiveTab] = useState<'all' | 'new' | 'processing' | 'packed' | 'ready_to_ship' | 'in_transit' | 'delivered' | 'returned' | 'failed_delivery'>('all');

  useEffect(() => {
    if (!token) {
      setOrders([]);
      setLoading(false);
      return;
    }

    let isMounted = true;

    fetch('/api/seller/orders', {
      headers: { Authorization: `Bearer ${token}` },
    })
      .then(async (res) => {
        const data = await res.json().catch(() => null);
        if (!res.ok) {
          throw new Error(data?.error || 'Failed to load orders');
        }
        return data;
      })
      .then((data) => {
        if (isMounted) {
          setOrders(Array.isArray(data) ? data : []);
          setError('');
        }
      })
      .catch((err) => {
        if (isMounted) {
          setOrders([]);
          setError(err instanceof Error ? err.message : 'Failed to load orders');
        }
      })
      .finally(() => {
        if (isMounted) {
          setLoading(false);
        }
      });

    return () => {
      isMounted = false;
    };
  }, [token]);

  useEffect(() => {
    if (typeof window === 'undefined') return;

    const params = new URLSearchParams(window.location.search);
    const nextSearch = params.get('search');
    if (nextSearch) {
      setSearch(nextSearch);
    }
  }, []);

  const getStatusStyle = (status: string) => {
    switch (status) {
      case 'delivered':
        return 'bg-green-100 text-green-800';
      case 'shipped':
        return 'bg-blue-100 text-blue-800';
      case 'processing':
        return 'bg-yellow-100 text-yellow-800';
      case 'cancelled':
        return 'bg-red-100 text-red-800';
      default:
        return 'bg-gray-100 text-gray-800';
    }
  };

  const getUrgencyBadge = (order: any) => {
    const ageHours = getOrderAgeHours(order);
    if (ageHours >= 48) return { label: 'Critical', className: 'bg-rose-100 text-rose-700' };
    if (ageHours >= 24) return { label: 'Aging', className: 'bg-amber-100 text-amber-700' };
    return { label: 'Fresh', className: 'bg-emerald-100 text-emerald-700' };
  };

  const updateStatus = async (id: number, status: string) => {
    try {
      const response = await fetch(`/api/orders/${id}/status`, {
        method: 'PATCH',
        headers: {
          'Content-Type': 'application/json',
          Authorization: `Bearer ${token}`,
        },
        body: JSON.stringify({ status }),
      });
      const data = await response.json().catch(() => null);
      if (!response.ok) {
        throw new Error(data?.error || 'Failed to update order');
      }
      setOrders((current) => current.map((o) => (o.id === id ? { ...o, status } : o)));
      setError('');
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Failed to update order');
    }
  };

  const orderMetrics = useMemo(() => {
    const stateCounts = orders.reduce<Record<string, number>>((acc, order) => {
      const state = getOperationalOrderState(order);
      acc[state] = (acc[state] || 0) + 1;
      return acc;
    }, {});

    return {
      total: orders.length,
      newOrders: stateCounts.new || 0,
      processingOrders: stateCounts.processing || 0,
      packed: stateCounts.packed || 0,
      readyToShip: stateCounts.ready_to_ship || 0,
      inTransit: stateCounts.in_transit || 0,
      deliveredOrders: stateCounts.delivered || 0,
      returned: stateCounts.returned || 0,
      failedDelivery: stateCounts.failed_delivery || 0,
    };
  }, [orders]);

  const filteredOrders = orders.filter((order) => {
    const term = search.trim().toLowerCase();
    const operationalState = getOperationalOrderState(order);
    const matchesTab = activeTab === 'all' ? true : operationalState === activeTab;

    if (!matchesTab) return false;
    if (!term) return true;
    const shipmentSummary = Array.isArray(order.shipments)
      ? order.shipments
          .flatMap((shipment: any) => [
            shipment.warehouse_name,
            shipment.courier_provider,
            shipment.tracking_id,
            shipment.status,
          ])
          .filter(Boolean)
          .join(' ')
          .toLowerCase()
      : '';
    const itemSummary = Array.isArray(order.items)
      ? order.items
          .flatMap((item: any) => [item.name, item.sku, item.variant_summary])
          .filter(Boolean)
          .join(' ')
          .toLowerCase()
      : '';

    return (
      `#${String(order.order_code || order.id)}`.toLowerCase().includes(term) ||
      String(order.status || '').toLowerCase().includes(term) ||
      String(order.courier_provider || '').toLowerCase().includes(term) ||
      String(order.tracking_id || '').toLowerCase().includes(term) ||
      shipmentSummary.includes(term) ||
      itemSummary.includes(term)
    );
  });

  const orderTabs = [
    { id: 'all', label: 'All orders', count: orderMetrics.total },
    { id: 'new', label: 'New', count: orderMetrics.newOrders },
    { id: 'processing', label: 'Processing', count: orderMetrics.processingOrders },
    { id: 'packed', label: 'Packed', count: orderMetrics.packed },
    { id: 'ready_to_ship', label: 'Ready to Ship', count: orderMetrics.readyToShip },
    { id: 'in_transit', label: 'In Transit', count: orderMetrics.inTransit },
    { id: 'delivered', label: 'Delivered', count: orderMetrics.deliveredOrders },
    { id: 'returned', label: 'Returned', count: orderMetrics.returned },
    { id: 'failed_delivery', label: 'Failed Delivery', count: orderMetrics.failedDelivery },
  ] as const;

  const handleExport = () => {
    const rows = filteredOrders.map((order) => ({
      order_id: String(order.order_code || order.id),
      date: new Date(order.created_at).toISOString(),
      total: order.total,
      status: order.status,
      shipment_count: Array.isArray(order.shipments) ? order.shipments.length : 0,
      courier: Array.isArray(order.shipments)
        ? order.shipments.map((shipment: any) => shipment.courier_provider || 'pending').join(' | ')
        : order.courier_provider || '',
      tracking: Array.isArray(order.shipments)
        ? order.shipments.map((shipment: any) => shipment.tracking_id || 'pending').join(' | ')
        : order.tracking_id || '',
      warehouses: Array.isArray(order.shipments)
        ? order.shipments.map((shipment: any) => shipment.warehouse_name || 'Pickup point').join(' | ')
        : '',
      items: Array.isArray(order.items)
        ? order.items.map((item: any) => (item.sku ? `${item.sku} ${item.name || ''}` : item.name || '')).join(' | ')
        : '',
    }));

    const headers = ['order_id', 'date', 'total', 'status', 'shipment_count', 'courier', 'tracking', 'warehouses', 'items'];
    const csv = [
      headers.join(','),
      ...rows.map((row) =>
        headers
          .map((header) => `"${String((row as any)[header] ?? '').replaceAll('"', '""')}"`)
          .join(','),
      ),
    ].join('\n');

    const blob = new Blob([csv], { type: 'text/csv;charset=utf-8;' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.href = url;
    link.download = `seller-orders-${new Date().toISOString().slice(0, 10)}.csv`;
    document.body.appendChild(link);
    link.click();
    link.remove();
    URL.revokeObjectURL(url);
  };

  if (loading)
    return (
      <div className="flex h-64 items-center justify-center">
        <Loader2 className="animate-spin text-primary" size={32} />
      </div>
    );

  return (
    <div className="space-y-6">
      {error && (
        <div className="rounded-xl border border-red-200 bg-red-50 px-4 py-3 text-sm text-red-700">
          {error}
        </div>
      )}

      <SellerPageHeader
        eyebrow="Order workspace"
        title="Seller Orders"
        description="Review new demand, move shipments forward, and keep courier pressure visible from one workspace."
        actions={
          <>
            <button
              onClick={handleExport}
              className="inline-flex h-11 items-center justify-center space-x-2 rounded-xl border border-slate-200 bg-white px-4 text-sm font-semibold text-slate-700 transition hover:border-primary/20 hover:text-primary"
            >
              <Download size={18} />
              <span>Export CSV</span>
            </button>
            <Link
              to="/seller/courier"
              className="inline-flex h-11 items-center justify-center rounded-xl bg-slate-950 px-4 text-sm font-semibold text-white transition hover:bg-slate-800"
            >
              Open courier
            </Link>
          </>
        }
      />

      <div className="grid gap-4 sm:grid-cols-2 xl:grid-cols-4">
        <SellerStatCard label="New" value={orderMetrics.newOrders} tone="warning" />
        <SellerStatCard label="Processing" value={orderMetrics.processingOrders} />
        <SellerStatCard label="Ready to Ship" value={orderMetrics.readyToShip} />
        <SellerStatCard label="Delivered" value={orderMetrics.deliveredOrders} tone="success" />
      </div>

      <div className="sticky top-[5.5rem] z-10 space-y-4 rounded-[1.75rem] border border-black/5 bg-white/95 p-4 shadow-sm backdrop-blur md:p-5">
        <div className="dashboard-chip-scroll -mx-1 flex gap-2 overflow-x-auto px-1">
          {orderTabs.map((tab) => (
            <button
              key={tab.id}
              type="button"
              onClick={() => setActiveTab(tab.id)}
              className={`inline-flex shrink-0 items-center gap-2 rounded-full px-4 py-2 text-sm font-semibold transition ${
                activeTab === tab.id
                  ? 'bg-slate-950 text-white shadow-sm'
                  : 'border border-slate-200 bg-white text-slate-600 hover:border-primary/20 hover:text-primary'
              }`}
            >
              <span>{tab.label}</span>
              <span
                className={`inline-flex min-w-[1.5rem] items-center justify-center rounded-full px-2 py-0.5 text-[11px] font-bold ${
                  activeTab === tab.id ? 'bg-white/15 text-white' : 'bg-slate-100 text-slate-500'
                }`}
              >
                {tab.count}
              </span>
            </button>
          ))}
        </div>

        <div className="flex flex-col gap-3 sm:flex-row sm:items-center sm:justify-between">
          <div className="relative flex-1 sm:max-w-xl">
            <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-gray-400" size={18} />
            <input
              type="text"
              placeholder="Search order, status, courier, tracking, warehouse, or item..."
              value={search}
              onChange={(e) => setSearch(e.target.value)}
              className="h-11 w-full rounded-xl border border-gray-200 bg-white pl-10 pr-4 text-sm focus:ring-2 focus:ring-primary"
            />
          </div>
          <div className="rounded-xl bg-slate-50 px-4 py-3 text-xs font-semibold text-slate-500">
            {filteredOrders.length} of {orders.length} orders visible
          </div>
        </div>
      </div>

      <div className="overflow-hidden rounded-[1.75rem] border border-black/5 bg-white shadow-sm">
        <div className="space-y-3 p-4 md:hidden">
          {filteredOrders.length === 0 ? (
            <SellerEmptyState message="No orders found for this filter yet." />
          ) : (
            filteredOrders.map((order) => (
              <div key={order.id} className="space-y-4 rounded-2xl border border-slate-200 bg-white p-4 shadow-sm">
                <div className="flex items-start justify-between gap-3">
                  <div>
                    <p className="text-sm font-bold text-slate-900">#{order.order_code || order.id}</p>
                    <p className="mt-1 text-xs text-gray-500">{new Date(order.created_at).toLocaleDateString()}</p>
                  </div>
                  <div className="text-right">
                    <p className="text-sm font-bold text-primary">{formatPrice(order.total)}</p>
                    <span className={`mt-2 inline-flex rounded-full px-2.5 py-1 text-[10px] font-bold uppercase tracking-[0.14em] ${getUrgencyBadge(order).className}`}>
                      {getUrgencyBadge(order).label}
                    </span>
                  </div>
                </div>

                <div className="rounded-2xl bg-slate-50 p-3">
                  <p className="text-[11px] font-semibold uppercase tracking-wide text-slate-500">
                    Shipment Summary
                  </p>
                  {Array.isArray(order.shipments) && order.shipments.length > 0 ? (
                    <div className="mt-2 space-y-2">
                      <p className="text-xs text-gray-500">
                        {order.shipments.length} shipment{order.shipments.length > 1 ? 's' : ''}
                      </p>
                      <div className="flex flex-wrap gap-1">
                        {order.shipments.slice(0, 3).map((shipment: any) => (
                          <span
                            key={shipment.id}
                            className="dashboard-stat-chip bg-white text-slate-600"
                          >
                            {shipment.warehouse_name || 'Pickup point'} /{' '}
                            {shipment.courier_provider || 'courier pending'}
                          </span>
                        ))}
                      </div>
                      <div className="text-[11px] text-gray-500">
                        {order.shipments
                          .slice(0, 2)
                          .map((shipment: any) => shipment.tracking_id || 'tracking pending')
                          .join(' / ')}
                      </div>
                    </div>
                  ) : (
                    <p className="mt-2 text-xs text-gray-400">No shipment summary yet</p>
                  )}
                  {Array.isArray(order.items) && order.items.length > 0 ? (
                    <div className="mt-2 flex flex-wrap gap-1">
                      {order.items.slice(0, 2).map((item: any) => (
                        <span
                          key={item.id}
                          className="dashboard-stat-chip bg-white text-slate-600"
                        >
                          {item.sku || 'SKU pending'}
                        </span>
                      ))}
                    </div>
                  ) : null}
                </div>

                <div className="space-y-3">
                  <select
                    value={order.status}
                    onChange={(e) => updateStatus(order.id, e.target.value)}
                    className={`w-full cursor-pointer rounded-xl border-none px-3 py-2 text-xs font-bold uppercase tracking-wider focus:ring-2 focus:ring-primary/20 ${getStatusStyle(order.status)}`}
                  >
                    <option value="pending">Pending</option>
                    <option value="processing">Processing</option>
                    <option value="shipped">Shipped</option>
                    <option value="delivered">Delivered</option>
                    <option value="cancelled">Cancelled</option>
                  </select>
                  <a
                    href={`/seller/courier?search=${encodeURIComponent(
                      Array.isArray(order.shipments) && order.shipments.length > 0
                        ? order.shipments[0]?.tracking_id ||
                            order.shipments[0]?.id ||
                            String(order.order_code || order.id)
                        : String(order.order_code || order.id),
                    )}`}
                    className="inline-flex w-full items-center justify-center rounded-xl border border-gray-200 px-3 py-2 text-xs font-semibold text-slate-700 transition hover:bg-gray-50"
                  >
                    Open courier
                  </a>
                </div>
              </div>
            ))
          )}
        </div>

        <div className="hidden overflow-x-auto md:block">
          <table className="w-full border-collapse text-left">
            <thead>
              <tr className="bg-gray-50 text-xs font-bold uppercase tracking-wider text-gray-500">
                <th className="px-6 py-4">Order ID</th>
                <th className="px-6 py-4">Date</th>
                <th className="px-6 py-4">Total</th>
                <th className="px-6 py-4">Shipment Summary</th>
