              <Sparkles size={14} />
              <span>{isEdit ? 'Listing editor' : 'New listing'}</span>
            </div>
            <h1 className="text-2xl font-black tracking-tight text-slate-950 sm:text-3xl">
              {isEdit ? 'Edit Product' : 'Add New Product'}
