                  <p className="text-[11px] font-bold uppercase text-slate-400">Specs</p>
                  <p className="mt-1 text-lg font-black text-slate-950">{formData.specifications.length}</p>
                </div>
                <div className="rounded-2xl bg-slate-50 p-3">
                  <p className="text-[11px] font-bold uppercase text-slate-400">Variants</p>
                  <p className="mt-1 text-lg font-black text-slate-950">{variantValueCount}</p>
                </div>
                <div className="rounded-2xl bg-slate-50 p-3">
                  <p className="text-[11px] font-bold uppercase text-slate-400">SKU</p>
                  <p className="mt-1 truncate text-sm font-black text-slate-950">{baseSkuPreview}</p>
                </div>
              </div>
            </div>
          </aside>

          <div className="space-y-6">
            <section className="rounded-[1.5rem] border border-black/5 bg-white p-5 shadow-sm sm:p-6">
              <div className="mb-6 flex items-start gap-3">
                <div className="flex h-10 w-10 shrink-0 items-center justify-center rounded-xl bg-primary/10 text-primary">
                  <Box size={20} />
                </div>
                <div>
                  <h2 className="text-lg font-black text-slate-950">Product Basics</h2>
                  <p className="mt-1 text-sm text-slate-500">Name, category, price, stock, SKU, and buyer-facing story.</p>
                </div>
              </div>

              <div className="grid gap-5">
                <div className="space-y-2">
                  <label className="text-sm font-semibold text-slate-700">Product Name</label>
                  <input
                    type="text"
                    required
                    value={formData.name}
                    onChange={(e) => setFormData({ ...formData, name: e.target.value })}
                    placeholder="e.g. Premium Cotton Panjabi"
                    className="h-12 w-full rounded-xl border border-slate-200 bg-slate-50 px-4 text-sm focus:bg-white focus:ring-2 focus:ring-primary/20"
                  />
                </div>

                <div className="grid grid-cols-1 gap-5 md:grid-cols-2">
                  <div className="space-y-2">
                    <label className="text-sm font-semibold text-slate-700">Category</label>
                    <select
                      value={formData.category}
                      onChange={(e) => setFormData({ ...formData, category: e.target.value })}
                      className="h-12 w-full rounded-xl border border-slate-200 bg-slate-50 px-4 text-sm focus:bg-white focus:ring-2 focus:ring-primary/20"
                    >
                      <option>Fashion</option>
                      <option>Electronics</option>
                      <option>Groceries</option>
                      <option>Home & Living</option>
                    </select>
                  </div>
                  <div className="space-y-2">
                    <label className="text-sm font-semibold text-slate-700">Price (BDT)</label>
                    <input
                      type="number"
                      required
                      min="0"
                      step="0.01"
                      value={formData.price}
                      onChange={(e) => setFormData({ ...formData, price: e.target.value })}
                      placeholder="0.00"
                      className="h-12 w-full rounded-xl border border-slate-200 bg-slate-50 px-4 text-sm focus:bg-white focus:ring-2 focus:ring-primary/20"
                    />
                  </div>
                </div>

                <div className="grid grid-cols-1 gap-5 md:grid-cols-2">
                  <div className="space-y-2">
                    <label className="text-sm font-semibold text-slate-700">Stock Quantity</label>
                    <input
                      type="number"
                      required
                      min="0"
                      value={formData.stock}
                      onChange={(e) => setFormData({ ...formData, stock: e.target.value })}
                      placeholder="0"
                      className="h-12 w-full rounded-xl border border-slate-200 bg-slate-50 px-4 text-sm focus:bg-white focus:ring-2 focus:ring-primary/20"
                    />
                  </div>
                  <div className="space-y-2">
                    <label className="text-sm font-semibold text-slate-700">SKU</label>
                    <input
                      type="text"
                      readOnly
                      value={baseSkuPreview}
                      className="h-12 w-full rounded-xl border border-slate-200 bg-slate-50 px-4 text-sm font-semibold text-slate-500 focus:ring-2 focus:ring-primary/20"
                    />
                    <p className="text-xs text-slate-500">SKU auto-generates when the product is saved.</p>
                  </div>
                </div>

                <div className="space-y-3">
                  <div className="flex flex-col gap-3 sm:flex-row sm:items-center sm:justify-between">
                    <label className="text-sm font-semibold text-slate-700">Description</label>
                    <div className="flex flex-wrap gap-2">
                      {[
                        { key: 'bold', label: 'B' },
                        { key: 'italic', label: 'I' },
                        { key: 'bullet', label: 'Bullets' },
                        { key: 'table', label: 'Table' },
                        { key: 'emoji', label: 'Tag' },
                      ].map((item) => (
                        <button
                          key={item.key}
                          type="button"
                          title={`Insert ${item.key}`}
                          onClick={() => applyDescriptionFormat(item.key as 'bold' | 'italic' | 'bullet' | 'table' | 'emoji')}
                          className="inline-flex h-9 min-w-9 items-center justify-center rounded-lg border border-slate-200 bg-white px-3 text-xs font-bold text-slate-600 transition hover:bg-slate-50"
                        >
                          {item.label}
                        </button>
                      ))}
                      <button
                        type="button"
                        onClick={() => setShowDescriptionPreview((current) => !current)}
                        className="inline-flex h-9 items-center gap-2 rounded-lg border border-primary/15 bg-primary/5 px-3 text-xs font-bold text-primary transition hover:bg-primary/10"
                      >
                        {showDescriptionPreview ? <EyeOff size={14} /> : <Eye size={14} />}
                        <span>{showDescriptionPreview ? 'Hide' : 'Preview'}</span>
                      </button>
                    </div>
                  </div>
                  <textarea
                    id="product-description-field"
                    rows={6}
                    required
                    value={formData.description}
                    onChange={(e) => setFormData({ ...formData, description: e.target.value })}
                    placeholder="Describe material, fit, use cases, care, warranty, and what makes this product worth buying."
                    className="w-full rounded-xl border border-slate-200 bg-slate-50 px-4 py-3 text-sm leading-6 focus:bg-white focus:ring-2 focus:ring-primary/20"
                  />
                  <p className="text-xs text-slate-500">Supports bold, italic, bullet lists, tables, and short highlights. Raw HTML is not allowed.</p>
                  {showDescriptionPreview ? (
                    <div className="rounded-2xl border border-slate-200 bg-slate-50 p-4">
                      <p className="text-xs font-bold uppercase tracking-[0.16em] text-slate-500">Customer preview</p>
                      <div
                        className="mt-3 space-y-4 text-sm leading-6 text-slate-700"
                        dangerouslySetInnerHTML={{ __html: descriptionPreview || '<p class="text-sm text-slate-500">Description preview will appear here.</p>' }}
                      />
                    </div>
                  ) : null}
                </div>
              </div>
            </section>

            <section className="rounded-[1.5rem] border border-black/5 bg-white p-5 shadow-sm sm:p-6">
              <div className="mb-5 flex items-start gap-3">
                <div className="flex h-10 w-10 shrink-0 items-center justify-center rounded-xl bg-sky-50 text-sky-600">
                  <ImageIcon size={20} />
                </div>
                <div>
                  <h2 className="text-lg font-black text-slate-950">Gallery And Rich Media</h2>
                  <p className="mt-1 text-sm text-slate-500">Add extra photos, a video link, or a GLB model for richer product pages.</p>
                </div>
              </div>

              <div className="space-y-5">
                <CloudinaryUpload
                  label="Add gallery image"
                  helper="Use detail shots, packaging, scale, and lifestyle images."
                  onUploaded={(url) =>
                    setFormData((current) => ({
                      ...current,
                      gallery_images: current.gallery_images.includes(url) ? current.gallery_images : [...current.gallery_images, url],
                    }))
                  }
                />

                {formData.gallery_images.length > 0 ? (
                  <div className="grid gap-4 sm:grid-cols-2 lg:grid-cols-3">
                    {formData.gallery_images.map((url, index) => (
                      <div key={`${url}-${index}`} className="rounded-2xl border border-slate-200 bg-slate-50 p-3">
                        <div className="aspect-square overflow-hidden rounded-xl bg-white">
                          <img src={url} alt={`Gallery ${index + 1}`} className="h-full w-full object-cover" />
                        </div>
                        <div className="mt-3 flex items-center justify-between gap-2">
                          <span className="text-xs font-bold text-slate-500">Image {index + 1}</span>
                          <div className="flex items-center gap-1">
                            <button
                              type="button"
                              title="Move up"
                              onClick={() => moveGalleryImage(index, index - 1)}
                              disabled={index === 0}
                              className="inline-flex h-8 w-8 items-center justify-center rounded-lg border border-slate-200 bg-white text-slate-500 transition hover:bg-slate-50 disabled:cursor-not-allowed disabled:opacity-40"
                            >
                              <ArrowUp size={14} />
                            </button>
                            <button
                              type="button"
                              title="Move down"
                              onClick={() => moveGalleryImage(index, index + 1)}
                              disabled={index === formData.gallery_images.length - 1}
                              className="inline-flex h-8 w-8 items-center justify-center rounded-lg border border-slate-200 bg-white text-slate-500 transition hover:bg-slate-50 disabled:cursor-not-allowed disabled:opacity-40"
                            >
                              <ArrowDown size={14} />
                            </button>
                            <button
                              type="button"
                              title="Remove image"
                              onClick={() =>
                                setFormData((current) => ({
                                  ...current,
                                  gallery_images: current.gallery_images.filter((_, itemIndex) => itemIndex !== index),
                                }))
                              }
                              className="inline-flex h-8 w-8 items-center justify-center rounded-lg border border-rose-200 bg-white text-rose-600 transition hover:bg-rose-50"
                            >
                              <Trash2 size={14} />
                            </button>
                          </div>
                        </div>
                        <input
                          type="url"
                          value={url}
                          onChange={(e) =>
                            setFormData((current) => ({
                              ...current,
                              gallery_images: current.gallery_images.map((item, itemIndex) => (itemIndex === index ? e.target.value : item)),
                            }))
                          }
                          className="mt-3 h-10 w-full rounded-xl border border-slate-200 bg-white px-3 text-xs focus:ring-2 focus:ring-primary/20"
                        />
                      </div>
                    ))}
                  </div>
                ) : (
                  <div className="rounded-2xl border border-dashed border-slate-200 bg-slate-50 px-4 py-6 text-center text-sm text-slate-500">
                    No gallery images added yet.
                  </div>
                )}

                <div className="grid gap-5 md:grid-cols-2">
                  <div className="space-y-2">
                    <label className="text-sm font-semibold text-slate-700">Product Video URL</label>
                    <input
                      type="url"
                      value={formData.video_url}
                      onChange={(e) => setFormData({ ...formData, video_url: e.target.value })}
                      placeholder="Paste hosted product video URL"
                      className="h-12 w-full rounded-xl border border-slate-200 bg-slate-50 px-4 text-sm focus:bg-white focus:ring-2 focus:ring-primary/20"
                    />
                  </div>
                  <div className="space-y-2">
                    <label className="text-sm font-semibold text-slate-700">3D Model URL (GLB)</label>
                    <input
                      type="url"
                      value={formData.model_3d}
                      onChange={(e) => setFormData({ ...formData, model_3d: e.target.value })}
                      placeholder="Paste hosted .glb model URL"
                      className="h-12 w-full rounded-xl border border-slate-200 bg-slate-50 px-4 text-sm focus:bg-white focus:ring-2 focus:ring-primary/20"
                    />
                  </div>
                </div>
              </div>
            </section>

            <section className="rounded-[1.5rem] border border-black/5 bg-white p-5 shadow-sm sm:p-6">
                <div className="mb-5 flex flex-col gap-4 sm:flex-row sm:items-start sm:justify-between">
                  <div className="flex items-start gap-3">
                    <div className="flex h-10 w-10 shrink-0 items-center justify-center rounded-xl bg-violet-50 text-violet-600">
                      <Tags size={20} />
                    </div>
                    <div>
                      <h2 className="text-lg font-black text-slate-950">Product Specifications</h2>
                      <p className="mt-1 text-sm text-slate-500">
                      Add category-wise details like color, weight, size, warranty, dimensions, or material.
                      </p>
                    </div>
                  </div>
                  <button
                    type="button"
                    onClick={() =>
                      setFormData((current) => ({
                        ...current,
                        specifications: [...current.specifications, { label: '', value: '' }],
                      }))
                    }
                    className="inline-flex h-10 items-center justify-center gap-2 rounded-xl border border-slate-200 bg-white px-4 text-xs font-bold text-slate-700 transition hover:bg-slate-50"
                  >
                    <Plus size={14} />
                    <span>Add spec</span>
                  </button>
                </div>

                {categorySpecSuggestions.length > 0 ? (
                  <div className="flex flex-wrap gap-2">
                    {categorySpecSuggestions.map((suggestion) => (
                      <button
                        key={suggestion}
                        type="button"
                        onClick={() =>
                          setFormData((current) => {
                            if (current.specifications.some((item) => item.label.toLowerCase() === suggestion.toLowerCase())) {
                              return current;
                            }
                            return {
                              ...current,
                              specifications: [...current.specifications, { label: suggestion, value: '' }],
                            };
                          })
                        }
                        className="rounded-full bg-slate-100 px-3 py-1.5 text-[11px] font-bold text-slate-600 transition hover:bg-slate-200"
                      >
                        {suggestion}
                      </button>
                    ))}
                  </div>
                ) : null}

                {formData.specifications.length === 0 ? (
                  <div className="rounded-2xl border border-dashed border-slate-200 bg-slate-50 px-4 py-6 text-center text-sm text-slate-500">
                    No specifications added yet.
                  </div>
                ) : (
                  <div className="space-y-3">
                    {formData.specifications.map((specification, index) => (
                      <div key={`spec-${index}`} className="grid gap-3 md:grid-cols-[0.8fr_1.2fr_auto]">
                        <input
                          type="text"
                          value={specification.label}
                          onChange={(e) =>
                            setFormData((current) => ({
                              ...current,
                              specifications: current.specifications.map((item, itemIndex) =>
                                itemIndex === index ? { ...item, label: e.target.value } : item,
                              ),
                            }))
                          }
                          placeholder="Spec label"
                          className="h-11 w-full rounded-xl border border-slate-200 bg-slate-50 px-4 text-sm focus:bg-white focus:ring-2 focus:ring-primary/20"
                        />
                        <input
                          type="text"
                          value={specification.value}
                          onChange={(e) =>
                            setFormData((current) => ({
                              ...current,
                              specifications: current.specifications.map((item, itemIndex) =>
                                itemIndex === index ? { ...item, value: e.target.value } : item,
                              ),
                            }))
                          }
                          placeholder="Spec value"
                          className="h-11 w-full rounded-xl border border-slate-200 bg-slate-50 px-4 text-sm focus:bg-white focus:ring-2 focus:ring-primary/20"
                        />
                        <button
                          type="button"
                          onClick={() =>
                            setFormData((current) => ({
                              ...current,
                              specifications: current.specifications.filter((_, itemIndex) => itemIndex !== index),
                            }))
                          }
                          className="inline-flex h-11 items-center justify-center rounded-xl border border-rose-200 px-3 text-rose-600 transition hover:bg-rose-50"
                        >
                          <Trash2 size={16} />
                        </button>
                      </div>
                    ))}
                  </div>
                )}
              </section>

              <section className="space-y-5 rounded-[1.5rem] border border-emerald-200 bg-emerald-50/60 p-5 shadow-sm sm:p-6">
                <div className="flex flex-col gap-4 sm:flex-row sm:items-start sm:justify-between">
                  <div className="flex items-start gap-3">
                    <div className="flex h-10 w-10 shrink-0 items-center justify-center rounded-xl bg-white text-emerald-600">
                      <BadgeDollarSign size={20} />
                    </div>
                    <div>
                      <h2 className="text-lg font-black text-slate-950">Reseller Sales</h2>
                      <p className="mt-1 text-sm text-slate-600">
                      Enable this if resellers can add this product to their shop and sell above your reseller base price.
                      </p>
                    </div>
                  </div>
                  <label className="inline-flex h-10 cursor-pointer items-center gap-2 rounded-xl bg-white px-4 text-sm font-bold text-slate-700 shadow-sm">
                    <input
                      type="checkbox"
                      checked={formData.reseller_enabled}
                      onChange={(e) => setFormData({ ...formData, reseller_enabled: e.target.checked })}
                    />
                    <span>Allow resellers</span>
                  </label>
                </div>

                {formData.reseller_enabled ? (
                  <div className="grid gap-4 md:grid-cols-2">
                    <div className="space-y-2">
                      <label className="text-xs font-bold text-gray-500 uppercase">Reseller base price</label>
                      <input
                        type="number"
                        min="0"
                        step="0.01"
                        value={formData.reseller_base_price}
                        onChange={(e) => setFormData({ ...formData, reseller_base_price: e.target.value })}
                        placeholder="Minimum seller price for reseller orders"
                        className="h-12 w-full rounded-xl border border-emerald-100 bg-white px-4 text-sm focus:ring-2 focus:ring-primary/20"
                      />
                    </div>
                    <div className="space-y-2">
                      <label className="text-xs font-bold text-gray-500 uppercase">Suggested reseller sale price</label>
                      <input
                        type="number"
                        min="0"
                        step="0.01"
                        value={formData.reseller_suggested_price}
                        onChange={(e) => setFormData({ ...formData, reseller_suggested_price: e.target.value })}
                        placeholder="Optional guidance for resellers"
                        className="h-12 w-full rounded-xl border border-emerald-100 bg-white px-4 text-sm focus:ring-2 focus:ring-primary/20"
                      />
                    </div>
                    <div className="space-y-2 md:col-span-2">
                      <label className="text-xs font-bold text-gray-500 uppercase">Reseller notes</label>
                      <textarea
                        rows={3}
                        value={formData.reseller_notes}
                        onChange={(e) => setFormData({ ...formData, reseller_notes: e.target.value })}
                        placeholder="Tell resellers how to pitch or position this product"
                        className="w-full rounded-xl border border-emerald-100 bg-white px-4 py-3 text-sm focus:ring-2 focus:ring-primary/20"
                      />
                    </div>
                  </div>
                ) : null}
              </section>

              <section className="rounded-[1.5rem] border border-black/5 bg-white p-5 shadow-sm sm:p-6">
                <div className="mb-5 flex flex-col gap-4 sm:flex-row sm:items-start sm:justify-between">
                  <div className="flex items-start gap-3">
                    <div className="flex h-10 w-10 shrink-0 items-center justify-center rounded-xl bg-indigo-50 text-indigo-600">
                      <Layers3 size={20} />
                    </div>
                    <div>
                      <h2 className="text-lg font-black text-slate-950">Variant Options</h2>
                      <p className="mt-1 text-sm text-slate-500">
                      Add simple options like Size, Color, or Storage. These options appear on the product page.
                      </p>
                    </div>
                  </div>
                  <button
                    type="button"
                    onClick={() =>
                      setFormData((current) => ({
                        ...current,
                        variant_options: [...current.variant_options, { name: '', values: [{ label: '', price_adjustment: 0, sku_suffix: null, stock_override: null }] }],
                      }))
                    }
                    className="inline-flex h-10 items-center justify-center gap-2 rounded-xl border border-slate-200 bg-white px-4 text-xs font-bold text-slate-700 transition hover:bg-slate-50"
                  >
                    <Plus size={14} />
                    <span>Add option</span>
                  </button>
                </div>

                {formData.variant_options.length === 0 ? (
                  <div className="rounded-2xl border border-dashed border-slate-200 bg-slate-50 px-4 py-6 text-center text-sm text-slate-500">
                    No variants yet. Add options if this product comes in multiple versions.
                  </div>
                ) : (
                  <div className="space-y-4">
                    {formData.variant_options.map((variant, index) => (
                      <div key={`variant-${index}`} className="rounded-2xl border border-slate-200 bg-slate-50 p-4">
                        <div className="grid gap-4 xl:grid-cols-[220px_minmax(0,1fr)_auto] xl:items-start">
                          <div className="space-y-2">
                            <label className="text-xs font-bold text-gray-500 uppercase">Option name</label>
                            <input
                              type="text"
                              value={variant.name}
                              onChange={(e) => updateVariant(index, { name: e.target.value })}
                              placeholder="Size"
                              className="h-11 w-full rounded-xl border border-slate-200 bg-white px-4 text-sm focus:ring-2 focus:ring-primary/20"
                            />
                          </div>
                          <div className="space-y-2">
                            <label className="text-xs font-bold text-gray-500 uppercase">Values</label>
                            <div className="space-y-3 rounded-xl bg-white p-3">
                              {variant.values.map((value, valueIndex) => (
                                <div key={`variant-${index}-value-${valueIndex}`} className="grid gap-3 lg:grid-cols-[1.1fr_0.75fr_0.75fr_0.85fr_auto]">
                                  <input
                                    type="text"
                                    value={value.label}
                                    onChange={(e) => updateVariantValue(index, valueIndex, { label: e.target.value })}
                                    placeholder="Blue"
                                    className="h-11 w-full rounded-xl border border-slate-200 px-4 text-sm focus:ring-2 focus:ring-primary/20"
                                  />
                                  <input
                                    type="number"
                                    value={value.price_adjustment ?? 0}
                                    onChange={(e) => updateVariantValue(index, valueIndex, { price_adjustment: Number(e.target.value) || 0 })}
                                    placeholder="0"
                                    className="h-11 w-full rounded-xl border border-slate-200 px-4 text-sm focus:ring-2 focus:ring-primary/20"
                                  />
                                  <input
                                    type="text"
                                    value={value.sku_suffix || ''}
                                    onChange={(e) =>
                                      updateVariantValue(index, valueIndex, {
                                        sku_suffix: e.target.value.toUpperCase().replace(/[^A-Z0-9-]/g, '') || null,
                                      })
                                    }
                                    placeholder="BLU"
                                    className="h-11 w-full rounded-xl border border-slate-200 px-4 text-sm focus:ring-2 focus:ring-primary/20"
                                  />
                                  <input
                                    type="number"
                                    value={value.stock_override ?? ''}
                                    onChange={(e) =>
                                      updateVariantValue(index, valueIndex, {
                                        stock_override: e.target.value === '' ? null : Math.max(0, parseInt(e.target.value, 10) || 0),
                                      })
                                    }
                                    placeholder="Base stock"
                                    className="h-11 w-full rounded-xl border border-slate-200 px-4 text-sm focus:ring-2 focus:ring-primary/20"
                                  />
                                  <button
                                    type="button"
                                    onClick={() =>
                                      setFormData((current) => ({
                                        ...current,
                                        variant_options: current.variant_options.map((currentVariant, currentVariantIndex) =>
                                          currentVariantIndex === index
                                            ? {
                                                ...currentVariant,
                                                values: currentVariant.values.filter((_, currentValueIndex) => currentValueIndex !== valueIndex),
                                              }
                                            : currentVariant,
                                        ),
                                      }))
                                    }
                                    className="inline-flex h-11 items-center justify-center rounded-xl border border-rose-200 px-3 text-rose-600 transition hover:bg-rose-50"
                                  >
                                    <Trash2 size={16} />
                                  </button>
                                </div>
                              ))}
                              <div className="hidden gap-3 text-[11px] font-bold uppercase tracking-wide text-gray-400 lg:grid lg:grid-cols-[1.1fr_0.75fr_0.75fr_0.85fr_auto]">
                                <span>Value label</span>
                                <span>Price adjust</span>
                                <span>SKU suffix</span>
                                <span>Stock override</span>
                                <span />
                              </div>
                              <button
                                type="button"
                                onClick={() =>
                                  setFormData((current) => ({
                                    ...current,
                                    variant_options: current.variant_options.map((currentVariant, currentVariantIndex) =>
                                      currentVariantIndex === index
                                        ? {
                                            ...currentVariant,
                                            values: [
                                              ...currentVariant.values,
                                              { label: '', price_adjustment: 0, sku_suffix: null, stock_override: null },
                                            ],
                                          }
                                        : currentVariant,
                                    ),
                                  }))
                                }
                                className="inline-flex h-10 items-center gap-2 rounded-xl border border-slate-200 bg-white px-3 text-xs font-bold text-slate-700 transition hover:bg-slate-50"
                              >
                                <Plus size={14} />
                                <span>Add value</span>
                              </button>
                              <div className="flex flex-wrap gap-2 pt-1">
                                {variant.values
                                  .filter((value) => String(value.label || '').trim())
                                  .map((value, valueIndex) => (
                                    <span
                                      key={`variant-preview-${index}-${valueIndex}`}
                                      className="rounded-full bg-slate-100 px-3 py-1 text-[11px] font-semibold text-slate-600"
                                    >
                                      {value.label}: {buildVariantSkuPreview(baseSkuPreview, value.sku_suffix)}
                                    </span>
                                  ))}
                              </div>
                            </div>
                          </div>
                          <button
                            type="button"
                            onClick={() =>
                              setFormData((current) => ({
                                ...current,
                                variant_options: current.variant_options.filter((_, variantIndex) => variantIndex !== index),
                              }))
                            }
                            className="inline-flex h-11 items-center justify-center rounded-xl border border-rose-200 bg-white px-3 text-rose-600 transition hover:bg-rose-50"
                          >
                            <Trash2 size={16} />
                          </button>
                        </div>
                      </div>
                    ))}
                  </div>
                )}
              </section>

            <div className="sticky bottom-4 z-10 flex flex-col gap-3 rounded-2xl border border-black/5 bg-white/95 p-3 shadow-lg backdrop-blur sm:flex-row sm:justify-end">
              <button
                type="button"
                onClick={() => navigate('/seller/products')}
                className="inline-flex h-12 items-center justify-center rounded-xl border border-slate-200 px-6 text-sm font-bold text-slate-700 transition hover:bg-slate-50"
              >
                Cancel
              </button>
              <button
                type="submit"
                disabled={loading}
                className="btn-primary inline-flex h-12 items-center justify-center gap-2 px-8 disabled:opacity-50"
              >
                {loading ? <Loader2 className="animate-spin" size={20} /> : <Save size={20} />}
                <span>{isEdit ? 'Update Product' : 'Publish Product'}</span>
              </button>
            </div>
          </div>
        </div>
      </form>
    </div>
  );
};

import React, { useEffect, useMemo, useState } from 'react';
import {
  Plus,
  Search,
  Edit,
  Trash2,
  ExternalLink,
  AlertCircle,
  Printer,
  Package,
  Boxes,
  Archive,
  AlertTriangle,
} from 'lucide-react';
import { Product } from '../../../types';
import { formatPrice } from '../../../lib/utils';
import OptimizedImage from '@/features/shared/ui/OptimizedImage';
import { Link, useNavigate } from '../../../lib/navigation';
import { useUser } from '../../../features/shared/state/UserContext';
import { TableSkeleton } from '@/features/shared/ui/DataSkeletons';
import { printSkuLabel, printSkuLabelSheet } from '../../../lib/skuLabel';
import toast from '@/lib/toast';
import { SellerEmptyState, SellerPageHeader, SellerStatCard } from '@/features/seller/components/SellerPageHeader';

type ProductTab = 'all' | 'active' | 'low_stock' | 'out_of_stock';

const getInventoryStatus = (stock: number): ProductTab => {
  if (stock <= 0) return 'out_of_stock';
  if (stock < 10) return 'low_stock';
  return 'active';
};

const renderInventoryLabel = (status: ProductTab) => {
  if (status === 'out_of_stock') return 'Out of stock';
  if (status === 'low_stock') return 'Low stock';
  return 'Active';
};

const renderInventoryTone = (status: ProductTab) => {
  if (status === 'out_of_stock') return 'bg-rose-100 text-rose-700';
  if (status === 'low_stock') return 'bg-amber-100 text-amber-700';
  return 'bg-green-100 text-green-800';
};

export const SellerProductsPage = () => {
  const [products, setProducts] = useState<Product[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState('');
  const [search, setSearch] = useState('');
  const [focusedProductId, setFocusedProductId] = useState('');
  const [deleteConfirmId, setDeleteConfirmId] = useState<number | null>(null);
  const [activeTab, setActiveTab] = useState<ProductTab | 'all'>('all');
  const { token, user } = useUser();
  const navigate = useNavigate();

  const fetchProducts = async () => {
    setLoading(true);
    setError('');
    try {
      const response = await fetch('/api/seller/products', {
        headers: { Authorization: `Bearer ${token}` },
      });
      const data = await response.json().catch(() => null);
      if (!response.ok) throw new Error(data?.error || 'Failed to fetch products');
      setProducts(Array.isArray(data) ? data : []);
    } catch (err: any) {
      setError(err.message);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    if (token) void fetchProducts();
  }, [token]);

  useEffect(() => {
    if (typeof window === 'undefined') return;

    const params = new URLSearchParams(window.location.search);
    const nextSearch = params.get('search');
    const nextProductId = params.get('product');

    if (nextSearch) {
      setSearch(nextSearch);
    }
    if (nextProductId) {
      setFocusedProductId(nextProductId);
    }
  }, []);

  const handleDelete = async (id: number) => {
    try {
      setError('');
      const response = await fetch(`/api/products/${id}`, {
        method: 'DELETE',
        headers: { Authorization: `Bearer ${token}` },
      });
      const data = await response.json().catch(() => null);
      if (!response.ok) throw new Error(data?.error || 'Failed to delete product');
      setDeleteConfirmId(null);
      setProducts((current) => current.filter((p) => p.id !== id));
      toast.success('Product deleted');
    } catch (err: any) {
      setError(err.message);
      toast.error(err instanceof Error ? err.message : 'Failed to delete product');
    }
  };

  const productMetrics = useMemo(() => {
    const active = products.filter((product) => getInventoryStatus(Number(product.stock || 0)) === 'active').length;
    const lowStock = products.filter((product) => getInventoryStatus(Number(product.stock || 0)) === 'low_stock').length;
    const outOfStock = products.filter((product) => getInventoryStatus(Number(product.stock || 0)) === 'out_of_stock').length;

    return {
      total: products.length,
      active,
      lowStock,
      outOfStock,
      drafts: products.filter((product) => product.product_status !== 'published').length,
    };
  }, [products]);

  const filteredProducts = useMemo(
    () =>
      products.filter((product) => {
        const inventoryStatus = getInventoryStatus(Number(product.stock || 0));
        const matchesTab = activeTab === 'all' ? true : inventoryStatus === activeTab;

        if (!matchesTab) return false;

        return (
          product.name.toLowerCase().includes(search.toLowerCase()) ||
          String(product.category || '').toLowerCase().includes(search.toLowerCase()) ||
          String(product.id).toLowerCase().includes(search.toLowerCase()) ||
          String(product.sku || '').toLowerCase().includes(search.toLowerCase())
        );
      }),
    [activeTab, products, search],
  );

  useEffect(() => {
    if (!focusedProductId) return;

    const matched = filteredProducts.find((product) => String(product.id) === focusedProductId);
    if (!matched) return;

    const timeoutId = window.setTimeout(() => {
      document.getElementById(`seller-product-${matched.id}`)?.scrollIntoView({
        behavior: 'smooth',
        block: 'center',
      });
    }, 120);

    return () => window.clearTimeout(timeoutId);
  }, [filteredProducts, focusedProductId]);

  const handlePrintSkuLabel = (product: Product) => {
    try {
      printSkuLabel(product);
    } catch (err) {
      toast.error(err instanceof Error ? err.message : 'Unable to print SKU label.');
    }
  };

  const handlePrintSkuLabelSheet = () => {
    try {
      printSkuLabelSheet(filteredProducts);
    } catch (err) {
      toast.error(err instanceof Error ? err.message : 'Unable to print SKU labels.');
    }
  };

  const productTabs = [
    { id: 'all', label: 'All products', count: productMetrics.total },
    { id: 'active', label: 'Active', count: productMetrics.active },
    { id: 'low_stock', label: 'Low stock', count: productMetrics.lowStock },
    { id: 'out_of_stock', label: 'Out of stock', count: productMetrics.outOfStock },
  ] as const;

  return (
    <div className="space-y-6">
      {error && (
        <div className="flex items-center space-x-2 rounded-xl bg-accent/10 p-4 text-accent">
          <AlertCircle size={20} />
          <p className="text-sm font-bold">{error}</p>
        </div>
      )}

      {user?.seller_status !== 'approved' ? (
        <div className="rounded-xl border border-amber-200 bg-amber-50 px-4 py-3 text-sm text-amber-800">
          Your account is still {String(user?.seller_status || 'draft').replaceAll('_', ' ')}. Products stay private as drafts until admin approval.
        </div>
      ) : null}

      <SellerPageHeader
        eyebrow="Inventory workspace"
        title="Seller Products"
        description="Manage your inventory, pricing, and product listings with SKU-ready actions and clearer stock visibility."
        actions={
          <>
            <Link
              to="/seller/products/bulk"
              className="inline-flex h-11 items-center space-x-2 rounded-xl border border-gray-200 px-4 text-sm font-medium transition-all hover:bg-gray-50"
            >
              <Archive size={16} />
              <span>Bulk Upload</span>
            </Link>
            <button
              onClick={handlePrintSkuLabelSheet}
              className="inline-flex h-11 items-center space-x-2 rounded-xl border border-gray-200 px-4 text-sm font-medium transition-all hover:bg-gray-50"
            >
              <Printer size={16} />
              <span>Print Labels</span>
            </button>
            <Link to="/seller/products/add" className="btn-primary inline-flex h-11 items-center space-x-2">
              <Plus size={18} />
              <span>Add Product</span>
            </Link>
          </>
        }
      />

      <div className="grid gap-4 sm:grid-cols-2 xl:grid-cols-4">
        <SellerStatCard label="All products" value={productMetrics.total} />
        <SellerStatCard label="Active" value={productMetrics.active} tone="success" />
        <SellerStatCard label="Low stock" value={productMetrics.lowStock} tone="warning" />
        <SellerStatCard label="Out of stock" value={productMetrics.outOfStock} tone="critical" />
        <SellerStatCard label="Draft only" value={productMetrics.drafts} tone="warning" />
      </div>

      <div className="sticky top-[5.5rem] z-10 space-y-4 rounded-[1.75rem] border border-black/5 bg-white/95 p-4 shadow-sm backdrop-blur md:p-5">
        <div className="dashboard-chip-scroll -mx-1 flex gap-2 overflow-x-auto px-1">
          {productTabs.map((tab) => (
            <button
              key={tab.id}
              type="button"
              onClick={() => setActiveTab(tab.id)}
              className={`inline-flex shrink-0 items-center gap-2 rounded-full px-4 py-2 text-sm font-semibold transition ${
                activeTab === tab.id
                  ? 'bg-slate-950 text-white shadow-sm'
                  : 'border border-slate-200 bg-white text-slate-600 hover:border-primary/20 hover:text-primary'
              }`}
            >
              <span>{tab.label}</span>
              <span
                className={`inline-flex min-w-[1.5rem] items-center justify-center rounded-full px-2 py-0.5 text-[11px] font-bold ${
                  activeTab === tab.id ? 'bg-white/15 text-white' : 'bg-slate-100 text-slate-500'
                }`}
              >
                {tab.count}
              </span>
            </button>
          ))}
        </div>

        <div className="flex flex-col gap-3 lg:flex-row lg:items-center lg:justify-between">
          <div className="relative flex-1 lg:max-w-xl">
            <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-gray-400" size={18} />
            <input
              type="text"
              placeholder="Search by name, category, id, or SKU"
              value={search}
              onChange={(e) => setSearch(e.target.value)}
              className="h-11 w-full rounded-xl border border-gray-200 bg-white pl-10 pr-4 text-sm focus:ring-2 focus:ring-primary"
            />
          </div>
          <div className="flex flex-wrap items-center gap-2">
            <Link
              to="/seller/inventory"
              className="inline-flex h-11 items-center rounded-xl border border-slate-200 bg-white px-4 text-xs font-semibold text-slate-600 transition hover:border-primary/20 hover:text-primary"
            >
              Stock Control
            </Link>
            <div className="rounded-xl bg-slate-50 px-4 py-3 text-xs font-semibold text-slate-500">
              {filteredProducts.length} of {products.length} products visible
            </div>
          </div>
        </div>
      </div>

      <div className="overflow-hidden rounded-[1.75rem] border border-black/5 bg-white shadow-sm">
        {loading ? (
          <div className="p-4">
            <TableSkeleton rows={5} columns={6} />
          </div>
        ) : (
          <>
            <div className="space-y-3 p-4 md:hidden">
              {filteredProducts.length === 0 ? (
                <SellerEmptyState
                  message="No products found for this filter. Try a different search or add your first product."
                  action={
                    <Link to="/seller/products/add" className="inline-flex rounded-xl bg-slate-950 px-4 py-2 text-xs font-semibold text-white">
                      Add product
                    </Link>
                  }
                />
              ) : (
                filteredProducts.map((product) => {
                  const inventoryStatus = getInventoryStatus(Number(product.stock || 0));
                  return (
                    <div
                      id={`seller-product-${product.id}`}
                      key={product.id}
                      className={`rounded-2xl border p-4 shadow-sm ${
                        String(product.id) === focusedProductId
                          ? 'border-indigo-300 ring-2 ring-indigo-200 bg-indigo-50/30'
                          : 'border-slate-200 bg-white'
                      }`}
                    >
                      <div className="flex items-start gap-3">
                        <OptimizedImage
                          src={product.image}
                          alt={product.name}
                          widthHint={112}
                          heightHint={112}
                          className="h-14 w-14 rounded-xl object-cover bg-gray-100"
                        />
                        <div className="min-w-0 flex-1">
                          <p className="font-bold text-gray-900">{product.name}</p>
                          <p className="mt-1 text-xs text-gray-500">SKU: {product.sku || 'Auto-generated on save'}</p>
                          <p className="mt-1 text-xs text-gray-500">{product.category}</p>
                          {Array.isArray(product.variant_options) && product.variant_options.length > 0 ? (
                            <p className="mt-1 text-xs font-medium text-slate-500">
                              {product.variant_options.length} variant group{product.variant_options.length === 1 ? '' : 's'}
                            </p>
                          ) : null}
                        </div>
                      </div>
                      <div className="mt-3 grid grid-cols-1 gap-3 rounded-2xl bg-slate-50 p-3 text-sm sm:grid-cols-3">
                        <div>
                          <p className="text-xs text-gray-500">Price</p>
                          <p className="font-bold text-primary">{formatPrice(product.price)}</p>
                        </div>
                        <div>
                          <p className="text-xs text-gray-500">Stock</p>
                          <p className={`font-bold ${product.stock < 10 ? 'text-accent' : 'text-gray-900'}`}>{product.stock}</p>
                        </div>
                        <div>
                          <p className="text-xs text-gray-500">Status</p>
                          <span
                            className={`inline-flex items-center rounded-full px-2.5 py-0.5 text-xs font-bold ${renderInventoryTone(
                              inventoryStatus,
                            )}`}
                          >
                            {renderInventoryLabel(inventoryStatus)}
                          </span>
                        </div>
                      </div>
                      {deleteConfirmId === product.id ? (
                        <div className="mt-3 flex flex-wrap items-center gap-2">
                          <span className="text-xs font-medium text-rose-700">Delete this product?</span>
                          <button
                            onClick={() => handleDelete(product.id)}
                            className="rounded-lg bg-rose-600 px-3 py-1.5 text-xs font-semibold text-white transition hover:bg-rose-700"
                          >
                            Confirm
                          </button>
                          <button
                            onClick={() => setDeleteConfirmId(null)}
                            className="rounded-lg border border-slate-200 px-3 py-1.5 text-xs font-semibold text-slate-600 transition hover:bg-slate-50"
                          >
                            Cancel
                          </button>
                        </div>
                      ) : (
                        <div className="mt-3 grid grid-cols-2 gap-2 sm:grid-cols-4">
                          <Link
                            to={`/product/${product.slug}`}
                            target="_blank"
                            className="inline-flex items-center justify-center rounded-xl border border-gray-200 p-3 text-gray-500 transition hover:text-primary"
                          >
                            <ExternalLink size={16} />
                          </Link>
                          <button
                            onClick={() => handlePrintSkuLabel(product)}
                            className="inline-flex items-center justify-center rounded-xl border border-gray-200 p-3 text-gray-500 transition hover:text-emerald-600"
                            title="Print SKU label"
                          >
                            <Printer size={16} />
                          </button>
                          <button
                            onClick={() => navigate(`/seller/products/edit/${product.id}`)}
                            className="inline-flex items-center justify-center rounded-xl border border-gray-200 p-3 text-gray-500 transition hover:text-blue-500"
                            title="Edit product"
                          >
                            <Edit size={16} />
                          </button>
                          <button
                            onClick={() => setDeleteConfirmId(product.id)}
                            className="inline-flex items-center justify-center rounded-xl border border-gray-200 p-3 text-gray-500 transition hover:text-accent"
                            title="Delete product"
                          >
                            <Trash2 size={16} />
                          </button>
                        </div>
                      )}
                    </div>
                  );
                })
              )}
            </div>

            <div className="hidden overflow-x-auto md:block">
              <table className="w-full border-collapse text-left">
                <thead>
                  <tr className="bg-gray-50 text-xs font-bold uppercase tracking-wider text-gray-500">
                    <th className="px-6 py-4">Product</th>
                    <th className="px-6 py-4">Category</th>
                    <th className="px-6 py-4">Price</th>
                    <th className="px-6 py-4">Stock</th>
                    <th className="px-6 py-4">Status</th>
                    <th className="px-6 py-4 text-right">Actions</th>
                  </tr>
                </thead>
                <tbody className="divide-y divide-gray-100">
                  {filteredProducts.length === 0 ? (
                    <tr>
                      <td colSpan={6} className="px-6 py-12 text-center text-gray-500">
                        <div className="flex justify-center">
                          <div className="w-full max-w-md">
                            <SellerEmptyState
                              message="No products found for this filter. Try a different search or add your first product."
                              action={
                                <Link to="/seller/products/add" className="inline-flex rounded-xl bg-slate-950 px-4 py-2 text-xs font-semibold text-white">
                                  Add product
                                </Link>
                              }
                            />
                          </div>
                        </div>
                      </td>
                    </tr>
                  ) : (
                    filteredProducts.map((product) => {
                      const inventoryStatus = getInventoryStatus(Number(product.stock || 0));
                      return (
                        <tr
                          id={`seller-product-${product.id}`}
                          key={product.id}
                          className={`group transition-colors ${
                            String(product.id) === focusedProductId
                              ? 'bg-indigo-50 ring-2 ring-inset ring-indigo-200'
                              : 'hover:bg-gray-50'
                          }`}
                        >
                          <td className="px-6 py-4">
                            <div className="flex items-center space-x-3">
                              <OptimizedImage
                                src={product.image}
                                alt={product.name}
                                widthHint={96}
                                heightHint={96}
                                className="h-12 w-12 rounded-lg object-cover bg-gray-100"
                              />
                              <div className="min-w-0">
                                <p className="max-w-[220px] truncate text-sm font-bold text-gray-900">{product.name}</p>
                                <p className="text-xs text-gray-500">SKU: {product.sku || 'Auto-generated on save'}</p>
                                {Array.isArray(product.variant_options) && product.variant_options.length > 0 ? (
                                  <p className="text-[11px] text-slate-500">
                                    {product.variant_options.length} variant group{product.variant_options.length === 1 ? '' : 's'}
                                  </p>
                                ) : null}
                              </div>
                            </div>
                          </td>
                          <td className="px-6 py-4 text-sm text-gray-600">{product.category}</td>
                          <td className="px-6 py-4 text-sm font-bold text-primary">{formatPrice(product.price)}</td>
                          <td className="px-6 py-4">
                            <div className="flex flex-col">
                              <span className={`text-sm font-bold ${product.stock < 10 ? 'text-accent' : 'text-gray-900'}`}>{product.stock}</span>
                              <div className="mt-1 h-1.5 w-16 overflow-hidden rounded-full bg-gray-100">
                                <div
                                  className={`h-full rounded-full ${product.stock < 10 ? 'bg-accent' : 'bg-primary'}`}
                                  style={{ width: `${Math.min(100, (Number(product.stock || 0) / 50) * 100)}%` }}
                                />
                              </div>
                            </div>
                          </td>
                          <td className="px-6 py-4">
                            <span className={`inline-flex items-center rounded-full px-2.5 py-0.5 text-xs font-bold ${renderInventoryTone(inventoryStatus)}`}>
                              {renderInventoryLabel(inventoryStatus)}
                            </span>
                          </td>
                          <td className="px-6 py-4 text-right">
                            {deleteConfirmId === product.id ? (
                              <div className="flex items-center justify-end gap-2">
                                <span className="text-xs font-medium text-rose-700">Delete this product?</span>
                                <button
                                  onClick={() => handleDelete(product.id)}
                                  className="rounded-lg bg-rose-600 px-3 py-1.5 text-xs font-semibold text-white transition hover:bg-rose-700"
                                >
                                  Confirm
                                </button>
                                <button
                                  onClick={() => setDeleteConfirmId(null)}
                                  className="rounded-lg border border-slate-200 px-3 py-1.5 text-xs font-semibold text-slate-600 transition hover:bg-slate-50"
                                >
                                  Cancel
                                </button>
                              </div>
                            ) : (
                              <div className="flex items-center justify-end space-x-2 opacity-0 transition-opacity group-hover:opacity-100">
                                <Link to={`/product/${product.slug}`} target="_blank" className="p-2 text-gray-400 transition-colors hover:text-primary">
                                  <ExternalLink size={18} />
                                </Link>
                                <button
                                  onClick={() => handlePrintSkuLabel(product)}
                                  className="p-2 text-gray-400 transition-colors hover:text-emerald-600"
                                  title="Print SKU label"
                                >
                                  <Printer size={18} />
                                </button>
                                <button
                                  onClick={() => navigate(`/seller/products/edit/${product.id}`)}
                                  className="p-2 text-gray-400 transition-colors hover:text-blue-500"
                                  title="Edit product"
                                >
                                  <Edit size={18} />
                                </button>
                                <button
                                  onClick={() => setDeleteConfirmId(product.id)}
                                  className="p-2 text-gray-400 transition-colors hover:text-accent"
                                  title="Delete product"
                                >
                                  <Trash2 size={18} />
                                </button>
                              </div>
                            )}
                          </td>
                        </tr>
                      );
                    })
                  )}
                </tbody>
              </table>
            </div>
          </>
        )}

        <div className="flex items-center justify-between border-t border-gray-100 p-4">
          <p className="text-xs text-gray-500">
            Showing {filteredProducts.length} of {products.length} products
          </p>
          <div className="flex space-x-2">
            <button disabled className="rounded-lg border border-gray-200 px-3 py-1 text-xs font-bold disabled:opacity-50">
              Previous
            </button>
            <button disabled className="rounded-lg border border-gray-200 px-3 py-1 text-xs font-bold disabled:opacity-50">
              Next
            </button>
          </div>
        </div>
      </div>
    </div>
  );
};

import React, { useEffect, useMemo, useState } from 'react';
import { Loader2, RotateCcw, ShieldAlert } from 'lucide-react';
import { Link } from '../../../lib/navigation';
import { SellerEmptyState, SellerPageHeader, SellerStatCard } from '@/features/seller/components/SellerPageHeader';
import { useUser } from '../../../features/shared/state/UserContext';
import { formatPrice } from '../../../lib/utils';

const RETURN_STATUSES = ['returned', 'cancelled', 'delivery_failed', 'return_in_transit'];

export const SellerReturnsPage = () => {
  const { token } = useUser();
  const [orders, setOrders] = useState<any[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState('');

  useEffect(() => {
    if (!token) {
      setLoading(false);
      return;
    }

    let mounted = true;
    setLoading(true);
    setError('');

    fetch('/api/seller/orders', {
      headers: { Authorization: `Bearer ${token}` },
    })
      .then(async (response) => {
        const payload = await response.json().catch(() => null);
        if (!response.ok) throw new Error(payload?.error || 'Failed to load return orders');
        if (!mounted) return;
        setOrders(Array.isArray(payload) ? payload : []);
      })
      .catch((requestError: unknown) => {
        if (!mounted) return;
        setOrders([]);
        setError(requestError instanceof Error ? requestError.message : 'Failed to load returns.');
      })
      .finally(() => {
        if (mounted) setLoading(false);
      });

    return () => {
      mounted = false;
    };
  }, [token]);

  const returnOrders = useMemo(
    () =>
      orders.filter((order) => {
        const orderStatus = String(order.status || '').toLowerCase();
        if (RETURN_STATUSES.includes(orderStatus)) return true;
        return Array.isArray(order.shipments)
          ? order.shipments.some((shipment: any) => RETURN_STATUSES.includes(String(shipment?.status || '').toLowerCase()))
          : false;
      }),
    [orders],
  );

  if (loading) {
    return (
      <div className="flex h-64 items-center justify-center">
        <Loader2 className="animate-spin text-primary" size={32} />
      </div>
    );
  }

  return (
    <div className="space-y-6">
      {error ? <div className="rounded-2xl border border-rose-200 bg-rose-50 px-4 py-3 text-sm text-rose-700">{error}</div> : null}

      <SellerPageHeader
        eyebrow="Post-delivery exceptions"
        title="Returns"
        description="Track returned, cancelled, and failed-delivery orders that need seller attention or stock reconciliation."
      />

      <div className="grid gap-4 md:grid-cols-2">
        <SellerStatCard label="Exception orders" value={returnOrders.length} />
        <SellerStatCard label="All seller orders" value={orders.length} />
      </div>

      <section className="rounded-[2rem] border border-black/5 bg-white p-6 shadow-sm">
        <div className="flex items-center gap-3">
          <RotateCcw size={18} className="text-rose-500" />
          <h2 className="text-lg font-bold text-slate-950">Return queue</h2>
        </div>
        <div className="mt-5 space-y-3">
          {returnOrders.length === 0 ? (
            <SellerEmptyState message="No return or failed-delivery cases are open right now." />
          ) : (
            returnOrders.map((order) => (
              <div key={order.id} className="rounded-2xl border border-slate-200 px-4 py-4">
                <div className="flex flex-col gap-4 sm:flex-row sm:items-start sm:justify-between">
                  <div>
                    <div className="flex items-center gap-2">
                      <p className="font-semibold text-slate-900">#{order.order_code || order.id}</p>
                      <span className="rounded-full bg-rose-50 px-3 py-1 text-xs font-bold text-rose-700">{String(order.status || 'exception')}</span>
                    </div>
                    <p className="mt-2 text-sm text-slate-600">
                      {Array.isArray(order.items) && order.items.length > 0 ? order.items.map((item: any) => item.name || item.sku || 'Item').join(', ') : 'Order items unavailable'}
                    </p>
                    <p className="mt-2 text-xs text-slate-500">{order.created_at ? new Date(order.created_at).toLocaleString() : 'No timestamp'} â€¢ {formatPrice(Number(order.total || 0))}</p>
                  </div>
                  <div className="flex items-center gap-3">
                    <ShieldAlert size={16} className="text-amber-500" />
                    <Link to={`/seller/orders?search=${encodeURIComponent(String(order.order_code || order.id))}`} className="text-sm font-semibold text-primary">
                      Open order
                    </Link>
                  </div>
                </div>
              </div>
            ))
          )}
        </div>
      </section>
    </div>
  );
};

export default SellerReturnsPage;

import React, { useEffect, useMemo, useState } from 'react';
import { Bell, Loader2, MessageSquareWarning } from 'lucide-react';
import { Link } from '../../../lib/navigation';
import { SellerEmptyState, SellerPageHeader, SellerStatCard } from '@/features/seller/components/SellerPageHeader';
import { useUser } from '../../../features/shared/state/UserContext';

type UserNotification = {
  id: string;
  title: string;
  message: string;
  read_at?: string | null;
  created_at?: string;
};

export const SellerSupportTicketsPage = () => {
  const { token } = useUser();
  const [notifications, setNotifications] = useState<UserNotification[]>([]);
  const [orders, setOrders] = useState<any[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState('');

  useEffect(() => {
    if (!token) {
      setLoading(false);
      return;
    }

    let mounted = true;
    setLoading(true);
    setError('');

    Promise.all([
      fetch('/api/notifications', { headers: { Authorization: `Bearer ${token}` } }),
      fetch('/api/seller/orders', { headers: { Authorization: `Bearer ${token}` } }),
    ])
      .then(async ([notificationsRes, ordersRes]) => {
        const notificationsPayload = await notificationsRes.json().catch(() => null);
        const ordersPayload = await ordersRes.json().catch(() => null);
        if (!notificationsRes.ok) throw new Error(notificationsPayload?.error || 'Failed to load notifications');
        if (!ordersRes.ok) throw new Error(ordersPayload?.error || 'Failed to load seller orders');
        if (!mounted) return;
        setNotifications(Array.isArray(notificationsPayload) ? notificationsPayload : []);
        setOrders(Array.isArray(ordersPayload) ? ordersPayload : []);
      })
      .catch((requestError: unknown) => {
        if (!mounted) return;
        setNotifications([]);
        setOrders([]);
        setError(requestError instanceof Error ? requestError.message : 'Failed to load support operations.');
      })
      .finally(() => {
        if (mounted) setLoading(false);
      });

    return () => {
      mounted = false;
    };
  }, [token]);

  const unreadNotifications = useMemo(() => notifications.filter((notification) => !notification.read_at), [notifications]);
  const issueOrders = useMemo(
    () => orders.filter((order) => ['cancelled', 'returned', 'delivery_failed'].includes(String(order.status || '').toLowerCase())),
    [orders],
  );

  if (loading) {
    return (
      <div className="flex h-64 items-center justify-center">
        <Loader2 className="animate-spin text-primary" size={32} />
      </div>
    );
  }

  return (
    <div className="space-y-6">
      {error ? <div className="rounded-2xl border border-rose-200 bg-rose-50 px-4 py-3 text-sm text-rose-700">{error}</div> : null}

      <SellerPageHeader
        eyebrow="Seller inbox"
        title="Support Tickets"
        description="Review customer-impacting alerts, unread notifications, and issue orders that may require support follow-up."
      />

      <div className="grid gap-4 md:grid-cols-2">
        <SellerStatCard label="Unread alerts" value={unreadNotifications.length} />
        <SellerStatCard label="Issue orders" value={issueOrders.length} />
      </div>

      <div className="grid gap-6 xl:grid-cols-[0.95fr_1.05fr]">
        <section className="rounded-[2rem] border border-black/5 bg-white p-6 shadow-sm">
          <div className="flex items-center gap-3">
            <Bell size={18} className="text-primary" />
            <h2 className="text-lg font-bold text-slate-950">Unread notifications</h2>
          </div>
          <div className="mt-5 space-y-3">
            {unreadNotifications.length === 0 ? (
              <SellerEmptyState message="No unread seller notifications right now." />
            ) : (
              unreadNotifications.slice(0, 12).map((notification) => (
                <div key={notification.id} className="rounded-2xl border border-slate-200 px-4 py-4">
                  <p className="font-semibold text-slate-900">{notification.title}</p>
                  <p className="mt-2 text-sm text-slate-600">{notification.message}</p>
                  <p className="mt-2 text-xs text-slate-500">{notification.created_at ? new Date(notification.created_at).toLocaleString() : 'No timestamp'}</p>
                </div>
              ))
            )}
          </div>
        </section>

        <section className="rounded-[2rem] border border-black/5 bg-white p-6 shadow-sm">
          <div className="flex items-center gap-3">
            <MessageSquareWarning size={18} className="text-amber-500" />
            <h2 className="text-lg font-bold text-slate-950">Orders needing follow-up</h2>
          </div>
          <div className="mt-5 space-y-3">
            {issueOrders.length === 0 ? (
              <SellerEmptyState message="No cancelled, returned, or failed-delivery orders need support follow-up right now." />
            ) : (
              issueOrders.slice(0, 12).map((order) => (
                <div key={order.id} className="rounded-2xl border border-slate-200 px-4 py-4">
                  <div className="flex items-center justify-between gap-4">
                    <div>
                      <p className="font-semibold text-slate-900">#{order.order_code || order.id}</p>
                      <p className="mt-1 text-xs text-slate-500">{String(order.status || '').replaceAll('_', ' ')}</p>
                    </div>
                    <Link to={`/seller/orders?search=${encodeURIComponent(String(order.order_code || order.id))}`} className="text-sm font-semibold text-primary">
                      Open
                    </Link>
                  </div>
                </div>
              ))
            )}
          </div>
        </section>
      </div>
    </div>
  );
};

export default SellerSupportTicketsPage;

import React, { ReactNode } from 'react';
import { motion } from 'framer-motion';

interface LoadingAnimationProps {
  size?: 'small' | 'medium' | 'large';
  type?: 'spinner' | 'dots' | 'pulse' | 'bars';
  color?: string;
}

const loadingVariants = {
  spinner: {
    rotate: 360,
    transition: {
      repeat: Infinity,
      duration: 1,
      ease: 'linear',
    },
  },
  dots: [
    { opacity: 0.3, y: 0 },
    { opacity: 1, y: -10 },
    { opacity: 0.3, y: 0 },
  ],
  bars: [
    { scaleY: 0.5 },
    { scaleY: 1 },
    { scaleY: 0.5 },
  ],
};

const sizeMap = {
  small: 'w-6 h-6',
  medium: 'w-10 h-10',
  large: 'w-16 h-16',
};

export const LoadingAnimation: React.FC<LoadingAnimationProps> = ({
  size = 'medium',
  type = 'spinner',
  color = 'text-blue-600',
}) => {
  if (type === 'spinner') {
    return (
      <motion.div
        className={`${sizeMap[size]} border-4 border-gray-200 border-t-blue-600 rounded-full ${color}`}
        animate={{ rotate: 360 }}
        transition={{
          repeat: Infinity,
          duration: 1,
          ease: 'linear',
        }}
      />
    );
  }

  if (type === 'dots') {
    return (
      <div className="flex gap-2">
        {[0, 1, 2].map((i) => (
          <motion.div
            key={i}
            className={`w-2 h-2 rounded-full bg-blue-600`}
            animate={{ y: [0, -8, 0] }}
            transition={{
              repeat: Infinity,
              duration: 0.8,
              delay: i * 0.1,
            }}
          />
        ))}
      </div>
    );
  }

  if (type === 'bars') {
    return (
      <div className="flex gap-1 items-center">
        {[0, 1, 2, 3, 4].map((i) => (
          <motion.div
            key={i}
            className="w-1 bg-blue-600 rounded-full"
            style={{ height: '24px' }}
            animate={{ scaleY: [0.5, 1, 0.5] }}
            transition={{
              repeat: Infinity,
              duration: 0.8,
              delay: i * 0.1,
            }}
          />
        ))}
      </div>
    );
  }

  // Pulse type
  return (
    <motion.div
      className={`${sizeMap[size]} rounded-full bg-blue-600`}
      animate={{ scale: [1, 1.1, 1], opacity: [1, 0.7, 1] }}
      transition={{
        repeat: Infinity,
        duration: 2,
        ease: 'easeInOut',
      }}
    />
  );
};

export default LoadingAnimation;

import React from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { X, CheckCircle, AlertCircle, Info } from 'lucide-react';

export type NotificationType = 'success' | 'error' | 'info' | 'warning';

export interface Notification {
  id: string;
  message: string;
  type: NotificationType;
  duration?: number;
  action?: {
    label: string;
    onClick: () => void;
  };
}

interface NotificationItemProps {
  notification: Notification;
  onClose: (id: string) => void;
}

const NotificationItem: React.FC<NotificationItemProps> = ({ notification, onClose }) => {
  const iconMap = {
    success: <CheckCircle className="w-5 h-5 text-green-600" />,
    error: <AlertCircle className="w-5 h-5 text-red-600" />,
    info: <Info className="w-5 h-5 text-blue-600" />,
    warning: <AlertCircle className="w-5 h-5 text-yellow-600" />,
  };

  const bgColorMap = {
    success: 'bg-green-50 border-green-200',
    error: 'bg-red-50 border-red-200',
    info: 'bg-blue-50 border-blue-200',
    warning: 'bg-yellow-50 border-yellow-200',
  };

  const textColorMap = {
    success: 'text-green-800',
    error: 'text-red-800',
    info: 'text-blue-800',
    warning: 'text-yellow-800',
  };

  React.useEffect(() => {
    if (notification.duration) {
      const timer = setTimeout(() => onClose(notification.id), notification.duration);
      return () => clearTimeout(timer);
    }
  }, [notification, onClose]);

  return (
    <motion.div
      initial={{ opacity: 0, y: -20, x: 400 }}
      animate={{ opacity: 1, y: 0, x: 0 }}
      exit={{ opacity: 0, y: -20, x: 400 }}
      transition={{ duration: 0.3 }}
      className={`flex items-center gap-3 px-4 py-3 rounded-lg border ${bgColorMap[notification.type]} shadow-md`}
    >
      {iconMap[notification.type]}
      <span className={`flex-1 ${textColorMap[notification.type]}`}>
        {notification.message}
      </span>
      {notification.action && (
        <button
          onClick={notification.action.onClick}
          className={`text-sm font-medium ${textColorMap[notification.type]} hover:opacity-70`}
        >
          {notification.action.label}
        </button>
      )}
      <button
        onClick={() => onClose(notification.id)}
        className={`${textColorMap[notification.type]} hover:opacity-70`}
      >
        <X className="w-4 h-4" />
      </button>
    </motion.div>
  );
};

interface NotificationContainerProps {
  notifications: Notification[];
  onClose: (id: string) => void;
}

export const NotificationContainer: React.FC<NotificationContainerProps> = ({
  notifications,
  onClose,
}) => {
  return (
    <div className="fixed top-6 right-6 z-50 flex flex-col gap-2 max-w-md">
      <AnimatePresence mode="popLayout">
        {notifications.map((notification) => (
          <NotificationItem
            key={notification.id}
            notification={notification}
            onClose={onClose}
          />
        ))}
      </AnimatePresence>
    </div>
  );
};

// Hook for managing notifications
export const useNotification = () => {
  const [notifications, setNotifications] = React.useState<Notification[]>([]);

  const addNotification = React.useCallback(
    (
      message: string,
      type: NotificationType = 'info',
      duration: number = 3000,
      action?: Notification['action']
    ) => {
      const id = `notification-${Date.now()}`;
      const notification: Notification = {
        id,
        message,
        type,
        duration,
        action,
      };

      setNotifications((prev) => [...prev, notification]);
      return id;
    },
    []
  );

  const removeNotification = React.useCallback((id: string) => {
    setNotifications((prev) => prev.filter((n) => n.id !== id));
  }, []);

  const success = (message: string, duration?: number) =>
    addNotification(message, 'success', duration);
  const error = (message: string, duration?: number) =>
    addNotification(message, 'error', duration);
  const info = (message: string, duration?: number) =>
    addNotification(message, 'info', duration);
  const warning = (message: string, duration?: number) =>
    addNotification(message, 'warning', duration);

  return {
    notifications,
    addNotification,
    removeNotification,
    success,
    error,
    info,
    warning,
  };
};

export default NotificationContainer;

import React, { ReactNode } from 'react';
import { motion } from 'framer-motion';
import { useInView } from 'react-intersection-observer';

type AnimationType = 'fadeUp' | 'fadeLeft' | 'fadeRight' | 'zoom' | 'parallax' | 'rotate';

interface ScrollAnimationProps {
  children: ReactNode;
  animation?: AnimationType;
  threshold?: number;
  delay?: number;
  duration?: number;
  speed?: number;
  className?: string;
}

const scrollVariants = {
  fadeUp: {
    hidden: { opacity: 0, y: 50 },
    visible: (custom: number) => ({
      opacity: 1,
      y: 0,
      transition: { delay: custom * 0.1, duration: 0.6 },
    }),
  },
  fadeLeft: {
    hidden: { opacity: 0, x: -50 },
    visible: (custom: number) => ({
      opacity: 1,
      x: 0,
      transition: { delay: custom * 0.1, duration: 0.6 },
    }),
  },
  fadeRight: {
    hidden: { opacity: 0, x: 50 },
    visible: (custom: number) => ({
      opacity: 1,
      x: 0,
      transition: { delay: custom * 0.1, duration: 0.6 },
    }),
  },
  zoom: {
    hidden: { opacity: 0, scale: 0.8 },
    visible: (custom: number) => ({
      opacity: 1,
      scale: 1,
      transition: { delay: custom * 0.1, duration: 0.6 },
    }),
  },
  parallax: {
    hidden: { opacity: 0, y: 100 },
    visible: { opacity: 1, y: 0 },
  },
  rotate: {
    hidden: { opacity: 0, rotate: -10 },
    visible: (custom: number) => ({
      opacity: 1,
      rotate: 0,
      transition: { delay: custom * 0.1, duration: 0.7 },
    }),
  },
};

export const ScrollAnimation: React.FC<ScrollAnimationProps> = ({
  children,
  animation = 'fadeUp',
  threshold = 0.1,
  delay = 0,
  duration = 0.6,
  speed = 1,
  className = '',
}) => {
  const { ref, inView } = useInView({
    threshold,
    triggerOnce: true,
  });

  const variants = scrollVariants[animation] || scrollVariants.fadeUp;

  return (
    <motion.div
      ref={ref}
      initial="hidden"
      animate={inView ? 'visible' : 'hidden'}
      variants={variants}
      custom={delay}
      className={className}
    >
      {children}
    </motion.div>
  );
};

export default ScrollAnimation;

