const layoutPrefsKey = 'amarshop_dashboard_sidebar_collapsed';
const sectionPrefsPrefix = 'amarshop_dashboard_sections';

type BadgeMap = Record<string, number>;

const roleAccentMap: Record<
  DashboardLayoutProps['type'],
  {
    chip: string;
    glow: string;
    soft: string;
    dot: string;
  }
