    dot: 'bg-sky-500',
  },
  seller: {
    chip: 'from-emerald-600 to-green-500',
    glow: 'shadow-[0_18px_38px_-24px_rgba(34,197,94,0.55)]',
    soft: 'bg-emerald-50 text-emerald-700',
    dot: 'bg-emerald-500',
  },
  admin: {
