        items: [
          { icon: <ShoppingBag size={20} />, label: 'My Orders', path: '/account/orders' },
          { icon: <Heart size={20} />, label: 'Wishlist', path: '/account/wishlist' },
        ],
      },
      {
        title: 'Wallet & Rewards',
        items: [
          { icon: <Wallet size={20} />, label: 'My Wallet', path: '/account/wallet' },
        ],
      },
      {
        title: 'Discover',
        items: [
        ],
