                    </button>
                  </div>
                  {couponStatus ? (
                    <p
                      className={cn(
                        'mt-2 text-sm font-medium',
                        couponStatusTone === 'success' && 'text-emerald-600',
                        couponStatusTone === 'error' && 'text-red-600',
                        couponStatusTone === 'info' && 'text-slate-500',
                      )}
                    >
                      {couponStatus}
                    </p>
                  ) : null}
                  {appliedCoupon ? (
                    <div className="mt-3 flex flex-wrap items-center justify-between gap-2 rounded-xl bg-emerald-50 px-4 py-3 text-sm text-emerald-700">
                      <span className="font-semibold">{appliedCoupon.code} applied</span>
                      <button type="button" onClick={handleRemoveCoupon} className="font-semibold text-emerald-800 underline-offset-4 hover:underline">
                        Remove
                      </button>
                    </div>
                  ) : null}
                </div>

                <div className="mt-6 space-y-3 border-t border-slate-100 pt-4">
                  <div className="flex justify-between text-sm text-slate-600">
                    <span>Subtotal</span>
                    <span className="font-medium text-slate-900">{formatPrice(subtotal)}</span>
                  </div>
                  {appliedCoupon && (
                    <div className="flex justify-between text-sm font-medium text-emerald-600">
                      <span>Discount ({appliedCoupon.code})</span>
                      <span>-{formatPrice(discountAmount)}</span>
                    </div>
                  )}
                  <div className="flex justify-between text-sm text-slate-600">
                    <span>Delivery Fee</span>
                    <span className="font-medium text-primary">
                      {shippingPreview
                        ? shippingPreview.qualifies_for_free_shipping
                          ? 'Free'
                          : formatPrice(shippingPreview.estimated_fee_payable)
                        : 'Add city'}
                    </span>
                  </div>
                  <div className="flex justify-between text-sm text-slate-600">
                    <span>Platform fee:</span>
                    <span className="font-semibold text-slate-900">{formatPrice(CHECKOUT_PLATFORM_FEE)}</span>
                  </div>

                  <div className="flex justify-between pt-4 text-slate-950">
                    <span className="text-lg font-bold">Total</span>
                    <span className="text-2xl font-bold text-primary">{formatPrice(checkoutTotal)}</span>
                  </div>
                  {shippingPreview && !shippingPreview.qualifies_for_free_shipping ? (
                    <p className="text-xs leading-5 text-slate-500">
                      Delivery fee is included in the checkout total.
                    </p>
                  ) : null}
                </div>

                <button
                  type="submit"
                  disabled={loading}
                  className="mt-6 inline-flex w-full items-center justify-center gap-2 rounded-2xl bg-slate-950 px-5 py-4 text-sm font-semibold text-white transition hover:bg-slate-800 disabled:cursor-not-allowed disabled:opacity-60"
                >
                  {loading ? (
                    <>
                      <Loader2 className="animate-spin" size={18} />
                      <span>Placing order...</span>
                    </>
                  ) : (
                    <>
                      <span>Place order</span>
                      <ArrowRight size={18} />
                    </>
                  )}
                </button>

                <div className="mt-4 rounded-2xl border border-slate-200 bg-slate-50 p-4">
                  <div className="flex items-start gap-3">
                    <ShieldCheck size={18} className="mt-0.5 shrink-0 text-primary" />
                    <div className="text-sm text-slate-600">
                      <p className="font-semibold text-slate-900">Secure checkout guaranteed</p>
                      <p className="mt-1 leading-6">Your order data, payment selection, and delivery details stay protected through confirmation.</p>
                    </div>
                  </div>
                </div>

                {(formData.paymentMethod === 'gateway' || formData.paymentMethod === 'bkash') && (
                  <div className="mt-4 rounded-2xl border border-amber-200 bg-amber-50 p-4">
                    <div className="flex items-start gap-3">
                      <AlertCircle size={18} className="mt-0.5 shrink-0 text-amber-600" />
                      <div className="text-sm text-amber-800">
                        <p className="font-semibold">Payment recovery tip</p>
                        <p className="mt-1 leading-6">
                          If verification fails or the payment app closes early, your cart will stay intact. You can retry checkout here or switch to Cash on delivery before placing the order.
                        </p>
                        <Link
                          to={`/contact?subject=${encodeURIComponent('Payment Support')}&message=${encodeURIComponent(
                            `I need help with a checkout payment issue. Payment method: ${formData.paymentMethod}.`,
                          )}`}
                          className="mt-3 inline-flex text-sm font-semibold text-amber-800 underline-offset-4 hover:underline"
                        >
                          Contact support about payment issues
                        </Link>
                      </div>
                    </div>
                  </div>
                )}
              </div>
            </aside>
          </form>
        </div>
      </div>
      <div className="fixed inset-x-3 bottom-[calc(5.25rem+env(safe-area-inset-bottom))] z-40 md:hidden">
        <div className="rounded-[1.5rem] border border-slate-200/80 bg-white/96 p-3 shadow-xl backdrop-blur">
          <div className="flex items-center justify-between gap-3">
            <div>
              <p className="text-[11px] font-semibold uppercase tracking-[0.18em] text-slate-500">Pay now</p>
              <p className="text-lg font-bold text-slate-950">{formatPrice(checkoutTotal)}</p>
            </div>
            <button
              type="button"
              disabled={loading}
              onClick={() => {
                const form = document.querySelector('form') as HTMLFormElement | null;
                form?.requestSubmit();
              }}
              className="inline-flex items-center justify-center gap-2 rounded-2xl bg-slate-950 px-4 py-3 text-sm font-semibold text-white transition hover:bg-slate-800 disabled:cursor-not-allowed disabled:opacity-60"
            >
              {loading ? <Loader2 className="animate-spin" size={16} /> : null}
              <span>{loading ? 'Placing...' : 'Place order'}</span>
            </button>
          </div>
        </div>
      </div>

      {showPaymentModal && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center bg-black/60 p-4 backdrop-blur-sm">
          <div className="w-full max-w-md overflow-hidden rounded-[2rem] bg-[#DC2626] shadow-2xl">
            <div className="space-y-6 p-8 text-center text-white">
              <div className="flex justify-center">
                <div className="flex h-20 w-20 items-center justify-center rounded-full bg-white p-4">
                  <img
                    src="https://upload.wikimedia.org/wikipedia/commons/thumb/8/8b/Bkash_logo.png/1200px-Bkash_logo.png"
                    alt="bKash"
                    className="w-full object-contain"
                  />
                </div>
              </div>

              {paymentStep === 'number' && (
                <div className="space-y-5">
                  <h3 className="text-xl font-bold">Enter payment number</h3>
                  <p className="text-sm text-white/75">
                    Use the number linked to your payment app. You can cancel and return to checkout if you want to switch methods.
                  </p>
                  <input
                    type="tel"
                    placeholder="01XXXXXXXXX"
                    className="w-full rounded-2xl border-2 border-white/20 bg-white/10 px-6 py-4 text-center text-2xl font-bold text-white placeholder:text-white/50 outline-none focus:border-white"
                    value={paymentData.number}
                    onChange={(e) => setPaymentData({ ...paymentData, number: e.target.value })}
                  />
                  <button onClick={handlePaymentSubmit} className="w-full rounded-2xl bg-white py-4 text-lg font-bold text-[#DC2626] transition hover:bg-gray-100">
                    Next
                  </button>
                </div>
              )}

              {paymentStep === 'otp' && (
                <div className="space-y-5">
                  <h3 className="text-xl font-bold">Enter OTP</h3>
                  <p className="text-sm text-white/75">A 6-digit verification code has been sent to {paymentData.number}</p>
                  <input
                    type="text"
                    placeholder="XXXXXX"
                    className="w-full rounded-2xl border-2 border-white/20 bg-white/10 px-6 py-4 text-center text-2xl font-bold text-white placeholder:text-white/50 outline-none focus:border-white"
                    value={paymentData.otp}
                    onChange={(e) => setPaymentData({ ...paymentData, otp: e.target.value })}
                  />
                  <button onClick={handlePaymentSubmit} className="w-full rounded-2xl bg-white py-4 text-lg font-bold text-[#DC2626] transition hover:bg-gray-100">
                    Verify OTP
                  </button>
                </div>
              )}

              {paymentStep === 'pin' && (
                <div className="space-y-5">
                  <h3 className="text-xl font-bold">Enter PIN</h3>
                  <input
                    type="password"
                    placeholder="XXXXX"
                    className="w-full rounded-2xl border-2 border-white/20 bg-white/10 px-6 py-4 text-center text-2xl font-bold text-white placeholder:text-white/50 outline-none focus:border-white"
                    value={paymentData.pin}
                    onChange={(e) => setPaymentData({ ...paymentData, pin: e.target.value })}
                  />
                  <button onClick={handlePaymentSubmit} className="w-full rounded-2xl bg-white py-4 text-lg font-bold text-[#DC2626] transition hover:bg-gray-100">
                    Confirm payment
                  </button>
                </div>
              )}

              {paymentStep === 'success' && (
                <div className="space-y-5 py-10">
                  <div className="mx-auto flex h-20 w-20 items-center justify-center rounded-full bg-white/20">
                    <CheckCircle2 className="h-10 w-10 text-white" />
                  </div>
                  <h3 className="text-2xl font-bold">Payment successful</h3>
                  <p className="text-white/75">Finalizing your order and redirecting to confirmation...</p>
                </div>
              )}

              {paymentStep !== 'success' && (
                <button
                  onClick={() => setShowPaymentModal(false)}
                  className="text-sm text-white/65 transition hover:text-white"
                >
                  Cancel payment
                </button>
              )}
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

import React, { useEffect, useMemo, useState } from 'react';
import { Clock3, Loader2, Zap } from 'lucide-react';
import { ProductCard } from '@/features/shop/components/ProductCard';

type FlashSaleProduct = {
  id: string;
  name: string;
  slug: string;
  description: string;
  price: number;
  old_price: number;
  image: string;
  category: string;
  stock: number;
  rating: number;
  reviews_count: number;
  seller_name?: string;
};

type FlashSaleCampaign = {
  id: string;
  title: string;
  description?: string;
  banner_image?: string;
  starts_at: string;
  ends_at: string;
  status: string;
  entries?: Array<{
    id: string;
    sale_price: number;
    allocated_stock: number;
    product: FlashSaleProduct | null;
  }>;
};

const calculateCountdown = (targetIso?: string) => {
  if (!targetIso) {
    return { hours: '00', mins: '00', secs: '00', ended: true };
  }

  const diff = new Date(targetIso).getTime() - Date.now();
  if (diff <= 0) {
    return { hours: '00', mins: '00', secs: '00', ended: true };
  }

  const totalSeconds = Math.floor(diff / 1000);
  const hours = String(Math.floor(totalSeconds / 3600)).padStart(2, '0');
  const mins = String(Math.floor((totalSeconds % 3600) / 60)).padStart(2, '0');
  const secs = String(totalSeconds % 60).padStart(2, '0');

  return { hours, mins, secs, ended: false };
};

export const FlashSalePage = () => {
  const [campaign, setCampaign] = useState<FlashSaleCampaign | null>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState('');
  const [countdown, setCountdown] = useState(calculateCountdown());

  useEffect(() => {
    let active = true;

    const loadCampaign = async () => {
      try {
        setLoading(true);
        setError('');
        const response = await fetch('/api/flash-sale/active', { cache: 'no-store' });
        const payload = await response.json().catch(() => null);
        if (!response.ok) {
          throw new Error(payload?.error || 'Failed to load flash sale');
        }

        if (!active) return;
        setCampaign(payload?.campaign || null);
      } catch (requestError) {
        if (!active) return;
        setCampaign(null);
        setError(requestError instanceof Error ? requestError.message : 'Failed to load flash sale');
      } finally {
        if (active) {
          setLoading(false);
        }
      }
    };

    void loadCampaign();

    return () => {
      active = false;
    };
  }, []);

  useEffect(() => {
    setCountdown(calculateCountdown(campaign?.ends_at || campaign?.starts_at));

    const interval = window.setInterval(() => {
      setCountdown(calculateCountdown(campaign?.ends_at || campaign?.starts_at));
    }, 1000);

    return () => {
      window.clearInterval(interval);
    };
  }, [campaign?.ends_at, campaign?.starts_at]);

  const products = useMemo(() => {
    return (campaign?.entries || [])
      .map((entry) => {
        if (!entry.product) return null;
        return {
          ...entry.product,
          old_price: entry.product.old_price || entry.product.price,
          price: entry.sale_price,
          stock: entry.allocated_stock || entry.product.stock,
        };
      })
      .filter(Boolean) as FlashSaleProduct[];
  }, [campaign]);

  if (loading) {
    return (
      <div className="flex min-h-[360px] items-center justify-center">
        <Loader2 className="animate-spin text-primary" size={34} />
      </div>
    );
  }

  return (
    <div className="pb-20">
      <div
        className="mb-12 bg-accent py-12 text-white"
        style={campaign?.banner_image ? { backgroundImage: `linear-gradient(rgba(15,23,42,0.72), rgba(15,23,42,0.72)), url(${campaign.banner_image})`, backgroundSize: 'cover', backgroundPosition: 'center' } : undefined}
      >
        <div className="mx-auto flex max-w-7xl flex-col items-center justify-between gap-8 px-4 md:flex-row">
          <div className="space-y-4 text-center md:text-left">
            <h1 className="flex items-center justify-center space-x-4 font-display text-4xl font-bold md:justify-start md:text-6xl">
              <Zap size={48} fill="currentColor" />
              <span>{campaign?.title || 'FLASH SALE'}</span>
            </h1>
            <p className="max-w-2xl text-xl opacity-90">
              {campaign?.description || 'Live limited-time marketplace offers managed by admin and fulfilled by approved sellers.'}
            </p>
            {error ? <p className="text-sm text-amber-100">{error}</p> : null}
          </div>
          <div className="w-full rounded-2xl bg-white/20 p-6 text-center backdrop-blur-md md:min-w-[300px] md:w-auto">
            <p className="mb-4 flex items-center justify-center gap-2 text-sm font-bold uppercase tracking-widest">
              <Clock3 size={16} />
              <span>{campaign?.status === 'scheduled' ? 'Starts In' : 'Ends In'}</span>
            </p>
            <div className="flex justify-center space-x-4">
              {[
                { label: 'Hours', value: countdown.hours },
                { label: 'Mins', value: countdown.mins },
                { label: 'Secs', value: countdown.secs },
              ].map((item) => (
                <div key={item.label} className="flex flex-col">
                  <span className="font-mono text-4xl font-bold">{item.value}</span>
                  <span className="text-[10px] font-bold uppercase opacity-70">{item.label}</span>
                </div>
              ))}
            </div>
          </div>
        </div>
      </div>

      <div className="mx-auto max-w-7xl px-4">
        {!campaign ? (
          <div className="rounded-[32px] border border-dashed border-slate-200 bg-white px-6 py-16 text-center shadow-sm">
            <h2 className="text-2xl font-bold text-slate-900">No live flash sale right now</h2>
            <p className="mt-3 text-sm text-slate-500">
              Admin campaigns will appear here after sellers are approved and the schedule goes live.
            </p>
          </div>
        ) : products.length === 0 ? (
          <div className="rounded-[32px] border border-dashed border-slate-200 bg-white px-6 py-16 text-center shadow-sm">
            <h2 className="text-2xl font-bold text-slate-900">Campaign ready, product approvals pending</h2>
            <p className="mt-3 text-sm text-slate-500">
              Approved seller entries will appear here as soon as admin reviews are complete.
            </p>
          </div>
        ) : (
          <>
            <div className="mb-8 flex items-end justify-between gap-4">
              <div>
                <h2 className="text-2xl font-bold text-slate-900">Approved flash sale products</h2>
                <p className="mt-2 text-sm text-slate-500">
                  Seller-submitted offers curated by admin for this campaign.
                </p>
              </div>
              <div className="rounded-full bg-primary/10 px-4 py-2 text-xs font-bold uppercase tracking-[0.18em] text-primary">
                {products.length} products
              </div>
            </div>

            <div className="grid grid-cols-2 gap-6 md:grid-cols-4 lg:grid-cols-5">
              {products.map((product) => (
                <ProductCard key={product.id} product={product as any} />
              ))}
            </div>
          </>
        )}
      </div>
    </div>
  );
};

import React, { useEffect, useRef, useState, Suspense, lazy } from 'react';
import dynamic from 'next/dynamic';
import { useParams, useNavigate, Link, useSearchParams } from '../../../lib/navigation';
import { Star, ShieldCheck, Truck, RefreshCw, ShoppingCart, Heart, Share2, Loader2, Box, Maximize2, View, X, CreditCard, BadgeCheck, Clock3, Scale, ChevronRight, Sparkles, ScanSearch, Store } from 'lucide-react';
import { Product, ProductVariantValue } from '../../../types';
import { formatPrice } from '../../../lib/utils';
import OptimizedImage from '@/features/shared/ui/OptimizedImage';
import { useCart } from '../../../features/shop/state/CartContext';
import { useCompare } from '../../../features/shop/state/CompareContext';
import { useWishlist } from '../../../features/shop/state/WishlistContext';
import { useUser } from '../../../features/shared/state/UserContext';
import { AnimatedIcon } from '@/features/shared/ui/AnimatedIcon';
import { getCachedClientValue } from '../../../lib/client-cache';
import { ProductCard } from '@/features/shop/components/ProductCard';
import { renderProductDescription } from '../../../lib/product-description';
import { ProductLightbox } from '../../../features/shop/components/ProductLightbox';

const ProductViewer3D = lazy(() => import('@/features/shared/immersive/components/3d/ProductViewer3D'));
const ARTryOn = lazy(() => import('@/features/shared/immersive/components/ar/ARTryOn'));
const AIRecommendation = dynamic(
  () => import('@/features/ai/components/AIRecommendation').then((module) => module.AIRecommendation),
  {
    loading: () => <div className="mt-12 h-80 animate-pulse rounded-[2rem] bg-slate-100" />,
  },
);
const SocialShare = dynamic(
  () => import('@/features/shared/components/SocialShare').then((module) => module.SocialShare),
  {
    ssr: false,
    loading: () => <div className="h-10 w-full animate-pulse rounded-2xl bg-slate-100" />,
  },
);
const FrequentlyBoughtTogether = dynamic(
  () => import('@/features/shop/components/FrequentlyBoughtTogether').then((module) => module.FrequentlyBoughtTogether),
  {
    loading: () => <div className="h-72 animate-pulse rounded-[2rem] bg-slate-100" />,
  },
);

function getVariantValueLabel(value: ProductVariantValue | string) {
  return typeof value === 'string' ? value : value.label;
}

function getVariantValuePriceAdjustment(value: ProductVariantValue | string) {
  return typeof value === 'string' ? 0 : Number(value.price_adjustment ?? 0) || 0;
}

function getVariantValueStockOverride(value: ProductVariantValue | string) {
  if (typeof value === 'string') return null;
  return value.stock_override === null || typeof value.stock_override === 'undefined'
    ? null
    : Number(value.stock_override);
}

function getVariantValueSkuSuffix(value: ProductVariantValue | string) {
  if (typeof value === 'string') return null;
  return value.sku_suffix ? String(value.sku_suffix).trim().toUpperCase() : null;
}

export const ProductDetailsPage = () => {
  const { slug } = useParams();
  const navigate = useNavigate();
  const [searchParams] = useSearchParams();
  const [product, setProduct] = useState<Product | null>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState('');
  const [reviewError, setReviewError] = useState('');
  const [quantity, setQuantity] = useState(1);
  const [viewMode, setViewMode] = useState<'image' | '3d'>('image');
  const { items, addToCart, setCartItemQuantity } = useCart();
  const { toggleCompare, isInCompare } = useCompare();
  const { toggleWishlist, isInWishlist } = useWishlist();
  const [reviews, setReviews] = useState<any[]>([]);
  const [reviewsLoading, setReviewsLoading] = useState(false);
  const [reviewsLoaded, setReviewsLoaded] = useState(false);
  const [newReview, setNewReview] = useState({ rating: 5, comment: '' });
  const [submittingReview, setSubmittingReview] = useState(false);
  const [showShare, setShowShare] = useState(false);
  const [showAR, setShowAR] = useState(false);
  const [showImageLightbox, setShowImageLightbox] = useState(false);
  const [freeShippingThreshold, setFreeShippingThreshold] = useState(2500);
  const [selectedVariants, setSelectedVariants] = useState<Record<string, string>>({});
  const { user, token, isAuthenticated } = useUser();
  const referralCode = searchParams.get('ref');
  const deferredSectionsRef = useRef<HTMLDivElement | null>(null);
  const [showDeferredSections, setShowDeferredSections] = useState(false);
  const [relatedProducts, setRelatedProducts] = useState<Product[]>([]);
  const [relatedProductsLoading, setRelatedProductsLoading] = useState(false);
  const [sellerProducts, setSellerProducts] = useState<Product[]>([]);
  const [sellerProductsLoading, setSellerProductsLoading] = useState(false);
  const [deliveryZone, setDeliveryZone] = useState<'dhaka' | 'outside'>('dhaka');
  const [imageZoomOrigin, setImageZoomOrigin] = useState('50% 50%');
  const [isImageZoomed, setIsImageZoomed] = useState(false);
  const [selectedMediaIndex, setSelectedMediaIndex] = useState(0);

  useEffect(() => {
    if (!referralCode || typeof window === 'undefined') {
      return;
    }

    window.localStorage.setItem('ref_code', referralCode || '');
  }, [referralCode]);

  useEffect(() => {
    const controller = new AbortController();
    setLoading(true);
    setError('');

    Promise.all([
      getCachedClientValue(`product-details:${slug}`, 5 * 60 * 1000, async () => {
        const res = await fetch(`/api/products/${slug}`, { cache: 'no-store', signal: controller.signal });
        const payload = await res.json().catch(() => null);
        if (!res.ok) {
          throw new Error(payload?.error || 'Unable to load this product');
        }
        return payload;
      }),
      getCachedClientValue('commerce-config:public:v1', 10 * 60 * 1000, async () => {
        const res = await fetch('/api/public/commerce-config', { cache: 'no-store', signal: controller.signal });
        return res.ok ? res.json() : null;
      }).catch(() => null),
    ])
      .then(async ([productData, configData]) => {
        if (controller.signal.aborted) return;
        setProduct(productData);
        if (Array.isArray(productData?.variant_options)) {
          const defaults = productData.variant_options.reduce((acc: Record<string, string>, option: any) => {
            if (option?.name && Array.isArray(option?.values) && option.values.length > 0) {
              acc[String(option.name)] = getVariantValueLabel(option.values[0]);
            }
            return acc;
          }, {});
          setSelectedVariants(defaults);
        } else {
          setSelectedVariants({});
        }
        setReviews([]);
        setReviewsLoaded(false);
        setRelatedProducts([]);
        setSellerProducts([]);
        setShowDeferredSections(false);
        setSelectedMediaIndex(0);
        setViewMode('image');

        if (configData?.free_shipping_threshold) {
          setFreeShippingThreshold(Number(configData.free_shipping_threshold));
        }
      })
      .catch((fetchError) => {
        if ((fetchError as Error).name !== 'AbortError') {
          setProduct(null);
          setReviews([]);
          setError(fetchError instanceof Error ? fetchError.message : 'Unable to load this product right now.');
        }
      })
      .finally(() => {
        if (!controller.signal.aborted) {
          setLoading(false);
        }
      });

    return () => controller.abort();
  }, [slug]);

  useEffect(() => {
    if (!product || showDeferredSections || typeof window === 'undefined') return;

    const target = deferredSectionsRef.current;
    if (!target) return;

    const observer = new IntersectionObserver(
      (entries) => {
        if (entries.some((entry) => entry.isIntersecting)) {
          setShowDeferredSections(true);
          observer.disconnect();
        }
      },
      { rootMargin: '480px 0px' },
    );

    observer.observe(target);
    return () => observer.disconnect();
  }, [product, showDeferredSections]);

  useEffect(() => {
    if (!product?.id || !showDeferredSections || reviewsLoaded) return;

    const controller = new AbortController();
    setReviewsLoading(true);

    getCachedClientValue(`product-reviews:${product.id}`, 2 * 60 * 1000, async () => {
      const reviewsResponse = await fetch(`/api/products/${product.id}/reviews`, {
        cache: 'no-store',
        signal: controller.signal,
      });
      if (!reviewsResponse.ok) {
        throw new Error('Failed to load reviews');
      }
      return reviewsResponse.json().catch(() => []);
    })
      .then((reviewsData) => {
        if (controller.signal.aborted) return;
        setReviews(Array.isArray(reviewsData) ? reviewsData : []);
      })
      .catch((fetchError) => {
        if ((fetchError as Error).name !== 'AbortError') {
          setReviews([]);
        }
      })
      .finally(() => {
        if (!controller.signal.aborted) {
          setReviewsLoaded(true);
          setReviewsLoading(false);
        }
      });

    return () => controller.abort();
  }, [product?.id, reviewsLoaded, showDeferredSections]);

  useEffect(() => {
    if (!product?.id || !product.category || !showDeferredSections) return;

    const controller = new AbortController();
    setRelatedProductsLoading(true);

    getCachedClientValue(`related-products:${product.category}`, 5 * 60 * 1000, async () => {
      const response = await fetch(`/api/products?limit=12&category=${encodeURIComponent(product.category)}`, {
        cache: 'no-store',
        signal: controller.signal,
      });
      if (!response.ok) {
        throw new Error('Failed to load related products');
      }
      return response.json().catch(() => []);
    })
      .then((productsData) => {
        if (controller.signal.aborted) return;

        const normalized = Array.isArray(productsData) ? productsData : [];
        const sameCategory = normalized.filter((entry) => entry?.slug !== product.slug).slice(0, 4);
        setRelatedProducts(sameCategory as Product[]);
      })
      .catch(() => {
        if (!controller.signal.aborted) {
          setRelatedProducts([]);
        }
      })
      .finally(() => {
        if (!controller.signal.aborted) {
          setRelatedProductsLoading(false);
        }
      });

    return () => controller.abort();
  }, [product?.category, product?.id, product?.slug, showDeferredSections]);

  useEffect(() => {
    if (!product?.seller_id || !showDeferredSections) return;

    const controller = new AbortController();
    setSellerProductsLoading(true);

    getCachedClientValue(`seller-products:${product.seller_id}`, 5 * 60 * 1000, async () => {
      const response = await fetch(`/api/products?limit=8&seller_id=${encodeURIComponent(String(product.seller_id))}`, {
        cache: 'no-store',
        signal: controller.signal,
      });
      if (!response.ok) {
        throw new Error('Failed to load seller products');
      }
      return response.json().catch(() => []);
    })
      .then((productsData) => {
        if (controller.signal.aborted) return;
        const normalized = Array.isArray(productsData) ? productsData : [];
        const sameSeller = normalized.filter((entry) => entry?.slug !== product.slug).slice(0, 4);
        setSellerProducts(sameSeller as Product[]);
      })
      .catch(() => {
        if (!controller.signal.aborted) {
          setSellerProducts([]);
        }
      })
      .finally(() => {
        if (!controller.signal.aborted) {
          setSellerProductsLoading(false);
        }
      });

    return () => controller.abort();
  }, [product?.seller_id, product?.slug, showDeferredSections]);

  const handlePostReview = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!product) return;
    setSubmittingReview(true);
    setReviewError('');
    try {
      const response = await fetch(`/api/products/${product.id}/reviews`, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'Authorization': `Bearer ${token}`
        },
        body: JSON.stringify(newReview)
      });
      const payload = await response.json().catch(() => null);
      if (!response.ok) {
        throw new Error(payload?.error || 'Unable to post your review');
      }
      const nextReview = {
        id: `local-${Date.now()}`,
        product_id: product.id,
        user_id: user?.id,
        rating: newReview.rating,
        comment: newReview.comment,
        created_at: new Date().toISOString(),
        user_name: user?.name || 'You',
      };
      const nextCount = (product.reviews_count ?? 0) + 1;
      const nextRating =
        ((product.rating ?? 0) * (product.reviews_count ?? 0) + Number(newReview.rating)) / Math.max(nextCount, 1);

      setReviews((current) => [nextReview, ...current]);
      setProduct((current) =>
        current
          ? {
              ...current,
              reviews_count: nextCount,
              rating: Number(nextRating.toFixed(1)),
            }
          : current,
      );
      setNewReview({ rating: 5, comment: '' });
    } catch (err) {
      setReviewError(err instanceof Error ? err.message : 'Unable to post your review');
    } finally {
      setSubmittingReview(false);
    }
  };

  useEffect(() => {
    if (!product) {
      return;
    }

    const selectedVariantEntries = Array.isArray(product.variant_options)
      ? product.variant_options.map((option) => {
          const selectedLabel = selectedVariants[option.name] || getVariantValueLabel(option.values?.[0] as any);
          const selectedValue =
            option.values.find((value) => getVariantValueLabel(value as any) === selectedLabel) ?? option.values?.[0];
          return selectedValue;
        })
      : [];

    const variantStockCandidates = selectedVariantEntries
      .map((value) => getVariantValueStockOverride(value as any))
      .filter((value): value is number => value !== null && Number.isFinite(value));
    const nextMaxSelectableQuantity = Math.max(
      0,
      variantStockCandidates.length > 0 ? Math.min(...variantStockCandidates) : product.stock,
    );

    if (nextMaxSelectableQuantity > 0 && quantity > nextMaxSelectableQuantity) {
      setQuantity(nextMaxSelectableQuantity);
    }
  }, [product, quantity, selectedVariants]);

  if (loading) {
    return (
      <div className="max-w-7xl mx-auto px-4 py-12">
        <div className="grid grid-cols-1 gap-12 lg:grid-cols-2 animate-pulse">
          <div className="aspect-square rounded-3xl bg-gray-200" />
          <div className="space-y-5">
            <div className="h-8 w-2/3 rounded bg-gray-200" />
            <div className="h-5 w-1/3 rounded bg-gray-200" />
            <div className="h-24 rounded-3xl bg-gray-100" />
            <div className="h-28 rounded-3xl bg-gray-100" />
            <div className="h-14 rounded-2xl bg-gray-200" />
          </div>
        </div>
      </div>
    );
  }

  if (!product) {
    return (
      <div className="max-w-4xl mx-auto px-4 py-16">
        <div className="rounded-[2rem] border border-amber-200 bg-amber-50 p-8 text-center">
          <h1 className="text-2xl font-bold text-slate-950">This product is unavailable right now</h1>
          <p className="mt-3 text-sm text-slate-600">
            {error || 'The product could not be loaded. Please try again or continue browsing other items.'}
          </p>
          <div className="mt-6 flex justify-center gap-3">
            <button
              type="button"
              onClick={() => window.location.reload()}
              className="rounded-2xl bg-slate-950 px-5 py-3 text-sm font-semibold text-white transition hover:bg-slate-800"
            >
              Try again
            </button>
            <Link
              to="/shop"
              className="rounded-2xl border border-slate-200 bg-white px-5 py-3 text-sm font-semibold text-slate-700 transition hover:bg-slate-50"
            >
              Continue shopping
            </Link>
          </div>
        </div>
      </div>
    );
  }

  const variantOptions = Array.isArray(product.variant_options) ? product.variant_options : [];
  const specificationItems = Array.isArray(product.specifications) ? product.specifications : [];
  const selectedVariantEntries = variantOptions.length > 0
    ? variantOptions.map((option) => {
        const selectedLabel = selectedVariants[option.name] || getVariantValueLabel(option.values?.[0] as any);
        const selectedValue = option.values.find((value) => getVariantValueLabel(value as any) === selectedLabel) ?? option.values?.[0];
        return {
          optionName: option.name,
          selectedLabel,
          selectedValue,
        };
      })
    : [];
  const variantPriceAdjustment = selectedVariantEntries.reduce(
    (sum, entry) => sum + getVariantValuePriceAdjustment(entry.selectedValue as any),
    0,
  );
  const variantStockCandidates = selectedVariantEntries
    .map((entry) => getVariantValueStockOverride(entry.selectedValue as any))
    .filter((value): value is number => value !== null && Number.isFinite(value));
  const effectiveStock = variantStockCandidates.length > 0 ? Math.min(...variantStockCandidates) : product.stock;
  const effectivePrice = Math.max(0, product.price + variantPriceAdjustment);
  const effectiveOldPrice =
    product.old_price > product.price
      ? Math.max(effectivePrice, product.old_price + variantPriceAdjustment)
      : product.old_price;
  const selectedVariantSummary = selectedVariantEntries
    .map((entry) => `${entry.optionName}: ${entry.selectedLabel}`)
    .join(' • ');
  const selectedVariantKey = selectedVariantEntries.map((entry) => `${entry.optionName}:${entry.selectedLabel}`).join('|');
  const selectedVariantSkuSuffix = selectedVariantEntries
    .map((entry) => getVariantValueSkuSuffix(entry.selectedValue as any))
    .filter((value): value is string => Boolean(value))
    .join('-');
  const selectedVariantSku = selectedVariantSkuSuffix
    ? `${String(product.sku || '').trim()}-${selectedVariantSkuSuffix}`
    : product.sku || undefined;
  const hasDiscount = effectiveOldPrice > effectivePrice;
  const discount = hasDiscount && effectiveOldPrice > 0
    ? Math.round(((effectiveOldPrice - effectivePrice) / effectiveOldPrice) * 100)
    : 0;
  const isWishlisted = isInWishlist(product.id);
  const isCompared = isInCompare(product.id);
  const isOutOfStock = effectiveStock <= 0;
  const lowStock = effectiveStock > 0 && effectiveStock <= 5;
  const maxSelectableQuantity = Math.max(0, effectiveStock);
  const estimatedDelivery = new Date(Date.now() + 3 * 24 * 60 * 60 * 1000).toLocaleDateString('en-BD', {
    month: 'short',
    day: 'numeric',
  });
  const freeShippingRemaining = Math.max(0, freeShippingThreshold - effectivePrice);
  const freeShippingProgress = Math.min((effectivePrice / freeShippingThreshold) * 100, 100);
  const hasVariantOptions = variantOptions.length > 0;
  const hasSpecifications = specificationItems.length > 0;
  const sellerDisplayName = product.seller_name?.trim() || 'Verified marketplace seller';
  const sellerStoreLabel = product.store_name?.trim() || sellerDisplayName;
  const sellerInitial = sellerDisplayName.charAt(0).toUpperCase() || 'S';
  const productImageSrc = typeof product.image === 'string' ? product.image.trim() : '';
  const galleryImages = Array.isArray(product.gallery_images)
    ? product.gallery_images.filter((item): item is string => typeof item === 'string' && item.trim().length > 0)
    : [];
  const productMediaImages = [productImageSrc, ...galleryImages].filter((item, index, array) => item && array.indexOf(item) === index);
  const activeImageSrc = productMediaImages[selectedMediaIndex] || productImageSrc;
  const hasProductImage = activeImageSrc.length > 0;
  const hasProductVideo = Boolean(product.video_url && String(product.video_url).trim());
  const arSource = `${product.category || ''} ${product.name || ''}`.toLowerCase();
  const arProductType =
    arSource.includes('shoe') || arSource.includes('sneaker') || arSource.includes('sandal')
      ? 'shoes'
      : arSource.includes('shirt') ||
          arSource.includes('t-shirt') ||
          arSource.includes('tee') ||
          arSource.includes('pant') ||
          arSource.includes('trouser') ||
          arSource.includes('dress') ||
          arSource.includes('jacket') ||
          arSource.includes('hoodie') ||
          arSource.includes('clothing') ||
          arSource.includes('fashion')
        ? 'clothing'
        : arSource.includes('glass') ||
            arSource.includes('watch') ||
            arSource.includes('cap') ||
            arSource.includes('bag') ||
            arSource.includes('accessor')
          ? 'accessories'
          : null;
  const supportsARTryOn = Boolean(arProductType);
  const sellerResponseLabel = product.response_time_hours
    ? `Responds in ~${product.response_time_hours}h`
    : 'Fast response';
  const sellerRatingLabel = product.seller_rating ? product.seller_rating.toFixed(1) : null;
  const quickFacts = [
    { label: 'Category', value: product.category || 'General' },
    { label: 'SKU', value: selectedVariantSku || product.sku || 'Auto assigned' },
    { label: 'Selection', value: selectedVariantSummary || 'Standard edition' },
    { label: 'Availability', value: isOutOfStock ? 'Temporarily unavailable' : `${effectiveStock} ready to order` },
  ];
  const deliveryEstimateLabel =
    deliveryZone === 'dhaka'
      ? `Inside Dhaka: ${estimatedDelivery}`
      : `Outside Dhaka: ${new Date(Date.now() + 5 * 24 * 60 * 60 * 1000).toLocaleDateString('en-BD', {
          month: 'short',
          day: 'numeric',
        })}`;
  const serviceHighlights = [
    {
      title: 'Cash on delivery',
      description: 'Pay when the order reaches you.',
      icon: <CreditCard size={18} />,
    },
    {
      title: 'Fast delivery',
      description: `Expected by ${estimatedDelivery}.`,
      icon: <Truck size={18} />,
    },
    {
      title: 'Easy return',
      description: '7-day return support on eligible orders.',
      icon: <ShieldCheck size={18} />,
    },
  ];
  const landingHighlights = ['Cash on delivery', 'Fast delivery', 'Verified seller', 'Easy return'];
  const featureBullets = [
    selectedVariantSummary || 'Standard selection ready to order',
    `${effectiveStock > 0 ? effectiveStock : 0} item${effectiveStock === 1 ? '' : 's'} available`,
    `Delivery by ${estimatedDelivery}`,
  ];
  const mediaHighlights = [
    {
      title: 'Primary image',
      value: 'High-resolution product photo',
      icon: <Box className="h-4 w-4" />,
    },
    {
      title: 'Close inspection',
      value: 'Zoom-friendly sharp display',
      icon: <ScanSearch className="h-4 w-4" />,
    },
    {
      title: 'Seller coverage',
      value: sellerDisplayName,
      icon: <Store className="h-4 w-4" />,
    },
    {
      title: product.model_3d ? '3D view ready' : 'Purchase support',
      value: product.model_3d ? 'Explore this item in 3D' : 'Returns and delivery support included',
      icon: product.model_3d ? <View className="h-4 w-4" /> : <Sparkles className="h-4 w-4" />,
    },
  ];
  const serviceTiles = [
    { label: 'Delivery', value: estimatedDelivery, icon: <Truck className="h-4 w-4" /> },
    { label: 'Return', value: '7 days', icon: <RefreshCw className="h-4 w-4" /> },
    { label: 'Payment', value: 'COD ready', icon: <CreditCard className="h-4 w-4" /> },
    { label: 'Seller', value: 'Verified', icon: <BadgeCheck className="h-4 w-4" /> },
  ];
  const reviewBreakdown = [5, 4, 3, 2, 1].map((star) => {
    const count = reviews.filter((review) => Number(review.rating) === star).length;
    const percentage = reviews.length > 0 ? (count / reviews.length) * 100 : 0;
    return { star, count, percentage };
  });
  const hasSellerOfferBlock = Boolean(product.seller_id && sellerProducts.length > 0);
  const renderedDescription = renderProductDescription(product.description);

  const productForCart: Product = {
    ...product,
    price: effectivePrice,
    old_price: effectiveOldPrice,
    stock: effectiveStock,
    reseller_ref_code: referralCode || product.reseller_ref_code,
    selected_variant_key: selectedVariantKey || undefined,
    selected_variant_summary: selectedVariantSummary || undefined,
    selected_variant_sku: selectedVariantSku || undefined,
  };

  const existingCartItem = items.find(
    (item) => item.id === productForCart.id && (item.selected_variant_key || '') === (productForCart.selected_variant_key || ''),
  );
  const isAlreadyInCart = Boolean(existingCartItem);

  const handleBuyNow = () => {
    if (product && !isOutOfStock) {
      setCartItemQuantity(productForCart, Math.min(quantity, maxSelectableQuantity || quantity));
      navigate('/cart');
    }
  };

  const handleAddToCart = () => {
    if (!product || isOutOfStock) {
      return;
    }

    addToCart(productForCart, Math.min(quantity, maxSelectableQuantity || quantity));
  };

  const handleCompareToggle = () => {
    toggleCompare(product);
  };

  const handleImagePointerMove = (event: React.MouseEvent<HTMLButtonElement>) => {
    const bounds = event.currentTarget.getBoundingClientRect();
    const x = ((event.clientX - bounds.left) / bounds.width) * 100;
    const y = ((event.clientY - bounds.top) / bounds.height) * 100;
    setImageZoomOrigin(`${Math.min(100, Math.max(0, x))}% ${Math.min(100, Math.max(0, y))}%`);
  };

  return (
    <div className="max-w-7xl mx-auto px-4 py-6 pb-28 md:py-12 md:pb-12">
      <script
        type="application/ld+json"
        dangerouslySetInnerHTML={{
          __html: JSON.stringify({
            '@context': 'https://schema.org',
            '@type': 'Product',
            name: product.name,
            description: product.description || undefined,
            image: activeImageSrc || undefined,
            sku: product.sku || undefined,
            brand: product.store_name ? { '@type': 'Brand', name: product.store_name } : undefined,
            offers: {
              '@type': 'Offer',
              priceCurrency: 'BDT',
              price: String(product.price),
              availability: (product.stock ?? 0) > 0 ? 'https://schema.org/InStock' : 'https://schema.org/OutOfStock',
              url: typeof window !== 'undefined' ? window.location.href : undefined,
            },
            aggregateRating: product.reviews_count
              ? {
                  '@type': 'AggregateRating',
                  ratingValue: String(product.rating || 0),
                  reviewCount: String(product.reviews_count),
                }
              : undefined,
          }),
        }}
      />
      <div className="mb-6 flex flex-wrap items-center gap-2 text-sm text-slate-500">
        <Link to="/" className="font-medium transition hover:text-primary">
          Home
        </Link>
        <ChevronRight className="h-4 w-4 text-slate-300" />
        <Link to="/shop" className="font-medium transition hover:text-primary">
          Shop
        </Link>
        {product.category ? (
          <>
            <ChevronRight className="h-4 w-4 text-slate-300" />
            <span className="font-medium text-slate-600">{product.category}</span>
          </>
        ) : null}
        <ChevronRight className="h-4 w-4 text-slate-300" />
        <span className="line-clamp-1 font-semibold text-slate-900">{product.name}</span>
      </div>
      <div className="grid grid-cols-1 gap-8 xl:grid-cols-[minmax(0,1.05fr)_minmax(20rem,0.95fr)] xl:gap-12">
        {/* Image Gallery / 3D Viewer */}
        <div className="order-1 space-y-3 sm:space-y-4 lg:order-1">
          <div className="relative aspect-square overflow-hidden rounded-[2rem] border border-black/5 bg-[linear-gradient(180deg,#ffffff_0%,#f8fafc_100%)] shadow-sm group">
            {viewMode === 'image' ? (
              hasProductImage ? (
                <button
                  type="button"
                  onClick={() => setShowImageLightbox(true)}
                  onMouseMove={handleImagePointerMove}
                  onMouseEnter={() => setIsImageZoomed(true)}
                  onMouseLeave={() => {
                    setIsImageZoomed(false);
                    setImageZoomOrigin('50% 50%');
                  }}
                  className="block h-full w-full cursor-zoom-in"
                  aria-label="Open product image"
                >
                  <div className="flex h-full w-full items-center justify-center p-4 sm:p-6 lg:p-8">
                    <OptimizedImage
                      src={activeImageSrc}
                      alt={product.name}
                      widthHint={1600}
                      heightHint={1600}
                      quality="auto:best"
                      fit="limit"
                      eager
                      showPlaceholder={false}
                      className="h-full w-full object-contain transition duration-300 ease-out"
                      style={{
                        transformOrigin: imageZoomOrigin,
                        transform: isImageZoomed ? 'scale(1.18)' : 'scale(1)',
                      }}
                    />
                  </div>
                </button>
              ) : (
                <div className="grid h-full w-full place-items-center bg-[radial-gradient(circle_at_top,#ffffff_0%,#f8fafc_45%,#e2e8f0_100%)] p-8 text-center">
                  <div className="max-w-xs">
                    <div className="mx-auto flex h-16 w-16 items-center justify-center rounded-3xl bg-white text-slate-400 shadow-sm">
                      <Box className="h-8 w-8" />
                    </div>
                    <p className="mt-4 text-base font-semibold text-slate-700">Product photo is being prepared</p>
                    <p className="mt-2 text-sm leading-6 text-slate-500">
                      This listing is live, but the main product image has not been added yet.
                    </p>
                  </div>
                </div>
              )
            ) : (
              <div className="w-full h-full">
                <Suspense fallback={<div className="h-full grid place-items-center text-sm text-gray-500">Loading 3D viewer...</div>}>
                  <ProductViewer3D modelUrl={product.model_3d || ''} />
                </Suspense>
              </div>
            )}
            
            {/* View Mode Toggles */}
            {product.model_3d && (
              <div className="absolute bottom-4 left-1/2 z-20 flex w-[calc(100%-1rem)] max-w-sm -translate-x-1/2 gap-2 rounded-2xl border border-white/20 bg-white/90 p-1.5 shadow-xl backdrop-blur-md sm:bottom-6 sm:w-auto">
                <button
                  onClick={() => setViewMode('image')}
                  className={`flex flex-1 items-center justify-center gap-2 rounded-xl px-4 py-2 text-xs font-bold transition-all ${
                    viewMode === 'image' 
                      ? 'bg-emerald-600 text-white shadow-lg shadow-emerald-200' 
                      : 'text-gray-600 hover:bg-gray-100'
                  }`}
                >
                  <AnimatedIcon loop="none"><Box className="w-4 h-4" /></AnimatedIcon>
                  Photo
                </button>
                <button
                  onClick={() => setViewMode('3d')}
                  className={`flex flex-1 items-center justify-center gap-2 rounded-xl px-4 py-2 text-xs font-bold transition-all ${
                    viewMode === '3d' 
                      ? 'bg-emerald-600 text-white shadow-lg shadow-emerald-200' 
                      : 'text-gray-600 hover:bg-gray-100'
                  }`}
                >
                  <AnimatedIcon loop="none"><View className="w-4 h-4" /></AnimatedIcon>
                  3D View
                </button>
              </div>
            )}

            {/* Quick preview actions */}
            <div className="absolute right-4 top-4 flex flex-col gap-2 sm:right-5 sm:top-5">
              <button
                type="button"
                onClick={() => setShowImageLightbox(true)}
                disabled={!hasProductImage}
                className="rounded-xl bg-white/90 p-3 shadow-lg backdrop-blur transition-all hover:bg-slate-950 hover:text-white disabled:cursor-not-allowed disabled:opacity-40 group/btn"
              >
                <AnimatedIcon loop="none"><Maximize2 className="w-5 h-5" /></AnimatedIcon>
                <span className="absolute right-full mr-2 top-1/2 -translate-y-1/2 px-2 py-1 bg-zinc-900 text-white text-[10px] rounded opacity-0 group-hover/btn:opacity-100 whitespace-nowrap transition-opacity">
                  Enlarge
                </span>
              </button>
              {supportsARTryOn ? (
                <button
                  onClick={() => setShowAR(true)}
                  className="rounded-xl bg-white/90 p-3 shadow-lg backdrop-blur transition-all hover:bg-emerald-600 hover:text-white group/btn"
                >
                  <AnimatedIcon loop="pulse"><Maximize2 className="w-5 h-5" /></AnimatedIcon>
                  <span className="absolute right-full mr-2 top-1/2 -translate-y-1/2 px-2 py-1 bg-zinc-900 text-white text-[10px] rounded opacity-0 group-hover/btn:opacity-100 whitespace-nowrap transition-opacity">
                    AR Try-on
                  </span>
                </button>
              ) : null}
            </div>
          </div>
          {(productMediaImages.length > 1 || hasProductVideo) && (
            <div className="grid grid-cols-3 gap-3 sm:grid-cols-4 lg:grid-cols-5">
              {productMediaImages.map((imageUrl, index) => (
                <button
                  key={`${imageUrl}-${index}`}
                  type="button"
                  onClick={() => {
                    setViewMode('image');
                    setSelectedMediaIndex(index);
                  }}
                  className={`aspect-square overflow-hidden rounded-2xl border bg-white shadow-sm transition ${
                    activeImageSrc === imageUrl && viewMode === 'image'
                      ? 'border-primary ring-2 ring-primary/15'
                      : 'border-slate-200 hover:border-slate-300'
                  }`}
                >
                  <OptimizedImage
                    src={imageUrl}
                    alt={`${product.name} view ${index + 1}`}
                    widthHint={240}
                    heightHint={240}
                    quality="auto:good"
                    fit="fill"
                    showPlaceholder={false}
                    className="h-full w-full object-cover"
                  />
                </button>
              ))}
              {hasProductVideo ? (
                <button
                  type="button"
                  onClick={() => {
                    if (typeof window !== 'undefined' && product.video_url) {
                      window.open(product.video_url, '_blank', 'noopener,noreferrer');
                    }
                  }}
                  className="aspect-square rounded-2xl border border-slate-200 bg-white p-3 text-left shadow-sm transition hover:border-slate-300"
                >
                  <p className="text-[10px] font-bold uppercase tracking-[0.18em] text-slate-500">Video</p>
                  <p className="mt-2 text-sm font-semibold text-slate-900">Watch demo</p>
                </button>
              ) : null}
            </div>
          )}

          <div className="hidden space-y-4 rounded-[2rem] border border-black/5 bg-white p-6 shadow-sm lg:block">
           

            <div className="grid gap-4 rounded-[2rem] border border-black/5 bg-white p-5 shadow-sm sm:grid-cols-2 2xl:grid-cols-4">
              {serviceTiles.map((item) => (
                <div key={item.label} className="rounded-2xl bg-slate-50 px-4 py-4">
                  <div className="mb-2 flex h-9 w-9 items-center justify-center rounded-2xl bg-white text-primary shadow-sm">
                    {item.icon}
                  </div>
                  <p className="text-[11px] font-bold uppercase tracking-wide text-slate-500">{item.label}</p>
                  <p className="mt-1 text-sm font-semibold text-slate-900">{item.value}</p>
                </div>
              ))}
            </div>

            <div className="flex items-center justify-between gap-3">
              <div>
                <p className="text-sm font-bold uppercase tracking-[0.22em] text-primary/70">About this item</p>
                <h3 className="mt-2 text-xl font-bold text-slate-900">Product description</h3>
              </div>
            </div>
            <div
              className="space-y-4"
              dangerouslySetInnerHTML={{ __html: renderedDescription }}
            />
          </div>
        
        </div>

        {/* Product Info */}
        <div className="order-2 min-w-0 space-y-6 self-start sm:space-y-8 lg:order-2 lg:sticky lg:top-24">
          <div>
            <div className="mb-2 flex items-start justify-between gap-3">
              <h1 className="text-2xl font-bold font-display leading-tight sm:text-3xl md:text-4xl">{product.name}</h1>
              <div className="relative">
                <button 
                  onClick={() => setShowShare(!showShare)}
                  className="p-3 bg-gray-100 rounded-xl hover:bg-gray-200 transition-colors"
                >
                  <AnimatedIcon loop="none"><Share2 className="w-5 h-5" /></AnimatedIcon>
                </button>
                {showShare && (
                  <div className="absolute right-0 top-full z-50 mt-2 w-[min(18rem,calc(100vw-2rem))] rounded-2xl border border-gray-100 bg-white p-4 shadow-2xl">
                    <div className="flex justify-between items-center mb-3">
                      <span className="text-xs font-bold text-gray-400 uppercase tracking-wider">Share Product</span>
                      <button onClick={() => setShowShare(false)}><AnimatedIcon loop="none"><X size={14} /></AnimatedIcon></button>
                    </div>
                    <SocialShare 
                      url={window.location.href} 
                      title={`Check out this ${product.name} on our store!`} 
                    />
                  </div>
                )}
              </div>
            </div>
            <div className="flex flex-wrap items-center gap-x-4 gap-y-2">
              <div className="flex items-center text-yellow-400">
                {[...Array(5)].map((_, i) => (
                  <Star key={i} size={18} fill={i < Math.floor(product.rating) ? "currentColor" : "none"} />
                ))}
                <span className="ml-2 text-sm font-bold text-gray-700">{product.rating}</span>
              </div>
              <span className="text-sm text-gray-400">|</span>
              <span className="text-sm text-gray-500">{product.reviews_count} Reviews</span>
              <span className="text-sm text-gray-400">|</span>
              <span className={effectiveStock > 0 ? "text-primary text-sm font-bold" : "text-accent text-sm font-bold"}>
                {effectiveStock > 0 ? "In Stock" : "Out of Stock"}
              </span>
            </div>
            <div className="mt-3 flex flex-wrap gap-3">
              {lowStock && (
                <div className="inline-flex items-center gap-2 rounded-full bg-accent/10 px-4 py-2 text-sm font-semibold text-accent">
                  <AnimatedIcon loop="pulse"><Clock3 size={16} /></AnimatedIcon>
                  Only {effectiveStock} left in stock
                </div>
              )}
                <div className="inline-flex items-center gap-2 rounded-full bg-primary/10 px-4 py-2 text-sm font-semibold text-primary">
                  <AnimatedIcon loop="none"><Truck size={16} /></AnimatedIcon>
                  Delivery by {estimatedDelivery}
                </div>
              </div>
            <div className="mt-4 flex flex-wrap gap-2">
              {landingHighlights.map((item) => (
                <span
                  key={item}
                  className="inline-flex items-center rounded-full border border-slate-200 bg-white px-3 py-1.5 text-xs font-semibold text-slate-700 shadow-sm"
                >
                  {item}
                </span>
              ))}
            </div>
          </div>

          <div className="rounded-2xl border border-[#fbd8c4] bg-[#fff7f2] p-5 shadow-sm sm:p-6">
            <div className="flex flex-wrap items-end gap-3">
              <span className="text-4xl font-bold text-[#F59E0B]">{formatPrice(effectivePrice)}</span>
              {effectiveOldPrice > effectivePrice && (
                <>
                  <span className="text-xl text-gray-400 line-through">{formatPrice(effectiveOldPrice)}</span>
                  <span className="rounded bg-[#F59E0B] px-2 py-1 text-xs font-bold text-white">-{discount}% OFF</span>
                </>
              )}
            </div>
            <div className="mt-3 grid gap-2 text-sm text-slate-600">
              
              <p>
              {discount > 0
                ? `You save ${formatPrice(effectiveOldPrice - effectivePrice)} on this order.`
                : 'Competitive pricing from a verified seller.'}
              </p>
            </div>
          </div>

          <div className="grid gap-3 rounded-[2rem] border border-black/5 bg-white p-5 shadow-sm sm:grid-cols-3">
            {featureBullets.map((item) => (
              <div key={item} className="rounded-2xl bg-slate-50 px-4 py-3 text-sm font-semibold text-slate-700">
                {item}
              </div>
            ))}
          </div>

          <div className="space-y-4">
            {hasVariantOptions ? (
              <div className="space-y-4 rounded-[2rem] border border-black/5 bg-white p-6 shadow-sm">
                <div className="flex flex-col gap-3 md:flex-row md:items-center md:justify-between">
                  <div>
                  <p className="text-sm font-bold uppercase tracking-[0.22em] text-primary/70">Available options</p>
                  <h3 className="mt-2 text-xl font-bold text-gray-900">Choose the version that fits best</h3>
                  </div>
                  <span className="rounded-full bg-slate-100 px-3 py-1 text-xs font-semibold text-slate-600">
                    SKU: {selectedVariantSku || product.sku || 'Auto'}
                  </span>
                </div>
                <div className="space-y-4">
                  {variantOptions.map((option) => (
                    <div key={option.name} className="space-y-3">
                      <div className="flex items-center justify-between gap-3">
                        <p className="text-sm font-semibold text-slate-900">{option.name}</p>
                        <span className="text-xs text-slate-500">
                          Selected: {selectedVariants[option.name] || getVariantValueLabel(option.values?.[0] as any) || 'Not selected'}
                        </span>
                      </div>
                      <div className="flex flex-wrap gap-2">
                        {option.values.map((value) => {
                          const valueLabel = getVariantValueLabel(value as any);
                          const adjustment = getVariantValuePriceAdjustment(value as any);
                          const stockOverride = getVariantValueStockOverride(value as any);
                          const isActive = selectedVariants[option.name] === valueLabel;
                          return (
                            <button
                              key={`${option.name}-${valueLabel}`}
                              type="button"
                              onClick={() =>
                                setSelectedVariants((current) => ({
                                  ...current,
                                  [option.name]: valueLabel,
                                }))
                              }
                              className={`rounded-full border px-4 py-2 text-sm font-semibold transition ${
                                isActive
                                  ? 'border-primary bg-primary text-white shadow-lg shadow-primary/20'
                                  : 'border-slate-200 bg-white text-slate-700 hover:border-primary/30 hover:bg-primary/5 hover:text-primary'
                              }`}
                            >
                              <span>{valueLabel}</span>
                              {adjustment !== 0 ? (
                                <span className={`ml-2 text-xs ${isActive ? 'text-white/80' : 'text-slate-400'}`}>
                                  {adjustment > 0 ? `+${formatPrice(adjustment)}` : formatPrice(adjustment)}
                                </span>
                              ) : null}
                              {stockOverride !== null ? (
                                <span className={`ml-2 text-xs ${isActive ? 'text-white/80' : 'text-slate-400'}`}>
                                  {stockOverride} stock
                                </span>
                              ) : null}
                            </button>
                          );
                        })}
                      </div>
                    </div>
                  ))}
                </div>
              </div>
            ) : null}

            <div className="rounded-[2rem] border border-black/5 bg-white p-6 shadow-sm">
              <div className="flex flex-col gap-5">
                <div className="flex flex-col gap-3 sm:flex-row sm:items-center sm:gap-4">
                  <div className="flex w-full items-center justify-between border border-gray-200 rounded-lg sm:w-auto sm:justify-start">
                    <button
                      onClick={() => setQuantity(q => Math.max(1, q - 1))}
                      disabled={quantity <= 1}
                      className="px-4 py-2 hover:bg-gray-100 transition-colors disabled:cursor-not-allowed disabled:opacity-40"
                    >
                      -
                    </button>
                    <span className="px-6 py-2 text-center font-bold">{quantity}</span>
                    <button
                      onClick={() => setQuantity(q => Math.min(maxSelectableQuantity || 1, q + 1))}
                      disabled={isOutOfStock || quantity >= maxSelectableQuantity}
                      className="px-4 py-2 hover:bg-gray-100 transition-colors disabled:cursor-not-allowed disabled:opacity-40"
                    >
                      +
                    </button>
                  </div>
                  <div className="min-w-0 flex-1 rounded-2xl bg-slate-50 px-4 py-3 text-sm font-semibold text-slate-700">
                    Qty {quantity} • Total {formatPrice(effectivePrice * quantity)}
                  </div>
                </div>
                <div className="grid gap-3 lg:grid-cols-[minmax(0,1fr)_auto_auto]">
                  <button
                    onClick={handleAddToCart}
                    disabled={isOutOfStock}
                    className="rounded-2xl bg-[#F59E0B] px-5 py-3.5 text-sm font-bold text-slate-900 transition hover:bg-[#D97706] disabled:cursor-not-allowed disabled:opacity-50"
                  >
                    <span className="inline-flex items-center justify-center space-x-2">
                      <AnimatedIcon loop="none"><ShoppingCart size={20} /></AnimatedIcon>
                      <span>{isOutOfStock ? 'Out of stock' : isAlreadyInCart ? 'Already in cart' : 'Add to cart'}</span>
                    </span>
                  </button>
                  <button
                    onClick={handleBuyNow}
                    disabled={isOutOfStock}
                    className="rounded-2xl bg-[#F59E0B] px-6 py-3.5 text-sm font-bold text-white transition hover:bg-[#D97706] disabled:cursor-not-allowed disabled:opacity-50"
                  >
                    {isOutOfStock ? 'Unavailable' : 'Buy now'}
                  </button>
                  <div className="flex gap-3">
                    <button
                      onClick={() => toggleWishlist(product)}
                      className={`rounded-2xl border p-3 transition-all ${isWishlisted ? 'border-accent text-accent bg-accent/5' : 'border-gray-200 hover:text-accent hover:border-accent'}`}
                    >
                      <AnimatedIcon loop={isWishlisted ? 'pulse' : 'float'} glow>
                        <Heart size={22} fill={isWishlisted ? "currentColor" : "none"} />
                      </AnimatedIcon>
                    </button>
                    <button
                      onClick={handleCompareToggle}
                      className={`rounded-2xl border p-3 transition-all ${isCompared ? 'border-primary text-primary bg-primary/5' : 'border-gray-200 hover:text-primary hover:border-primary'}`}
                    >
                      <AnimatedIcon loop={isCompared ? 'pulse' : 'none'}>
                        <Scale size={22} />
                      </AnimatedIcon>
                    </button>
                  </div>
                </div>
              <div className="grid gap-3 sm:grid-cols-3">
                  {serviceHighlights.map((item) => (
                    <div key={item.title} className="rounded-2xl border border-slate-100 bg-slate-50 px-4 py-4">
                      <div className="mb-2 flex h-9 w-9 items-center justify-center rounded-2xl bg-white text-primary shadow-sm">
                        {item.icon}
                      </div>
                      <p className="text-sm font-bold text-slate-900">{item.title}</p>
                      <p className="mt-1 text-xs leading-5 text-slate-500">{item.description}</p>
                    </div>
                  ))}
                </div>
              </div>
            </div>

            <div className="space-y-4 rounded-[2rem] border border-black/5 bg-white p-5 shadow-sm sm:p-6 lg:hidden">
              <div className="rounded-[2rem] border border-black/5 bg-white p-5 shadow-sm">
                <div className="flex flex-col gap-4 sm:flex-row sm:items-center sm:justify-between">
                  <div>
                    <p className="text-sm font-bold uppercase tracking-[0.22em] text-primary/70">Delivery estimator</p>
                    <h3 className="mt-2 text-xl font-bold text-slate-900">{deliveryEstimateLabel}</h3>
                    <p className="mt-1 text-sm text-slate-500">Pick your delivery zone to get a quick timing estimate before checkout.</p>
                  </div>
                  <div className="grid grid-cols-1 rounded-2xl bg-slate-100 p-1 sm:inline-flex sm:grid-cols-none">
                    <button
                      type="button"
                      onClick={() => setDeliveryZone('dhaka')}
                      className={`rounded-2xl px-4 py-2 text-sm font-semibold transition ${deliveryZone === 'dhaka' ? 'bg-white text-slate-950 shadow-sm' : 'text-slate-500'}`}
                    >
                      Inside Dhaka
                    </button>
                    <button
                      type="button"
                      onClick={() => setDeliveryZone('outside')}
                      className={`rounded-2xl px-4 py-2 text-sm font-semibold transition ${deliveryZone === 'outside' ? 'bg-white text-slate-950 shadow-sm' : 'text-slate-500'}`}
                    >
                      Outside Dhaka
                    </button>
                  </div>
                </div>
              </div>

            <div className="grid gap-4 rounded-[2rem] border border-black/5 bg-white p-5 shadow-sm sm:grid-cols-2">
                {serviceTiles.map((item) => (
                  <div key={`mobile-${item.label}`} className="rounded-2xl bg-slate-50 px-4 py-4">
                    <div className="mb-2 flex h-9 w-9 items-center justify-center rounded-2xl bg-white text-primary shadow-sm">
                      {item.icon}
                    </div>
                    <p className="text-[11px] font-bold uppercase tracking-wide text-slate-500">{item.label}</p>
                    <p className="mt-1 text-sm font-semibold text-slate-900">{item.value}</p>
                  </div>
                ))}
              </div>

              <div className="flex items-center justify-between gap-3">
                <div>
                  <p className="text-sm font-bold uppercase tracking-[0.22em] text-primary/70">About this item</p>
                  <h3 className="mt-2 text-xl font-bold text-slate-900">Product description</h3>
                </div>
              </div>
              <div
                className="space-y-4"
                dangerouslySetInnerHTML={{ __html: renderedDescription }}
              />
            </div>

            <div className="grid gap-4 rounded-[2rem] border border-black/5 bg-white p-5 shadow-sm xl:grid-cols-[1.1fr_0.9fr] sm:p-6">
              <div className="flex items-center space-x-4">
                <div className="flex h-14 w-14 items-center justify-center rounded-full bg-primary/10 text-xl font-bold text-primary">
                  {sellerInitial}
                </div>
                <div>
                  <p className="text-xs uppercase tracking-[0.22em] text-gray-500">Sold by</p>
                  <div className="mt-1 flex flex-wrap items-center gap-2">
                    <p className="font-bold text-slate-900">{sellerStoreLabel}</p>
                    {product.verification_badge ? (
                      <span className="rounded-full bg-emerald-50 px-2 py-0.5 text-[11px] font-bold text-emerald-700">
                        Verified
                      </span>
                    ) : null}
                  </div>
                  <p className="mt-1 text-sm text-slate-500">
                    {sellerRatingLabel ? `${sellerRatingLabel}/5 seller rating` : 'Trusted marketplace seller'} • {sellerResponseLabel}
                  </p>
                </div>
              </div>
              <div className="rounded-2xl bg-slate-50 p-4">
                <div className="space-y-3">
                  <div className="flex items-start justify-between gap-3 text-sm">
                    <span className="font-medium text-slate-500">Ships from</span>
                    <span className="text-right font-semibold text-slate-900">LofiMart network</span>
                  </div>
                  <div className="flex items-start justify-between gap-3 text-sm">
                    <span className="font-medium text-slate-500">Sold by</span>
                    <span className="text-right font-semibold text-slate-900">{sellerStoreLabel}</span>
                  </div>
                  <div className="flex items-start justify-between gap-3 text-sm">
                    <span className="font-medium text-slate-500">Returns</span>
                    <span className="text-right font-semibold text-slate-900">7-day support</span>
                  </div>
                  <div className="flex items-start justify-between gap-3 text-sm">
                    <span className="font-medium text-slate-500">Reply time</span>
                    <span className="text-right font-semibold text-slate-900">{sellerResponseLabel}</span>
                  </div>
                  <div className="border-t border-slate-200 pt-3">
                    <div className="grid gap-3 sm:grid-cols-2">
                      {quickFacts.map((fact) => (
                        <div key={fact.label}>
                          <p className="text-[11px] font-bold uppercase tracking-wide text-slate-500">{fact.label}</p>
                          <p className="mt-1 text-sm font-semibold text-slate-900">{fact.value}</p>
                        </div>
                      ))}
                    </div>
                  </div>
                </div>
                {product.seller_id ? (
                  <Link
                    to={`/seller-profile/${product.seller_id}`}
                    className="mt-4 inline-flex text-sm font-bold text-primary hover:underline"
                  >
                    Visit seller
                  </Link>
                ) : null}
              </div>
            </div>

            {hasSpecifications ? (
              <div className="space-y-4 rounded-[2rem] border border-black/5 bg-white p-6 shadow-sm">
                <div>
                  <p className="text-sm font-bold uppercase tracking-[0.22em] text-primary/70">Specifications</p>
                  <h3 className="mt-2 text-xl font-bold text-gray-900">Important product details</h3>
                </div>
                <div className="grid gap-3 sm:grid-cols-2">
                  {specificationItems.map((specification, index) => (
                    <div key={`${specification.label}-${index}`} className="rounded-2xl bg-slate-50 px-4 py-3">
                      <p className="text-[11px] font-bold uppercase tracking-wide text-slate-500">{specification.label}</p>
                      <p className="mt-1 text-sm font-semibold text-slate-900">{specification.value}</p>
                    </div>
                  ))}
                </div>
              </div>
            ) : null}
            <div className="rounded-[2rem] border border-black/5 bg-white/90 p-5 shadow-sm sm:p-6">
              <div className="flex flex-col items-start gap-4 sm:flex-row sm:justify-between">
                <div>
                  <p className="text-sm font-bold uppercase tracking-[0.22em] text-primary/70">Free delivery progress</p>
                  <h3 className="mt-2 text-xl font-bold text-gray-900">
                    {freeShippingRemaining > 0
                      ? `Add ${formatPrice(freeShippingRemaining)} more for free delivery`
                      : 'This item already qualifies for free delivery'}
                  </h3>
                </div>
                <span className="rounded-full bg-primary/10 px-3 py-1 text-xs font-semibold text-primary">
                  Threshold {formatPrice(freeShippingThreshold)}
                </span>
              </div>
              <div className="mt-5 h-3 overflow-hidden rounded-full bg-gray-100">
                <div
                  className="h-full rounded-full bg-[linear-gradient(90deg,#0f766e_0%,#22c55e_100%)] transition-all"
                  style={{ width: `${freeShippingProgress}%` }}
                />
              </div>
            </div>

           

        </div>
      </div>
      </div>

      {/* Reviews Section */}
      <div className="mt-20 space-y-12">
        <div className="flex flex-col gap-4 border-b border-gray-100 pb-6 sm:flex-row sm:items-center sm:justify-between">
          <h2 className="text-2xl font-bold">Customer Reviews ({reviews.length})</h2>
          <div className="flex flex-wrap items-center gap-3 sm:space-x-4">
            <div className="flex items-center text-yellow-400">
              {[...Array(5)].map((_, i) => (
                <Star key={i} size={20} fill={i < Math.floor(product.rating || 0) ? "currentColor" : "none"} />
              ))}
            </div>
            <span className="text-lg font-bold sm:text-xl">{(product.rating || 0).toFixed(1)} out of 5</span>
          </div>
        </div>

        <div className="grid grid-cols-1 gap-8 xl:grid-cols-[minmax(17rem,0.9fr)_minmax(17rem,0.9fr)_minmax(0,1.1fr)] xl:gap-12">
          {/* Review Form */}
          <div className="lg:col-span-1 space-y-6">
            <div className="rounded-3xl border border-black/5 bg-white p-6 shadow-sm">
              <p className="text-sm font-bold uppercase tracking-[0.22em] text-primary/70">Customer rating</p>
              <div className="mt-4 flex items-center gap-4">
                <span className="text-4xl font-bold text-slate-950">{(product.rating || 0).toFixed(1)}</span>
                <div>
                  <div className="flex items-center text-yellow-400">
                    {[...Array(5)].map((_, i) => (
                      <Star key={`summary-${i}`} size={18} fill={i < Math.floor(product.rating || 0) ? 'currentColor' : 'none'} />
                    ))}
                  </div>
                  <p className="mt-1 text-sm text-slate-500">{reviews.length} customer review{reviews.length === 1 ? '' : 's'}</p>
                </div>
              </div>
              <div className="mt-6 space-y-3">
                {reviewBreakdown.map((item) => (
                  <div key={`breakdown-${item.star}`} className="grid grid-cols-[48px_1fr_32px] items-center gap-3 text-sm">
                    <span className="font-medium text-slate-600">{item.star} star</span>
                    <div className="h-2 overflow-hidden rounded-full bg-slate-100">
                      <div
                        className="h-full rounded-full bg-[#f59e0b] transition-all"
                        style={{ width: `${item.percentage}%` }}
                      />
                    </div>
                    <span className="text-right text-slate-500">{item.count}</span>
                  </div>
                ))}
              </div>
            </div>

            <div className="bg-bg-light rounded-3xl p-6 space-y-6 sm:p-8">
              <h3 className="font-bold text-lg">Write a Review</h3>
              {isAuthenticated ? (
                <form onSubmit={handlePostReview} className="space-y-4">
                  {reviewError ? (
                    <div className="rounded-2xl border border-red-200 bg-red-50 px-4 py-3 text-sm text-red-700">
                      {reviewError}
                    </div>
                  ) : null}
                  <div className="space-y-2">
                    <label className="text-sm font-medium">Rating</label>
                    <div className="flex flex-wrap gap-2">
                      {[1, 2, 3, 4, 5].map(star => (
                        <button
                          key={star}
                          type="button"
                          onClick={() => setNewReview({ ...newReview, rating: star })}
                          className={`p-1 transition-colors ${star <= newReview.rating ? 'text-yellow-400' : 'text-gray-300'}`}
                        >
                          <Star size={24} fill={star <= newReview.rating ? "currentColor" : "none"} />
                        </button>
                      ))}
                    </div>
                  </div>
                  <div className="space-y-2">
                    <label className="text-sm font-medium">Your Comment</label>
                    <textarea
                      required
                      value={newReview.comment}
                      onChange={(e) => setNewReview({ ...newReview, comment: e.target.value })}
                      className="w-full bg-white border-none rounded-xl py-3 px-4 h-32 focus:ring-2 focus:ring-primary/20"
                      placeholder="What did you like or dislike?"
                    />
                  </div>
                  <button
                    type="submit"
                    disabled={submittingReview}
                    className="w-full btn-primary py-3 flex items-center justify-center space-x-2"
                  >
                    {submittingReview && <Loader2 size={18} className="animate-spin" />}
                    <span>Post Review</span>
                  </button>
                </form>
              ) : (
                <div className="text-center space-y-4">
                  <p className="text-sm text-gray-500">Please login to write a review.</p>
                  <Link to="/login" className="btn-primary inline-block px-8 py-2 text-sm">Login</Link>
                </div>
              )}
            </div>
          </div>

          {/* Review List */}
          <div className="lg:col-span-2 space-y-8">
            {reviewsLoading ? (
              <div className="rounded-3xl border border-gray-100 bg-gray-50 p-8">
                <div className="flex items-center gap-3 text-sm text-gray-500">
                  <Loader2 size={18} className="animate-spin" />
                  <span>Loading customer reviews...</span>
                </div>
              </div>
            ) : reviews.length === 0 ? (
              <div className="text-center py-12 bg-gray-50 rounded-3xl border border-dashed border-gray-200">
                <p className="text-gray-500">No reviews yet. Be the first to review this product!</p>
              </div>
            ) : (
              reviews.map((review, i) => (
                <div key={review.id} className="space-y-4">
                  <div className="flex items-center justify-between">
                    <div className="flex items-center space-x-3">
                      <div className="w-10 h-10 bg-gray-100 rounded-full flex items-center justify-center font-bold text-gray-500">
                        {review.user_name[0]}
                      </div>
                      <div>
                        <p className="font-bold text-sm">{review.user_name}</p>
                        <div className="flex items-center text-yellow-400">
                          {[...Array(5)].map((_, i) => (
                            <Star key={i} size={12} fill={i < review.rating ? "currentColor" : "none"} />
                          ))}
                        </div>
                      </div>
                    </div>
                    <span className="text-xs text-gray-400">{new Date(review.created_at).toLocaleDateString()}</span>
                  </div>
                  <p className="pl-0 text-sm leading-relaxed text-gray-600 sm:pl-[3.25rem]">
                    {review.comment}
                  </p>
                  {i < reviews.length - 1 && <div className="border-b border-gray-100 pt-4" />}
                </div>
              ))
            )}
          </div>
        </div>
      </div>

      <div className="mt-16 grid gap-4 rounded-[2rem] border border-black/5 bg-white p-5 shadow-sm sm:grid-cols-2 lg:grid-cols-4 sm:p-6">
        {mediaHighlights.map((item) => (
          <div key={`bottom-${item.title}`} className="rounded-2xl bg-slate-50 px-4 py-4">
            <div className="mb-3 flex h-10 w-10 items-center justify-center rounded-2xl bg-white text-slate-700 shadow-sm">
              {item.icon}
            </div>
            <p className="text-[11px] font-bold uppercase tracking-[0.18em] text-slate-500">{item.title}</p>
            <p className="mt-2 text-sm font-semibold leading-5 text-slate-900">{item.value}</p>
          </div>
        ))}
      </div>

      {/* AI Recommendations */}
      {showDeferredSections ? (
        <AIRecommendation productId={product.id} title="You Might Also Like" />
      ) : (
        <div className="mt-12 h-80 animate-pulse rounded-[2rem] bg-slate-100" />
      )}

      <div className="fixed inset-x-0 bottom-0 z-40 border-t border-black/5 bg-white/95 p-4 shadow-[0_-10px_30px_rgba(15,23,42,0.08)] backdrop-blur md:hidden">
        <div className="mx-auto flex max-w-7xl items-center gap-3">
          <div className="min-w-0 flex-1">
            <p className="truncate text-sm font-semibold text-slate-900">{product.name}</p>
            <div className="mt-1 flex items-center gap-2">
              <span className="text-base font-bold text-primary">{formatPrice(effectivePrice)}</span>
              {hasDiscount ? (
                <span className="text-xs text-slate-400 line-through">{formatPrice(effectiveOldPrice)}</span>
              ) : null}
            </div>
            <p className={`mt-1 text-xs font-medium ${isOutOfStock ? 'text-rose-600' : 'text-slate-500'}`}>
              {isOutOfStock ? 'Unavailable right now' : `${quantity} selected • delivery by ${estimatedDelivery}`}
            </p>
          </div>
          <button
            type="button"
            onClick={handleAddToCart}
            disabled={isOutOfStock}
            className="rounded-2xl border border-primary/15 px-4 py-3 text-sm font-semibold text-primary transition hover:bg-primary/5 disabled:cursor-not-allowed disabled:opacity-50"
          >
            Cart
          </button>
          <button
            type="button"
            onClick={handleBuyNow}
            disabled={isOutOfStock}
            className="rounded-2xl bg-accent px-4 py-3 text-sm font-semibold text-white transition hover:opacity-95 disabled:cursor-not-allowed disabled:opacity-50"
          >
            Buy now
          </button>
        </div>
      </div>

      <div ref={deferredSectionsRef} className="mt-16 space-y-16">
        <section className="rounded-[2rem] border border-black/5 bg-white p-6 shadow-sm">
          <div className="flex flex-col gap-3 md:flex-row md:items-end md:justify-between">
            <div>
              <p className="text-sm font-bold uppercase tracking-[0.22em] text-primary/70">Complete the look</p>
              <h2 className="mt-2 text-2xl font-bold text-slate-950">
                {product.category ? `More in ${product.category}` : 'More products shoppers also explore'}
              </h2>
              <p className="mt-2 text-sm text-slate-500">
                Similar picks help buyers compare faster and keep browsing without losing momentum.
              </p>
            </div>
            <Link to="/shop" className="text-sm font-bold text-primary hover:underline">
              View all products
            </Link>
          </div>

          {relatedProductsLoading ? (
            <div className="mt-6 grid gap-5 sm:grid-cols-2 xl:grid-cols-4">
              {[1, 2, 3, 4].map((item) => (
                <div key={item} className="h-80 animate-pulse rounded-[2rem] bg-slate-100" />
              ))}
            </div>
          ) : relatedProducts.length > 0 ? (
            <div className="mt-6 grid gap-5 sm:grid-cols-2 xl:grid-cols-4">
              {relatedProducts.map((relatedProduct) => (
                <ProductCard key={relatedProduct.id} product={relatedProduct} />
              ))}
            </div>
          ) : (
            <div className="mt-6 rounded-[2rem] bg-slate-50 px-5 py-6 text-sm text-slate-600">
              More products from this category will appear here as your catalog grows.
            </div>
          )}
        </section>

        {showDeferredSections ? (
          <FrequentlyBoughtTogether productId={product.id} />
        ) : (
          <div className="h-72 animate-pulse rounded-[2rem] bg-slate-100" />
        )}

        {hasSellerOfferBlock || sellerProductsLoading ? (
          <section className="rounded-[2rem] border border-black/5 bg-white p-6 shadow-sm">
            <div className="flex flex-col gap-3 md:flex-row md:items-end md:justify-between">
              <div>
                <p className="text-sm font-bold uppercase tracking-[0.22em] text-primary/70">More from this seller</p>
                <h2 className="mt-2 text-2xl font-bold text-slate-950">{sellerDisplayName} storefront picks</h2>
                <p className="mt-2 text-sm text-slate-500">
                  Compare more products from the same seller before you checkout.
                </p>
              </div>
              {product.seller_id ? (
                <Link to={`/seller-profile/${product.seller_id}`} className="text-sm font-bold text-primary hover:underline">
                  Visit seller store
                </Link>
              ) : null}
            </div>

            {sellerProductsLoading ? (
              <div className="mt-6 grid gap-5 sm:grid-cols-2 xl:grid-cols-4">
                {[1, 2, 3, 4].map((item) => (
                  <div key={`seller-skeleton-${item}`} className="h-80 animate-pulse rounded-[2rem] bg-slate-100" />
                ))}
              </div>
            ) : (
              <div className="mt-6 grid gap-5 sm:grid-cols-2 xl:grid-cols-4">
                {sellerProducts.map((sellerProduct) => (
                  <ProductCard key={`seller-${sellerProduct.id}`} product={sellerProduct} />
                ))}
              </div>
            )}
          </section>
        ) : null}
      </div>

      <ProductLightbox
        images={productMediaImages}
        initialIndex={selectedMediaIndex}
        productName={product.name}
        isOpen={showImageLightbox && hasProductImage}
        onClose={() => setShowImageLightbox(false)}
      />

      {showAR && (
        <Suspense fallback={<div className="fixed inset-0 grid place-items-center bg-black/70 text-white z-50">Loading AR Try-On...</div>}>
          <ARTryOn
            productName={product.name}
            productType={arProductType || 'accessories'}
            onClose={() => setShowAR(false)}
          />
        </Suspense>
      )}
    </div>
  );
};

import React, { useEffect, useState } from 'react';
import { useSearchParams, Link, useNavigate } from '../../../lib/navigation';
import { Search, Loader2 } from 'lucide-react';
import { Product } from '../../../types';
import { ProductCard } from '@/features/shop/components/ProductCard';
import { ProductGridSkeleton } from '@/features/shared/ui/DataSkeletons';
import { EmptyState } from '@/features/shared/ui/FeedbackState';
import { getCachedClientValue } from '../../../lib/client-cache';

export const SearchPage = () => {
  const RECENT_SEARCHES_KEY = 'amarshop_recent_searches';
  const [searchParams] = useSearchParams();
  const navigate = useNavigate();
  const query = searchParams.get('q') || '';
  const [products, setProducts] = useState<Product[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState('');
  const [searchDraft, setSearchDraft] = useState(query);
  const [recentSearches, setRecentSearches] = useState<string[]>([]);
  const [trendingSearches, setTrendingSearches] = useState<string[]>([]);

  useEffect(() => {
    setSearchDraft(query);
  }, [query]);

  useEffect(() => {
    if (typeof window === 'undefined') return;
    try {
      const stored = window.localStorage.getItem(RECENT_SEARCHES_KEY);
      if (!stored) return;
      const parsed = JSON.parse(stored);
      if (Array.isArray(parsed)) {
        setRecentSearches(parsed.filter((item): item is string => typeof item === 'string').slice(0, 6));
      }
    } catch {
      setRecentSearches([]);
    }
  }, []);

  useEffect(() => {
    if (!query.trim() || typeof window === 'undefined') return;
    const next = [query.trim(), ...recentSearches.filter((item) => item.toLowerCase() !== query.trim().toLowerCase())].slice(0, 6);
    setRecentSearches(next);
    window.localStorage.setItem(RECENT_SEARCHES_KEY, JSON.stringify(next));
  }, [query]);

  useEffect(() => {
    let cancelled = false;

    const loadDiscovery = async () => {
      try {
        const payload = await getCachedClientValue('search-discovery:v1', 10 * 60 * 1000, async () => {
          const response = await fetch('/api/search/discovery', { cache: 'no-store' });
          if (!response.ok) {
            return null;
          }
          return response.json().catch(() => null);
        });
        if (!cancelled && Array.isArray(payload?.trending)) {
          setTrendingSearches(payload.trending.filter((item: unknown): item is string => typeof item === 'string').slice(0, 8));
        }
      } catch {
        if (!cancelled) {
          setTrendingSearches([]);
        }
      }
    };

    void loadDiscovery();
    return () => {
      cancelled = true;
    };
  }, []);

  useEffect(() => {
    const controller = new AbortController();

    setLoading(true);
    setError('');

    getCachedClientValue(`search-products:${query.trim().toLowerCase()}`, 2 * 60 * 1000, async () => {
      const res = await fetch(`/api/search/products?q=${encodeURIComponent(query)}`, {
        cache: 'no-store',
      });
      const data = await res.json().catch(() => null);
      if (!res.ok) {
        throw new Error(data?.error || 'Unable to load search results right now.');
      }
      return data;
    })
      .then((data) => {
        if (controller.signal.aborted) return;
        setProducts(Array.isArray(data) ? data : []);
      })
      .catch((fetchError) => {
        if ((fetchError as Error).name !== 'AbortError') {
          setProducts([]);
          setError(fetchError instanceof Error ? fetchError.message : 'Unable to load search results right now.');
        }
      })
      .finally(() => {
        if (!controller.signal.aborted) {
          setLoading(false);
        }
      });

    return () => controller.abort();
  }, [query]);

  return (
    <div className="max-w-7xl mx-auto px-4 py-12">
      <div className="flex flex-col md:flex-row md:items-center justify-between gap-6 mb-12">
        <div>
          <h1 className="text-3xl font-bold mb-2">Search Results</h1>
          <p className="text-gray-500">
            {loading ? 'Searching...' : `Found ${products.length} results for "${query}"`}
          </p>
        </div>
        
        <form
          onSubmit={(event) => {
            event.preventDefault();
            const nextQuery = searchDraft.trim();
            if (!nextQuery) {
              navigate('/shop');
              return;
            }
            navigate(`/search?q=${encodeURIComponent(nextQuery)}`);
          }}
          className="flex w-full max-w-xl items-center gap-3 rounded-2xl border border-black/5 bg-white px-4 py-3 shadow-sm"
        >
          <Search className="h-4 w-4 text-gray-400" />
          <input
            value={searchDraft}
            onChange={(event) => setSearchDraft(event.target.value)}
            placeholder="Refine your search"
            className="min-w-0 flex-1 bg-transparent text-sm text-gray-700 outline-none placeholder:text-gray-400"
          />
          {searchDraft ? (
            <button
              type="button"
              onClick={() => setSearchDraft('')}
              className="text-xs font-semibold text-gray-500 hover:text-primary"
            >
              Clear
            </button>
          ) : null}
          <button
            type="submit"
            className="rounded-xl bg-slate-950 px-4 py-2 text-sm font-semibold text-white transition hover:bg-slate-800"
          >
            Search
          </button>
        </form>
      </div>

      {loading ? (
        <div className="space-y-6">
          <div className="surface-card-soft flex items-center gap-3 px-5 py-4">
            <Loader2 className="h-5 w-5 animate-spin text-primary" />
            <p className="text-sm font-medium text-slate-600">Searching the catalog for the closest matches...</p>
          </div>
          <ProductGridSkeleton cards={10} />
        </div>
      ) : error ? (
        <EmptyState
          tone="danger"
          icon={<Search className="h-8 w-8" />}
          title="Search is temporarily unavailable"
          description={error}
          actions={
            <Link to="/shop" className="rounded-xl bg-slate-950 px-8 py-3 font-bold text-white transition-colors hover:bg-slate-800">
              Browse All Products
            </Link>
          }
        />
      ) : products.length > 0 ? (
        <>
          <div className="mb-6 flex flex-wrap gap-2">
            <Link
              to={`/shop${query ? `?q=${encodeURIComponent(query)}` : ''}`}
              className="rounded-full bg-primary/10 px-4 py-2 text-sm font-semibold text-primary transition hover:bg-primary/15"
            >
              Open full filters
            </Link>
            <Link
              to="/shop"
              className="rounded-full bg-secondary px-4 py-2 text-sm font-semibold text-secondary-foreground transition hover:bg-primary/10 hover:text-primary"
            >
              Browse all categories
            </Link>
          </div>
          <div className="grid grid-cols-2 md:grid-cols-3 lg:grid-cols-4 xl:grid-cols-5 gap-6">
            {products.map((product) => (
              <div key={product.id}>
                <ProductCard product={product} />
              </div>
            ))}
          </div>
        </>
      ) : (
        <div className="space-y-8">
          <EmptyState
            tone="soft"
            icon={<Search className="h-8 w-8" />}
            title="No results found"
            description={`We couldn't find anything matching "${query}". Try a different keyword, category, or brand.`}
            actions={
              <>
                <Link to="/shop" className="rounded-xl bg-slate-950 px-8 py-3 font-bold text-white transition-colors hover:bg-slate-800">
                  Browse All Products
                </Link>
                <Link
                  to="/categories"
                  className="rounded-xl border border-gray-200 bg-white px-8 py-3 font-bold text-slate-700 transition-colors hover:bg-gray-50"
                >
                  Explore Categories
                </Link>
              </>
            }
          />
          <div className="text-center">
            {trendingSearches.length > 0 || recentSearches.length > 0 ? (
              <div className="space-y-4">
                {trendingSearches.length > 0 ? (
                  <div>
                    <p className="mb-3 text-xs font-bold uppercase tracking-[0.2em] text-gray-400">Trending searches</p>
                    <div className="flex flex-wrap justify-center gap-2">
                      {trendingSearches.map((term) => (
                        <button
                          key={term}
                          onClick={() => navigate(`/search?q=${encodeURIComponent(term)}`)}
                          className="rounded-full bg-primary/10 px-4 py-2 text-sm font-semibold text-primary transition hover:bg-primary/15"
                        >
                          {term}
                        </button>
                      ))}
                    </div>
                  </div>
                ) : null}
                {recentSearches.length > 0 ? (
                  <div>
                    <p className="mb-3 text-xs font-bold uppercase tracking-[0.2em] text-gray-400">Recent searches</p>
                    <div className="flex flex-wrap justify-center gap-2">
                      {recentSearches.map((term) => (
                        <button
                          key={term}
                          onClick={() => navigate(`/search?q=${encodeURIComponent(term)}`)}
                          className="rounded-full bg-white px-4 py-2 text-sm font-semibold text-slate-700 transition hover:bg-slate-100"
                        >
                          {term}
                        </button>
                      ))}
                    </div>
                  </div>
                ) : null}
              </div>
            ) : null}
          </div>
        </div>
      )}
    </div>
  );
};

import React, { useCallback, useEffect, useMemo, useRef, useState } from 'react';
import { useSearchParams, Link } from '../../../lib/navigation';
import {
  ChevronDown,
  LayoutGrid,
  List,
  ChevronRight,
  Search,
  Star,
  Sparkles,
  Scale,
  SlidersHorizontal,
  X,
  RotateCcw,
  PackageSearch,
} from 'lucide-react';
import { ProductCard } from '@/features/shop/components/ProductCard';
import { Product } from '../../../types';
import { useCompare } from '../../../features/shop/state/CompareContext';
import { getCachedClientValue } from '../../../lib/client-cache';
import { ProductQuickView } from '../../../features/shop/components/ProductQuickView';

type ShopCategory = {
  id: string | number;
  name: string;
};

type SortOption = 'featured' | 'price-low' | 'price-high' | 'rating' | 'discount';
type ViewMode = 'grid' | 'list';

const DEFAULT_MAX_PRICE = 50000;
const MIN_PRICE = 500;
const SEARCH_DEBOUNCE_MS = 300;
const PRICE_DEBOUNCE_MS = 180;

function getProductList(payload: unknown): Product[] {
  if (Array.isArray(payload)) return payload;
  if (!payload || typeof payload !== 'object') return [];

  const record = payload as Record<string, unknown>;
  if (Array.isArray(record.products)) return record.products;
  if (Array.isArray(record.items)) return record.items;
  if (Array.isArray(record.data)) return record.data;
  const data = record.data && typeof record.data === 'object' ? (record.data as Record<string, unknown>) : null;
  if (Array.isArray(data?.products)) return data.products;
  if (Array.isArray(data?.items)) return data.items;

  return [];
}

function getCategoryList(payload: unknown): ShopCategory[] {
  if (Array.isArray(payload)) return payload;
  if (!payload || typeof payload !== 'object') return [];

  const record = payload as Record<string, unknown>;
  if (Array.isArray(record.categories)) return record.categories;
  if (Array.isArray(record.data)) return record.data;
  const data = record.data && typeof record.data === 'object' ? (record.data as Record<string, unknown>) : null;
  if (Array.isArray(data?.categories)) return data.categories;

  return [];
}

function normalizeSort(value: string | null): SortOption {
  return value === 'price-low' || value === 'price-high' || value === 'rating' || value === 'discount' ? value : 'featured';
}

function normalizeViewMode(value: string | null): ViewMode {
  return value === 'list' ? 'list' : 'grid';
}

function normalizeRating(value: string | null) {
  const rating = Number(value || 0);
  return Number.isFinite(rating) ? Math.max(0, Math.min(5, Math.round(rating))) : 0;
}

function normalizePrice(value: string | null) {
  const price = Number(value || DEFAULT_MAX_PRICE);
  return Number.isFinite(price) ? Math.max(MIN_PRICE, Math.min(DEFAULT_MAX_PRICE, Math.round(price))) : DEFAULT_MAX_PRICE;
}

function getDiscountAmount(product: Product) {
  return Math.max(0, Number(product.old_price || 0) - Number(product.price || 0));
}

export const ShopPage = () => {
  const { items: compareItems, clearCompare } = useCompare();
  const [searchParams, setSearchParams] = useSearchParams();
  const [products, setProducts] = useState<Product[]>([]);
  const [categories, setCategories] = useState<ShopCategory[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState('');
  const [searchDraft, setSearchDraft] = useState(() => searchParams.get('q') || '');
  const [maxPriceDraft, setMaxPriceDraft] = useState(() => normalizePrice(searchParams.get('price')));
  const [mobileFiltersOpen, setMobileFiltersOpen] = useState(false);
  const [quickViewProduct, setQuickViewProduct] = useState<Product | null>(null);
  const searchInputRef = useRef<HTMLInputElement | null>(null);

  const categoryParam = searchParams.get('category') || '';
  const queryParam = searchParams.get('q') || '';
  const sortBy = normalizeSort(searchParams.get('sort'));
  const selectedRating = normalizeRating(searchParams.get('rating'));
  const maxPrice = normalizePrice(searchParams.get('price'));
  const viewMode = normalizeViewMode(searchParams.get('view'));

  const loadShopData = useCallback((signal: AbortSignal) => {
    const controller = new AbortController();
    const abortForwarder = () => controller.abort();
    signal.addEventListener('abort', abortForwarder, { once: true });

    setLoading(true);
    setError('');

    return getCachedClientValue('shop-page:v2', 5 * 60 * 1000, async () => {
      const res = await fetch('/api/shop-page', { cache: 'force-cache', signal: controller.signal });
      const data = await res.json().catch(() => null);
      if (!res.ok) {
        throw new Error(data?.error || 'Unable to load shop products right now.');
      }
      return data;
    })
      .then((data) => {
        if (controller.signal.aborted) return;
        setCategories(getCategoryList(data));
        setProducts(getProductList(data));
      })
      .catch((fetchError) => {
        if ((fetchError as Error).name !== 'AbortError') {
          setCategories([]);
          setProducts([]);
          setError(fetchError instanceof Error ? fetchError.message : 'Unable to load shop products right now.');
        }
      })
      .finally(() => {
        if (!controller.signal.aborted) {
          setLoading(false);
        }
        signal.removeEventListener('abort', abortForwarder);
      });
  }, []);

  useEffect(() => {
    const controller = new AbortController();

    queueMicrotask(() => {
      if (!controller.signal.aborted) {
        void loadShopData(controller.signal);
      }
    });

    return () => controller.abort();
  }, [loadShopData]);

  useEffect(() => {
    let active = true;
    queueMicrotask(() => {
      if (active) {
        setSearchDraft(queryParam || '');
      }
    });
    return () => {
      active = false;
    };
  }, [queryParam]);

  useEffect(() => {
    let active = true;
    queueMicrotask(() => {
      if (active) {
        setMaxPriceDraft(maxPrice);
      }
    });
    return () => {
      active = false;
    };
  }, [maxPrice]);

  const updateUrlParams = useCallback(
    (
      updates: Record<string, string | number | null | undefined>,
      options: { replace?: boolean; scroll?: boolean } = {},
    ) => {
      const nextParams = new URLSearchParams(searchParams.toString());

      Object.entries(updates).forEach(([key, value]) => {
        if (value === null || typeof value === 'undefined' || value === '') {
          nextParams.delete(key);
          return;
        }
        nextParams.set(key, String(value));
      });

      setSearchParams(nextParams, { scroll: false, ...options });
    },
    [searchParams, setSearchParams],
  );

  useEffect(() => {
    const normalizedDraft = searchDraft.trim();
    if (normalizedDraft === queryParam) return undefined;

    const timeoutId = window.setTimeout(() => {
      updateUrlParams({ q: normalizedDraft || null }, { replace: true, scroll: false });
    }, SEARCH_DEBOUNCE_MS);

    return () => window.clearTimeout(timeoutId);
  }, [queryParam, searchDraft, updateUrlParams]);

  useEffect(() => {
    if (maxPriceDraft === maxPrice) return undefined;

    const timeoutId = window.setTimeout(() => {
      updateUrlParams({ price: maxPriceDraft < DEFAULT_MAX_PRICE ? maxPriceDraft : null }, { replace: true, scroll: false });
    }, PRICE_DEBOUNCE_MS);

    return () => window.clearTimeout(timeoutId);
  }, [maxPrice, maxPriceDraft, updateUrlParams]);

  const safeProducts = useMemo(() => getProductList(products), [products]);
  const safeCategories = useMemo(() => getCategoryList(categories), [categories]);
  const safeCompareItems = useMemo(() => (Array.isArray(compareItems) ? compareItems : []), [compareItems]);
  const normalizedQuery = useMemo(() => queryParam.trim().toLowerCase(), [queryParam]);
  const categoryOptions = useMemo(
    () =>
      safeCategories.length > 0
        ? safeCategories
        : Array.from(new Set(safeProducts.map((product) => product.category).filter(Boolean))).map((name) => ({
            id: name,
            name,
          })),
    [safeCategories, safeProducts],
  );

  const filteredProducts = useMemo(() => {
    const filtered = safeProducts.filter((product) => {
      if (categoryParam && product.category !== categoryParam) {
        return false;
      }

      if (normalizedQuery) {
        const productName = product.name?.toLowerCase() || '';
        const productCategory = product.category?.toLowerCase() || '';
        const productDescription = product.description?.toLowerCase() || '';
        const sellerName = (product.store_name || product.seller_name || '').toLowerCase();
        const matchesQuery =
          productName.includes(normalizedQuery) ||
          productCategory.includes(normalizedQuery) ||
          productDescription.includes(normalizedQuery) ||
          sellerName.includes(normalizedQuery);

        if (!matchesQuery) {
          return false;
        }
      }

      if (selectedRating > 0 && Number(product.rating || 0) < selectedRating) {
        return false;
      }

      if (Number(product.price || 0) > maxPrice) {
        return false;
      }

      return true;
    });

    return filtered
      .map((product, index) => ({ product, index }))
      .sort((a, b) => {
        let result = 0;
        switch (sortBy) {
          case 'price-low':
            result = Number(a.product.price || 0) - Number(b.product.price || 0);
            break;
          case 'price-high':
            result = Number(b.product.price || 0) - Number(a.product.price || 0);
            break;
          case 'rating':
            result = Number(b.product.rating || 0) - Number(a.product.rating || 0);
            break;
          case 'discount':
            result = getDiscountAmount(b.product) - getDiscountAmount(a.product);
            break;
          default:
            result = Number(b.product.reviews_count || 0) - Number(a.product.reviews_count || 0);
        }
        return result || a.index - b.index;
      })
      .map(({ product }) => product);
  }, [categoryParam, maxPrice, normalizedQuery, safeProducts, selectedRating, sortBy]);

  const featuredCategories = useMemo(() => categoryOptions.slice(0, 5), [categoryOptions]);
  const priceProgress = useMemo(() => Math.max(0, Math.min(100, (maxPriceDraft / DEFAULT_MAX_PRICE) * 100)), [maxPriceDraft]);
  const activeFiltersCount = useMemo(
    () =>
      Number(Boolean(categoryParam)) +
      Number(Boolean(queryParam)) +
      Number(selectedRating > 0) +
      Number(maxPrice < DEFAULT_MAX_PRICE),
    [categoryParam, maxPrice, queryParam, selectedRating],
  );

  const updateSearchQuery = useCallback(
    (nextQuery?: string, replace = false) => {
      const normalizedSearch = nextQuery?.trim();
      updateUrlParams({ q: normalizedSearch || null }, { replace, scroll: false });
    },
    [updateUrlParams],
  );

  const updateCategoryFilter = useCallback(
    (categoryName?: string) => {
      updateUrlParams({ category: categoryName || null }, { scroll: false });
    },
    [updateUrlParams],
  );

  const updateRatingFilter = useCallback(
    (rating: number) => {
      updateUrlParams({ rating: rating > 0 ? rating : null }, { scroll: false });
    },
    [updateUrlParams],
  );

  const updateSort = useCallback(
    (value: string) => {
      updateUrlParams({ sort: normalizeSort(value) === 'featured' ? null : normalizeSort(value) }, { scroll: false });
    },
    [updateUrlParams],
  );

  const updateViewMode = useCallback(
    (value: ViewMode) => {
      updateUrlParams({ view: value === 'grid' ? null : value }, { replace: true, scroll: false });
    },
    [updateUrlParams],
  );

  const clearAllFilters = useCallback(() => {
    setSearchDraft('');
    setMaxPriceDraft(DEFAULT_MAX_PRICE);
    updateUrlParams({ category: null, q: null, rating: null, price: null }, { scroll: false });
  }, [updateUrlParams]);

  const openMobileFilters = useCallback(() => setMobileFiltersOpen(true), []);
  const closeMobileFilters = useCallback(() => setMobileFiltersOpen(false), []);
  const openQuickView = useCallback((product: Product) => setQuickViewProduct(product), []);
  const closeQuickView = useCallback(() => setQuickViewProduct(null), []);
  const retryLoad = useCallback(() => {
    const controller = new AbortController();
    void loadShopData(controller.signal);
  }, [loadShopData]);

  const activeFilterChips = useMemo(
    () =>
      [
        categoryParam
          ? {
              key: 'category',
              label: `Category: ${categoryParam}`,
              onRemove: () => updateCategoryFilter(undefined),
            }
          : null,
        queryParam
          ? {
              key: 'query',
              label: `Search: ${queryParam}`,
              onRemove: () => {
                setSearchDraft('');
                updateSearchQuery(undefined);
              },
            }
          : null,
        selectedRating > 0
          ? {
              key: 'rating',
              label: `${selectedRating}+ stars`,
              onRemove: () => updateRatingFilter(0),
            }
          : null,
        maxPrice < DEFAULT_MAX_PRICE
          ? {
              key: 'price',
              label: `Up to ${maxPrice.toLocaleString()} BDT`,
              onRemove: () => {
                setMaxPriceDraft(DEFAULT_MAX_PRICE);
                updateUrlParams({ price: null }, { scroll: false });
              },
            }
          : null,
      ].filter(Boolean) as Array<{ key: string; label: string; onRemove: () => void }>,
    [categoryParam, maxPrice, queryParam, selectedRating, updateCategoryFilter, updateRatingFilter, updateSearchQuery, updateUrlParams],
  );

  const productGridClass = useMemo(
    () =>
      viewMode === 'grid'
        ? 'grid grid-cols-2 gap-3 sm:gap-4 md:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 2xl:grid-cols-5'
        : 'grid grid-cols-1 gap-4',
    [viewMode],
  );

  const filterContent = (
    <div className="content-stack">
    

      <div className="surface-card p-5 sm:p-6">
        <h3 className="mb-4 flex items-center justify-between text-base font-bold sm:text-lg">
          Categories
          <ChevronDown size={16} />
        </h3>
        <div className="space-y-2">
          {categoryOptions.map((cat) => (
            <label key={cat.id} className="group flex min-h-11 cursor-pointer items-center gap-3 rounded-xl px-2 transition hover:bg-primary/5">
              <input
                type="checkbox"
                checked={categoryParam === cat.name}
                onChange={() => updateCategoryFilter(categoryParam === cat.name ? undefined : cat.name)}
                className="rounded text-primary focus:ring-primary"
              />
              <span className="text-sm font-medium text-gray-600 transition-colors group-hover:text-primary">{cat.name}</span>
            </label>
          ))}
        </div>
      </div>

      <div className="surface-card p-5 sm:p-6">
        <h3 className="mb-4 text-base font-bold sm:text-lg">Price Range</h3>
        <input
          type="range"
          className="w-full accent-primary"
          min="5"
          max="50000"
          step="500"
          value={maxPriceDraft}
          onChange={(e) => setMaxPriceDraft(Number(e.target.value))}
          aria-label="Maximum product price"
        />
        
        <div className="mt-2 flex justify-between text-xs text-gray-500">
          <span>0 BDT</span>
          <span>Up to {maxPriceDraft.toLocaleString()} BDT</span>
        </div>
      </div>

      <div className="surface-card p-5 sm:p-6">
        <h3 className="mb-4 text-base font-bold sm:text-lg">Rating</h3>
        <div className="space-y-2">
          {[5, 4, 3, 2, 1].map((star) => (
            <label key={star} className="flex min-h-11 cursor-pointer items-center gap-3 rounded-xl px-2 transition hover:bg-amber-50">
              <input
                type="checkbox"
                checked={selectedRating === star}
                onChange={() => updateRatingFilter(selectedRating === star ? 0 : star)}
                className="rounded text-primary focus:ring-primary"
              />
              <span className="flex items-center gap-1 text-sm text-gray-600">
                <Star size={14} fill="currentColor" className="text-amber-400" />
                {star} Stars & Up
              </span>
            </label>
          ))}
        </div>
      </div>
    </div>
  );

  return (
    <div className="page-shell scroll-smooth py-5 md:py-10 xl:py-12">
      <nav className="mb-6 hidden items-center space-x-2 text-sm text-gray-500 md:flex" aria-label="Breadcrumb">
        <Link to="/" className="transition-colors hover:text-primary">Home</Link>
        <ChevronRight size={14} />
        <Link to="/shop" className="transition-colors hover:text-primary">Shop</Link>
        {categoryParam ? (
          <>
            <ChevronRight size={14} />
            <span className="font-medium text-gray-900">{categoryParam}</span>
          </>
        ) : null}
        {queryParam ? (
          <>
            <ChevronRight size={14} />
            <span className="font-medium italic text-gray-900">Search: "{queryParam}"</span>
          </>
        ) : null}
      </nav>

      <div className="mb-4 flex items-center gap-3 md:hidden">
        <button
          type="button"
          onClick={openMobileFilters}
          aria-label="Open product filters"
          className="inline-flex min-h-12 items-center gap-2 rounded-2xl border border-black/5 bg-white px-4 py-3 text-sm font-semibold text-slate-800 shadow-sm transition active:scale-[0.98]"
        >
          <SlidersHorizontal size={16} />
          Filters
          {activeFiltersCount > 0 ? (
            <span className="rounded-full bg-primary px-2 py-0.5 text-[11px] font-bold text-white">{activeFiltersCount}</span>
          ) : null}
        </button>
        <div className="surface-card min-w-0 flex-1 px-4 py-3 text-sm text-slate-500">
          {filteredProducts.length} items
        </div>
      </div>

      {mobileFiltersOpen ? (
        <div
          className="fixed inset-0 z-[70] bg-slate-950/45 backdrop-blur-sm md:hidden"
          onClick={closeMobileFilters}
          role="presentation"
        >
          <div
            className="absolute inset-x-0 bottom-0 max-h-[88dvh] overflow-y-auto rounded-t-[2rem] bg-white p-5 shadow-2xl transition-transform duration-200 ease-out"
            onClick={(event) => event.stopPropagation()}
            role="dialog"
            aria-modal="true"
            aria-label="Product filters"
          >
            <div className="mb-5 flex items-center justify-between">
              <div>
                <p className="text-xs font-bold uppercase tracking-[0.24em] text-primary/70">Smart Filters</p>
                <h2 className="text-xl font-bold text-gray-900">Refine your results</h2>
              </div>
              <button
                type="button"
                onClick={closeMobileFilters}
                className="flex h-11 w-11 items-center justify-center rounded-full bg-slate-100 text-slate-600 transition hover:bg-slate-200 focus:outline-none focus:ring-2 focus:ring-primary/30"
                aria-label="Close filters"
              >
                <X size={18} />
              </button>
            </div>

            {filterContent}

            <div className="sticky bottom-0 -mx-5 mt-6 border-t border-slate-200 bg-white px-5 pb-[max(1rem,env(safe-area-inset-bottom))] pt-4">
              <button
                type="button"
                onClick={closeMobileFilters}
                className="min-h-12 w-full rounded-2xl bg-slate-950 px-4 py-3 text-sm font-semibold text-white shadow-lg shadow-slate-950/20 transition hover:bg-slate-800 active:scale-[0.99]"
              >
                Show {filteredProducts.length} products
              </button>
            </div>
          </div>
        </div>
      ) : null}

      <div className="flex flex-col gap-6 lg:flex-row lg:gap-8">
        <aside className="hidden w-full md:block lg:w-72 lg:shrink-0 xl:w-80">
          {filterContent}
        </aside>

        <main className="min-w-0 flex-1" aria-live="polite">
          {safeCompareItems.length > 0 ? (
            <div className="sticky top-3 z-30 mb-6 rounded-[1.5rem] border border-primary/10 bg-white/95 p-4 shadow-lg shadow-primary/5 backdrop-blur sm:flex sm:items-center sm:justify-between md:static md:rounded-[1.75rem] md:bg-primary/5 md:shadow-none">
              <div className="flex items-center gap-3">
                <div className="rounded-2xl bg-white p-3 text-primary shadow-sm">
                  <Scale size={18} />
                </div>
                <div>
                  <p className="text-sm font-semibold text-slate-900">{safeCompareItems.length} product{safeCompareItems.length === 1 ? '' : 's'} ready to compare</p>
                  <p className="text-xs text-slate-500">Open side-by-side comparison before making the final call.</p>
                </div>
              </div>
              <div className="mt-4 flex gap-3 sm:mt-0">
                <button
                  type="button"
                  onClick={clearCompare}
                  className="inline-flex min-h-11 flex-1 items-center justify-center gap-2 rounded-2xl border border-slate-200 bg-white px-4 py-3 text-sm font-semibold text-slate-700 transition hover:bg-slate-50 focus:outline-none focus:ring-2 focus:ring-primary/25 sm:flex-none"
                  aria-label="Clear compare list"
                >
                  <X size={16} />
                  <span>Clear</span>
                </button>
                <Link
                  to="/compare"
                  className="inline-flex min-h-11 flex-1 items-center justify-center gap-2 rounded-2xl bg-slate-950 px-4 py-3 text-sm font-semibold text-white transition hover:bg-slate-800 focus:outline-none focus:ring-2 focus:ring-primary/25 sm:flex-none"
                >
                  <Scale size={16} />
                  <span>Compare now</span>
                </Link>
              </div>
            </div>
          ) : null}

          <div className="surface-card mb-6 p-4 sm:p-6">
            <div className="mb-5 flex flex-col gap-4 lg:flex-row lg:items-center lg:justify-between">
              <div className="space-y-2">
                
                <h1 className="text-2xl font-bold text-gray-900 sm:text-3xl">
                  {categoryParam ? `${categoryParam} collection` : 'All products'}
                </h1>
