                    {cat.name}
                  </button>
                ))}
              </div>
            </div>
          )}
        </main>
      </div>

      {quickViewProduct && (
        <ProductQuickView
          product={quickViewProduct}
          isOpen={!!quickViewProduct}
          onClose={closeQuickView}
        />
      )}
    </div>
  );
};

import React, { createContext, useContext, useState, useEffect } from 'react';
import { CartItem, Product } from '@/types';
import { useUser } from '@/features/shared/state/UserContext';
import api from '@/lib/api';

interface Coupon {
  code: string;
  discount_type: 'percentage' | 'flat';
  discount_value: number;
  seller_id?: string | null;
  seller_name?: string | null;
}

interface CartContextType {
  items: CartItem[];
  addToCart: (product: Product, quantity?: number) => void;
  setCartItemQuantity: (product: Product, quantity: number) => void;
  replaceCart: (nextItems: CartItem[]) => void;
  removeFromCart: (productId: number, variantKey?: string) => void;
  updateQuantity: (productId: number, quantity: number, variantKey?: string) => void;
  clearCart: () => void;
  applyCoupon: (coupon: Coupon) => void;
  removeCoupon: () => void;
  totalItems: number;
  subtotal: number;
  totalPrice: number;
  discountAmount: number;
  appliedCoupon: Coupon | null;
  isReady: boolean;
}

const CartContext = createContext<CartContextType | undefined>(undefined);

const CART_STORAGE_KEY = 'cart';
const CART_COUPON_STORAGE_KEY = 'cart_coupon';
const GUEST_CART_SNAPSHOT_KEY = 'guest_cart_snapshot';
const GUEST_CART_SNAPSHOT_OWNER_KEY = 'guest_cart_snapshot_owner';
const GUEST_CART_COUPON_SNAPSHOT_KEY = 'guest_cart_coupon_snapshot';
const isDev = process.env.NODE_ENV !== 'production';

function readStoredCart() {
  if (typeof window === 'undefined') {
    return [] as CartItem[];
  }

  try {
    const saved = localStorage.getItem(CART_STORAGE_KEY);
    const parsed = saved ? JSON.parse(saved) : [];
    return Array.isArray(parsed) ? (parsed as CartItem[]) : [];
  } catch (error) {
    if (isDev) {
      console.warn('Failed to hydrate cart from storage:', error);
    }
    return [];
  }
}

function readStoredCoupon(): Coupon | null {
  if (typeof window === 'undefined') {
    return null;
  }

  try {
    const saved = localStorage.getItem(CART_COUPON_STORAGE_KEY);
    if (!saved) return null;
    const parsed = JSON.parse(saved);
    if (!parsed || typeof parsed !== 'object' || typeof parsed.code !== 'string') {
      return null;
    }
    return parsed as Coupon;
  } catch (error) {
    if (isDev) {
      console.warn('Failed to hydrate coupon from storage:', error);
    }
    return null;
  }
}

function saveGuestCartSnapshot(userId: string, items: CartItem[], coupon: Coupon | null) {
  if (typeof window === 'undefined') return;
  localStorage.setItem(GUEST_CART_SNAPSHOT_OWNER_KEY, userId);
  localStorage.setItem(GUEST_CART_SNAPSHOT_KEY, JSON.stringify(items));
  if (coupon) {
    localStorage.setItem(GUEST_CART_COUPON_SNAPSHOT_KEY, JSON.stringify(coupon));
  } else {
    localStorage.removeItem(GUEST_CART_COUPON_SNAPSHOT_KEY);
  }
}

function restoreGuestCartSnapshot() {
  if (typeof window === 'undefined') {
    return { items: [] as CartItem[], coupon: null as Coupon | null };
  }

  try {
    const savedItems = JSON.parse(localStorage.getItem(GUEST_CART_SNAPSHOT_KEY) || '[]');
    const savedCouponRaw = localStorage.getItem(GUEST_CART_COUPON_SNAPSHOT_KEY);
    const savedCoupon = savedCouponRaw ? (JSON.parse(savedCouponRaw) as Coupon) : null;
    localStorage.setItem(CART_STORAGE_KEY, JSON.stringify(Array.isArray(savedItems) ? savedItems : []));
    if (savedCoupon) {
      localStorage.setItem(CART_COUPON_STORAGE_KEY, JSON.stringify(savedCoupon));
    } else {
      localStorage.removeItem(CART_COUPON_STORAGE_KEY);
    }
    localStorage.removeItem(GUEST_CART_SNAPSHOT_KEY);
    localStorage.removeItem(GUEST_CART_SNAPSHOT_OWNER_KEY);
    localStorage.removeItem(GUEST_CART_COUPON_SNAPSHOT_KEY);
    return { items: Array.isArray(savedItems) ? (savedItems as CartItem[]) : [], coupon: savedCoupon };
  } catch {
    localStorage.removeItem(GUEST_CART_SNAPSHOT_KEY);
    localStorage.removeItem(GUEST_CART_SNAPSHOT_OWNER_KEY);
    localStorage.removeItem(GUEST_CART_COUPON_SNAPSHOT_KEY);
    return { items: [] as CartItem[], coupon: null as Coupon | null };
  }
}

function buildCartItemKey(item: Pick<CartItem, 'id' | 'selected_variant_key'>) {
  return `${item.id}:${item.selected_variant_key || ''}`;
}

function mergeCartItems(serverItems: CartItem[], guestItems: CartItem[]) {
  const merged = new Map<string, CartItem>();

  for (const item of serverItems) {
    merged.set(buildCartItemKey(item), { ...item });
  }

  for (const item of guestItems) {
    const key = buildCartItemKey(item);
    const existing = merged.get(key);

    if (existing) {
      merged.set(key, {
        ...existing,
        ...item,
        quantity: Math.max(1, existing.quantity, item.quantity),
      });
      continue;
    }

    merged.set(key, { ...item, quantity: Math.max(1, item.quantity) });
  }

  return Array.from(merged.values());
}

export const CartProvider: React.FC<{ children: React.ReactNode }> = ({ children }) => {
  const { token, user, isAuthenticated } = useUser(); // Access token from UserContext
  const [items, setItems] = useState<CartItem[]>([]);
  const [appliedCoupon, setAppliedCoupon] = useState<Coupon | null>(null);
  const [isReady, setIsReady] = useState(false);
  const [hasSyncedServerCart, setHasSyncedServerCart] = useState(false);

  useEffect(() => {
    if (typeof window === 'undefined') {
      return;
    }

    setItems(readStoredCart());
    setAppliedCoupon(readStoredCoupon());
    setIsReady(true);
  }, []);

  useEffect(() => {
    const syncGuestCartIntoAccount = async () => {
      if (!isReady) {
        return;
      }

      if (!isAuthenticated || !token || !user) {
        setHasSyncedServerCart(false);
        const snapshotOwner = typeof window !== 'undefined' ? localStorage.getItem(GUEST_CART_SNAPSHOT_OWNER_KEY) : null;
        if (snapshotOwner) {
          const restored = restoreGuestCartSnapshot();
          setItems(restored.items);
          setAppliedCoupon(restored.coupon);
        } else {
          setItems(readStoredCart());
          setAppliedCoupon(readStoredCoupon());
        }
        return;
      }

      const guestItems = readStoredCart();
      const guestCoupon = readStoredCoupon();
      const existingSnapshotOwner = typeof window !== 'undefined' ? localStorage.getItem(GUEST_CART_SNAPSHOT_OWNER_KEY) : null;
      if (existingSnapshotOwner !== String(user.id)) {
        saveGuestCartSnapshot(String(user.id), guestItems, guestCoupon);
      }

      try {
        const res = await api.get('/cart');
        const serverItems = Array.isArray(res.data?.items) ? (res.data.items as CartItem[]) : [];
        const mergedItems = mergeCartItems(serverItems, guestItems);
        const needsServerUpdate =
          mergedItems.length !== serverItems.length ||
          mergedItems.some((item, index) => {
            const serverItem = serverItems[index];
            return !serverItem || buildCartItemKey(serverItem) !== buildCartItemKey(item) || serverItem.quantity !== item.quantity;
          });

        if (needsServerUpdate) {
          await api.put('/cart', { items: mergedItems });
        }

        setItems(mergedItems);
        localStorage.setItem(CART_STORAGE_KEY, JSON.stringify(mergedItems));
      } catch (error) {
        const status = (error as any)?.response?.status;
        if (status !== 401 && status !== 403) {
          if (isDev) {
            console.warn('Server cart load failed:', error);
          }
        }
        setItems(guestItems);
      } finally {
        setHasSyncedServerCart(true);
      }
    };

    void syncGuestCartIntoAccount();
  }, [isAuthenticated, isReady, token, user]);

  // Hybrid: Optimistic localStorage + API sync
  useEffect(() => {
    if (!isReady) {
      return;
    }

    if (items.length === 0 && appliedCoupon) {
      setAppliedCoupon(null);
      return;
    }

    localStorage.setItem(CART_STORAGE_KEY, JSON.stringify(items));
    if (appliedCoupon) {
      localStorage.setItem(CART_COUPON_STORAGE_KEY, JSON.stringify(appliedCoupon));
    } else {
      localStorage.removeItem(CART_COUPON_STORAGE_KEY);
    }

    if (isAuthenticated && token && user && hasSyncedServerCart) {
      void (async () => {
        try {
          await api.put('/cart', { items });
        } catch (error) {
          const status = (error as any)?.response?.status;
          if (status !== 401 && status !== 403) {
            if (isDev) {
              console.warn('Cart sync failed (offline fallback):', error);
            }
          }
        }
      })();
    }
  }, [appliedCoupon, hasSyncedServerCart, isAuthenticated, isReady, items, token, user]);

  const addToCart = (product: Product, quantity: number = 1) => {
    setItems(prev => {
      const existing = prev.find(
        item => item.id === product.id && (item.selected_variant_key || '') === (product.selected_variant_key || ''),
      );
      if (existing) {
        return prev.map(item =>
          item.id === product.id && (item.selected_variant_key || '') === (product.selected_variant_key || '')
            ? { ...item, quantity: item.quantity + quantity }
            : item
        );
      }
      return [...prev, { ...product, quantity }];
    });
  };

  const setCartItemQuantity = (product: Product, quantity: number) => {
    const normalizedQuantity = Math.max(1, quantity);
    setItems(prev => {
      const existing = prev.find(
        item => item.id === product.id && (item.selected_variant_key || '') === (product.selected_variant_key || ''),
      );
      if (existing) {
        return prev.map(item =>
          item.id === product.id && (item.selected_variant_key || '') === (product.selected_variant_key || '')
            ? { ...item, quantity: normalizedQuantity }
            : item
        );
      }
      return [...prev, { ...product, quantity: normalizedQuantity }];
    });
  };

  const replaceCart = (nextItems: CartItem[]) => {
    setItems(
      Array.isArray(nextItems)
        ? nextItems.map((item) => ({
            ...item,
            quantity: Math.max(1, Number(item.quantity) || 1),
          }))
        : [],
    );
    setAppliedCoupon(null);
  };

  const removeFromCart = (productId: number, variantKey?: string) => {
    setItems(prev => prev.filter(item => !(item.id === productId && (item.selected_variant_key || '') === (variantKey || ''))));
  };

  const updateQuantity = (productId: number, quantity: number, variantKey?: string) => {
    if (quantity < 1) return;
    setItems(prev => prev.map(item =>
      item.id === productId && (item.selected_variant_key || '') === (variantKey || '') ? { ...item, quantity } : item
    ));
  };

  const clearCart = () => {
    setItems([]);
    setAppliedCoupon(null);
  };

  const applyCoupon = (coupon: Coupon) => setAppliedCoupon(coupon);
  const removeCoupon = () => setAppliedCoupon(null);

  const totalItems = items.reduce((sum, item) => sum + item.quantity, 0);
  const subtotal = items.reduce((sum, item) => sum + item.price * item.quantity, 0);

  let discountAmount = 0;
  if (appliedCoupon) {
    if (appliedCoupon.discount_type === 'percentage') {
      discountAmount = (subtotal * appliedCoupon.discount_value) / 100;
    } else {
      discountAmount = appliedCoupon.discount_value;
    }
  }

  const totalPrice = Math.max(0, subtotal - discountAmount);

  return (
    <CartContext.Provider value={{ 
      items, 
      addToCart, 
      setCartItemQuantity,
      replaceCart,
      removeFromCart, 
      updateQuantity, 
      clearCart, 
      applyCoupon,
      removeCoupon,
      totalItems, 
      subtotal,
      totalPrice,
      discountAmount,
      appliedCoupon,
      isReady
    }}>
      {children}
    </CartContext.Provider>
  );
};

export const useCart = () => {
  const context = useContext(CartContext);
  if (!context) throw new Error('useCart must be used within a CartProvider');
  return context;
};

'use client';

import React, { createContext, useContext, useEffect, useState } from 'react';
import { Product } from '../../../types';
import toast from '@/lib/toast';

interface CompareContextType {
  items: Product[];
  toggleCompare: (product: Product) => { added: boolean; reason?: string };
  removeFromCompare: (productId: number) => void;
  clearCompare: () => void;
  isInCompare: (productId: number) => boolean;
}

const CompareContext = createContext<CompareContextType | undefined>(undefined);
const STORAGE_KEY = 'compare-products';
const MAX_COMPARE_ITEMS = 4;

export const CompareProvider: React.FC<{ children: React.ReactNode }> = ({ children }) => {
  const [items, setItems] = useState<Product[]>([]);

  useEffect(() => {
    if (typeof window === 'undefined') return;
    try {
      const raw = localStorage.getItem(STORAGE_KEY);
      const parsed = raw ? JSON.parse(raw) : [];
      setItems(Array.isArray(parsed) ? parsed : []);
    } catch {
      setItems([]);
    }
  }, []);

  useEffect(() => {
    if (typeof window === 'undefined') return;
    localStorage.setItem(STORAGE_KEY, JSON.stringify(items));
  }, [items]);

  const toggleCompare = (product: Product) => {
    const exists = items.some((item) => item.id === product.id);
    if (exists) {
      setItems((current) => current.filter((item) => item.id !== product.id));
      toast.success(product.name ? `${product.name} removed from compare` : 'Removed from compare', {
        action: {
          label: 'Undo',
          onClick: () => setItems((current) => [product, ...current.filter((item) => item.id !== product.id)]),
        },
      });
      return { added: false };
    }

    if (items.length >= MAX_COMPARE_ITEMS) {
      const reason = `You can compare up to ${MAX_COMPARE_ITEMS} products at once.`;
      toast.warning(reason);
      return { added: false, reason };
    }

    setItems((current) => [...current, product]);
    toast.success(product.name ? `${product.name} added to compare` : 'Added to compare');
    return { added: true };
  };

  const removeFromCompare = (productId: number) => {
    const removed = items.find((item) => item.id === productId);
    setItems((current) => current.filter((item) => item.id !== productId));
    if (removed) {
      toast.success(removed.name ? `${removed.name} removed from compare` : 'Removed from compare', {
        action: {
          label: 'Undo',
          onClick: () => setItems((current) => [removed, ...current.filter((item) => item.id !== removed.id)]),
        },
      });
    }
  };

  const clearCompare = () => {
    setItems([]);
    toast.success('Compare list cleared');
  };
  const isInCompare = (productId: number) => items.some((item) => item.id === productId);

  return (
    <CompareContext.Provider value={{ items, toggleCompare, removeFromCompare, clearCompare, isInCompare }}>
      {children}
    </CompareContext.Provider>
  );
};

export const useCompare = () => {
  const context = useContext(CompareContext);
  if (!context) {
    throw new Error('useCompare must be used within a CompareProvider');
  }
  return context;
};

import React, { createContext, useContext, useState, useEffect } from 'react';
import { Product } from '../../../types';
import { useUser } from '../../../features/shared/state/UserContext';
import toast from '@/lib/toast';

interface WishlistContextType {
  items: Product[];
  addToWishlist: (product: Product) => Promise<void>;
  removeFromWishlist: (productId: number) => Promise<void>;
  isInWishlist: (productId: number) => boolean;
  toggleWishlist: (product: Product) => Promise<void>;
}

const WishlistContext = createContext<WishlistContextType | undefined>(undefined);

const WISHLIST_STORAGE_KEY = 'wishlist';
const GUEST_WISHLIST_SNAPSHOT_KEY = 'guest_wishlist_snapshot';
const GUEST_WISHLIST_SNAPSHOT_OWNER_KEY = 'guest_wishlist_snapshot_owner';

function dedupeWishlist(products: Product[]) {
  const seen = new Set<number>();
  return products.filter((product) => {
    if (seen.has(product.id)) {
      return false;
    }
    seen.add(product.id);
    return true;
  });
}

function saveGuestWishlistSnapshot(userId: string, items: Product[]) {
  if (typeof window === 'undefined') return;
  localStorage.setItem(GUEST_WISHLIST_SNAPSHOT_OWNER_KEY, userId);
  localStorage.setItem(GUEST_WISHLIST_SNAPSHOT_KEY, JSON.stringify(dedupeWishlist(items)));
}

function restoreGuestWishlistSnapshot() {
  if (typeof window === 'undefined') {
    return [] as Product[];
  }

  try {
    const parsed = JSON.parse(localStorage.getItem(GUEST_WISHLIST_SNAPSHOT_KEY) || '[]') as Product[];
    const restored = Array.isArray(parsed) ? dedupeWishlist(parsed) : [];
    localStorage.setItem(WISHLIST_STORAGE_KEY, JSON.stringify(restored));
    localStorage.removeItem(GUEST_WISHLIST_SNAPSHOT_KEY);
    localStorage.removeItem(GUEST_WISHLIST_SNAPSHOT_OWNER_KEY);
    return restored;
  } catch {
    localStorage.removeItem(GUEST_WISHLIST_SNAPSHOT_KEY);
    localStorage.removeItem(GUEST_WISHLIST_SNAPSHOT_OWNER_KEY);
    return [] as Product[];
  }
}

export const WishlistProvider: React.FC<{ children: React.ReactNode }> = ({ children }) => {
  const [items, setItems] = useState<Product[]>([]);
  const { token, isAuthenticated, user } = useUser();

  const readLocalWishlist = () => {
    if (typeof window === 'undefined') {
      return [] as Product[];
    }

    try {
      const parsed = JSON.parse(localStorage.getItem(WISHLIST_STORAGE_KEY) || '[]') as Product[];
      return Array.isArray(parsed) ? dedupeWishlist(parsed) : [];
    } catch {
      return [];
    }
  };

  useEffect(() => {
    const syncWishlist = async () => {
      if (isAuthenticated && token && user) {
        const localItems = readLocalWishlist();
        const existingSnapshotOwner = typeof window !== 'undefined' ? localStorage.getItem(GUEST_WISHLIST_SNAPSHOT_OWNER_KEY) : null;
        if (existingSnapshotOwner !== String(user.id)) {
          saveGuestWishlistSnapshot(String(user.id), localItems);
        }
        
        // Fetch server items
        try {
          const res = await fetch('/api/wishlist', {
            headers: { 'Authorization': `Bearer ${token}` }
          });
          if (res.status === 401 || res.status === 403) {
            setItems(localItems);
            return;
          }
          if (!res.ok) {
            throw new Error(`Wishlist sync failed with status ${res.status}`);
          }
          const serverItems = dedupeWishlist(await res.json());
          
          // Merge local into server if any
          if (localItems.length > 0) {
            for (const item of localItems) {
              if (!serverItems.some((si: any) => si.id === item.id)) {
                await fetch('/api/wishlist', {
                  method: 'POST',
                  headers: {
                    'Content-Type': 'application/json',
                    'Authorization': `Bearer ${token}`
                  },
                  body: JSON.stringify({ productId: item.id })
                });
                serverItems.push(item);
              }
            }
          }
          
          const mergedItems = dedupeWishlist(serverItems);
          setItems(mergedItems);
          localStorage.setItem(WISHLIST_STORAGE_KEY, JSON.stringify(mergedItems));
        } catch {
          setItems(localItems);
        }
      } else {
        const snapshotOwner = typeof window !== 'undefined' ? localStorage.getItem(GUEST_WISHLIST_SNAPSHOT_OWNER_KEY) : null;
        if (snapshotOwner) {
          setItems(restoreGuestWishlistSnapshot());
        } else {
          setItems(readLocalWishlist());
        }
      }
    };

    syncWishlist();
  }, [isAuthenticated, token, user]);

  useEffect(() => {
    if (typeof window === 'undefined') {
      return;
    }

    localStorage.setItem(WISHLIST_STORAGE_KEY, JSON.stringify(items));
  }, [items]);

  const addToWishlist = async (product: Product) => {
    const notifyAdded = () => {
      toast.success(product.name ? `${product.name} added to wishlist` : 'Added to wishlist');
    };

    if (isAuthenticated && token && user) {
      try {
        const res = await fetch('/api/wishlist', {
          method: 'POST',
          headers: {
            'Content-Type': 'application/json',
            'Authorization': `Bearer ${token}`
          },
          body: JSON.stringify({ productId: product.id })
        });
        if (res.ok) {
          setItems(prev => {
            const next = [...prev.filter(i => i.id !== product.id), product];
            return next;
          });
          notifyAdded();
        } else if (res.status === 401 || res.status === 403) {
          setItems(prev => (prev.find(item => item.id === product.id) ? prev : [...prev, product]));
          notifyAdded();
        }
      } catch {
        setItems(prev => (prev.find(item => item.id === product.id) ? prev : [...prev, product]));
        notifyAdded();
      }
    } else {
      const alreadySaved = items.some(item => item.id === product.id);
      setItems(prev => {
        if (prev.find(item => item.id === product.id)) return prev;
        return [...prev, product];
      });
      if (!alreadySaved) {
        notifyAdded();
      }
    }
  };

  const removeFromWishlist = async (productId: number) => {
    const removed = items.find((it) => it.id === productId);
    const notifyRemoved = () => {
      if (!removed) return;
      toast.success(removed.name ? `${removed.name} removed from wishlist` : 'Removed from wishlist', {
        action: {
          label: 'Undo',
          onClick: () => setItems((current) => [removed, ...current]),
        },
      });
    };

    if (isAuthenticated && token && user) {
      try {
        const res = await fetch(`/api/wishlist/${productId}`, {
          method: 'DELETE',
          headers: { 'Authorization': `Bearer ${token}` }
        });
        if (res.ok || res.status === 401 || res.status === 403) {
          setItems(prev => prev.filter(item => item.id !== productId));
          notifyRemoved();
        }
      } catch {
        setItems(prev => prev.filter(item => item.id !== productId));
        notifyRemoved();
      }
    } else {
      setItems(prev => prev.filter(item => item.id !== productId));
      notifyRemoved();
    }
  };

  const isInWishlist = (productId: number) => {
    return items.some(item => item.id === productId);
  };

  const toggleWishlist = async (product: Product) => {
    if (isInWishlist(product.id)) {
      await removeFromWishlist(product.id);
    } else {
      await addToWishlist(product);
    }
  };

  return (
    <WishlistContext.Provider value={{ 
      items, 
      addToWishlist, 
      removeFromWishlist, 
      isInWishlist,
      toggleWishlist
    }}>
      {children}
    </WishlistContext.Provider>
  );
};

export const useWishlist = () => {
  const context = useContext(WishlistContext);
  if (!context) throw new Error('useWishlist must be used within a WishlistProvider');
  return context;
};

import { prisma } from '@/lib/server';
import { getServerEnv } from '../../../lib/env';
import { createHmac, timingSafeEqual } from 'crypto';
import { sendTelegramDocument } from './telegram';

const INVOICE_TOKEN_TTL_SECONDS = 7 * 24 * 60 * 60;

function getInvoiceTokenSecret() {
  return getServerEnv().JWT_SECRET || getServerEnv().TELEGRAM_WEBHOOK_SECRET || 'lofimart-telegram-invoice';
}

function signInvoicePayload(orderId: string, expiresAt: number) {
  return createHmac('sha256', getInvoiceTokenSecret())
    .update(`${orderId}.${expiresAt}`)
    .digest('base64url');
}

export function createTelegramInvoiceToken(orderId: string, ttlSeconds = INVOICE_TOKEN_TTL_SECONDS) {
  const expiresAt = Math.floor(Date.now() / 1000) + ttlSeconds;
  const signature = signInvoicePayload(orderId, expiresAt);
  return `${expiresAt}.${signature}`;
}

export function verifyTelegramInvoiceToken(orderId: string, token: string | null | undefined) {
  const [expiresAtRaw, signature] = String(token || '').split('.', 2);
  const expiresAt = Number(expiresAtRaw);

  if (!expiresAt || !signature || expiresAt < Math.floor(Date.now() / 1000)) {
    return false;
  }

  const expected = signInvoicePayload(orderId, expiresAt);
  const expectedBuffer = Buffer.from(expected);
  const signatureBuffer = Buffer.from(signature);

  return expectedBuffer.length === signatureBuffer.length && timingSafeEqual(expectedBuffer, signatureBuffer);
}

export async function ensureTelegramInvoice(orderId: string) {
  const order = await prisma.order.findUnique({
    where: { id: orderId },
    include: { invoice: true },
  });

  if (!order) {
    throw new Error('Order not found');
  }

  const frontendUrl = getServerEnv().FRONTEND_URL;
  const invoiceUrl = new URL(`/account/orders/${order.id}/invoice`, frontendUrl).toString();
  const token = createTelegramInvoiceToken(order.id);
  const documentUrl = new URL(
    `/api/telegram/invoices/${encodeURIComponent(order.id)}?token=${encodeURIComponent(token)}`,
    frontendUrl,
  ).toString();

  const invoice = await (prisma.invoice as any).upsert({
    where: { orderId: order.id },
    create: {
      orderId: order.id,
      userId: order.userId,
      status: order.paymentStatus === 'paid' ? 'paid' : 'draft',
      subtotal: order.total,
      total: order.total,
      invoiceUrl,
      documentUrl,
    },
    update: {
      invoiceUrl,
      documentUrl,
      status: order.paymentStatus === 'paid' ? 'paid' : order.invoice?.status ?? 'draft',
    },
  });

  return {
    invoice,
    invoiceUrl,
    documentUrl,
  };
}

export async function sendInvoiceToTelegram(input: {
  chatId: string | number;
  orderId: string;
  caption?: string;
}) {
  const invoice = await ensureTelegramInvoice(input.orderId);

  await sendTelegramDocument({
    chatId: input.chatId,
    documentUrl: invoice.documentUrl,
    caption: input.caption || `Invoice for order ${input.orderId}`,
    buttons: [[{ text: 'Open invoice', url: invoice.invoiceUrl }]],
  });

  return invoice;
}

import { prisma } from '@/lib/server';
import { escapeTelegramHtml, getTelegramDashboardUrl, sendTelegramMessage } from './telegram';

type SellerOrderMessageInput = {
  sellerId: string;
  orderId: string;
  orderCode?: string | null;
  total?: string | number;
};

type TelegramUserContact = {
  telegramChatId?: string | null;
  storeName?: string | null;
  name?: string | null;
};

async function getTelegramUserContact(userId: string): Promise<TelegramUserContact | null> {
  return (prisma.user as any).findUnique({
    where: { id: userId },
    select: { telegramChatId: true, storeName: true, name: true },
