}

export async function sendLowStockAlert(input: {
  sellerId: string;
  productName: string;
  stock: number;
  threshold: number;
}) {
  const seller = await getTelegramUserContact(input.sellerId);

  if (!seller?.telegramChatId) return false;

  await sendTelegramMessage({
