export async function sendPaymentReceivedNotification(input: SellerOrderMessageInput) {
  return sendOrderStatusNotification({ ...input, status: 'payment received' });
}

export async function sendPaymentReceivedNotificationsForOrder(orderId: string) {
  const order = await prisma.order.findUnique({
    where: { id: orderId },
    select: {
      id: true,
      orderCode: true,
      total: true,
      shipments: {
        select: {
          sellerId: true,
          total: true,
        },
      },
      resellerCommissions: {
        select: {
          resellerId: true,
          amount: true,
        },
      },
    },
  });

  if (!order) return { sellerNotifications: 0, resellerNotifications: 0 };

  const sellerTotals = new Map<string, number>();
  for (const shipment of order.shipments || []) {
    sellerTotals.set(
      shipment.sellerId,
      (sellerTotals.get(shipment.sellerId) || 0) + Number(shipment.total || 0),
    );
  }

  const sellerResults = await Promise.all(
    [...sellerTotals.entries()].map(([sellerId, total]) =>
      sendPaymentReceivedNotification({
        sellerId,
        orderId: order.id,
        orderCode: order.orderCode,
        total,
      }),
    ),
  );

  const resellerResults = await Promise.all(
    (order.resellerCommissions || []).map((commission) =>
      sendCommissionEarnedNotification({
        resellerId: commission.resellerId,
        amount: Number(commission.amount || 0),
        orderId: order.orderCode || order.id,
      }),
    ),
  );

  return {
    sellerNotifications: sellerResults.filter(Boolean).length,
    resellerNotifications: resellerResults.filter(Boolean).length,
  };
}

export async function sendCommissionEarnedNotification(input: {
  resellerId: string;
  amount: string | number;
  orderId: string;
}) {
  const reseller = await getTelegramUserContact(input.resellerId);

  if (!reseller?.telegramChatId) return false;

  await sendTelegramMessage({
    chatId: reseller.telegramChatId,
    text: `<b>Commission Earned</b>\nAmount: ${escapeTelegramHtml(input.amount)} BDT\nOrder: <code>${escapeTelegramHtml(input.orderId)}</code>`,
    buttons: [[{ text: 'Open Earnings', web_app: { url: getTelegramDashboardUrl('/reseller-dashboard/earnings') } }]],
  });

  return true;
}

import { prisma } from '@/lib/server';
import type { TelegramUpdate } from '../types';
import { answerTelegramCallback, escapeTelegramHtml, getTelegramDashboardUrl, sendTelegramMessage } from './telegram';
import { updateSellerOrderStatus } from './orderService';

type TelegramConnectRole = 'seller' | 'admin' | 'reseller';

function parseStartPayload(text?: string) {
  const [command, payload] = String(text || '').trim().split(/\s+/, 2);
  if (command !== '/start' || !payload) return null;
  return payload;
}

function parseConnectPayload(payload: string | null): { role: TelegramConnectRole; userId: string } | null {
  const match = String(payload || '').match(/^(seller|admin|reseller)_(.+)$/);
  if (!match) return null;
  return {
    role: match[1] as TelegramConnectRole,
    userId: match[2].trim(),
  };
}

function dashboardPathForRole(role: TelegramConnectRole) {
  if (role === 'admin') return '/admin/dashboard';
  if (role === 'reseller') return '/reseller-dashboard/overview';
  return '/seller/dashboard';
}

function roleLabel(role: TelegramConnectRole) {
  if (role === 'admin') return 'admin';
  if (role === 'reseller') return 'reseller';
  return 'seller';
}

async function handleAccountOnboarding(update: TelegramUpdate) {
  const chatId = update.message?.chat.id;
  const text = update.message?.text;
  const payload = parseStartPayload(text);
  const connect = parseConnectPayload(payload);

  if (!chatId || !connect) return false;

  const account = await (prisma.user as any).findFirst({
    where: {
      id: connect.userId,
      role: connect.role,
    },
    select: {
      id: true,
      role: true,
      name: true,
      storeName: true,
      telegramChatId: true,
    },
  });

  if (!account) {
    await sendTelegramMessage({
      chatId,
      text: `${roleLabel(connect.role)} account not found or not eligible for Telegram onboarding.`,
    });
    return true;
  }

  if (account.telegramChatId && account.telegramChatId !== String(chatId)) {
    await sendTelegramMessage({
      chatId,
      text: `This ${roleLabel(connect.role)} account is already linked to another Telegram chat.`,
    });
    return true;
  }

  await (prisma.user as any).update({
    where: { id: account.id },
    data: {
      telegramChatId: String(chatId),
      telegramLinkedAt: new Date(),
    },
  });

  await sendTelegramMessage({
    chatId,
    text: [
      '<b>LofiMart Telegram connected</b>',
      `Account: ${escapeTelegramHtml(account.storeName || account.name || roleLabel(connect.role))}`,
      `Role: ${escapeTelegramHtml(roleLabel(connect.role))}`,
      'You will now receive order, stock, payment, and commission alerts here.',
    ].join('\n'),
    buttons: [[{ text: 'Open Dashboard', web_app: { url: getTelegramDashboardUrl(dashboardPathForRole(connect.role)) } }]],
  });

  return true;
}

async function handleCallbackQuery(update: TelegramUpdate) {
  const query = update.callback_query;
  if (!query?.data || !query.message?.chat.id) return false;

  const [scope, action, orderId, sellerId] = query.data.split(':');
  if (scope !== 'order' || !action || !orderId || !sellerId) {
    await answerTelegramCallback(query.id, 'Unsupported action', true);
    return true;
  }

  try {
    const mappedAction =
      action === 'accept'
        ? 'accept'
        : action === 'reject'
          ? 'reject'
          : action === 'ship'
            ? 'ship'
            : action === 'deliver'
              ? 'deliver'
              : null;

    if (!mappedAction) {
      await answerTelegramCallback(query.id, 'Unknown order action', true);
      return true;
    }

    const result = await updateSellerOrderStatus({
      chatId: query.message.chat.id,
      sellerId,
      orderId,
      action: mappedAction,
    });

    await answerTelegramCallback(query.id, `Order ${result.status}`);
    return true;
  } catch (error) {
    await answerTelegramCallback(
      query.id,
      error instanceof Error ? error.message : 'Action failed',
      true,
    );
    return true;
  }
}

export async function processTelegramUpdate(update: TelegramUpdate) {
  if (await handleAccountOnboarding(update)) {
    return { handled: true };
  }

  if (await handleCallbackQuery(update)) {
    return { handled: true };
  }

  if (update.message?.chat.id) {
    await sendTelegramMessage({
      chatId: update.message.chat.id,
      text: [
        '<b>LofiMart Bot</b>',
        'Use your seller, reseller, or admin deep link to connect this chat.',
        'After linking, you can receive marketplace alerts and use supported action buttons.',
      ].join('\n'),
    });
  }

  return { handled: false };
}

export type AccountRole = 'customer' | 'seller' | 'reseller';

const AUTH_EXCHANGE_TIMEOUT_MS = 15_000;
const PENDING_OAUTH_STORAGE_KEY = 'lofimart_pending_oauth';

function extractAuthMessage(input: unknown): string {
  if (typeof input === 'string') {
    const normalized = input.trim();
    if (!normalized || normalized === '{}' || normalized === '[object Object]' || normalized === 'null' || normalized === 'undefined') {
      return '';
    }
    return normalized;
  }

  if (input instanceof Error) {
    return input.message;
  }

  if (input && typeof input === 'object') {
    const maybeMessage =
      'message' in input
        ? extractAuthMessage((input as { message?: unknown }).message)
        : 'error' in input
          ? extractAuthMessage((input as { error?: unknown }).error)
          : '';

    if (maybeMessage) {
      return maybeMessage;
    }
  }

  return '';
}

export function hasSupabaseBrowserEnv() {
  return Boolean(
    process.env.NEXT_PUBLIC_SUPABASE_URL &&
      (process.env.NEXT_PUBLIC_SUPABASE_PUBLISHABLE_KEY || process.env.NEXT_PUBLIC_SUPABASE_ANON_KEY),
  );
}

export async function getSupabaseBrowserClient() {
  const { createClient } = await import('@/lib/client');
  return createClient();
}

export async function exchangeSupabaseSession(params: {
  accessToken: string;
  role?: string;
  name?: string;
  referralCode?: string;
  mode?: 'login' | 'register';
}) {
  const controller = new AbortController();
  const timeoutId = window.setTimeout(() => controller.abort(), AUTH_EXCHANGE_TIMEOUT_MS);

  try {
    const response = await fetch('/api/auth/supabase/exchange', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(params),
      signal: controller.signal,
    });

    const data = await response.json().catch(() => null);
    if (!response.ok) {
      throw new Error(extractAuthMessage(data) || 'Failed to sync Supabase session');
    }

    return data;
  } catch (error: any) {
    if (error?.name === 'AbortError') {
      throw new Error('Authentication timed out. Please try again.');
    }

    throw error;
  } finally {
    window.clearTimeout(timeoutId);
  }
}

export function normalizeRedirectTarget(value: string | null) {
  if (!value || !value.startsWith('/')) {
    return null;
  }

  return value;
}

export function resolvePostAuthDestination(userRole: string, redirectTarget: string | null) {
  if (redirectTarget) {
    return redirectTarget;
  }

  if (userRole === 'admin') return '/admin/dashboard';
  if (userRole === 'seller') return '/seller/dashboard';
  if (userRole === 'reseller') return '/reseller-dashboard/overview';
  return '/account/dashboard';
}

export function buildAuthCallbackUrl(options?: {
  redirectTarget?: string | null;
  role?: AccountRole;
  referralCode?: string;
  mode?: 'login' | 'register';
}) {
  const params = new URLSearchParams();

  if (options?.redirectTarget) {
    params.set('redirect', options.redirectTarget);
  }

  if (options?.role) {
    params.set('role', options.role);
  }

  if (options?.referralCode) {
    params.set('ref', options.referralCode);
  }

  if (options?.mode) {
    params.set('mode', options.mode);
  }

  const query = params.toString();
  const configuredSiteUrl = process.env.NEXT_PUBLIC_SITE_URL;
  const origin =
    configuredSiteUrl && typeof window !== 'undefined' && !['localhost', '127.0.0.1'].includes(window.location.hostname)
      ? configuredSiteUrl.replace(/\/+$/, '')
      : window.location.origin;

  return `${origin}/auth/callback${query ? `?${query}` : ''}`;
}

export function rememberPendingOAuthRedirect(options?: {
  redirectTarget?: string | null;
  role?: AccountRole;
  referralCode?: string;
  mode?: 'login' | 'register';
}) {
  if (typeof window === 'undefined') return;

  try {
    window.sessionStorage.setItem(
      PENDING_OAUTH_STORAGE_KEY,
      JSON.stringify({
        redirectTarget: options?.redirectTarget || null,
        role: options?.role || null,
        referralCode: options?.referralCode || null,
        mode: options?.mode || 'login',
      }),
    );
  } catch {
    // Storage can be unavailable in privacy modes; OAuth still works without this hint.
  }
}

export function getPasswordStrength(password: string) {
  if (!password) {
    return { label: 'Add a password', tone: 'bg-slate-200', width: 'w-0' };
  }

  const score =
    Number(password.length >= 8) +
    Number(/[A-Z]/.test(password)) +
    Number(/[0-9]/.test(password)) +
    Number(/[^A-Za-z0-9]/.test(password));

  if (score <= 1) {
    return { label: 'Weak password', tone: 'bg-rose-500', width: 'w-1/4' };
  }

  if (score === 2) {
    return { label: 'Fair password', tone: 'bg-amber-500', width: 'w-2/4' };
  }

  if (score === 3) {
    return { label: 'Strong password', tone: 'bg-sky-500', width: 'w-3/4' };
  }

  return { label: 'Very strong password', tone: 'bg-emerald-500', width: 'w-full' };
}

export function mapAuthMessage(message: unknown) {
  const safeMessage = extractAuthMessage(message) || 'Authentication could not be completed right now.';
  const normalized = String(safeMessage || '').trim().toLowerCase();

  if (!normalized) {
    return 'Authentication could not be completed right now.';
  }

  if (normalized.includes('invalid login credentials')) {
    return 'Invalid email or password. Please try again.';
  }

  if (normalized.includes('email not confirmed') || normalized.includes('confirm')) {
    return 'Your email is not verified yet. Please verify it first, then sign in again.';
  }

  if (normalized.includes('session expired') || normalized.includes('token expired')) {
    return 'Your session expired. Please sign in again.';
  }

  if (normalized.includes('failed to complete sign in') || normalized.includes('failed to complete sign-in')) {
    return 'We could not complete your sign-in. Please try again.';
  }

  if (normalized.includes('supabase session not found')) {
    return 'Your social sign-in session could not be confirmed. Please try again.';
  }

  if (normalized.includes('pkce code verifier not found')) {
    return 'Your social sign-in session could not be completed in this browser. Please try again from the same tab.';
  }

  if (normalized.includes('supabase auth is not configured')) {
    return 'Authentication is not configured correctly for this environment yet.';
  }

  if (normalized.includes('email already exists') || normalized.includes('already registered')) {
    return 'This email is already registered. Please sign in or verify your existing account.';
  }

  if (normalized.includes('email rate limit exceeded')) {
    return 'Too many verification emails were requested recently. Please wait a few minutes and try again.';
  }

  if (normalized.includes('over_email_send_rate_limit')) {
    return 'Too many verification emails were requested recently. Please wait a few minutes and try again.';
  }

  if (normalized.includes('registration failed')) {
    return 'We could not create your authentication account right now. Please try again in a moment.';
  }

  if (normalized.includes('gateway timeout') || normalized.includes('504')) {
    return 'The authentication service took too long to respond. Please wait a moment and try again.';
  }

  if (normalized.includes('failed to fetch') || normalized.includes('network request failed')) {
    return 'We could not reach the authentication service. Please check your connection and try again.';
  }

  if (normalized.includes('supabase session was not created')) {
    return 'Your account was created, but your session could not be started automatically. Please sign in after verifying your email.';
  }

  if (normalized.includes('we could not create your account right now')) {
    return 'We could not create your authentication account right now. Please try again in a moment.';
  }

  return safeMessage;
}

'use client';

import NextLink from 'next/link';
import {
  useParams as useNextParams,
  usePathname,
  useRouter,
} from 'next/navigation';
import React from 'react';

type To = string;

type NavigateOptions = {
  replace?: boolean;
  scroll?: boolean;
  state?: unknown;
};

type LinkProps = Omit<React.ComponentProps<typeof NextLink>, 'href'> & {
  to: To;
  state?: unknown;
};

const NAVIGATION_STATE_PREFIX = '__amarshop_nav_state__:';
const isDev = process.env.NODE_ENV !== 'production';

function normalizeTarget(target: To) {
  return target || '/';
}

function storageKey(target: To) {
  return `${NAVIGATION_STATE_PREFIX}${normalizeTarget(target)}`;
}

function persistNavigationState(target: To, state: unknown) {
  if (typeof window === 'undefined' || typeof state === 'undefined') return;

  try {
    window.sessionStorage.setItem(storageKey(target), JSON.stringify(state));
  } catch (error) {
    if (isDev) {
      console.warn('Failed to persist navigation state', error);
    }
  }
}

function readNavigationState(target: To) {
  if (typeof window === 'undefined') return null;

  try {
    const value = window.sessionStorage.getItem(storageKey(target));
    return value ? JSON.parse(value) : null;
  } catch (error) {
    if (isDev) {
      console.warn('Failed to read navigation state', error);
    }
    return null;
  }
}

function toSearchString(params: URLSearchParams) {
  const value = params.toString();
  return value ? `?${value}` : '';
}

export function Link({ to, state, onClick, replace, scroll, ...props }: LinkProps) {
  const href = normalizeTarget(to);

  return (
    <NextLink
      href={href}
      replace={replace}
      scroll={scroll}
      onClick={(event) => {
        persistNavigationState(href, state);
        onClick?.(event);
      }}
      {...props}
    />
  );
}

export function useNavigate() {
  const router = useRouter();

  return React.useCallback(
    (to: To, options: NavigateOptions = {}) => {
      const href = normalizeTarget(to);
      persistNavigationState(href, options.state);
      const method = options.replace ? router.replace : router.push;
      method(href, { scroll: options.scroll });
    },
    [router],
  );
}

export function useLocation() {
  const pathname = usePathname();
  const [search, setSearch] = React.useState('');

  React.useEffect(() => {
    if (typeof window !== 'undefined') {
      setSearch(window.location.search);
    }
  }, [pathname]);

  const current = `${pathname}${search}`;

  return React.useMemo(
    () => ({
      pathname,
      search,
      hash: '',
      state: readNavigationState(current) ?? readNavigationState(pathname),
      key: current,
    }),
    [current, pathname, search],
  );
}

export function useParams<T extends Record<string, string | string[] | undefined>>() {
  return useNextParams<T>();
}

export function useSearchParams(): [
  URLSearchParams,
  (
    nextInit:
      | string
      | URLSearchParams
      | Record<string, string | number | boolean | null | undefined>,
    options?: { replace?: boolean; scroll?: boolean },
  ) => void,
] {
  const pathname = usePathname();
  const navigate = useNavigate();
  const [search, setSearch] = React.useState('');

  React.useEffect(() => {
    if (typeof window !== 'undefined') {
      setSearch(window.location.search);
    }
  }, [pathname]);

  const params = React.useMemo(() => new URLSearchParams(search), [search]);

  const setSearchParams = React.useCallback(
    (
      nextInit:
        | string
        | URLSearchParams
        | Record<string, string | number | boolean | null | undefined>,
      options?: { replace?: boolean; scroll?: boolean },
    ) => {
      const nextParams =
        typeof nextInit === 'string'
          ? new URLSearchParams(nextInit)
          : nextInit instanceof URLSearchParams
            ? new URLSearchParams(nextInit.toString())
            : new URLSearchParams(
                Object.entries(nextInit).reduce<Record<string, string>>((acc, [key, value]) => {
                  if (value !== null && typeof value !== 'undefined') {
                    acc[key] = String(value);
                  }
                  return acc;
                }, {}),
              );

      navigate(`${pathname}${toSearchString(nextParams)}`, options);
    },
    [navigate, pathname],
  );

  return [params, setSearchParams];
}

import { describe, expect, it, vi } from 'vitest';
import toast, { getToastDedupeKey, subscribe } from './toast';

describe('getToastDedupeKey', () => {
  it('returns the same key for identical toast payloads', () => {
    const first = getToastDedupeKey('success', {
      title: 'Profile updated',
      description: 'Your changes were saved.',
    });

    const second = getToastDedupeKey('success', {
      title: 'Profile updated',
      description: 'Your changes were saved.',
    });

    expect(first).toBe(second);
  });

  it('returns different keys for different messages', () => {
    const first = getToastDedupeKey('error', {
      title: 'Payment failed',
      description: 'Please try again.',
    });

    const second = getToastDedupeKey('warning', {
      title: 'Payment failed',
      description: 'Please try again.',
    });

    expect(first).not.toBe(second);
  });

  it('suppresses duplicate toasts while they are queued', () => {
    vi.useFakeTimers();

    let latestToasts: Array<{ title: string }> = [];
    const unsubscribe = subscribe((snapshot) => {
      latestToasts = snapshot.visible.map((item) => ({ title: String(item.title) }));
    });

    const alphaId = toast.success('Alpha');
    const betaId = toast.success('Beta');
    const gammaId = toast.success('Gamma');
    const deltaId = toast.success('Delta');
    const echoId = toast.success('Echo');
    const duplicateEchoId = toast.success('Echo');

    expect(echoId).toBeTruthy();
    expect(duplicateEchoId).toBe(echoId);

    toast.dismiss(alphaId);
    vi.advanceTimersByTime(250);

    toast.dismiss(betaId);
    vi.advanceTimersByTime(250);

    const echoCount = latestToasts.filter((item) => item.title === 'Echo').length;

    unsubscribe();
    vi.useRealTimers();

    expect(echoCount).toBe(1);
  });
});

'use client';

import React from 'react';
import { AnimatePresence, motion } from 'framer-motion';
import { AlertCircle, AlertTriangle, CheckCircle2, Info, LoaderCircle, X } from 'lucide-react';
import { cn } from './utils';

type ToastType = 'success' | 'error' | 'warning' | 'info' | 'loading';

type ToastAction = {
  label: string;
  onClick: () => void;
};

type ToastOptions = {
  id?: string;
  description?: React.ReactNode;
  duration?: number;
  action?: ToastAction;
  icon?: React.ReactNode;
  className?: string;
};

type ToastPosition = 'top-center' | 'top-right' | 'bottom-center' | 'bottom-right';

type ToasterProps = {
  position?: ToastPosition;
};

type ToastContent = string | React.ReactNode | { title?: string; description?: React.ReactNode };

type ToastItem = {
  id: string;
  type: ToastType;
  title: React.ReactNode;
  description?: React.ReactNode;
  action?: ToastAction;
  duration: number;
  createdAt: number;
  icon?: React.ReactNode;
  className?: string;
  dedupeKey?: string;
};

type ToastApi = ((content: ToastContent, options?: ToastOptions) => string) & {
  success: (content: ToastContent, options?: ToastOptions) => string;
  error: (content: ToastContent, options?: ToastOptions) => string;
  warning: (content: ToastContent, options?: ToastOptions) => string;
  info: (content: ToastContent, options?: ToastOptions) => string;
  loading: (content: ToastContent, options?: ToastOptions) => string;
  dismiss: (id?: string) => void;
  remove: (id?: string) => void;
  custom: (render: (t: { id: string; dismiss: () => void }) => React.ReactNode, options?: ToastOptions) => string;
  promise: <T>(
    promise: Promise<T>,
    messages: {
      loading: ToastContent;
      success: ToastContent | ((data: T) => ToastContent);
      error: ToastContent | ((error: unknown) => ToastContent);
    },
    options?: ToastOptions,
  ) => Promise<T>;
};

const MAX_VISIBLE_TOASTS = 4;
const DEFAULT_DURATION_MS = 4200;

type ToastSnapshot = {
  visible: ToastItem[];
  queued: ToastItem[];
};

let listeners: Array<(snapshot: ToastSnapshot) => void> = [];
let toasts: ToastItem[] = [];
let queuedToasts: ToastItem[] = [];
const timers = new Map<string, { timeoutId: number; startedAt: number; remaining: number; paused: boolean }>();
const activeDedupeKeys = new Map<string, string>();
let counter = 0;

function notify() {
  const snapshot: ToastSnapshot = {
    visible: [...toasts],
    queued: [...queuedToasts],
  };

  listeners.forEach((listener) => listener(snapshot));
}

function resolveContent(content: ToastContent) {
  if (typeof content === 'string' || typeof content === 'number') {
    return content;
  }

  if (React.isValidElement(content)) {
    return content;
  }

  if (content && typeof content === 'object' && 'title' in content) {
    return content.title ?? '';
  }

  return '';
}

function createDedupeKey(type: ToastType, content: ToastContent, options?: ToastOptions) {
  const normalized = normalizeContent(content);
  const title = String(normalized.title ?? resolveContent(content) ?? '');
  const description = String(options?.description ?? normalized.description ?? '');
  return `${type}:${title}:${description}`.trim().toLowerCase();
}

export function getToastDedupeKey(type: ToastType, content: ToastContent, options?: ToastOptions) {
  return createDedupeKey(type, content, options);
}

function getToastThemeClasses(type: ToastType) {
  switch (type) {
    case 'success':
      return 'border-emerald-200/70 bg-white/95 text-slate-950 shadow-[0_22px_55px_-28px_rgba(16,185,129,0.55)] dark:border-emerald-500/30 dark:bg-slate-950/90 dark:text-slate-50';
    case 'error':
      return 'border-red-200/70 bg-white/95 text-slate-950 shadow-[0_22px_55px_-28px_rgba(239,68,68,0.5)] dark:border-red-500/30 dark:bg-slate-950/90 dark:text-slate-50';
    case 'warning':
      return 'border-orange-200/70 bg-white/95 text-slate-950 shadow-[0_22px_55px_-28px_rgba(249,115,22,0.48)] dark:border-orange-500/30 dark:bg-slate-950/90 dark:text-slate-50';
    case 'loading':
      return 'border-slate-200/80 bg-white/95 text-slate-950 shadow-[0_22px_55px_-30px_rgba(15,23,42,0.38)] dark:border-slate-700/70 dark:bg-slate-950/90 dark:text-slate-50';
    default:
      return 'border-blue-200/70 bg-white/95 text-slate-950 shadow-[0_22px_55px_-28px_rgba(59,130,246,0.5)] dark:border-blue-500/30 dark:bg-slate-950/90 dark:text-slate-50';
  }
}

function getToastAccentClasses(type: ToastType) {
  switch (type) {
    case 'success':
      return 'bg-emerald-500';
    case 'error':
      return 'bg-red-500';
    case 'warning':
      return 'bg-orange-500';
    case 'loading':
      return 'bg-slate-500';
    default:
      return 'bg-blue-500';
  }
}

function getToastIconClasses(type: ToastType) {
  switch (type) {
    case 'success':
      return 'bg-emerald-50 text-emerald-600 ring-emerald-100 dark:bg-emerald-500/15 dark:text-emerald-300 dark:ring-emerald-500/20';
    case 'error':
      return 'bg-red-50 text-red-600 ring-red-100 dark:bg-red-500/15 dark:text-red-300 dark:ring-red-500/20';
    case 'warning':
      return 'bg-orange-50 text-orange-600 ring-orange-100 dark:bg-orange-500/15 dark:text-orange-300 dark:ring-orange-500/20';
    case 'loading':
      return 'bg-slate-100 text-slate-600 ring-slate-200 dark:bg-slate-800 dark:text-slate-300 dark:ring-slate-700';
    default:
      return 'bg-blue-50 text-blue-600 ring-blue-100 dark:bg-blue-500/15 dark:text-blue-300 dark:ring-blue-500/20';
  }
}

function getToastIcon(type: ToastType, fallback?: React.ReactNode) {
  if (fallback) return fallback;

  switch (type) {
    case 'success':
      return <CheckCircle2 className="h-5 w-5" />;
    case 'error':
      return <AlertCircle className="h-5 w-5" />;
    case 'warning':
      return <AlertTriangle className="h-5 w-5" />;
    case 'loading':
      return <LoaderCircle className="h-5 w-5 animate-spin" />;
    default:
      return <Info className="h-5 w-5" />;
  }
}

function clearTimer(id: string) {
  const timer = timers.get(id);
  if (!timer) return;
  if (typeof window !== 'undefined' && timer.timeoutId) {
    window.clearTimeout(timer.timeoutId);
  }
  timers.delete(id);
}

function startTimer(id: string, duration: number) {
  if (duration <= 0 || typeof window === 'undefined') return;

  const startedAt = Date.now();
  const timeoutId = window.setTimeout(() => {
    dismiss(id);
  }, duration);

  timers.set(id, { timeoutId, startedAt, remaining: duration, paused: false });
}

function pauseTimer(id: string) {
  const timer = timers.get(id);
  if (!timer || typeof window === 'undefined') return;

  if (timer.timeoutId) {
    window.clearTimeout(timer.timeoutId);
  }

  const elapsed = Date.now() - timer.startedAt;
  const remaining = Math.max(0, timer.remaining - elapsed);
  timers.set(id, { timeoutId: 0, startedAt: Date.now(), remaining, paused: true });
}

function resumeTimer(id: string) {
  const timer = timers.get(id);
  if (!timer || timer.remaining <= 0 || typeof window === 'undefined') return;

  const timeoutId = window.setTimeout(() => {
    dismiss(id);
  }, timer.remaining);

  timers.set(id, { timeoutId, startedAt: Date.now(), remaining: timer.remaining, paused: false });
}

function normalizeContent(content: ToastContent) {
  if (typeof content === 'string' || typeof content === 'number') {
    return { title: String(content), description: undefined as React.ReactNode | undefined };
  }

  if (content && typeof content === 'object' && 'title' in content) {
    return {
      title: content.title ?? '',
      description: content.description,
    };
  }

  return {
    title: content as React.ReactNode,
    description: undefined as React.ReactNode | undefined,
  };
}

function createToast(options: {
  type: ToastType;
  content: ToastContent;
  toastOptions?: ToastOptions;
}) {
  const resolved = normalizeContent(options.content);
  const duration = options.toastOptions?.duration ?? DEFAULT_DURATION_MS;
  const dedupeKey = createDedupeKey(options.type, options.content, options.toastOptions);

  if (dedupeKey && activeDedupeKeys.has(dedupeKey)) {
    return activeDedupeKeys.get(dedupeKey)!;
  }

  const id = options.toastOptions?.id ?? `toast-${++counter}`;

  const item: ToastItem = {
    id,
    type: options.type,
    title: resolved.title,
    description: options.toastOptions?.description ?? resolved.description,
    action: options.toastOptions?.action,
    duration,
    createdAt: Date.now(),
    icon: options.toastOptions?.icon,
    className: options.toastOptions?.className,
    dedupeKey,
  };

  if (toasts.length >= MAX_VISIBLE_TOASTS) {
    queuedToasts.push(item);
    if (dedupeKey) {
      activeDedupeKeys.set(dedupeKey, item.id);
    }
  } else {
    toasts.push(item);
    if (dedupeKey) {
      activeDedupeKeys.set(dedupeKey, item.id);
    }
    startTimer(item.id, item.duration);
  }

  notify();

  return item.id;
}

function flushQueue() {
  if (queuedToasts.length === 0 || toasts.length >= MAX_VISIBLE_TOASTS) return;

  const next = queuedToasts.shift();
  if (!next) return;

  toasts.push(next);
  if (next.dedupeKey) {
    activeDedupeKeys.set(next.dedupeKey, next.id);
  }
  startTimer(next.id, next.duration);
  notify();
}

export function dismissToast(id?: string) {
  if (!id) {
    toasts.forEach((toast) => clearTimer(toast.id));
    queuedToasts = [];
    toasts = [];
    activeDedupeKeys.clear();
    notify();
    return;
  }

  const fromVisible = toasts.findIndex((toast) => toast.id === id);
  if (fromVisible >= 0) {
    const toastToRemove = toasts[fromVisible];
    clearTimer(id);
    toasts.splice(fromVisible, 1);
    if (toastToRemove.dedupeKey && !queuedToasts.some((queued) => queued.dedupeKey === toastToRemove.dedupeKey)) {
      activeDedupeKeys.delete(toastToRemove.dedupeKey);
    }
    if (toasts.length < MAX_VISIBLE_TOASTS) {
      flushQueue();
    }
    notify();
    return;
  }

  const fromQueue = queuedToasts.findIndex((toast) => toast.id === id);
  if (fromQueue >= 0) {
    const toastToRemove = queuedToasts[fromQueue];
    queuedToasts.splice(fromQueue, 1);
    if (toastToRemove.dedupeKey && !toasts.some((visible) => visible.dedupeKey === toastToRemove.dedupeKey)) {
      activeDedupeKeys.delete(toastToRemove.dedupeKey);
    }
    notify();
  }
}

export function dismiss(id?: string) {
  dismissToast(id);
}

function createToastApi(): ToastApi {
  const api = ((content: ToastContent, options?: ToastOptions) => {
    return createToast({ type: 'info', content, toastOptions: options });
  }) as ToastApi;

  api.success = (content: ToastContent, options?: ToastOptions) => {
    return createToast({ type: 'success', content, toastOptions: options });
  };
  api.error = (content: ToastContent, options?: ToastOptions) => {
    return createToast({ type: 'error', content, toastOptions: options });
  };
  api.warning = (content: ToastContent, options?: ToastOptions) => {
    return createToast({ type: 'warning', content, toastOptions: options });
  };
  api.info = (content: ToastContent, options?: ToastOptions) => {
    return createToast({ type: 'info', content, toastOptions: options });
  };
  api.loading = (content: ToastContent, options?: ToastOptions) => {
    return createToast({ type: 'loading', content, toastOptions: { ...options, duration: 0 } });
  };
  api.dismiss = dismiss;
  api.remove = dismiss;
  api.custom = (render, options) => {
    const id = options?.id ?? `toast-${++counter}`;
    const item: ToastItem = {
      id,
      type: 'info',
      title: render({ id, dismiss: () => dismiss(id) }),
      description: '',
      duration: options?.duration ?? DEFAULT_DURATION_MS,
      createdAt: Date.now(),
      icon: options?.icon,
      className: options?.className,
    };
    if (toasts.length >= MAX_VISIBLE_TOASTS) {
      queuedToasts.push(item);
    } else {
      toasts.push(item);
      startTimer(item.id, item.duration);
    }
    notify();
    return id;
  };
  api.promise = async (promise, messages, options) => {
    const loadingId = api.loading(messages.loading ?? 'Working...', options);

    try {
      const result = await promise;
      dismiss(loadingId);
      const successMessage = typeof messages.success === 'function' ? messages.success(result) : messages.success;
      api.success(successMessage, options);
      return result;
    } catch (error) {
      dismiss(loadingId);
      const errorMessage = typeof messages.error === 'function' ? messages.error(error) : messages.error;
      api.error(errorMessage, options);
      throw error;
    }
  };

  return api;
}

const toast = createToastApi();

export function subscribe(listener: (snapshot: ToastSnapshot) => void) {
  listeners = [...listeners, listener];
  return () => {
    listeners = listeners.filter((current) => current !== listener);
  };
}

export function Toaster({ position = 'top-right' }: ToasterProps = {}) {
  const [snapshot, setSnapshot] = React.useState<ToastSnapshot>({ visible: [], queued: [] });

  React.useEffect(() => {
    return subscribe(setSnapshot);
  }, []);

  const positionClasses = {
    'top-right': 'inset-x-0 top-3 sm:top-4 sm:right-4 sm:left-auto sm:items-end',
    'top-center': 'inset-x-0 top-3 sm:top-4 sm:left-1/2 sm:-translate-x-1/2',
    'bottom-right': 'inset-x-0 bottom-3 sm:bottom-4 sm:right-4 sm:left-auto sm:items-end',
    'bottom-center': 'inset-x-0 bottom-3 sm:bottom-4 sm:left-1/2 sm:-translate-x-1/2',
  }[position] ?? 'inset-x-0 top-3 sm:top-4 sm:right-4 sm:left-auto sm:items-end';

  return (
    <div className={cn('pointer-events-none fixed z-[110] flex flex-col items-center gap-3 px-3 sm:px-0', positionClasses)} aria-live="polite" aria-atomic="false">
      <AnimatePresence initial={false} mode="popLayout">
        {snapshot.visible.map((item) => {
          const icon = getToastIcon(item.type, item.icon);
          const toastClasses = cn(
            'pointer-events-auto relative flex min-h-[72px] w-full max-w-[92vw] items-start gap-3 overflow-hidden rounded-2xl border px-4 py-3 shadow-xl ring-1 ring-black/[0.03] backdrop-blur-xl sm:max-w-[420px] sm:min-w-[320px] dark:ring-white/[0.05]',
            getToastThemeClasses(item.type),
            item.className,
          );

          return (
            <motion.div
              key={item.id}
              layout
              initial={{ opacity: 0, y: -18, scale: 0.96 }}
              animate={{ opacity: 1, y: 0, scale: 1 }}
              exit={{ opacity: 0, y: -10, scale: 0.96 }}
              transition={{ duration: 0.2, ease: 'easeOut' }}
              role={item.type === 'error' ? 'alert' : 'status'}
              aria-live={item.type === 'error' ? 'assertive' : 'polite'}
              className={toastClasses}
              onMouseEnter={() => pauseTimer(item.id)}
              onMouseLeave={() => resumeTimer(item.id)}
              onFocus={() => pauseTimer(item.id)}
              onBlur={() => resumeTimer(item.id)}
            >
              <div aria-hidden className={cn('absolute bottom-0 left-0 top-0 w-1', getToastAccentClasses(item.type))} />
              <div className={cn('mt-0.5 flex-shrink-0 rounded-full p-1.5 ring-1', getToastIconClasses(item.type))}>
                {icon}
              </div>
              <div className="min-w-0 flex-1">
                <div className="text-sm font-semibold leading-5 tracking-normal">{item.title}</div>
                {item.description ? <div className="mt-1 text-sm leading-5 text-slate-600 dark:text-slate-300">{item.description}</div> : null}
                {item.action ? (
                  <button
                    type="button"
                    className="mt-2 rounded-md border border-slate-200 bg-white px-2.5 py-1 text-xs font-semibold text-slate-900 shadow-sm transition hover:bg-slate-50 focus:outline-none focus:ring-2 focus:ring-slate-400 dark:border-slate-700 dark:bg-slate-900 dark:text-slate-50 dark:hover:bg-slate-800"
                    onClick={() => {
                      item.action?.onClick();
                      dismiss(item.id);
                    }}
                  >
                    {item.action.label}
                  </button>
                ) : null}
              </div>
              <button
                type="button"
                aria-label="Close notification"
                className="rounded-md p-1.5 text-slate-400 transition hover:bg-slate-100 hover:text-slate-700 focus:outline-none focus:ring-2 focus:ring-slate-400 dark:text-slate-500 dark:hover:bg-slate-800 dark:hover:text-slate-200"
                onClick={() => dismiss(item.id)}
              >
                <X className="h-4 w-4" />
              </button>
              {/* Progress bar (hidden for loading toasts) */}
              {item.type !== 'loading' ? <ToastProgress id={item.id} type={item.type} duration={item.duration} /> : null}
            </motion.div>
          );
        })}
      </AnimatePresence>
    </div>
  );
}

function ToastProgress({ id, type, duration }: { id: string; type: ToastType; duration: number }) {
  const [progress, setProgress] = React.useState(1);

  React.useEffect(() => {
    let raf = 0 as number;
    let mounted = true;

    const tick = () => {
      const timer = timers.get(id);
      if (!timer || !mounted) {
        setProgress(0);
        return;
      }

      const original = duration;
      const elapsed = timer.paused ? 0 : Date.now() - timer.startedAt;
      const currentRemaining = Math.max(0, timer.remaining - elapsed);
      const pct = Math.max(0, Math.min(1, currentRemaining / original));
      setProgress(pct);

      if (pct > 0) {
        raf = requestAnimationFrame(tick);
      }
    };

    raf = requestAnimationFrame(tick);

    return () => {
      mounted = false;
      if (raf) cancelAnimationFrame(raf);
    };
  }, [id, duration]);

  return (
    <div className="absolute left-0 right-0 bottom-0 h-[3px] overflow-hidden rounded-b-2xl">
      <div className="h-full origin-left transform will-change-transform" style={{ transform: `scaleX(${progress})` }}>
        <div className={cn('h-full', getToastAccentClasses(type))} />
      </div>
    </div>
  );
}

export default toast;

import { validateAccessToken } from '../features/auth/services/sessionStore';

export function createAuthenticateToken(_jwtSecret: string) {
  return async (req: any, res: any, next: any) => {
    const authHeader = req.headers['authorization'];
    const token = authHeader && String(authHeader).split(' ')[1];

    if (!token) return res.status(401).json({ error: 'Unauthorized' });

    try {
      const user = await validateAccessToken(token);
      req.user = user;
      next();
    } catch {
      return res.status(403).json({ error: 'Session expired. Please log in again.', code: 'SESSION_EXPIRED' });
    }
  };
}

import { NextResponse } from 'next/server';
import { isAllowedRequestOrigin } from '../security/origin';
import { requirePermission, requireRole, requireUser, type ApiUser } from './requireUser';
import { takeRateLimitToken } from '../rateLimit';
import type { Permission } from '../../modules/rbac/index';

type SecurityOptions = {
  keyPrefix: string;
  limit?: number;
  windowMs?: number;
  requireAuth?: boolean;
  roles?: string[];
  permission?: Permission;
  enforceOriginForMutations?: boolean;
};

type AuthenticatedSecurityOptions = SecurityOptions & {
  requireAuth: true;
};

export async function secureApiRoute(
  req: Request,
  options: AuthenticatedSecurityOptions,
): Promise<ApiUser | NextResponse>;

export async function secureApiRoute(
  req: Request,
  options: SecurityOptions & { requireAuth?: false },
): Promise<NextResponse | null>;

export async function secureApiRoute(
  req: Request,
  {
    keyPrefix,
    limit = 60,
    windowMs = 60_000,
    requireAuth = false,
    roles,
    permission,
    enforceOriginForMutations = true,
  }: SecurityOptions,
) {
  const forwardedFor = req.headers.get('x-forwarded-for');
  const ip = forwardedFor?.split(',')[0]?.trim() || 'unknown';
  const rate = await takeRateLimitToken(`${keyPrefix}:${ip}`, limit, windowMs);

  if (!rate.allowed) {
    return NextResponse.json(
      { error: 'Too many requests, please slow down.' },
      {
        status: 429,
        headers: {
          'Retry-After': String(Math.ceil(rate.resetAfterMs / 1000)),
        },
      },
    );
  }

  if (enforceOriginForMutations && !['GET', 'HEAD', 'OPTIONS'].includes(req.method)) {
    const origin = req.headers.get('origin');
    if (origin && !isAllowedRequestOrigin(origin, req.url)) {
      return NextResponse.json({ error: 'Origin not allowed' }, { status: 403 });
    }
  }

  if (!requireAuth) {
    return null;
  }

  const user = await requireUser(req);
  if (user instanceof NextResponse) {
    return user;
  }

  if (roles?.length) {
    const roleResponse = requireRole(user, roles as any);
    if (roleResponse) {
      return roleResponse;
    }
  }

  if (permission) {
    const permissionResponse = requirePermission(user, permission);
    if (permissionResponse) {
      return permissionResponse;
    }
  }

  return user as ApiUser;
}

import type { RouteContext } from "./context.js";
import bcrypt from "bcryptjs";
import crypto from "crypto";
import { Prisma } from "@prisma/client";
import { logger } from "../../lib/logger.js";
import {
  createSession,
  getAccessCookieOptions,
  getRefreshCookieOptions,
  listSessionsForUser,
  rotateSession,
  revokeAllSessionsForUser,
  revokeSessionByRefreshToken,
} from "../../features/auth/services/sessionStore.js";
import { claimDailyLoginReward } from "../../features/admin/services/engagement/gamification.js";
import {
  csrfHeaderName,
  getCsrfCookieHeader,
  issueCsrfToken,
} from "../../server/security/csrf.js";
import { rateLimit, rateLimits } from "../../server/rateLimit.js";

export function registerAuthRoutes(ctx: RouteContext): void {
  const {
    app,
    env,
    prisma,
    supabaseAdmin,
    supabaseAuth,
    authenticateToken,
    serializeUser,
    hashPassword,
    validateEmail,
    validatePassword,
    logServerError,
    isDatabaseUnavailableError,
    mailer,
    mailFrom,
    resendApiKey,
    ensureEngagementBootstrap,
    normalizePublicRole,
    resolveAuthRole,
    extractSupabaseAvatarUrl,
    getSessionMetadataFromRequest,
    ensureNotificationPreference,
    markLoginActivitiesRevoked,
    awardSignupBonus,
    ensureLocalSupabaseUser,
  } = ctx;

  const sendEmail = async (to: string, subject: string, html: string) => {
    if (mailer) {
      try {
        await mailer.sendMail({ from: mailFrom, to, subject, html });
        return;
      } catch (err) {
        console.error("Email send error", err);
      }
    }

    if (!resendApiKey) return;

    try {
      const response = await fetch("https://api.resend.com/emails", {
        method: "POST",
        headers: {
          Authorization: `Bearer ${resendApiKey}`,
          "Content-Type": "application/json",
        },
        body: JSON.stringify({
          from: mailFrom,
          to: [to],
          subject,
          html,
        }),
      });

      if (!response.ok) {
        const body = await response.text();
        console.error("Resend send error", response.status, body);
      }
    } catch (err) {
      console.error("Email send error", err);
    }
  };

  async function createVerificationToken(
    userId: string,
    table: "email_verifications" | "password_resets" | "phone_verifications",
    ttlMinutes: number,
  ) {
    const token = crypto.randomUUID();
    const expiresAt = new Date(Date.now() + ttlMinutes * 60 * 1000);

    if (table === "email_verifications") {
      await prisma.emailVerificationToken.create({
        data: {
          userId,
          token,
          expiresAt,
        },
      });
    } else if (table === "password_resets") {
      await prisma.passwordResetToken.create({
        data: {
          userId,
          token,
          expiresAt,
        },
      });
    } else {
      await prisma.phoneVerificationToken.create({
        data: {
          userId,
          token,
          expiresAt,
        },
      });
    }

    return { token, expiresAt };
  }

  const recordLoginActivity = async (userId: string, sessionId: string, metadata: ReturnType<typeof getSessionMetadataFromRequest>) => {
    await prisma.loginActivity.upsert({
      where: {
        userId_sessionId: {
          userId,
          sessionId,
        },
      },
      update: {
        ipAddress: metadata.ipAddress,
        userAgent: metadata.userAgent,
        deviceName: metadata.deviceName,
        location: metadata.location,
        lastSeenAt: new Date(),
        revokedAt: null,
      },
      create: {
        userId,
        sessionId,
        ipAddress: metadata.ipAddress,
        userAgent: metadata.userAgent,
        deviceName: metadata.deviceName,
        location: metadata.location,
      },
    });
  };

  const runAuthSideEffect = (label: string, task: Promise<unknown>) => {
    void task.catch((error) => {
      logger.warn(`auth.${label}_failed`, {
        error: error instanceof Error ? error.message : String(error),
      });
    });
  };

  const queueEngagementBootstrap = (userId: string, tenantId?: string | null) => {
    void (async () => {
      try {
        await ensureEngagementBootstrap(userId, tenantId);
      } catch (error) {
        logger.warn("auth.engagement_bootstrap_failed", {
          userId,
          tenantId: tenantId ?? null,
          error: error instanceof Error ? error.message : String(error),
        });
      }
    })();
  };

  const extractSupabaseAuthErrorMessage = (input: unknown): string => {
    if (typeof input === "string") {
      return input.trim();
    }
    if (input && typeof input === "object") {
      const record = input as Record<string, unknown>;
      if (typeof record.code === "string" && record.code.trim()) {
        return record.code.trim();
      }
      if (typeof record.message === "string" && record.message.trim()) {
        return record.message.trim();
      }
      if (typeof record.error === "string" && record.error.trim()) {
        return record.error.trim();
      }
      if (typeof record.error_description === "string" && record.error_description.trim()) {
        return record.error_description.trim();
      }
      if (typeof record.msg === "string" && record.msg.trim()) {
        return record.msg.trim();
      }
    }

    return "";
  };

  const findSupabaseAuthUserByEmail = async (email: string) => {
    if (!supabaseAdmin) {
      return null;
    }

    const normalizedEmail = email.toLowerCase();
    const perPage = 200;

    for (let page = 1; page <= 10; page += 1) {
      const { data, error } = await supabaseAdmin.auth.admin.listUsers({
        page,
        perPage,
      });

      if (error) {
        throw error;
      }

      const matchedUser =
        data.users.find((candidate: any) => candidate?.email?.toLowerCase() === normalizedEmail) ?? null;
      if (matchedUser) {
        return matchedUser;
      }

      if (data.users.length < perPage) {
        break;
      }
    }

    return null;
  };

  const supabaseUrl = process.env.NEXT_PUBLIC_SUPABASE_URL;
  const supabasePublishableKey =
    process.env.NEXT_PUBLIC_SUPABASE_PUBLISHABLE_KEY || process.env.NEXT_PUBLIC_SUPABASE_ANON_KEY;

  app.get("/api/auth/csrf", (_req, res) => {
    const token = issueCsrfToken();
    res.setHeader("Set-Cookie", getCsrfCookieHeader(token));
    res.json({ csrf_token: token, header_name: csrfHeaderName });
  });

  app.post("/api/auth/register", rateLimit("register", 10, 60_000), async (req, res) => {
    const { name, email, password, role } = req.body;
    if (!validateEmail(email)) return res.status(400).json({ error: "Invalid email" });
    if (!validatePassword(password)) return res.status(400).json({ error: "Password must be at least 8 characters with letters and numbers" });
    if (!name || name.length < 2) return res.status(400).json({ error: "Name is required" });
    const safeRole = ["customer", "seller", "reseller", "admin"].includes(role) ? role : "customer";

    try {
      const normalizedEmail = email.toLowerCase();
      const hashedPassword = await hashPassword(password);
      const slugBase = name
        .toLowerCase()
        .replace(/[^a-z0-9]+/g, "-")
        .replace(/^-|-$/g, "")
        .slice(0, 32) || "store";
      const tenantPayload = safeRole === "seller" || safeRole === "reseller"
        ? {
            create: {
              slug: `${slugBase}-${crypto.randomBytes(3).toString("hex")}`,
              name: `${name}'s workspace`,
              settings: {
                create: {},
              },
              stores: {
                create: {
                  name: `${name}'s storefront`,
                  currency: "BDT",
                  locale: "en-BD",
                },
              },
            },
          }
        : undefined;

      const createdUser = await prisma.user.create({
        data: {
          name,
          email: normalizedEmail,
          passwordHash: hashedPassword,
          role: safeRole,
          emailVerified: false,
          profileVisibility: safeRole === "customer" ? "private" : "public",
          tenant: tenantPayload,
        },
        include: {
          tenant: true,
        },
      });
      if (createdUser.tenantId) {
        await prisma.tenantMembership.create({
          data: {
            userId: createdUser.id,
            tenantId: createdUser.tenantId,
            role: safeRole,
            isPrimary: true,
            acceptedAt: new Date(),
          },
        });
      }
      runAuthSideEffect("notification_preference", ensureNotificationPreference(createdUser.id));
      queueEngagementBootstrap(createdUser.id, createdUser.tenantId);
      runAuthSideEffect("signup_bonus", awardSignupBonus(createdUser.id, createdUser.tenantId));
      const user = serializeUser(createdUser);

      const { token: verificationToken, expiresAt } = await createVerificationToken(createdUser.id, "email_verifications", 60 * 24);
      await sendEmail(
        normalizedEmail,
        "Verify your LofiMart account",
        `<p>Hello ${name},</p><p>Please verify your email by clicking the link below:</p><p><a href="${env.FRONTEND_URL}/api/auth/verify-email?token=${verificationToken}">Verify email</a></p><p>This link expires at ${new Date(expiresAt).toLocaleString()}.</p>`,
      );

      const sessionResult = await createSession(user, getSessionMetadataFromRequest(req));
      runAuthSideEffect("record_login_activity", recordLoginActivity(createdUser.id, sessionResult.session.sid, getSessionMetadataFromRequest(req)));
      res.cookie("access_token", sessionResult.accessToken, getAccessCookieOptions(user));
      res.cookie("refresh_token", sessionResult.refreshToken, getRefreshCookieOptions(user));
      res.json({
        user,
        token: sessionResult.accessToken,
        refreshToken: sessionResult.refreshToken,
        refreshExpiresAt: sessionResult.expiresAt,
        emailVerificationToken: process.env.NODE_ENV === "production" ? undefined : verificationToken,
        emailVerificationExpiresAt: expiresAt,
      });
    } catch (error: any) {
      if (error.code === "P2002") {
        res.status(400).json({ error: "Email already exists" });
      } else {
        res.status(500).json({ error: "Registration failed" });
      }
    }
  });

  app.post("/api/auth/login", rateLimit("login", 20, 60_000), async (req, res) => {
    const { email, password } = req.body;
    const normalizedEmail = typeof email === "string" ? email.toLowerCase() : "";
    const user = normalizedEmail
      ? await prisma.user.findUnique({
          where: { email: normalizedEmail },
        })
      : null;

    const MAX_ATTEMPTS = 5;
    const LOCK_WINDOW = 15 * 60 * 1000; // 15m
    const lockKey = `login-lock-${normalizedEmail}`;
    const attemptsKey = `login-attempts-${normalizedEmail}`;

    const now = Date.now();
    const lock = rateLimits[lockKey];
    if (lock && lock.timestamps[0] && now - lock.timestamps[0] < LOCK_WINDOW) {
      return res.status(429).json({ error: "Too many failed attempts. Try again later." });
    }

    const passwordOk = user && (await bcrypt.compare(password, user.passwordHash));
    if (!user || !passwordOk) {
      const bucket = rateLimits[attemptsKey] || { timestamps: [] };
      bucket.timestamps = bucket.timestamps.filter((t) => now - t < LOCK_WINDOW);
      bucket.timestamps.push(now);
      rateLimits[attemptsKey] = bucket;
      if (bucket.timestamps.length >= MAX_ATTEMPTS) {
        rateLimits[lockKey] = { timestamps: [now] };
        rateLimits[attemptsKey] = { timestamps: [] };
      }
      return res.status(401).json({ error: "Invalid email or password" });
    }

    // success: clear attempt bucket
    delete rateLimits[attemptsKey];
    delete rateLimits[lockKey];
    if (!user.emailVerified) {
      return res.status(403).json({ error: "Email not verified", requiresVerification: true });
    }

    if (user.isBlocked || user.deactivatedAt) {
      return res.status(403).json({ error: "This account is not currently allowed to sign in" });
    }

    queueEngagementBootstrap(user.id, user.tenantId);
    const userWithoutPassword = serializeUser(user);
    const sessionResult = await createSession(userWithoutPassword, getSessionMetadataFromRequest(req));
    runAuthSideEffect("record_login_activity", recordLoginActivity(user.id, sessionResult.session.sid, getSessionMetadataFromRequest(req)));
    runAuthSideEffect("claim_daily_login_reward", claimDailyLoginReward(user.id, user.tenantId));
    res.cookie("access_token", sessionResult.accessToken, getAccessCookieOptions(userWithoutPassword));
    res.cookie("refresh_token", sessionResult.refreshToken, getRefreshCookieOptions(userWithoutPassword));
    res.json({ user: userWithoutPassword, token: sessionResult.accessToken, refreshToken: sessionResult.refreshToken, refreshExpiresAt: sessionResult.expiresAt });
  });

  app.post("/api/auth/supabase/exchange", rateLimit("supabase-exchange", 30, 60_000), async (req: any, res: any) => {
    try {
      const { accessToken, role, name, mode } = req.body ?? {};
      if (!accessToken || !supabaseAuth) {
        return res.status(400).json({ error: "Supabase auth is not configured" });
      }

      const { data, error } = await supabaseAuth.auth.getUser(String(accessToken));
      if (error || !data.user?.email) {
        return res.status(401).json({ error: "Invalid Supabase session" });
      }

      const supabaseUser = data.user;
      if (!supabaseUser.email) {
        return res.status(400).json({ error: 'Supabase user email is missing' });
      }
      const normalizedEmail = supabaseUser.email.toLowerCase();
      const confirmedAt = (supabaseUser as any).email_confirmed_at || (supabaseUser as any).confirmed_at || null;
      const authMode = mode === 'register' ? 'register' : 'login';
      const safeRole = resolveAuthRole(role, supabaseUser as any);
      const preferredName =
        name ||
        (supabaseUser.user_metadata?.name as string | undefined) ||
        (supabaseUser.user_metadata?.full_name as string | undefined) ||
        normalizedEmail.split("@")[0];
      const localUser = await ensureLocalSupabaseUser({
        email: normalizedEmail,
        preferredName,
        preferredAvatarUrl: extractSupabaseAvatarUrl(supabaseUser as any),
        safeRole,
        confirmedAt,
        authMode,
      });

      if (localUser.isBlocked || localUser.deactivatedAt) {
        return res.status(403).json({ error: "This account is not currently allowed to sign in" });
      }

      queueEngagementBootstrap(localUser.id, localUser.tenantId);
      const user = serializeUser(localUser);
      const sessionResult = await createSession(user, getSessionMetadataFromRequest(req));
      runAuthSideEffect("record_login_activity", recordLoginActivity(localUser.id, sessionResult.session.sid, getSessionMetadataFromRequest(req)));
      runAuthSideEffect("claim_daily_login_reward", claimDailyLoginReward(localUser.id, localUser.tenantId));
      res.cookie("access_token", sessionResult.accessToken, getAccessCookieOptions(user));
      res.cookie("refresh_token", sessionResult.refreshToken, getRefreshCookieOptions(user));
      res.json({ user, token: sessionResult.accessToken, refreshToken: sessionResult.refreshToken, refreshExpiresAt: sessionResult.expiresAt });
    } catch (error) {
      logServerError("supabase auth exchange", error);
      const statusCode = typeof (error as any)?.statusCode === "number" ? (error as any).statusCode : null;
      if (statusCode) {
        return res.status(statusCode).json({ error: (error as any)?.message || "Failed to complete sign-in" });
      }
      if (isDatabaseUnavailableError(error)) {
        return res.status(503).json({ error: "Database is busy right now. Please try signing in again in a moment." });
      }
      return res.status(500).json({ error: "Failed to complete sign-in" });
    }
  });

  app.post("/api/auth/supabase/provision", rateLimit("supabase-provision", 20, 60_000), async (req: any, res: any) => {
    try {
      const { supabaseUserId, email, role, name } = req.body ?? {};
      if (!supabaseUserId || !supabaseAdmin || !supabaseUrl) {
        return res.status(400).json({ error: "Supabase provisioning is not configured" });
      }

      const { data, error } = await supabaseAdmin.auth.admin.getUserById(String(supabaseUserId));
      if (error || !data.user?.email) {
        return res.status(401).json({ error: "Unable to verify the newly created account" });
      }

      const normalizedEmail = data.user.email.toLowerCase();
      if (typeof email === "string" && email.toLowerCase() !== normalizedEmail) {
        return res.status(400).json({ error: "Registration email mismatch detected" });
      }

      const confirmedAt = (data.user as any).email_confirmed_at || (data.user as any).confirmed_at || null;
      const safeRole = resolveAuthRole(role, data.user as any);
      const preferredName =
        name ||
        (data.user.user_metadata?.name as string | undefined) ||
        (data.user.user_metadata?.full_name as string | undefined) ||
        normalizedEmail.split("@")[0];

      await ensureLocalSupabaseUser({
        email: normalizedEmail,
        preferredName,
        preferredAvatarUrl: extractSupabaseAvatarUrl(data.user as any),
        safeRole,
        confirmedAt,
        authMode: "register",
      });

      return res.json({ success: true });
    } catch (error) {
      logServerError("supabase auth provision", error);
      const statusCode = typeof (error as any)?.statusCode === "number" ? (error as any).statusCode : null;
      if (statusCode) {
        return res.status(statusCode).json({ error: (error as any)?.message || "Failed to provision account" });
      }
      if (isDatabaseUnavailableError(error)) {
        return res.status(503).json({ error: "Database is busy right now. Please try again in a moment." });
      }
      return res.status(500).json({ error: "Failed to provision account" });
    }
  });

  app.post("/api/auth/supabase/recover-register", rateLimit("supabase-recover-register", 10, 60_000), async (req: any, res: any) => {
    try {
      const { email, role, name } = req.body ?? {};
      if (!email || typeof email !== "string" || !supabaseAdmin) {
        return res.status(400).json({ error: "Supabase recovery is not configured" });
      }

      const recoveredUser = await findSupabaseAuthUserByEmail(email);
      if (!recoveredUser?.email) {
        return res.status(404).json({ error: "No matching Supabase account was found yet" });
      }

      const normalizedEmail = recoveredUser.email.toLowerCase();
      const confirmedAt = (recoveredUser as any).email_confirmed_at || (recoveredUser as any).confirmed_at || null;
      const safeRole = resolveAuthRole(role, recoveredUser as any);
      const preferredName =
        name ||
        (recoveredUser.user_metadata?.name as string | undefined) ||
        (recoveredUser.user_metadata?.full_name as string | undefined) ||
        normalizedEmail.split("@")[0];

      await ensureLocalSupabaseUser({
        email: normalizedEmail,
        preferredName,
        preferredAvatarUrl: extractSupabaseAvatarUrl(recoveredUser as any),
        safeRole,
        confirmedAt,
        authMode: "register",
      });

      return res.json({
        success: true,
        requiresVerification: !confirmedAt,
      });
    } catch (error) {
      logServerError("supabase register recovery", error);
      const statusCode = typeof (error as any)?.statusCode === "number" ? (error as any).statusCode : null;
      if (statusCode) {
        return res.status(statusCode).json({ error: (error as any)?.message || "Failed to recover account registration" });
      }
      if (isDatabaseUnavailableError(error)) {
        return res.status(503).json({ error: "Database is busy right now. Please try again in a moment." });
      }
      return res.status(500).json({ error: "Failed to recover account registration" });
    }
  });

  app.post("/api/auth/supabase/register", rateLimit("supabase-register", 10, 60_000), async (req: any, res: any) => {
    try {
      const { email, password, role, name, referralCode, redirectTo } = req.body ?? {};

      if (!supabaseUrl || !supabasePublishableKey || !supabaseAdmin) {
        return res.status(400).json({ error: "Supabase registration is not configured" });
      }
      if (!validateEmail(email)) {
        return res.status(400).json({ error: "Invalid email" });
      }
      if (!validatePassword(password)) {
        return res.status(400).json({ error: "Password must be at least 8 characters with letters and numbers" });
      }
      if (!name || String(name).trim().length < 2) {
        return res.status(400).json({ error: "Name is required" });
      }

      const safeRole = normalizePublicRole(role);
      const normalizedEmail = String(email).toLowerCase();
      const callbackUrl =
        typeof redirectTo === "string" && redirectTo.startsWith("http")
          ? redirectTo
          : `${env.FRONTEND_URL}/login`;

      const signupResponse = await fetch(
        `${supabaseUrl}/auth/v1/signup?redirect_to=${encodeURIComponent(callbackUrl)}`,
        {
          method: "POST",
          headers: {
            "Content-Type": "application/json",
            apikey: supabasePublishableKey,
            Authorization: `Bearer ${supabasePublishableKey}`,
          },
          body: JSON.stringify({
            email: normalizedEmail,
            password,
            data: {
              name: String(name).trim(),
              role: safeRole,
              referralCode: typeof referralCode === "string" && referralCode.trim() ? referralCode.trim() : undefined,
            },
          }),
        },
      );

      const payload = (await signupResponse.json().catch(() => null)) as any;

      if (!signupResponse.ok) {
        const supabaseError =
          extractSupabaseAuthErrorMessage(payload) ||
          (signupResponse.status === 504
            ? "The authentication service took too long to respond. Please wait a moment and try again."
            : "Supabase registration failed");
        const isRetryableSignupFailure =
          signupResponse.status >= 500 ||
          signupResponse.status === 504 ||
          /email rate limit exceeded/i.test(String(supabaseError)) ||
          /over_email_send_rate_limit/i.test(String(supabaseError));
        const recoveredUser = isRetryableSignupFailure
          ? await findSupabaseAuthUserByEmail(normalizedEmail)
          : null;

        if (recoveredUser?.email) {
          const confirmedAt = (recoveredUser as any).email_confirmed_at || (recoveredUser as any).confirmed_at || null;
          const localUser = await ensureLocalSupabaseUser({
            email: recoveredUser.email.toLowerCase(),
            preferredName:
              String(name).trim() ||
              (recoveredUser.user_metadata?.name as string | undefined) ||
              (recoveredUser.user_metadata?.full_name as string | undefined) ||
              recoveredUser.email.split("@")[0],
            preferredAvatarUrl: extractSupabaseAvatarUrl(recoveredUser as any),
            safeRole,
            confirmedAt,
            authMode: "register",
          });

          return res.json({
            success: true,
            recovered: true,
            requiresVerification: !confirmedAt,
            user: serializeUser(localUser),
          });
        }

        if (isRetryableSignupFailure) {
          const { data: createdByAdmin, error: createByAdminError } = await supabaseAdmin.auth.admin.createUser({
            email: normalizedEmail,
            password,
            email_confirm: true,
            user_metadata: {
              name: String(name).trim(),
              role: safeRole,
              referralCode: typeof referralCode === "string" && referralCode.trim() ? referralCode.trim() : undefined,
            },
          } as any);

          if (!createByAdminError && createdByAdmin?.user?.email) {
            const confirmedAt =
              (createdByAdmin.user as any).email_confirmed_at ||
              (createdByAdmin.user as any).confirmed_at ||
              new Date().toISOString();
            const localUser = await ensureLocalSupabaseUser({
              email: createdByAdmin.user.email.toLowerCase(),
              preferredName:
                String(name).trim() ||
                (createdByAdmin.user.user_metadata?.name as string | undefined) ||
                (createdByAdmin.user.user_metadata?.full_name as string | undefined) ||
                createdByAdmin.user.email.split("@")[0],
              preferredAvatarUrl: extractSupabaseAvatarUrl(createdByAdmin.user as any),
              safeRole,
              confirmedAt,
              authMode: "register",
            });

            const user = serializeUser(localUser);
            const sessionResult = await createSession(user, getSessionMetadataFromRequest(req));
            runAuthSideEffect("record_login_activity", recordLoginActivity(localUser.id, sessionResult.session.sid, getSessionMetadataFromRequest(req)));
            runAuthSideEffect("claim_daily_login_reward", claimDailyLoginReward(localUser.id, localUser.tenantId));
            res.cookie("access_token", sessionResult.accessToken, getAccessCookieOptions(user));
            res.cookie("refresh_token", sessionResult.refreshToken, getRefreshCookieOptions(user));
            return res.json({
              success: true,
              recovered: true,
              fallback: "admin-create-user",
              requiresVerification: false,
              user,
              token: sessionResult.accessToken,
              refreshToken: sessionResult.refreshToken,
              refreshExpiresAt: sessionResult.expiresAt,
            });
          }

          if (createByAdminError) {
            const lateRecoveredUser = await findSupabaseAuthUserByEmail(normalizedEmail);
            if (lateRecoveredUser?.email) {
              const confirmedAt =
                (lateRecoveredUser as any).email_confirmed_at ||
                (lateRecoveredUser as any).confirmed_at ||
                new Date().toISOString();
              const localUser = await ensureLocalSupabaseUser({
                email: lateRecoveredUser.email.toLowerCase(),
                preferredName:
                  String(name).trim() ||
                  (lateRecoveredUser.user_metadata?.name as string | undefined) ||
                  (lateRecoveredUser.user_metadata?.full_name as string | undefined) ||
                  lateRecoveredUser.email.split("@")[0],
                preferredAvatarUrl: extractSupabaseAvatarUrl(lateRecoveredUser as any),
                safeRole,
                confirmedAt,
                authMode: "register",
              });

              const user = serializeUser(localUser);
              const sessionResult = await createSession(user, getSessionMetadataFromRequest(req));
              runAuthSideEffect("record_login_activity", recordLoginActivity(localUser.id, sessionResult.session.sid, getSessionMetadataFromRequest(req)));
              runAuthSideEffect("claim_daily_login_reward", claimDailyLoginReward(localUser.id, localUser.tenantId));
              res.cookie("access_token", sessionResult.accessToken, getAccessCookieOptions(user));
              res.cookie("refresh_token", sessionResult.refreshToken, getRefreshCookieOptions(user));
              return res.json({
                success: true,
                recovered: true,
                fallback: "late-recover-existing-user",
                requiresVerification: false,
                user,
                token: sessionResult.accessToken,
                refreshToken: sessionResult.refreshToken,
                refreshExpiresAt: sessionResult.expiresAt,
              });
            }
          }
        }

        const statusCode =
          signupResponse.status === 429
            ? 429
            : /already/i.test(String(supabaseError))
              ? 409
              : signupResponse.status >= 400 && signupResponse.status < 600
                ? signupResponse.status
                : 500;
        return res.status(statusCode).json({ error: supabaseError });
      }

      const supabaseUser = payload?.user;
      if (!supabaseUser?.email) {
        return res.status(500).json({ error: "Supabase did not return the created user" });
      }

      const confirmedAt = (supabaseUser as any).email_confirmed_at || (supabaseUser as any).confirmed_at || null;
      const localUser = await ensureLocalSupabaseUser({
        email: supabaseUser.email.toLowerCase(),
        preferredName:
          String(name).trim() ||
          (supabaseUser.user_metadata?.name as string | undefined) ||
          (supabaseUser.user_metadata?.full_name as string | undefined) ||
          supabaseUser.email.split("@")[0],
        preferredAvatarUrl: extractSupabaseAvatarUrl(supabaseUser as any),
        safeRole,
        confirmedAt,
        authMode: "register",
      });

      if (payload?.session?.access_token && confirmedAt) {
        const user = serializeUser(localUser);
        const sessionResult = await createSession(user, getSessionMetadataFromRequest(req));
        runAuthSideEffect("record_login_activity", recordLoginActivity(localUser.id, sessionResult.session.sid, getSessionMetadataFromRequest(req)));
        runAuthSideEffect("claim_daily_login_reward", claimDailyLoginReward(localUser.id, localUser.tenantId));
        res.cookie("access_token", sessionResult.accessToken, getAccessCookieOptions(user));
        res.cookie("refresh_token", sessionResult.refreshToken, getRefreshCookieOptions(user));
        return res.json({
          success: true,
          user,
          token: sessionResult.accessToken,
          refreshToken: sessionResult.refreshToken,
          refreshExpiresAt: sessionResult.expiresAt,
          requiresVerification: false,
        });
      }

      return res.json({
        success: true,
        requiresVerification: !confirmedAt,
        user: serializeUser(localUser),
      });
    } catch (error) {
      logServerError("supabase register", error);
      const statusCode = typeof (error as any)?.statusCode === "number" ? (error as any).statusCode : null;
      if (statusCode) {
        return res.status(statusCode).json({ error: (error as any)?.message || "Failed to register with Supabase" });
      }
      if (isDatabaseUnavailableError(error)) {
        return res.status(503).json({ error: "Database is busy right now. Please try again in a moment." });
      }
      return res.status(500).json({ error: "Failed to register with Supabase" });
    }
  });

  app.post("/api/auth/refresh", rateLimit("refresh", 40, 60_000), async (req: any, res: any) => {
    const { refreshToken } = req.body;
    if (!refreshToken) return res.status(400).json({ error: "Missing refreshToken" });

    const rotatedSession = await rotateSession(refreshToken);
    if (!rotatedSession) {
      return res.status(401).json({ error: "Invalid refresh token" });
    }

    res.cookie("access_token", rotatedSession.accessToken, getAccessCookieOptions(rotatedSession.session.user));
    res.cookie("refresh_token", rotatedSession.refreshToken, getRefreshCookieOptions(rotatedSession.session.user));
    res.json({
      token: rotatedSession.accessToken,
      refreshToken: rotatedSession.refreshToken,
      refreshExpiresAt: rotatedSession.expiresAt,
    });
  });

  app.post("/api/auth/change-password", authenticateToken, async (req: any, res: any) => {
    const { currentPassword, newPassword } = req.body;
    if (!validatePassword(newPassword)) return res.status(400).json({ error: "Password must be at least 8 characters with letters and numbers" });

    const user = await prisma.user.findUnique({ where: { id: String(req.user.id) } });
    if (!user || !(await bcrypt.compare(currentPassword, user.passwordHash))) {
      return res.status(400).json({ error: "Current password is incorrect" });
    }

    const hashed = await hashPassword(newPassword);
    await prisma.user.update({
      where: { id: user.id },
      data: { passwordHash: hashed },
    });
    await revokeAllSessionsForUser(req.user.id);
    await markLoginActivitiesRevoked(String(req.user.id));
    res.json({ success: true });
  });

  app.post("/api/auth/request-reset", rateLimit("request-reset", 10, 60_000), async (req: any, res: any) => {
    const { email } = req.body;
    if (!validateEmail(email)) return res.status(400).json({ error: "Invalid email" });
    const user = await prisma.user.findUnique({
      where: { email: email.toLowerCase() },
      select: { id: true },
    });
    if (user) {
      const { token, expiresAt } = await createVerificationToken(user.id, "password_resets", 30);
      await sendEmail(
        email.toLowerCase(),
        "Reset your LofiMart password",
        `<p>We received a request to reset your password.</p><p>Use this token: <strong>${token}</strong></p><p>Or open the reset page and submit it there. This token expires at ${new Date(expiresAt).toLocaleString()}.</p>`,
      );
      res.json({ success: true, resetToken: process.env.NODE_ENV === "production" ? undefined : token, expiresAt });
    } else {
      res.json({ success: true });
    }
  });

  app.post("/api/auth/reset-password", rateLimit("reset-password", 20, 60_000), async (req: any, res: any) => {
    const { token, newPassword } = req.body;
    if (!validatePassword(newPassword)) return res.status(400).json({ error: "Password must be at least 8 characters with letters and numbers" });
    const record = await prisma.passwordResetToken.findUnique({
      where: { token },
    });
    if (!record || record.used) return res.status(400).json({ error: "Invalid or used token" });
    if (new Date(record.expiresAt).getTime() < Date.now()) {
      return res.status(400).json({ error: "This reset link has expired. Please request a new one.", code: "TOKEN_EXPIRED" });
    }

    const hashed = await hashPassword(newPassword);
    await prisma.$transaction([
      prisma.user.update({
        where: { id: record.userId },
        data: { passwordHash: hashed },
      }),
      prisma.passwordResetToken.update({
        where: { id: record.id },
        data: { used: true },
      }),
    ]);
    await revokeAllSessionsForUser(record.userId);
    await markLoginActivitiesRevoked(String(record.userId));
    res.json({ success: true });
  });

  app.get("/api/auth/sessions", authenticateToken, async (req: any, res: any) => {
    const [sessions, activities] = await Promise.all([
      listSessionsForUser(req.user.id),
      prisma.loginActivity.findMany({
        where: { userId: String(req.user.id) },
        orderBy: { loggedInAt: "desc" },
      }),
    ]);

    const activityBySession = new Map<string, any>(activities.map((activity: any) => [activity.sessionId, activity]));

    res.json(
      sessions.map((session) => ({
        session_id: session.sid,
        created_at: session.createdAt,
        expires_at: session.expiresAt,
        device_name: session.deviceName ?? activityBySession.get(session.sid)?.deviceName ?? null,
        ip_address: session.ipAddress ?? activityBySession.get(session.sid)?.ipAddress ?? null,
        user_agent: session.userAgent ?? activityBySession.get(session.sid)?.userAgent ?? null,
        location: session.location ?? activityBySession.get(session.sid)?.location ?? null,
      })),
    );
  });

  app.post("/api/auth/logout-all", authenticateToken, async (req: any, res: any) => {
    await revokeAllSessionsForUser(req.user.id);
    await markLoginActivitiesRevoked(String(req.user.id));
    res.clearCookie("access_token", getAccessCookieOptions());
    res.clearCookie("refresh_token", getRefreshCookieOptions());
    res.json({ success: true });
  });

  app.post("/api/auth/send-verification", authenticateToken, rateLimit("send-verification", 5, 60_000), async (req: any, res: any) => {
    const user = await prisma.user.findUnique({ where: { id: String(req.user.id) } });
    if (!user) return res.status(404).json({ error: "User not found" });
    if (user.emailVerified) return res.json({ success: true, message: "Already verified" });
    const { token, expiresAt } = await createVerificationToken(user.id, "email_verifications", 60 * 24);
    await sendEmail(
      user.email,
      "Verify your LofiMart account",
      `<p>Hello ${user.name || "there"},</p><p>Please verify your email by clicking the link below:</p><p><a href="${env.FRONTEND_URL}/api/auth/verify-email?token=${token}">Verify email</a></p><p>This link expires at ${new Date(expiresAt).toLocaleString()}.</p>`,
    );
    res.json({ success: true, verificationToken: process.env.NODE_ENV === "production" ? undefined : token, expiresAt });
  });

  app.post("/api/auth/send-phone-verification", authenticateToken, rateLimit("send-phone-verification", 5, 60_000), async (req: any, res: any) => {
    const user = await prisma.user.findUnique({ where: { id: String(req.user.id) } });
    if (!user) return res.status(404).json({ error: "User not found" });
    if (!user.phone) return res.status(400).json({ error: "Add a phone number before requesting verification" });
    if (user.phoneVerified) return res.json({ success: true, message: "Phone already verified" });

    const { token, expiresAt } = await createVerificationToken(user.id, "phone_verifications", 10);
    const otp = token.replace(/-/g, "").slice(0, 6).toUpperCase();

    res.json({
      success: true,
      expiresAt,
      phoneVerificationCode: process.env.NODE_ENV === "production" ? undefined : otp,
    });
  });

  app.post("/api/auth/verify-phone", authenticateToken, rateLimit("verify-phone", 10, 60_000), async (req: any, res: any) => {
    const submittedCode = String(req.body?.code || "").trim().toUpperCase();
    if (!submittedCode || submittedCode.length < 6) {
      return res.status(400).json({ error: "A valid verification code is required" });
    }

    const records = await prisma.phoneVerificationToken.findMany({
      where: {
        userId: String(req.user.id),
        used: false,
      },
      orderBy: { createdAt: "desc" },
      take: 10,
    });

    const matchingRecord = records.find((record: any) => record.token.replace(/-/g, "").slice(0, 6).toUpperCase() === submittedCode);
    if (!matchingRecord) {
      return res.status(400).json({ error: "Invalid verification code" });
    }

    if (new Date(matchingRecord.expiresAt).getTime() < Date.now()) {
      return res.status(400).json({ error: "Verification code expired" });
    }

    await prisma.$transaction([
      prisma.user.update({
        where: { id: String(req.user.id) },
        data: {
          phoneVerified: true,
          phoneVerifiedAt: new Date(),
        },
      }),
      prisma.phoneVerificationToken.update({
        where: { id: matchingRecord.id },
        data: { used: true },
      }),
    ]);

    res.json({ success: true });
  });

  app.get("/api/auth/verify-email", rateLimit("verify-email", 20, 60_000), async (req: any, res: any) => {
    const token = req.query.token as string;
    if (!token) return res.status(400).send("Missing token");
    const record = await prisma.emailVerificationToken.findUnique({
      where: { token },
    });
    if (!record || record.used) return res.status(400).send("Invalid or used token");
    if (new Date(record.expiresAt).getTime() < Date.now()) {
      return res.status(400).send("This verification link has expired. Please request a new one.");
    }

    await prisma.$transaction([
      prisma.user.update({
        where: { id: record.userId },
        data: {
          emailVerified: true,
          emailVerifiedAt: new Date(),
        },
      }),
      prisma.emailVerificationToken.update({
        where: { id: record.id },
        data: { used: true },
      }),
    ]);
    res.send("Email verified. You can close this tab.");
  });

  app.post("/api/auth/logout", async (req, res) => {
    const { refreshToken } = req.body;
    if (refreshToken) {
      await revokeSessionByRefreshToken(refreshToken);
    }
    res.clearCookie("access_token", { path: "/" });
    res.clearCookie("refresh_token", { path: "/" });
    res.json({ success: true });
  });
}

import type express from "express";
import type Stripe from "stripe";

type Middleware = (req: any, res: any, next: any) => void;

export interface RouteContext {
  app: express.Express;
  env: Record<string, unknown>;
  prisma: any;
  prismaDirect: any;
  stripe: Stripe | null;
  supabaseAuth: any;
  supabaseAdmin: any;
  cloudinary: any;
  mailer: any;
  mailFrom: string;
  resendApiKey: string;
  webpush: any;
  authenticateToken: Middleware;
  requireRole: (...roles: string[]) => Middleware;
  signAccessToken: (payload: any, sid: string) => string;
  ensureReferralCode: (resellerId: string) => Promise<{ code: string; clicks: number }>;
  getResellerIdFromOrderRefCode: (refCode?: string | null) => Promise<string | null>;
  settleResellerCommissionsForOrder: (orderId: string) => Promise<void>;
  syncResellerSettlementFromShipmentStatus: (orderId: string, status: string) => Promise<void>;
  sendEmail: (to: string, subject: string, html: string) => Promise<void>;
  broadcast: (msg: unknown) => void;
  emitStockUpdate: (productId: number, stock: number) => void;
  recordReferralClick: (code?: string) => Promise<string | null>;
  handleAuditLog: (userId: string | null | undefined, action: string, entityType: string, entityId?: string | null, metadata?: Record<string, unknown>) => Promise<void>;
  getActiveAdminUsers: () => Promise<Array<{ id: string; email: string; name: string | null }>>;
  getSettingsPathForRole: (role: string) => string;
  ensureNotificationPreference: (userId: string, tenantId?: string | null) => Promise<any>;
  markLoginActivitiesRevoked: (userId: string, currentSessionId?: string) => Promise<void>;
  reverseResellerCommissionsForOrder: (orderId: string, reason: "cancelled" | "returned" | "delivery_failed") => Promise<void>;
  awardSignupBonus: (userId: string, tenantId?: string | null) => Promise<void>;
  ensureLocalSupabaseUser: (params: {
    email: string;
    preferredName: string;
    preferredAvatarUrl?: string | null;
    safeRole: "customer" | "seller" | "reseller" | "admin";
    confirmedAt: string | null;
    authMode: "login" | "register";
  }) => Promise<any>;
  normalizePublicRole: (value: unknown) => "customer" | "seller" | "reseller";
  resolveAuthRole: (requestedRole: unknown, supabaseUser?: any) => "customer" | "seller" | "reseller";
  extractSupabaseAvatarUrl: (supabaseUser?: any) => string | null;
  getRequestIp: (req: any) => string | null;
  getRequestLocation: (req: any) => string | null;
  getSessionMetadataFromRequest: (req: any) => Record<string, unknown>;
  serializeUser: (user: any) => any;
  hashPassword: (plain: string) => Promise<string>;
  validateEmail: (email: string) => boolean;
  validatePassword: (pwd: string) => boolean;
  logServerError: (context: string, error: unknown, meta?: Record<string, unknown>) => void;
  isDatabaseUnavailableError: (error: unknown) => boolean;
  ensureEngagementBootstrap: (userId: string, tenantId?: string | null) => Promise<void>;
  generateUniqueOrderCode: () => Promise<string>;
  validateCouponForCart: (input: { code?: string | null; orderValue: number; sellerId?: string | null; productIds?: string[] }) => Promise<any>;
  userCartKey: (userId: string | number) => string;
  loadManualOrderCatalogForRole: (role: "seller" | "reseller", userId: string) => Promise<any[]>;
  createManualMarketplaceOrder: (args: { role: "seller" | "reseller"; creator: { id: string; name?: string | null; tenantId?: string | null; refCode?: string | null }; payload: any }) => Promise<any>;
  updateManualMarketplaceOrder: (args: { role: "seller" | "reseller"; userId: string; orderId: string; payload: any }) => Promise<any>;
  cancelManualMarketplaceOrder: (args: { role: "seller" | "reseller"; userId: string; orderId: string }) => Promise<any>;
}

