                <h1 style="margin:18px 0 0;font-size:28px;">Order #${escapeHtml(order.orderCode || order.id)}</h1>
                <p style="margin:12px 0 0;font-size:14px;color:#475569;">Placed on ${escapeHtml(new Date(order.createdAt).toLocaleString())}</p>
