          : null,
        parcel: {
          quantity: Math.max(1, Number(shipment.itemCount || shipment.items?.length || 1)),
          weightKg: Math.min(10, Math.max(0.5, Number((shipment.itemCount || 1) * 0.5))),
          deliveryType: 48,
